    *,
    action: str,
) -> bool:
    plan = scheme.get_query_permission_plan(model_cls, action=action)
    return scheme.has_object_level_enforcement() or plan.filter_rows


@pure_lazy
def _get_object_level_permission_scheme(
    permission_input: PermissionPlanningInput,
) -> PermissionScheme[object] | None:
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme):
        return None
    if not _has_object_permission_enforcement(
        scheme,
        permission_input.model_cls,
        action="write",
    ):
        return None
    return scheme


def _get_runtime_object_level_permission_scheme(
    model_cls: type[DatabaseObjectRow],
) -> PermissionScheme[object] | None:
    if _is_permission_bootstrap_model(model_cls):
        return None
    scheme = get_permission_scheme(model_cls)
    if not isinstance(scheme, PermissionScheme):
        return None
    if not _has_object_permission_enforcement(
        scheme,
        model_cls,
        action="write",
    ):
        return None
    return scheme


@pure_lazy
def _permission_shape_without_catalog(
    model_cls: type[DatabaseObjectRow],
) -> PermissionShape | None:
    """Return permission metadata for one model without building a global catalog."""
    if _is_permission_bootstrap_model_lazy(model_cls):
        return PermissionShape(
            model_cls=model_cls,
            scheme=None,
            scheme_factory=None,
            visibility_fields=(),
        )
    try:
        scheme = get_permission_scheme(model_cls)
    except RuntimeError:
        return PermissionShape(
            model_cls=model_cls,
            scheme=None,
            scheme_factory=None,
            visibility_fields=(),
        )
    visibility_fields = tuple(get_visibility_fields(model_cls))
    return PermissionShape(
        model_cls=model_cls,
        scheme=scheme,
        scheme_factory=type(scheme) if scheme is not None else None,
        visibility_fields=visibility_fields,
    )


@pure_lazy
def _permission_context_for_shape(
    txn: object,
    permission_shape: PermissionShape,
) -> tuple[type[ResolvedSessionContext] | None, ObjectServerRef[ResolvedSessionContext] | None]:
    scheme = permission_shape.scheme
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return None, None
    context_ref = getattr(txn, "_permission_session_context_ref", None)
    if context_ref is None:
        return None, None
    if not isinstance(context_ref, ObjectServerRef):
        msg = "Permission context authority must be an ObjectServerRef"
        raise TypeError(msg)
    context_type = context_ref.value_type
    if not isinstance(context_type, type) or not issubclass(context_type, ResolvedSessionContext):
        msg = "Permission context authority must declare a ResolvedSessionContext model type"
        raise TypeError(msg)
    return context_type, context_ref


@pure_lazy
def permission_planning_input_for_model(
    txn: object,
    model_cls: type[DatabaseObjectRow],
) -> PermissionPlanningInput:
    """Resolve permission facts, using the transaction catalog only when needed."""
    permission_shape = _permission_shape_without_catalog(model_cls)
    if permission_shape is not None:
        context_type, context_ref = _permission_context_for_shape(txn, permission_shape)
        return PermissionPlanningInput(
            model_cls=model_cls,
            permission_shape=permission_shape,
            session_id_source=_require_session_id_source(cast("WriteTransactionLazyMixin", txn)),
            provider_authority_resolved=model_cls in getattr(txn, "_provider_authority_models", ()),
            context_type=context_type,
            context_ref=context_ref,
        )
    planning_catalog = getattr(txn, "planning_catalog", None)
    if planning_catalog is None:
        msg = "Lazy write permission planning requires a transaction planning_catalog snapshot."
        raise RuntimeError(msg)
    permission_shape = planning_catalog.permission_for_model(model_cls)
    if permission_shape is None:
        permission_shape = PermissionShape(
            model_cls=model_cls,
            scheme=None,
            scheme_factory=None,
            visibility_fields=(),
        )
    context_type, context_ref = _permission_context_for_shape(txn, permission_shape)
    return PermissionPlanningInput(
        model_cls=model_cls,
        permission_shape=permission_shape,
        session_id_source=_require_session_id_source(cast("WriteTransactionLazyMixin", txn)),
        provider_authority_resolved=model_cls in getattr(txn, "_provider_authority_models", ()),
        context_type=context_type,
        context_ref=context_ref,
    )


@pure_lazy
def _session_context_lazy_for_write(
    txn: LazyReadTransaction,
    session_id: SessionIdSource,
) -> LazyResult[ResolvedSessionContext]:
    if _in_lazy_context() or _supports_serverplan_permission_intents(txn):
        return resolve_session_user_context_lazy(session_id, txn)
    msg = "Lazy session context requested without active lazy context or plan-intent support."
    raise RuntimeError(msg)


@pure_lazy
def _literal_lazy_result_value[T](
    source: LazyResult[T],
    *,
    context: str,
    _type_marker: type[T] | None = None,
) -> T:
    del _type_marker
    shape = inspect_server_value_shape_for_planning(source, site=context)
    if shape.symbolic_ref_id is not None:
        msg = f"{context} requires a literal LazyResult, got ref {shape.symbolic_ref_id!r}"
        raise RuntimeError(msg)
    if shape.has_literal_value:
        return cast(T, shape.literal_value)
    if source._state is LazyState.ERROR:
        assert source._error is not None
        raise source._error
    msg = f"{context} requires a concrete literal LazyResult"
    raise RuntimeError(msg)


@pure_lazy
def _ensure_permission_context_plan_ref(
    txn: WriteTransactionLazyMixin,
    permission_context: LazyResult[object],
) -> ServerPlanRefId:
    shape = inspect_server_value_shape_for_planning(
        permission_context,
        site="Permission context lazy result",
    )
    if shape.symbolic_ref_id is not None:
        return ServerPlanRefId(shape.symbolic_ref_id)

    plan = txn._get_transaction_plan_lazy()
    ref_id = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        ReturnValueStep(
            ref_id,
            _literal_lazy_result_value(
                permission_context,
                context="permission context plan ref",
            ),
        ),
    )
    return ref_id


@pure_lazy
def _resolve_scheme_permission_context_ref(
    txn: WriteTransactionLazyMixin,
    scheme: PermissionScheme[object],
    session_id_source: SessionIdSource,
) -> ServerPlanRefId:
    permission_context = scheme.resolve_context_lazy(
        cast(SessionId, session_id_source),
        cast("LazyReadTransaction", txn),
    )
    return _ensure_permission_context_plan_ref(txn, permission_context)


@pure_lazy
def _require_session_id_source(
    txn: WriteTransactionLazyMixin,
) -> SessionIdSource:
    session_id_source_fn = getattr(txn, "_session_id_source_lazy", None)
    session_id_source = session_id_source_fn() if callable(session_id_source_fn) else getattr(txn, "_session_id", None)
    # ``LazySessionSqlSource`` is accepted alongside the value and reference
    # shapes because a write under ``authenticated_session_lazy`` has no other
    # shape to offer. Rejecting it here is what the write path did until this
    # ladder tried it, and the refusal was indistinguishable from "the caller
    # forgot to set a session" -- the same message for a plan whose session is
    # perfectly well specified, only as a query.
    if isinstance(session_id_source, SessionId | LazyResult | ScalarServerRef | LazySessionSqlSource):
        return session_id_source
    msg = "Lazy write permission checks require an explicit session_id."
    raise RuntimeError(msg)


@pure_lazy
def _enqueue_permission_step[T](
    txn: ReadTransactionLazyMixin,
    step: ServerPlanStep[T],
) -> LazyResult[T]:
    if _in_lazy_context() or _supports_serverplan_permission_intents(txn):
        return txn._add_intent(step)
    msg = "Lazy permission step requires active lazy context or plan-intent support."
    raise RuntimeError(msg)


@pure_lazy
def assert_permission_allowed_lazy(
    txn: ReadTransactionLazyMixin,
    allowed: LazyResult[bool],
    error: Exception,
) -> LazyResult[None]:
    """Enqueue a permission guard for a lazy boolean predicate."""
    shape = inspect_server_value_shape_for_planning(
        allowed,
        site="Permission assertion predicate",
    )
    if shape.symbolic_ref_id is None:
        if allowed._state is LazyState.PENDING:
            msg = "Permission assertion requires an explicit ServerPlan predicate ref"
            raise RuntimeError(msg)
        if _literal_lazy_result_value(allowed, context="permission assertion"):
            return LazyResult.of(None)
        raise error

    plan = txn._get_transaction_plan_lazy()
    predicate_ref = ServerRefs.from_ref_id(shape.symbolic_ref_id, variant="scalar", type_hint=bool)
    step = AssertStep(
        ref_id=ServerPlanRefId(plan._next_ref()),
        predicate_ref=predicate_ref,
        error=error,
    )
    return _enqueue_permission_step(txn, step)


def run_table_write_permission_check_after_session_context(
    txn: ReadTransaction | WriteTransaction,
    model_cls: type[DatabaseObjectRow],
    scheme: object,
    session_id: SessionId,
    resolved: ResolvedSessionContext,
) -> None:
    """Run table-level write permission using a materialized session context (executor/runtime)."""
    if isinstance(scheme, GraphInheritedPermissionScheme):
        # Graph-inherited table writes are allowed; object-level checks enforce graph access.
        return
    if not isinstance(scheme, PermissionScheme):
        msg = f"Unsupported runtime table-write permission scheme: {type(scheme).__name__}"
        raise TypeError(msg)
    context = _build_table_write_permission_context(
        txn,
        scheme,
        session_id,
        resolved,
    )
    dispatch_write_permission_operation_with_scheme(
        RuntimeWritePermissionSpec(
            model_cls=model_cls,
            operation="table_write",
            permission_scheme_cls=type(scheme),
        ),
        scheme,
        context,
    )


def run_object_write_permission_check_after_session_context(
    txn: ReadTransaction | WriteTransaction,
    model_cls: type[DatabaseObjectRow],
    obj: DatabaseObjectRow,
    session_id: SessionId,
    resolved: ResolvedSessionContext,
) -> None:
    """Run object-level write permission using a materialized session context."""
    del txn, session_id
    scheme = _get_runtime_object_level_permission_scheme(model_cls)
    if scheme is None:
        return
    context = _build_object_write_permission_context(scheme, resolved)
    dispatch_write_permission_operation_with_scheme(
        RuntimeWritePermissionSpec(
            model_cls=model_cls,
            operation="object_write",
            permission_scheme_cls=type(scheme),
        ),
        scheme,
        context,
        instance=obj,
    )


@pure_lazy
def get_cached_resolved_session_context(
    session_id: SessionId,
    txn: ReadTransaction,
) -> tuple[bool, ResolvedSessionContext | None]:
    """Return a prevalidated session context when one is available without I/O.

    ``@pure_lazy`` states what the docstring already claimed: reachable from
    lazy permission compilation, and reading attributes the transaction set
    during validation rather than going to the database.
    """
    session_type = getattr(txn, "_nera_validated_session_type", None)
    if session_type not in {"system", "user"}:
        return False, None
    raw_user_id = getattr(txn, "_nera_validated_session_user_id", None)
    user_id = None if raw_user_id is None else UserId(str(raw_user_id))
    has_system_authority = _has_validated_system_authority(txn)
    is_system_session = session_id.is_schema_session() or has_system_authority
    return True, ResolvedSessionContext(
        session_id=session_id,
        user_id=user_id,
        effective_user_id=None,
        session_type="system" if is_system_session else "user",
        is_system_session=is_system_session,
    )


@pure_lazy
def get_cached_validated_session_user_id(
    session_id: SessionId,
    txn: ReadTransaction,
) -> tuple[bool, UserId | None]:
    """Return a cached validated user id when available without I/O.

    ``@pure_lazy`` for the same reason as the context reader it delegates to.
    """
    cached, context = get_cached_resolved_session_context(session_id, txn)
    if not cached or context is None:
        return False, None
    return True, context.user_id


def check_write_permission(
    model_cls: type[DatabaseObjectRow],
    session_id: str,
    txn: ReadTransaction,
) -> None:
    """Compatibility boundary for eager no-I/O fallback paths."""
    _check_write_permission(model_cls, SessionId(session_id), txn)


@pure_lazy
def _has_lazy_read_semantics(txn: object) -> bool:
    return isinstance(txn, ReadTransaction) or hasattr(txn, "base_read_transaction")


@pure_lazy
def _has_validated_system_authority(
    txn: object,
    model_cls: type[DatabaseObjectRow] | None = None,
) -> bool:
    """Return whether admission bound non-transferable authority to this transaction."""
    from l1300_session.system_authority_service import ValidatedSystemAuthority

    authority = getattr(txn, "_validated_system_authority", None)
    if isinstance(authority, ValidatedSystemAuthority) or getattr(txn, "_system_authority_planning_only", False) is True:
        return True
    if model_cls is None or getattr(txn, "_capability_lifecycle_admin_authority", None) is None:
        return False
    return model_cls.__module__ == "l6500_evidence.capability_models" and model_cls.__name__ in {
        "CapabilitySecurityEvent",
        "CapabilityTokenFamily",
        "CapabilityTokenIssued",
        "CapabilityTokenRevocation",
        "CapabilityTokenUsage",
    }


@pure_lazy
def check_write_permission_lazy(
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
) -> LazyResult[None]:
    model_cls = permission_input.model_cls
    if _is_permission_bootstrap_model_lazy(model_cls) or _has_validated_system_authority(txn, model_cls):
        return LazyResult.of(None)
    if not _has_lazy_read_semantics(txn):
        msg = "Lazy write permission checks require a transaction with read semantics."
        raise TypeError(msg)
    scheme = permission_input.permission_shape.scheme
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if literal_session_id is not None and is_system_or_schema_session(
        session_id_to_str(literal_session_id),
    ):
        return LazyResult.of(None)
    if not _supports_serverplan_permission_intents(txn):
        msg = "Lazy write permission checks require lazy-plan transaction support."
        raise RuntimeError(msg)
    if scheme is None:
        return LazyResult.of(None)
    if not isinstance(scheme, PermissionScheme):
        msg = f"Unsupported lazy table-write permission scheme: {type(scheme).__name__}"
        raise TypeError(msg)
    if isinstance(scheme, GraphInheritedPermissionScheme):
        return LazyResult.of(None)
    decision = scheme.get_table_write_permission_decision(model_cls, literal_session_id)
    if decision.allowed:
        return LazyResult.of(None)
    context_ref = (
        _bound_permission_context_ref(
            permission_input,
            site="Table write permission context",
        )
        if permission_input.context_ref is not None
        else _resolve_scheme_permission_context_ref(
            txn,
            cast("PermissionScheme[object]", scheme),
            session_id_source,
        )
    )
    return _queue_table_write_permission_guard_intent(
        txn,
        context_ref,
        model_cls,
    )


@pure_lazy
def upsert_requires_action_authority(permission_input: PermissionPlanningInput) -> bool:
    """Select guarded SQL rowset compilation for actors subject to write policies."""
    if object_write_permission_bypassed_by_session(permission_input):
        return False
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme):
        raise PermissionCompilationError("Upsert requires a registered permission scheme")
    return any(scheme.get_query_permission_plan(permission_input.model_cls, action=action).filter_rows for action in ("insert", "update"))


@pure_lazy
def check_insert_permission_lazy(
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
    instance: LazyResult[DatabaseObjectRow | None],
    source_ref: ServerPlanRefId | None = None,
    source_is_sequence: bool = False,
) -> LazyResult[None]:
    """Check the proposed row using its insert policy, not legacy write flags."""
    from impl.common.l2070_server_plan.steps.insert_permission import InsertPermissionAssertionStep
    from l1000_schema.schema_def import DatabaseObjectRow

    scheme = permission_input.permission_shape.scheme
    proposed_row = _literal_lazy_result_value(
        instance,
        context="check_insert_permission_lazy instance",
    )
    assert proposed_row is None or isinstance(proposed_row, permission_input.model_cls)
    if proposed_row is not None and isinstance(scheme, PermissionScheme) and scheme.requires_validated_insert_models():
        permission_input.model_cls.model_validate(proposed_row.model_dump(mode="python"))
    if (
        object_write_permission_bypassed_by_session(permission_input)
        or _is_permission_bootstrap_model_lazy(permission_input.model_cls)
        or _has_validated_system_authority(txn, permission_input.model_cls)
    ):
        return LazyResult.of(None)
    if not isinstance(scheme, PermissionScheme):
        raise PermissionCompilationError("Insert authorization requires a registered permission scheme")
    policy = scheme.get_query_permission_plan(permission_input.model_cls, action="insert")
    if not policy.filter_rows:
        return LazyResult.of(None)
    assert proposed_row is None or isinstance(proposed_row, DatabaseObjectRow)
    if not _has_lazy_read_semantics(txn) or not _supports_serverplan_permission_intents(txn):
        raise RuntimeError("Insert authorization requires a transaction-backed lazy plan")
    plan = txn._get_transaction_plan_lazy()
    permission_context_ref = (
        _bound_permission_context_ref(
            permission_input,
            site="Insert permission context",
        )
        if permission_input.context_ref is not None
        else None
    )
    return _enqueue_permission_step(
        txn,
        InsertPermissionAssertionStep(
            plan._next_ref(),
            permission_input.model_cls,
            proposed_row,
            source_ref=source_ref,
            source_is_sequence=source_is_sequence,
            permission_context_ref=permission_context_ref,
            permission_context_type=permission_input.context_type,
        ),
    )


@pure_lazy
def check_object_write_permission_lazy[T: DatabaseObjectRow](
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
    instance: T,
) -> LazyResult[T]:
    model_cls = cast("type[T]", permission_input.model_cls)
    scheme = _get_object_level_permission_scheme(permission_input)
    if scheme is None or _has_validated_system_authority(txn, model_cls):
        return LazyResult.of(instance)
    if not _has_lazy_read_semantics(txn):
        msg = "Lazy object write permission checks require a transaction with read semantics."
        raise TypeError(msg)
    if not _supports_serverplan_permission_intents(txn):
        msg = "Lazy object write permission checks require lazy-plan transaction support."
        raise RuntimeError(msg)
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if (
        literal_session_id is not None
        and is_system_or_schema_session(session_id_to_str(literal_session_id))
        and not scheme.get_query_permission_plan(model_cls, action="write").filter_reserved_sessions
    ):
        return LazyResult.of(instance)
    permission_context_ref = get_object_write_permission_context_ref(txn, permission_input)
    permission_context_type = permission_input.context_type
    if not isinstance(permission_context_ref, ServerPlanRefId):
        msg = "Lazy object write permission checks require a branded deferred permission context ref."
        raise RuntimeError(msg)
    plan = txn._get_transaction_plan_lazy()
    step = lazy_runtime.ReturnLiteralAfterObjectWritePermissionCheckStep(
        ref_id=plan._next_ref(),
        instance=instance,
        permission_context_ref=permission_context_ref,
        permission_context_type=permission_context_type,
        model_cls=model_cls,
    )
    return cast("LazyResult[T]", _enqueue_permission_step(txn, cast("ServerPlanStep[DatabaseObjectRow]", step)))


def _build_table_write_permission_context(
    txn: ReadTransaction,
    scheme: object,
    session_id: SessionId,
    session_context: ResolvedSessionContext,
) -> object:
    from l4000_permissions.multi_field_ownership_scheme import (
        MultiFieldOwnershipContext,
        MultiFieldOwnershipScheme,
    )
    from l4000_permissions.rbac_scheme import RBACContext, RBACScheme
    from l4000_permissions.self_ownership_scheme import (
        SelfOwnershipContext,
        SelfOwnershipScheme,
    )

    if isinstance(scheme, PermissionScheme):
        runtime_context = scheme.build_runtime_table_write_permission_context(
            txn=txn,
            session_id=session_id,
            session_context=session_context,
        )
        if runtime_context is not None:
            return runtime_context

    context: object
    if isinstance(scheme, SystemOnlyScheme):
        context = SystemPermissionContext(session_id, session_context)
    elif isinstance(scheme, NoSecurityScheme):
        context = NoSecurityContext(
            session_context.user_id,
            is_authenticated=(
                session_context.is_system_session or session_context.user_id is not None or session_context.effective_user_id is not None
            ),
            session_context=session_context,
        )
    elif isinstance(scheme, OwnershipScheme):
        context = OwnershipContext(session_context)
    elif isinstance(scheme, SelfOwnershipScheme):
        context = SelfOwnershipContext(session_context)
    elif isinstance(scheme, OwnerSharesScheme):
        context = OwnerSharesContext.from_session_context(session_context)
    elif isinstance(scheme, OwnerRoleSharesScheme):
        role_permissions = frozenset({"*"}) if session_context.is_system_session else frozenset()
        context = OwnerRoleSharesContext(session_context, role_permissions)
    elif isinstance(scheme, QueueMessagePermissionScheme):
        context = QueuePermissionContext.from_session_context(
            session_id,
            session_context,
        )
    elif isinstance(scheme, MultiFieldOwnershipScheme):
        context = MultiFieldOwnershipContext(session_context)
    elif isinstance(scheme, AssignedRoleScheme):
        context = AssignedRoleContext(session_context)
    elif isinstance(scheme, AssignedPermissionScheme):
        context = AssignedPermissionContext(session_context)
    elif isinstance(scheme, RBACScheme):
        rbac_permissions: set[str] = {"*"} if session_context.is_system_session else set()
        context = RBACContext(session_context.user_id, rbac_permissions)
    elif isinstance(scheme, GraphInheritedPermissionScheme):
        context = GraphInheritedPermissionContext(
            session_id,
            session_context,
            getattr(txn, "domain", None),
        )
    else:
        msg = f"Unsupported runtime table-write permission scheme: {type(scheme).__name__}"
        raise TypeError(msg)
    return context


def _build_object_write_permission_context(
    scheme: PermissionScheme[object],
    session_context: ResolvedSessionContext,
) -> object:
    from l4000_permissions.self_ownership_scheme import SelfOwnershipContext, SelfOwnershipScheme

    if isinstance(scheme, OwnershipScheme):
        return OwnershipContext(session_context)
    if isinstance(scheme, SelfOwnershipScheme):
        return SelfOwnershipContext(session_context)
    msg = f"Unsupported runtime object-write permission scheme: {type(scheme).__name__}"
    raise TypeError(msg)


@pure_lazy
def _queue_table_write_permission_guard_intent(
    txn: WriteTransactionLazyMixin,
    permission_context_ref: str | None,
    model_cls: type[DatabaseObjectRow],
) -> LazyResult[None]:
    plan = txn._get_transaction_plan_lazy()
    intent = lazy_runtime.TableWritePermissionGuardIntent(
        ref_id=ServerPlanRefId(plan._next_ref()),
        permission_context_ref=(None if permission_context_ref is None else ServerPlanRefId(permission_context_ref)),
        config=lazy_runtime._TableWritePermissionGuardConfig(
            model_cls=model_cls,
        ),
    )
    return _enqueue_permission_step(txn, intent)


@pure_lazy
def has_object_level_write_permission_scheme(
    permission_input: PermissionPlanningInput,
) -> bool:
    """Return whether writes require object-level permission checks."""
    return _get_object_level_permission_scheme(permission_input) is not None


@pure_lazy
def has_object_level_insert_permission_scheme(
    permission_input: PermissionPlanningInput,
) -> bool:
    """Use insert admission, not future-row write metadata, for new rows."""
    scheme = permission_input.permission_shape.scheme
    return isinstance(scheme, PermissionScheme) and _has_object_permission_enforcement(
        scheme,
        permission_input.model_cls,
        action="insert",
    )


@pure_lazy
def is_system_only_permission_input(
    permission_input: PermissionPlanningInput,
) -> bool:
    """Return whether the resolved permission shape is system-only."""
    return isinstance(permission_input.permission_shape.scheme, SystemOnlyScheme)


@pure_lazy
def object_write_permission_bypassed_by_session(
    permission_input: PermissionPlanningInput,
) -> bool:
    """Return whether object write guards are unnecessary for this session."""
    if permission_input.provider_authority_resolved:
        return True
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if literal_session_id is None or not is_system_or_schema_session(session_id_to_str(literal_session_id)):
        return False
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme):
        return True
    return not scheme.get_query_permission_plan(
        permission_input.model_cls,
        action="write",
    ).filter_reserved_sessions


@pure_lazy
def permission_scheme_requires_validated_insert_models(scheme: object) -> bool:
    """Return whether insert proposals require model revalidation."""
    return isinstance(scheme, PermissionScheme) and scheme.requires_validated_insert_models()


def is_system_only_permission_scheme(
    model_cls: type[DatabaseObjectRow],
) -> bool:
    """Return whether the model uses system-only table permissions at runtime."""
    return isinstance(get_permission_scheme(model_cls), SystemOnlyScheme)


@pure_lazy
def _bound_permission_context_ref(
    permission_input: PermissionPlanningInput,
    *,
    site: str,
) -> ServerPlanRefId:
    context_ref = permission_input.context_ref
    if context_ref is None:
        msg = f"{site} requires the bound session context authority"
        raise RuntimeError(msg)
    context_shape = inspect_server_value_shape_for_planning(
        context_ref,
        site=site,
    )
    if context_shape.symbolic_ref_id is None:
        msg = f"{site} must publish a symbolic ref"
        raise RuntimeError(msg)
    return ServerPlanRefId(context_shape.symbolic_ref_id)


@pure_lazy
def get_object_write_permission_context_ref(
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
) -> ServerPlanRefId | None:
    """Return the scheme-context plan ref needed for object-level write guards."""
    scheme = _get_object_level_permission_scheme(permission_input)
    if scheme is None or not _has_lazy_read_semantics(txn):
        return None
    if not _in_lazy_context() and not _supports_serverplan_permission_intents(txn):
        return None
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if (
        literal_session_id is not None
        and is_system_or_schema_session(session_id_to_str(literal_session_id))
        and not scheme.get_query_permission_plan(permission_input.model_cls, action="write").filter_reserved_sessions
    ):
        return None
    if permission_input.context_ref is not None:
        return _bound_permission_context_ref(
            permission_input,
            site="Object write permission context",
        )
    return _resolve_scheme_permission_context_ref(
        txn,
        scheme,
        session_id_source,
    )


@pure_lazy
def _versioned_permission_domain(txn: object) -> type[VersioningDomain] | None:
    try:
        domain = getattr(txn, "domain", None)
    except RuntimeError:
        domain = None
    if domain is None:
        domain = getattr(txn, "_domain", None)
    if domain is None:
        return None
    if isinstance(domain, type) and issubclass(domain, VersioningDomain):
        return domain
    msg = f"Expected VersioningDomain type on transaction, got {type(domain).__name__}"
    raise TypeError(msg)


@pure_lazy
def _uses_sparse_historical_permission_context(txn: object) -> bool:
    revision_id = getattr(txn, "_revision_id", None)
    if revision_id is None:
        try:
            revision_id = getattr(txn, "revision_id", None)
        except RuntimeError:
            revision_id = None
    if revision_id is None:
        return False
    from l7000_versioned_schema.branch_materialization import BranchTipMaterialization

    return getattr(txn, "_branch_tip_materialization", None) is not BranchTipMaterialization.MATERIALIZED


@pure_lazy
def _permission_version_anchor_for_txn(
    txn: object,
) -> PermissionVersionAnchor | None:
    domain = _versioned_permission_domain(txn)
    if domain is None:
        return None
    return permission_version_anchor_from_txn(domain, txn)


@pure_lazy
def compile_permission_expression(
    model_cls: type[DatabaseObjectRow],
    session_id: object,
    *,
    txn: object,
    action: str = "read",
) -> SqlRenderable | None:
    """Compile the read filter for a model/session pair."""
    if _is_permission_bootstrap_model(model_cls) or _has_validated_system_authority(txn, model_cls):
        return None
    session_str = session_id_to_str(session_id)
    scheme = get_permission_scheme(model_cls)
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return None
    if not isinstance(session_id, SessionId | ScalarServerRef):
        msg = (
            "Permission compilation requires a literal or scalar-ref session identity; "
            f"got {type(session_id).__name__} for {type(scheme).__name__}"
        )
        raise PermissionCompilationError(msg)
    typed_session_id = session_id
    if isinstance(typed_session_id, ScalarServerRef):
        msg = "compile_permission_expression() requires a literal SessionId"
        raise PermissionCompilationError(msg)
    if is_system_or_schema_session(session_str):
        scheme = get_permission_scheme(model_cls)
        if isinstance(scheme, OwnerSharesScheme):
            if not isinstance(txn, ReadTransaction):
                msg = f"compile_permission_expression() expected ReadTransaction, got {type(txn).__name__}"
                raise TypeError(msg)
            return lazy_runtime.compile_permission_where_for_scheme(
                model_cls,
                scheme,
                typed_session_id,
                table_alias=get_table_name(model_cls),
                action=action,
                domain=_versioned_permission_domain(txn),
                version_anchor=_permission_version_anchor_for_txn(txn),
            )
        return None

    if txn is not None:
        if not isinstance(txn, ReadTransaction):
            msg = f"compile_permission_expression() expected ReadTransaction, got {type(txn).__name__}"
            raise TypeError(msg)
        alias = get_table_name(model_cls)
        scheme = get_permission_scheme(model_cls)
        if isinstance(scheme, GraphInheritedPermissionScheme):
            return lazy_runtime.compile_permission_where_for_scheme(
                model_cls,
                scheme,
                typed_session_id,
                table_alias=alias,
                action=action,
                version_anchor=_permission_version_anchor_for_txn(txn),
            )
        # Keep lazy permission compilation fail-closed. If the dedicated
        # compiler cannot lower a permission expression, do not fall back to
        # the generic Expression compiler, which can leak raw permission helper
        # functions like GRAPH_INHERITED_CHECK() into SQL.
        scheme = get_permission_scheme(model_cls)
        if scheme is None:
            return None
        return lazy_runtime.compile_permission_where_for_scheme(
            model_cls,
            scheme,
            typed_session_id,
            table_alias=alias,
            action=action,
            domain=_versioned_permission_domain(txn),
            version_anchor=_permission_version_anchor_for_txn(txn),
        )

    scheme = get_permission_scheme(model_cls)
    if scheme is None:
        return None
    msg = (
        "compile_permission_expression() requires a transaction-backed permission compiler; "
        "refusing to lower permission expressions through the generic expression compiler"
    )
    raise PermissionCompilationError(msg)


@pure_lazy
def _compile_permission_from_bound_context(
    permission_input: PermissionPlanningInput,
    scheme: PermissionScheme[Any, Any, Any, Any],
    *,
    txn: object,
    action: str,
    table_alias: str,
) -> SqlRenderable:
    context_type = permission_input.context_type
    context_ref = permission_input.context_ref
    if context_type is None or context_ref is None:
        msg = "Permission compilation requires the transaction-bound session context authority"
        raise PermissionCompilationError(msg)
    context_shape = inspect_server_value_shape_for_planning(
        context_ref,
        site="Permission expression context",
    )
    if context_shape.symbolic_ref_id is None:
        msg = "Permission expression context must publish a symbolic ref"
        raise PermissionCompilationError(msg)
    return lazy_runtime.compile_permission_where_for_scheme_with_context_sql(
        permission_input.model_cls,
        scheme,
        context_type,
        context_shape.symbolic_ref_id,
        table_alias,
        action=action,
        domain=_versioned_permission_domain(txn),
        version_anchor=_permission_version_anchor_for_txn(txn),
    )


@pure_lazy
def compile_permission_expression_from_input(
    permission_input: PermissionPlanningInput,
    *,
    txn: object,
    action: str = "read",
) -> SqlRenderable | None:
    """Compile a permission expression from resolved planning metadata."""
    model_cls = permission_input.model_cls
    if _is_permission_bootstrap_model(model_cls) or _has_validated_system_authority(txn, model_cls):
        return None
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return None
    literal_session_id = _literal_session_id_or_none(
        cast("SessionIdSource", permission_input.session_id_source),
    )
    if (
        permission_input.context_ref is None
        and literal_session_id is not None
        and is_system_or_schema_session(session_id_to_str(literal_session_id))
        and not scheme.get_query_permission_plan(model_cls, action=action).filter_reserved_sessions
    ):
        return None
    if permission_input.context_ref is not None:
        if not _has_lazy_read_semantics(txn):
            msg = f"compile_permission_expression_from_input() expected ReadTransaction, got {type(txn).__name__}"
            raise TypeError(msg)
        return _compile_permission_from_bound_context(
            permission_input,
            scheme,
            txn=txn,
            action=action,
            table_alias=str(get_table_name(model_cls)),
        )

    session_id = permission_input.session_id_source
    session_str = session_id_to_str(session_id)
    typed_session_id = session_id if isinstance(session_id, SessionId | ScalarServerRef) else SessionId(session_str)
    if isinstance(typed_session_id, ScalarServerRef):
        msg = "compile_permission_expression_from_input() requires a literal SessionId"
        raise PermissionCompilationError(msg)
    if is_system_or_schema_session(session_str):
        if isinstance(scheme, OwnerSharesScheme):
            if not _has_lazy_read_semantics(txn):
                msg = f"compile_permission_expression_from_input() expected ReadTransaction, got {type(txn).__name__}"
                raise TypeError(msg)
            return lazy_runtime.compile_permission_where_for_scheme(
                model_cls,
                scheme,
                typed_session_id,
                table_alias=get_table_name(model_cls),
                action=action,
                version_anchor=_permission_version_anchor_for_txn(txn),
            )
        return None

    if not _has_lazy_read_semantics(txn):
        msg = f"compile_permission_expression_from_input() expected ReadTransaction, got {type(txn).__name__}"
        raise TypeError(msg)
    return lazy_runtime.compile_permission_where_for_scheme(
        model_cls,
        scheme,
        typed_session_id,
        table_alias=get_table_name(model_cls),
        action=action,
        version_anchor=_permission_version_anchor_for_txn(txn),
        user_id=_validated_session_user_id_or_none(typed_session_id, txn),
    )


@pure_lazy
def _validated_session_user_id_or_none(
    session_id: SessionId,
    txn: object,
) -> UserId | None:
    """Return the session's user if this transaction already validated it.

    Only a *validated* result counts. The distinction matters: a value read
    from somewhere the session was merely mentioned would be a permission
    decision made on unchecked input, which is the one thing a permission
    predicate may not be built from.

    Marked ``@pure_lazy`` because it is reached from permission compilation,
    which is a lazy call chain, and it does no I/O -- it reads a cache the
    transaction has already populated, returning ``None`` when it has not. The
    marker distinguishes that from the thing the rule is looking for, which is
    an eager lookup hiding behind a lazy caller.
    """
    if not isinstance(txn, ReadTransaction):
        return None
    cached, user_id = get_cached_validated_session_user_id(session_id, txn)
    return user_id if cached else None


def permission_filter_defers_the_session_user(
    permission_input: PermissionPlanningInput,
    *,
    txn: object,
    action: str = "read",
) -> bool:
    """Return whether the filter just built still has to look the user up.

    True means the predicate contains ``SELECT user_id FROM sys_sessions ...``
    because nothing here knew the answer yet, and that a later phase which does
    know it may rebind the predicate rather than let the database repeat the
    work. False means either that no user is involved or that one was bound, and
    in both cases the predicate is final.

    Deliberately a separate question from compiling the filter, rather than a
    second return value: the answer is about what a *later* phase is allowed to
    do, and only the plan-backed caller has any use for it.
    """
    model_cls = permission_input.model_cls
    if _is_permission_bootstrap_model(model_cls):
        return False
    if permission_input.context_ref is not None:
        return False
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return False
    session_id = permission_input.session_id_source
    session_str = session_id_to_str(session_id)
    if is_system_or_schema_session(session_str):
        return False
    if not isinstance(session_id, SessionId):
        return lazy_runtime.scheme_policy_reads_the_session_user(
            model_cls,
            scheme,
            action=action,
        )
    if _validated_session_user_id_or_none(session_id, txn) is not None:
        return False
    return lazy_runtime.scheme_policy_reads_the_session_user(model_cls, scheme, action=action)


def get_column_masking_info(
    model_cls: type[DatabaseObjectRow],
    session_id: object,
) -> tuple[str, list[str]] | None:
    """Return any owner-based column masking metadata for lazy reads."""
    session_str = session_id_to_str(session_id)
    if _is_permission_bootstrap_model(model_cls) or is_system_or_schema_session(session_str):
        return None

    scheme = get_permission_scheme(model_cls)
    if (
        scheme is None
        or not getattr(scheme, "supports_column_visibility", False)
        or not getattr(scheme, "_column_filter_for_others", False)
    ):
        return None

    owner_field = getattr(scheme, "_owner_field", "sys_id")
    infra_fields = {
        "sys_id",
        "created_at",
        "updated_at",
        "type_id",
        "revision_id",
        "staged_commit_id",
        "deleted",
    }
    private_columns: list[str] = []
    for field_name, field_info in model_cls.model_fields.items():
        if field_name == owner_field or field_name in infra_fields:
            continue
        if get_field_visibility(model_cls, DynamicFieldName(field_name)) == ColumnVisibility.PUBLIC:
            continue
        ann = field_info.annotation
        if ann is not None and is_optional_type(ann):
            private_columns.append(field_name)
            continue
        msg = (
            f"{model_cls.__name__}.{field_name} is private but non-nullable; "
            "SelfOwnership column masking can only hide nullable private fields. "
            "Make the field nullable or use strict row filtering for this scheme."
        )
        raise PermissionCompilationError(msg)

    if not private_columns:
        return None
    return (owner_field, private_columns)


