@dataclass(frozen=True, slots=True)
class CompoundCandidateStepFacts:
    """Immutable child topology and basic scheduling facts for one selection pass."""

    compound_children: tuple[ServerPlanStep[Any], ...]
    sql_children: tuple[ServerPlanStep[Any], ...]
    ref_aliases: frozenset[str]
    is_read_only: bool
    execution_role: StepExecutionRole
    step_tags: frozenset[str]


_compound_candidate_fact_cache: ContextVar[dict[int, tuple[ServerPlanStep[Any], CompoundCandidateStepFacts]] | None] = ContextVar(
    "compound_candidate_fact_cache", default=None
)


@contextmanager
def compound_candidate_fact_scope() -> Generator[None]:
    """Reuse exact child facts during one immutable candidate-selection pass."""
    if _compound_candidate_fact_cache.get() is not None:
        yield
        return
    token = _compound_candidate_fact_cache.set({})
    try:
        yield
    finally:
        _compound_candidate_fact_cache.reset(token)


@dataclass(frozen=True, slots=True)
class StableDependencyRejection:
    """First append-monotone rejection in one exact authored run."""

    first_parent_index: int
    run_length: int

    def __post_init__(self: StableDependencyRejection) -> None:
        if not 0 <= self.first_parent_index <= self.run_length:
            msg = f"Invalid stable dependency rejection index {self.first_parent_index}. Use a value from 0 through {self.run_length}."
            raise ValueError(msg)

    def exists(self: StableDependencyRejection) -> bool:
        """Return whether the strategy found a stable rejection."""
        return self.first_parent_index < self.run_length


def _result_label_for_step(step: ServerPlanStep[Any]) -> str:
    return str(step.ref_id)


def _batch_result_alias_labels(step: ServerPlanStep[Any]) -> tuple[str, ...]:
    """Return prior result labels that can satisfy a virtual return-source step."""
    return step.batch_result_alias_labels()


def _ref_aliases[ResultT](step: ServerPlanStep[ResultT]) -> frozenset[str]:
    aliases = {
        step.ref_id,
        *step.additional_batch_binding_ref_ids(),
        *step.additional_sql_binding_ref_ids(),
    }
    result_ref = step.publication_result_ref()
    if result_ref is not None:
        aliases.add(result_ref)
    return frozenset(str(alias) for alias in aliases)


def _exact_ref_aliases[ResultT](step: ServerPlanStep[ResultT]) -> frozenset[str]:
    return frozenset({*_ref_aliases(step), *step.batch_result_labels()})


def _source_tables_for_step(step: ServerPlanStep[Any]) -> frozenset[str] | None:
    tables = step.tables_written() or step.tables_read() or step.provided_staged_sources()
    return tables or None


def _sql_visible_contract(step: ServerPlanStep[Any]) -> CtePublicationContract | None:
    return _cte_publication_contract_for_step(step)


def _sql_visible_columns(step: ServerPlanStep[Any]) -> tuple[str, ...] | None:
    contract = _sql_visible_contract(step)
    if contract is None:
        return None
    columns = contract.columns
    if isinstance(columns, tuple) and columns:
        return columns
    labels = step.batch_result_labels()
    if "__exists" in labels:
        return ("__exists",)
    if "count" in labels:
        return ("count",)
    return None


def _is_compilable_child(child: ServerPlanStep[Any]) -> bool:
    if child.level != 0:
        return False
    return child.execution_role() is StepExecutionRole.SQL


def _is_transport_glue_child(child: ServerPlanStep[Any]) -> bool:
    if child.level == 0 and child.batch_result_alias_labels():
        return True
    if child.level == 0 and child.batch_postprocess_reduction_contract() is not None:
        return True
    if child.level == 0 and child.batch_postprocess_reduction_source_ref() is not None and not child.is_executor_owned_runtime_step():
        return True
    if (
        child.level == 0
        and child.execution_role() is StepExecutionRole.VIRTUAL
        and child.emits_sql_for_accounting() is False
        and child.is_inline_commit_admission()
    ):
        return True
    return (
        child.level == 0
        and child.scheduling_facts().supports_sql_batch_transport
        and child.emits_sql_for_accounting() is False
        and not child.is_executor_owned_runtime_step()
        and (
            child.execution_role()
            in {StepExecutionRole.SQL, StepExecutionRole.APPLY, StepExecutionRole.CONTROL, StepExecutionRole.VIRTUAL}
            or _cte_publication_contract_for_step(child) is not None
            or child.batch_postprocess_reduction_source_ref() is not None
        )
    )


def _is_guaranteed_sql_statement_child(child: ServerPlanStep[Any]) -> bool:
    if not _is_compilable_child(child) or child.emits_sql_for_accounting() is False:
        return False
    tags = child.step_tags()
    return not ("timestamp" in tags and "session" in tags)


def _sql_raw_source_aliases[T](children: tuple[ServerPlanStep[T], ...]) -> frozenset[ServerPlanRefId]:
    """Return aliases produced by in-batch SQL raw-source children."""
    return frozenset(
        ServerPlanRefId(alias)
        for parent in children
        for child in _compound_children(parent)
        if _is_guaranteed_sql_statement_child(child) and row_hydration_raw_payload_source_ref(child) is None
        for alias in child.batch_result_labels()
    )


def _has_sql_raw_source_child(
    source_ref: ServerPlanRefId,
    producer_aliases: frozenset[ServerPlanRefId],
) -> bool:
    """Return whether an SQL child produces the raw-source binding."""
    return source_ref in producer_aliases


def _physical_compound_cte_ref_id(ref_id: ServerPlanRefId) -> ServerPlanRefId:
    ref_text = str(ref_id)
    if len(ref_text.encode("utf-8")) <= 60:
        return ref_id
    digest = hashlib.sha256(ref_text.encode("utf-8")).hexdigest()[:40]
    return ServerPlanRefId(f"cte_{digest}")


def _discard_statement_local_staged_sources(
    ctx: CompilationContext,
    grammar: SqlRenderable,
) -> None:
    """Remove staged-source aliases whose lifetime ends with one SQL statement."""
    local_names: set[str] = set()
    visited: set[int] = set()

    def _collect(value: object) -> None:
        value_id = id(value)
        if value_id in visited:
            return
        visited.add(value_id)
        statement_batch = extract_statement_batch(value)
        if statement_batch is not None and len(statement_batch.statements) > 1:
            for statement in statement_batch.statements:
                _collect(statement)
            return
        split_for_outer_cte = _outer_cte_splitter(value, dialect=ctx.dialect)
        if callable(split_for_outer_cte):
            split_result = split_for_outer_cte()
            assert isinstance(split_result, tuple) and len(split_result) == 2
            definitions, body = split_result
            assert isinstance(definitions, Sequence)
            local_names.update(_cte_definition_name(definition) for definition in definitions)
            for definition in definitions:
                _collect(_cte_definition_query(definition))
            _collect(body)
            return
        if isinstance(value, Mapping):
            children: Iterable[object] = value.values()
        elif isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
            children = value
        else:
            shape_parts = getattr(value, "render_order_shape_parts", None)
            has_explicit_shape = getattr(value, "provides_explicit_render_order_shape", None)
            if callable(shape_parts) and (not callable(has_explicit_shape) or has_explicit_shape()):
                rendered_parts = shape_parts(ctx.dialect)
                assert isinstance(rendered_parts, Iterable)
                children = (part_value for _part_name, part_value in rendered_parts)
            else:
                children = ()
        for child in children:
            _collect(child)

    _collect(grammar)
    if not local_names:
        return
    for mapping in (ctx.staged_source_cte_by_table, ctx.overlay_cte_by_table):
        for table_name, source_name in tuple(mapping.items()):
            if str(source_name) in local_names:
                mapping.pop(table_name, None)


def _publish_sql_visible_child(
    ctx: CompilationContext,
    step: ServerPlanStep[Any],
    grammar: Any,
    *,
    post_write_publication_query: SqlRenderable | None = None,
) -> None:
    physical_ref_id = physical_server_plan_ref_alias(ServerPlanRefId(step.ref_id))
    for staged_table in step.provided_staged_sources():
        ctx.staged_source_cte_by_table.pop(staged_table, None)
        ctx.overlay_cte_by_table.pop(staged_table, None)
    publication_contract = _sql_visible_contract(step)
    publication_source = step.publication_source_ref()
    if publication_source is not None and publication_contract is not None:
        source_binding = ctx.cte_refs.get(str(publication_source))
        if (
            source_binding is not None
            and source_binding.auxiliary_query is not None
            and source_binding.columns == _sql_visible_columns(step)
            and source_binding.column_type_hints == publication_contract.column_type_hints
            and source_binding.relation_role == publication_contract.relation_role
            and source_binding.source_tables == _source_tables_for_step(step)
            and source_binding.scalar_control_kind == publication_contract.scalar_control_kind
            and source_binding.scalar_value_column == publication_contract.scalar_value_column
        ):
            for alias in _ref_aliases(step):
                register_cte_relation_binding(ctx, ServerPlanRefId(alias), source_binding)
            return
    if not step.is_read_only():
        if post_write_publication_query is not None and publication_contract is not None:
            columns = _sql_visible_columns(step)
            if columns is None:
                msg = f"Post-write publication for {step.ref_id!r} has no declared columns."
                raise TypeError(msg)
            binding = CteReference(
                physical_ref_id,
                source_tables=_source_tables_for_step(step),
                columns=columns,
                column_type_hints=publication_contract.column_type_hints,
                relation_role=publication_contract.relation_role,
                scalar_control_kind=publication_contract.scalar_control_kind,
                scalar_value_column=publication_contract.scalar_value_column,
                auxiliary_query=post_write_publication_query,
            )
            for alias in _ref_aliases(step):
                register_cte_relation_binding(ctx, ServerPlanRefId(alias), binding)
            return
        # Write children execute as standalone statements in the compound
        # batch: their RETURNING relation only exists inside that statement,
        # and later statements observe their effects through the base tables
        # or runtime result labels. A count-only result keeps a metadata-only
        # binding so batch reducers can consume its labeled runtime result,
        # but it must never carry the write grammar as an auxiliary CTE.
        if publication_contract is not None and publication_contract.relation_role == "count_only":
            columns = _sql_visible_columns(step)
            if columns is not None:
                runtime_binding = CteReference(
                    ServerPlanRefId(step.ref_id),
                    source_tables=_source_tables_for_step(step),
                    columns=columns,
                    column_type_hints=publication_contract.column_type_hints,
                    relation_role=publication_contract.relation_role,
                    scalar_control_kind=publication_contract.scalar_control_kind,
                    scalar_value_column=publication_contract.scalar_value_column,
                    auxiliary_query=None,
                    scope=CteReferenceScope.RESULT_ONLY,
                )
                for alias in _ref_aliases(step):
                    register_cte_relation_binding(ctx, ServerPlanRefId(alias), runtime_binding)
                return
        for alias in _ref_aliases(step):
            for candidate in (alias, f"{alias}.raw"):
                prior_alias_binding = ctx.cte_refs.get(candidate)
                if prior_alias_binding is not None and prior_alias_binding.ephemeral:
                    retire_cte_binding(ctx, candidate)
        for staged_table in step.provided_staged_sources():
            ctx.pending_staged_source_ctes_by_table.pop(staged_table, None)
        for read_table in step.tables_read():
            overlay_ref = ctx.staged_source_cte_by_table.get(read_table)
            if overlay_ref is not None and overlay_ref.startswith("_compound_ov"):
                ctx.staged_source_cte_by_table.pop(read_table, None)
                ctx.overlay_cte_by_table.pop(read_table, None)
        return
    reduction_source_ref = step.batch_postprocess_reduction_source_ref()
    if reduction_source_ref is not None:
        source_ref = ctx.cte_refs.get(reduction_source_ref)
        if (
            isinstance(source_ref, CteReference)
            and source_ref.columns is not None
            and len(source_ref.columns) == 1
            and source_ref.column_type_hints is not None
        ):
            reduction_binding = CteReference(
                physical_ref_id,
                source_tables=source_ref.source_tables,
                columns=source_ref.columns,
                column_type_hints=source_ref.column_type_hints,
                relation_role=step.cte_relation_role(),
                scalar_control_kind=source_ref.scalar_control_kind,
                scalar_value_column=source_ref.scalar_value_column,
                auxiliary_query=grammar,
            )
            register_cte_relation_binding(ctx, step.ref_id, reduction_binding)
            return
    contract = publication_contract
    columns = None if contract is None else _sql_visible_columns(step)
    if columns is None:
        return
    assert contract is not None
    as_policy_relation = getattr(grammar, "as_policy_dispatch_relation", None)
    if callable(as_policy_relation):
        policy_relation = as_policy_relation()
        if policy_relation is not None:
            grammar = policy_relation
    source_tables = _source_tables_for_step(step)
    # Only read-only grammars are valid CTE bodies; consumers re-attach them
    # as auxiliary WITH definitions inside their own standalone statement.
    cte_ref = CteReference(
        physical_ref_id,
        source_tables=source_tables,
        columns=columns,
        column_type_hints=contract.column_type_hints,
        relation_role=step.cte_relation_role(),
        scalar_control_kind=contract.scalar_control_kind,
        scalar_value_column=contract.scalar_value_column,
        auxiliary_query=grammar,
    )
    for alias in _ref_aliases(step):
        register_cte_relation_binding(ctx, ServerPlanRefId(alias), cte_ref)
    _discard_statement_local_staged_sources(ctx, grammar)
    for staged_table in step.provided_staged_sources():
        ctx.pending_staged_source_ctes_by_table.setdefault(staged_table, []).append(
            str(physical_ref_id),
        )


def _compound_children(step: ServerPlanStep[Any]) -> tuple[ServerPlanStep[Any], ...]:
    if isinstance(step, PhysicalStatementGroup):
        return tuple(child for nested in step.children for child in _compound_children(nested))
    return (step,)


def _sql_children(step: ServerPlanStep[Any]) -> tuple[ServerPlanStep[Any], ...]:
    if isinstance(step, PhysicalStatementGroup):
        return tuple(child for child in step.children if _is_compilable_child(child))
    return (step,) if _is_compilable_child(step) else ()


def _build_compound_candidate_step_facts(step: ServerPlanStep[Any]) -> CompoundCandidateStepFacts:
    return CompoundCandidateStepFacts(
        compound_children=_compound_children(step),
        sql_children=_sql_children(step),
        ref_aliases=_exact_ref_aliases(step),
        is_read_only=step.is_read_only(),
        execution_role=step.execution_role(),
        step_tags=step.step_tags(),
    )


def _compound_candidate_step_facts(step: ServerPlanStep[Any]) -> CompoundCandidateStepFacts:
    cache = _compound_candidate_fact_cache.get()
    if cache is None:
        return _build_compound_candidate_step_facts(step)
    entry = cache.get(id(step))
    if entry is not None and entry[0] is step:
        return entry[1]
    facts = _build_compound_candidate_step_facts(step)
    cache[id(step)] = (step, facts)
    return facts


def _has_tombstone_step(step: ServerPlanStep[Any]) -> bool:
    if step.is_tombstone_operation():
        return True
    return isinstance(step, PhysicalStatementGroup) and any(_has_tombstone_step(child) for child in step.children)


def _has_commit_publish_step(step: ServerPlanStep[Any]) -> bool:
    ref_id = str(step.ref_id)
    if ref_id.startswith("publish") or "_publish" in ref_id:
        return True
    if step.is_commit_publish_step():
        return True
    if isinstance(step, ConditionalStep):
        return any(_has_commit_publish_step(child) for child in (*step.then_plan.steps, *step.else_plan.steps))
    return isinstance(step, PhysicalStatementGroup) and any(_has_commit_publish_step(child) for child in step.children)


def _has_conditional_with_overlapping_writes(step: ServerPlanStep[Any]) -> bool:
    from impl.common.l2070_server_plan.steps._conditional_compile import (
        _branch_has_overlapping_writes,
    )

    if isinstance(step, ConditionalStep):
        return _branch_has_overlapping_writes(step.then_plan.steps) or _branch_has_overlapping_writes(step.else_plan.steps)
    if isinstance(step, PhysicalStatementGroup):
        return any(_has_conditional_with_overlapping_writes(child) for child in step.children)
    return False


def _first_prior_unsafe_parent_index[T](
    steps: tuple[ServerPlanStep[T], ...],
    *,
    repeatable_relation_consumer: Callable[[ServerPlanStep[T]], bool],
    dependency_resolver: Callable[[ServerPlanStep[T]], frozenset[ServerPlanRefId]],
    ordered_dependency_resolver: Callable[[ServerPlanStep[T]], frozenset[ServerPlanRefId]],
) -> int:
    """Return the first unsafe parent index, or the run length when none exists.

    ``CompoundSequenceCodegen`` compiles the full SQLite batch before it runs
    any statement. Thus, one SQL statement cannot consume an executor result
    from an earlier statement in the same batch.
    """

    def _references_prior_alias(
        prior_refs: set[ServerPlanRefId],
        dependency_refs: frozenset[ServerPlanRefId],
    ) -> bool:
        # Each dependency set includes its qualified value and base value.
        # Exact intersection therefore implements both forms of matching.
        return not prior_refs.isdisjoint(dependency_refs)

    raw_source_producer_aliases = _sql_raw_source_aliases(steps)
    unsafe_prior_refs: set[ServerPlanRefId] = set()
    prior_sql_refs: set[ServerPlanRefId] = set()
    uncarryable_prior_sql_refs: set[ServerPlanRefId] = set()
    for parent_index, parent in enumerate(steps):
        for step in _compound_children(parent):
            dependency_refs = frozenset(
                ServerPlanRefId(alias)
                for dependency in dependency_resolver(step)
                for alias in (str(dependency), str(dependency).split(".", 1)[0])
            )
            sql_dependency_refs = frozenset(
                ServerPlanRefId(alias)
                for dependency in ordered_dependency_resolver(step)
                for alias in (str(dependency), str(dependency).split(".", 1)[0])
            )
            raw_source_ref = row_hydration_raw_payload_source_ref(step)
            raw_source_is_in_batch_sql = raw_source_ref is not None and _has_sql_raw_source_child(
                raw_source_ref,
                raw_source_producer_aliases,
            )
            if (
                _references_prior_alias(uncarryable_prior_sql_refs, sql_dependency_refs)
                and not raw_source_is_in_batch_sql
                and not repeatable_relation_consumer(step)
                and not _is_transport_glue_child(step)
            ):
                return parent_index
            if (
                step.execution_role() == StepExecutionRole.VIRTUAL
                and not _is_transport_glue_child(step)
                and _references_prior_alias(prior_sql_refs, dependency_refs)
                and not raw_source_is_in_batch_sql
            ):
                return parent_index
            if (
                not _is_compilable_child(step)
                and step.execution_role() == StepExecutionRole.VIRTUAL
                and not _is_transport_glue_child(step)
            ):
                unsafe_prior_refs.add(ServerPlanRefId(step.ref_id))
                continue
            if _references_prior_alias(unsafe_prior_refs, dependency_refs):
                return parent_index
            if _is_guaranteed_sql_statement_child(step):
                for alias_text in _exact_ref_aliases(step):
                    alias = ServerPlanRefId(alias_text)
                    prior_sql_refs.add(alias)
                    if not step.is_read_only():
                        uncarryable_prior_sql_refs.add(alias)
                if raw_source_ref is not None and raw_source_ref in uncarryable_prior_sql_refs:
                    uncarryable_prior_sql_refs.update(ServerPlanRefId(alias) for alias in _exact_ref_aliases(step))
            elif _is_transport_glue_child(step) and raw_source_ref is not None:
                if raw_source_ref in prior_sql_refs:
                    prior_sql_refs.update(ServerPlanRefId(alias) for alias in _exact_ref_aliases(step))
                    if raw_source_ref in uncarryable_prior_sql_refs:
                        uncarryable_prior_sql_refs.update(ServerPlanRefId(alias) for alias in _exact_ref_aliases(step))
            if not _is_compilable_child(step):
                if _is_transport_glue_child(step) or step.scheduling_facts().supports_ordered_sql_statement_batch:
                    continue
                if step.consumes_executor_visible_dependencies():
                    if _references_prior_alias(unsafe_prior_refs, dependency_refs):
                        return parent_index
                unsafe_prior_refs.add(ServerPlanRefId(step.ref_id))
                continue
    return len(steps)


def _depends_on_prior_unsafe_child(
    steps: Sequence[ServerPlanStep[Any]],
    *,
    repeatable_relation_consumer: Callable[[ServerPlanStep[Any]], bool] | None = None,
    dependency_resolver: Callable[[ServerPlanStep[Any]], frozenset[str]] | None = None,
    ordered_dependency_resolver: Callable[[ServerPlanStep[Any]], frozenset[str]] | None = None,
) -> bool:
    """Return whether a child has an unsafe dependency on a prior child."""
    steps_tuple = tuple(steps)
    relation_is_repeatable = repeatable_relation_consumer or (lambda candidate: candidate.consumes_repeatable_post_write_relations())
    resolve_dependencies = dependency_resolver or frozen_step_dependencies
    resolve_ordered_dependencies = ordered_dependency_resolver or frozen_step_ordered_dependencies
    first_rejection = _first_prior_unsafe_parent_index(
        steps_tuple,
        repeatable_relation_consumer=relation_is_repeatable,
        dependency_resolver=lambda candidate: frozenset(ServerPlanRefId(dependency) for dependency in resolve_dependencies(candidate)),
        ordered_dependency_resolver=lambda candidate: frozenset(
            ServerPlanRefId(dependency) for dependency in resolve_ordered_dependencies(candidate)
        ),
    )
    return first_rejection < len(steps_tuple)


def _compile_to_ir(
    step: ServerPlanStep[Any],
    ctx: CompilationContext,
) -> tuple[SqlStepIR | None, CompiledStep[Any] | SqlStepIR | None]:
    with mutable_grammar_construction():
        compiled = compile_child_for_batch(step, ctx)
    if isinstance(compiled, CompiledStep):
        if compiled.output_shape is None or compiled.result_relation is None or compiled.column_type_hints is None:
            contract = _cte_publication_contract_for_step(step)
            if contract is not None and contract.columns:
                output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                    contract,
                )
                compiled = replace(
                    compiled,
                    output_shape=compiled.output_shape or output_shape,
                    result_relation=compiled.result_relation or result_relation,
                    column_type_hints=compiled.column_type_hints or column_type_hints,
                )
        contract = _cte_publication_contract_for_step(step)
        if contract is not None and not contract.columns:
            compiled = replace(
                compiled,
                output_shape=None,
                result_relation=None,
                column_type_hints=None,
            )
        materialization_source = compiled
        publication_query = compiled.repeatable_sql_publication_query()
        if compiled.grammar is None and compiled.ir is None and publication_query is not None:
            materialization_source = replace(compiled, grammar=publication_query)
        try:
            # Transportable SQL children are embedded into the compound batch,
            # while non-transport steps retain their statement-local definitions.
            materialized = materialization_source.materialize_ir(
                exclude_auxiliary_ctes=step.supports_sql_batch_transport(),
            )
        except ValueError as exc:
            msg = f"{type(step).__name__}({step.ref_id}) failed SQL IR materialization: {exc}"
            raise ValueError(msg) from exc
        return (materialized if isinstance(materialized, SqlStepIR) else None), compiled
    if isinstance(compiled, SqlStepIR):
        return compiled, compiled
    return None, None


type _CteDefinitionLike = SqlCteDefinition | SqlWithCteDefinition | tuple[str, SqlRenderable]


def _cte_definition_name(defn: _CteDefinitionLike) -> str:
    raw_name = str(defn[0]) if isinstance(defn, tuple) else str(defn.name)
    return raw_name.split("(", 1)[0].strip('"`')


def _cte_definition_query(defn: _CteDefinitionLike) -> SqlRenderable:
    if isinstance(defn, tuple):
        return defn[1]
    return defn.query


def _cte_definition_tuple(defn: _CteDefinitionLike) -> tuple[str, SqlRenderable]:
    return _cte_definition_name(defn), _cte_definition_query(defn)


def _materialized_cte_definition(
    definition: _CteDefinitionLike,
    *,
    query: SqlRenderable | None = None,
    recursive: bool = False,
) -> SqlCteDefinition:
    effective_query = query if query is not None else _cte_definition_query(definition)
    if isinstance(definition, (SqlCteDefinition, SqlWithCteDefinition)):
        return replace(
            tree_cte_definition(definition),
            query=effective_query,
            materialized=True,
            recursive=definition.recursive or recursive,
        )
    return SqlCteDefinition(
        _cte_definition_name(definition),
        effective_query,
        materialized=True,
        recursive=recursive or _grammar_needs_recursive_with(effective_query),
    )


def _copy_carried_definition(
    name: str,
    query: SqlRenderable,
    carried_defs: Mapping[str, SqlRenderable],
) -> SqlCteDefinition:
    original = carried_defs.get(name)
    if isinstance(original, SqlCteDefinition):
        return replace(original, materialized=True)
    return SqlCteDefinition(
        name,
        query,
        materialized=True,
        recursive=_grammar_needs_recursive_with(query),
    )


def _grammar_needs_recursive_with(grammar: SqlRenderable) -> bool:
    with_clause = getattr(grammar, "_with_clause", None)
    statement_local_with = getattr(grammar, "_with", None)
    return bool(
        getattr(grammar, "_recursive", False)
        or getattr(grammar, "recursive", False)
        or getattr(grammar, "requires_recursive_cte_prefix", False)
        or getattr(with_clause, "_recursive", False)
        or getattr(statement_local_with, "_recursive", False)
    )


def _query_requires_recursive_cte_prefix(query: SqlRenderable) -> bool:
    if isinstance(query, SqlCte):
        return query._recursive
    if isinstance(query, (SqlInsertWithCte, SqlSelectWithCte)):
        return query._with_clause._recursive
    return _grammar_needs_recursive_with(query)


def _cte_definitions_need_recursive(definitions: Sequence[SqlCteDefinition]) -> bool:
    return any(
        bool(getattr(definition, "recursive", False)) or _grammar_needs_recursive_with(_cte_definition_query(definition))
        for definition in definitions
    )


@read_only_render_memo()
def _cte_definitions_have_self_reference(
    definitions: Sequence[SqlCteDefinition],
    *,
    dialect: Any,
) -> bool:
    return any(
        _cte_alias_reference_state(
            _render_cte_reference_sql(_cte_definition_query(definition), dialect),
            _cte_definition_name(definition),
            dialect.identifier_quote,
        )[0]
        for definition in definitions
    )


def _with_cte_definition(defn: SqlCteDefinition) -> SqlWithCteDefinition:
    return SqlWithCteDefinition(
        _cte_definition_name(defn),
        _cte_definition_query(defn),
        materialized=True,
        recursive=defn.recursive,
    )


@dataclass
class _CteReferenceCache:
    renders: dict[tuple[int, int, tuple[object, ...]], tuple[SqlRenderable, object, str]]
    aliases: dict[tuple[int, str], tuple[str, tuple[bool, bool]]]
    dependencies: dict[tuple[int, frozenset[str], str], tuple[str, frozenset[str]]]


_cte_reference_render_cache: ContextVar[_CteReferenceCache | None] = ContextVar(
    "cte_reference_render_cache",
    default=None,
)


@contextmanager
def _cte_reference_analysis_scope() -> Generator[None]:
    """Reuse renders only while inspecting an unchanged CTE graph."""
    if _cte_reference_render_cache.get() is not None:
        yield
        return
    token = _cte_reference_render_cache.set(_CteReferenceCache(renders={}, aliases={}, dependencies={}))
    try:
        with read_only_render_memo():
            yield
    finally:
        _cte_reference_render_cache.reset(token)


def _render_policy_dependency_sql(value: SqlRenderable, dialect: Any) -> str:
    if dialect.backend_type is not BackendType.MARIADB:
        return render_sql_for_analysis(value, dialect)
    from impl.common.l2100_sql_grammar.domain.versioning.policy_dispatched_read import (
        policy_dispatch_dependency_analysis_scope,
    )

    with policy_dispatch_dependency_analysis_scope():
        return render_sql_for_analysis(value, dialect)


def _render_cte_reference_sql(value: SqlRenderable, dialect: Any) -> str:
    policy_dependency_queries = getattr(
        value,
        "policy_dispatch_dependency_queries",
        None,
    )
    if callable(policy_dependency_queries):
        dependency_queries = cast(
            "Iterable[SqlRenderable] | None",
            policy_dependency_queries(),
        )
        if dependency_queries is not None:
            return " ".join(_render_cte_reference_sql(query, dialect) for query in dependency_queries)
    cache = _cte_reference_render_cache.get()
    if cache is None:
        return _render_policy_dependency_sql(value, dialect)
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import _SQL_INLINE_CTE_DEFS
    from impl.common.l2100_sql_grammar.domain.graph.graph_predicates import get_graph_predicate_sql_context
    from impl.common.l2100_sql_grammar.tree.with_placement import _PARENT_MYSQL_CTE_DEFINITIONS

    context = (
        _SQL_INLINE_CTE_DEFS.get(),
        _PARENT_MYSQL_CTE_DEFINITIONS.get(),
        get_graph_predicate_sql_context(),
    )
    key = (id(value), id(dialect), tuple(id(component) for component in context))
    entry = cache.renders.get(key)
    if entry is not None:
        return entry[2]
    sql = _render_policy_dependency_sql(value, dialect)
    cache.renders[key] = (value, dialect, sql)
    return sql


def _cte_alias_reference_state(sql_text: str, alias: str, quote: str) -> tuple[bool, bool]:
    """Return whether ``sql_text`` references and defines CTE ``alias``."""
    cache = _cte_reference_render_cache.get()
    quoted_key = str.__str__(quote) + alias + str.__str__(quote)
    key = (id(sql_text), quoted_key) if cache is not None and type(sql_text) is str else None
    if cache is not None and key is not None:
        cached = cache.aliases.get(key)
        if cached is not None and cached[0] is sql_text:
            return cached[1]
    quoted = f"{quote}{alias}{quote}"

    if quoted not in sql_text:
        result = False, False
        if cache is not None and key is not None:
            cache.aliases[key] = (sql_text, result)
        return result
    if f" AS {quoted}" in sql_text:
        result = True, True
        if cache is not None and key is not None:
            cache.aliases[key] = (sql_text, result)
        return result

    definition_prefixes = (
        f"WITH {quoted} AS",
        f"WITH RECURSIVE {quoted} AS",
        f", {quoted} AS",
        f"WITH {quoted}(",
        f"WITH RECURSIVE {quoted}(",
        f", {quoted}(",
    )
    result = True, any(prefix in sql_text for prefix in definition_prefixes)
    if cache is not None and key is not None:
        cache.aliases[key] = (sql_text, result)
    return result


def _external_alias_dependencies(
    sql_text: str,
    candidates: frozenset[str],
    quote: str,
) -> frozenset[str]:
    """Reuse complete dependency sets within one read-only CTE analysis."""
    cache = _cte_reference_render_cache.get()
    key = (id(sql_text), candidates, quote)
    if cache is not None:
        entry = cache.dependencies.get(key)
        if entry is not None and entry[0] is sql_text:
            return entry[1]
    dependencies = frozenset(name for name in candidates if _cte_alias_reference_state(sql_text, name, quote) == (True, False))
    if cache is not None:
        cache.dependencies[key] = (sql_text, dependencies)
    return dependencies


def _grammar_has_external_cte_reference(
    value: SqlRenderable,
    cte_name: str,
    *,
    dialect: Any,
    render_cache: dict[int, tuple[SqlRenderable, str]] | None = None,
) -> bool:
    """Return whether grammar reads but does not define ``cte_name``."""
    value_id = id(value)
    cached = None if render_cache is None else render_cache.get(value_id)
    if cached is None:
        sql_text = _render_cte_reference_sql(value, dialect)
        if render_cache is not None:
            render_cache[value_id] = (value, sql_text)
    else:
        sql_text = cached[1]
    referenced, defined = _cte_alias_reference_state(
        sql_text,
        cte_name,
        dialect.identifier_quote,
    )
    return referenced and not defined


def _structural_statement_local_cte_refs(
    value: object,
    *,
    dialect: Any,
    seen: set[int] | None = None,
) -> frozenset[str]:
    """Return exact CTE refs declared by typed grammar nodes."""
    from impl.common.l2100_sql_grammar.statement_local_cte_refs import (
        structural_statement_local_cte_refs,
    )

    return structural_statement_local_cte_refs(value, dialect=dialect, seen=seen)


def _outer_cte_splitter(
    value: object,
    *,
    dialect: Any,
) -> Callable[[], tuple[list[SqlCteDefinition], SqlRenderable]] | None:
    """Select the backend-specific CTE split seam when one is declared."""
    if dialect.backend_type.is_mysql_family:
        mysql_split = getattr(value, "split_for_mysql_outer_cte", None)
        if callable(mysql_split):

            def _split_mysql() -> tuple[list[SqlCteDefinition], SqlRenderable]:
                return _validated_outer_cte_split(mysql_split())

            return _split_mysql
    generic_split = getattr(value, "split_for_outer_cte", None)
    if not callable(generic_split):
        return None

    def _split_generic() -> tuple[list[SqlCteDefinition], SqlRenderable]:
        return _validated_outer_cte_split(generic_split())

    return _split_generic


@_cte_reference_analysis_scope()
def _structural_carried_definitions(
    statement: SqlRenderable,
    carried_defs: Mapping[str, SqlCteDefinition],
    *,
    dialect: Any,
) -> tuple[SqlCteDefinition, ...]:
    """Return the transitive producer-owned definitions consumed by a statement."""
    if not carried_defs:
        return ()
    owned_dependency_names: set[str] = set()
    owned_names: set[str] = set()

    def _definition_dependencies(
        definition: SqlCteDefinition,
    ) -> frozenset[str]:
        definition_name = _cte_definition_name(definition)
        definition_query = _cte_definition_query(definition)
        dependencies = set(str(dependency) for dependency in getattr(definition, "dependency_names", ()))
        dependencies.update(
            _structural_statement_local_cte_refs(
                definition_query,
                dialect=dialect,
            ),
        )
        split_definition_query = _outer_cte_splitter(definition_query, dialect=dialect)
        if callable(split_definition_query):
            nested_split = split_definition_query()
            assert isinstance(nested_split, tuple) and len(nested_split) == 2
            nested_definitions, _nested_body = nested_split
            assert isinstance(nested_definitions, Sequence)
            dependencies.update(_cte_definition_name(nested_definition) for nested_definition in nested_definitions)
        definition_sql = _render_cte_reference_sql(definition_query, dialect)
        dependencies.update(
            candidate
            for candidate in carried_defs
            if candidate != definition_name and _cte_alias_reference_state(definition_sql, candidate, dialect.identifier_quote)[0]
        )
        return frozenset(dependencies)

    split_for_outer_cte = _outer_cte_splitter(statement, dialect=dialect)
    if callable(split_for_outer_cte):
        owned_split = split_for_outer_cte()
        assert isinstance(owned_split, tuple) and len(owned_split) == 2
        owned_definitions, _body = owned_split
        assert isinstance(owned_definitions, Sequence)
        for owned_definition in owned_definitions:
            owned_names.add(_cte_definition_name(owned_definition))
            owned_dependency_names.update(
                _definition_dependencies(owned_definition),
            )
    ordered: list[SqlCteDefinition] = []
    visiting: set[str] = set()
    visited: set[str] = set(owned_names)

    def _visit(name: str) -> None:
        if name in visited or name not in carried_defs:
            return
        if name in visiting:
            msg = f"Carried CTE definitions contain a dependency cycle at {name!r}."
            raise ValueError(msg)
        visiting.add(name)
        definition = carried_defs[name]
        for dependency in _definition_dependencies(definition):
            _visit(dependency)
        visiting.remove(name)
        visited.add(name)
        ordered.append(definition)

    consumed_names = owned_dependency_names | set(
        _structural_statement_local_cte_refs(statement, dialect=dialect),
    )
    for ref_name in consumed_names:
        _visit(ref_name)
    return tuple(ordered)


def _canonical_select_root_bindings(statement: SqlRenderable) -> frozenset[str]:
    """Return bindings whose canonical SELECT wrapper retains its WITH scope."""
    if not isinstance(statement, SqlWith) or type(statement) not in {SqlWith, SqlCte}:
        return frozenset()
    if type(statement._final_query) not in {SqlSelect, SqlDynamicSelectStmt}:
        return frozenset()
    return frozenset(definition.base_name for definition in statement._definitions)


@_cte_reference_analysis_scope()
def _carried_defs_referenced_by(
    stmt: SqlRenderable,
    carried_defs: Mapping[str, SqlRenderable],
    *,
    defined_names: Iterable[str],
    dialect: Any,
    render_cache: dict[int, tuple[SqlRenderable, str]] | None = None,
    rendered_queries: dict[int, tuple[SqlRenderable, str]] | None = None,
) -> list[tuple[str, SqlRenderable]]:
    """Return carried split CTE definitions the statement references but does not define.

    Steps reach chunk CTEs published by an earlier statement of the same
    compound sequence through ``ctx.cte_refs`` without always declaring the
    chunk alias in ``dependencies()``. Each statement in the sequence is a
    standalone round trip, so a referenced chunk alias must be re-declared in
    the statement that reads it or the statement is unrunnable.
    """
    already_defined = set(defined_names)
    candidates = [name for name in carried_defs if name not in already_defined]
    if not candidates:
        return []
    quote = dialect.identifier_quote
    query_sql = rendered_queries if rendered_queries is not None else ({} if render_cache is None else render_cache)

    def _direct_references(target: SqlRenderable, excluded: set[str]) -> tuple[str, ...]:
        if all(name in excluded for name in candidates):
            return ()
        if isinstance(target, SqlStatementBatch):
            return tuple(
                dict.fromkeys(reference for statement in target.statements for reference in _direct_references(statement, excluded)),
            )
        split_for_outer_cte = getattr(target, "split_for_outer_cte", None)
        noncanonical_with_wrapper = isinstance(target, SqlWith) and type(target) not in {SqlWith, SqlCte}
        if callable(split_for_outer_cte) and not noncanonical_with_wrapper:
            split_result = split_for_outer_cte()
            assert isinstance(split_result, tuple) and len(split_result) == 2
            split_definitions, split_body = split_result
            assert isinstance(split_definitions, Sequence)
            assert isinstance(split_body, SqlRenderable)
            if split_body is not target:
                owned_names = {_cte_definition_name(definition) for definition in split_definitions}
                nested_excluded = excluded | owned_names
                return tuple(
                    dict.fromkeys(
                        reference
                        for nested_query in (
                            *(_cte_definition_query(definition) for definition in split_definitions),
                            split_body,
                        )
                        for reference in _direct_references(nested_query, nested_excluded)
                    ),
                )
        if isinstance(target, DeclaresCompleteStatementLocalCteRefs):
            exact_refs = target.complete_statement_local_cte_refs()
            return tuple(name for name in candidates if name not in excluded and name in exact_refs)
        local_bindings = _canonical_select_root_bindings(target)
        remaining = tuple(name for name in candidates if name not in excluded and name not in local_bindings)
        if not remaining:
            return ()
        cached = query_sql.get(id(target))
        if cached is None:
            sql_text = _render_cte_reference_sql(target, dialect)
            query_sql[id(target)] = (target, sql_text)
        else:
            sql_text = cached[1]
        dependencies = _external_alias_dependencies(
            sql_text,
            frozenset(remaining),
            quote,
        )
        return tuple(name for name in remaining if name in dependencies)

    ordered: list[tuple[str, SqlRenderable]] = []
    visiting: set[str] = set()
    visited: set[str] = set(already_defined)

    def _visit(name: str) -> None:
        if name in visited:
            return
        if name in visiting:
            msg = f"Carried CTE definitions contain a dependency cycle at {name!r}."
            raise ValueError(msg)
        visiting.add(name)
        definition = carried_defs[name]
        query = _cte_definition_query(definition) if isinstance(definition, SqlCteDefinition) else definition
        for dependency in _direct_references(query, {name}):
            _visit(dependency)
        visiting.remove(name)
        visited.add(name)
        ordered.append((name, query))

    for referenced_name in _direct_references(stmt, set()):
        _visit(referenced_name)
    return ordered


@_cte_reference_analysis_scope()
def _normalize_cte_definition_order(
    statement: SqlRenderable,
    *,
    dialect: Any,
) -> SqlRenderable:
    """Reorder every exposed WITH graph after carried definitions are merged."""
    split_for_outer_cte = _outer_cte_splitter(statement, dialect=dialect)
    if not callable(split_for_outer_cte):
        return statement
    typed_definitions, terminal = split_for_outer_cte()
    if not typed_definitions:
        return statement
    ordered_definitions = _order_carried_cte_definitions(
        typed_definitions,
        terminal,
        dialect=dialect,
    )
    return SqlCte(
        ordered_definitions,
        terminal,
        recursive=(_query_requires_recursive_cte_prefix(statement) or _cte_definitions_need_recursive(ordered_definitions)),
    )


@_cte_reference_analysis_scope()
def _order_carried_cte_definitions(
    definitions: Sequence[SqlCteDefinition],
    terminal: SqlRenderable,
    *,
    dialect: Any,
    render_cache: dict[int, tuple[SqlRenderable, str]] | None = None,
) -> list[SqlCteDefinition]:
    """Place each carried definition after its transitive prerequisites."""
    del terminal
    if len(definitions) < 2:
        return list(definitions)
    definitions_by_name = {_cte_definition_name(definition): definition for definition in definitions}
    names = tuple(definitions_by_name)
    quote = dialect.identifier_quote

    def direct_references(source: SqlRenderable, *, owner_name: str | None = None) -> tuple[str, ...]:
        if isinstance(source, SqlStatementBatch):
            return tuple(
                dict.fromkeys(
                    reference for statement in source.statements for reference in direct_references(statement, owner_name=owner_name)
                ),
            )
        source_id = id(source)
        cached = render_cache.get(source_id) if render_cache is not None else None
        if cached is None:
            sql_text = _render_cte_reference_sql(source, dialect)
            if render_cache is not None:
                render_cache[source_id] = (source, sql_text)
        else:
            sql_text = cached[1]
        dependencies = _external_alias_dependencies(
            sql_text,
            frozenset(name for name in names if name != owner_name),
            quote,
        )
        return tuple(name for name in names if name in dependencies)

    dependencies = {
        name: direct_references(
            _cte_definition_query(definition),
            owner_name=name,
        )
        for name, definition in definitions_by_name.items()
    }
    ordered_names: list[str] = []
    visited: set[str] = set()
    visiting: set[str] = set()

    def visit(name: str) -> None:
        if name in visited:
            return
        if name in visiting:
            msg = f"Carried CTE definitions contain a dependency cycle at {name!r}."
            raise ValueError(msg)
        visiting.add(name)
        for dependency in dependencies[name]:
            visit(dependency)
        visiting.remove(name)
        visited.add(name)
        ordered_names.append(name)

    for name in names:
        visit(name)
    return [definitions_by_name[name] for name in ordered_names]


@_cte_reference_analysis_scope()
def _order_with_clause_definitions(
    definitions: Sequence[SqlWithCteDefinition],
    terminal: SqlRenderable,
    *,
    dialect: Any,
) -> list[SqlWithCteDefinition]:
    """Place WITH-clause definitions after their transitive prerequisites."""
    del terminal
    if len(definitions) < 2:
        return list(definitions)
    definitions_by_name = {str(definition.name): definition for definition in definitions}
    queries_by_name = {name: definition.query for name, definition in definitions_by_name.items()}
    ordered_names: list[str] = []
    ordered_name_set: set[str] = set()
    for definition in definitions:
        name = str(definition.name)
        for dependency_name, _query in _carried_defs_referenced_by(
            definition.query,
            queries_by_name,
            defined_names=(name,),
            dialect=dialect,
        ):
            if dependency_name not in ordered_name_set:
                ordered_name_set.add(dependency_name)
                ordered_names.append(dependency_name)
        if name not in ordered_name_set:
            ordered_name_set.add(name)
            ordered_names.append(name)
    return [definitions_by_name[name] for name in ordered_names]


@_cte_reference_analysis_scope()
def _attach_referenced_carried_ctes(
    statements: Sequence[SqlRenderable],
    carried_defs: Mapping[str, SqlRenderable],
    *,
    dialect: Any,
    render_cache: dict[int, tuple[SqlRenderable, str]] | None = None,
) -> list[SqlRenderable]:
    """Attach the transitive carried definitions that each statement reads."""

    closed_statements: list[SqlRenderable] = []
    for statement in statements:
        if isinstance(statement, SqlTxnControl):
            closed_statements.append(statement)
            continue
        required: dict[str, SqlCteDefinition] = {}
        pending = [statement]
        while pending:
            source = pending.pop()
            for name, query in _carried_defs_referenced_by(
                source,
                carried_defs,
                defined_names=required,
                dialect=dialect,
                render_cache=render_cache,
            ):
                definition = carried_defs[name]
                typed_definition = (
                    definition if isinstance(definition, SqlCteDefinition) else SqlCteDefinition(name, query, materialized=True)
                )
                required[name] = typed_definition
                pending.append(query)
        closed_statements.append(
            _wrap_with_carried_defs(
                statement,
                tuple(required.values()),
                recursive=_cte_definitions_need_recursive(tuple(required.values())),
                dialect=dialect,
                render_cache=render_cache,
            ),
        )
    return closed_statements


@_cte_reference_analysis_scope()
def _verify_no_dangling_carried_ctes(
    statements: Sequence[Any],
    carried_defs: Mapping[str, SqlRenderable],
    *,
    dialect: Any,
) -> None:
    """Raise when an emitted statement reads a chunk CTE it never defines."""
    if not carried_defs:
        return
    for index, statement in enumerate(statements):
        dangling = _carried_defs_referenced_by(
            statement,
            carried_defs,
            defined_names=(),
            dialect=dialect,
        )
        if dangling:
            alias = dangling[0][0]
            sql_text = _render_cte_reference_sql(statement, dialect)
            msg = (
                f"Compound sequence statement {index} ({type(statement).__name__}) references "
                f"undefined CTE {alias!r}. Chunked producers must carry every CTE definition "
                f"they reference. sql={sql_text[:300]!r}"
            )
            raise ValueError(msg)


def _same_canonical_cte_structure(original: SqlRenderable, normalized: SqlRenderable) -> bool:
    """Compare canonical wrapper metadata without equating independent queries."""
    if not isinstance(original, SqlWith) or not isinstance(normalized, SqlWith):
        return False
    if type(original) not in {SqlWith, SqlCte} or type(normalized) not in {SqlWith, SqlCte}:
        return False
    return (
        original._final_query is normalized._final_query
        and original._materialized == normalized._materialized
        and original._recursive == normalized._recursive
        and len(original._definitions) == len(normalized._definitions)
        and all(before.query is after.query for before, after in zip(original._definitions, normalized._definitions, strict=True))
        and original._definitions == normalized._definitions
    )


@_cte_reference_analysis_scope()
def _finalize_carried_cte_statements(
    statements: Sequence[SqlRenderable],
    carried_defs: Mapping[str, SqlRenderable],
    *,
    dialect: SqlDialect,
    render_cache: dict[int, tuple[SqlRenderable, str]] | None = None,
) -> list[SqlRenderable]:
    """Close, order, and validate the completed statement graph."""
    closed = _attach_referenced_carried_ctes(
        statements,
        carried_defs,
        dialect=dialect,
        render_cache=render_cache,
    )
    normalized = [_normalize_cte_definition_order(statement, dialect=dialect) for statement in closed]
    normalized = [
        original if _same_canonical_cte_structure(original, candidate) else candidate
        for original, candidate in zip(statements, normalized, strict=True)
    ]
    _verify_no_dangling_carried_ctes(normalized, carried_defs, dialect=dialect)
    return normalized


@_cte_reference_analysis_scope()
def _order_carried_definitions(
    definitions: Sequence[SqlCteDefinition],
    *,
    dialect: Any,
) -> tuple[SqlCteDefinition, ...]:
    """Order exact carried definitions after every producer dependency."""
    unique_definitions: list[SqlCteDefinition] = []
    seen_names: set[str] = set()
    for definition in definitions:
        definition_name = _cte_definition_name(definition)
        if definition_name in seen_names:
            continue
        seen_names.add(definition_name)
        unique_definitions.append(definition)
    definitions = tuple(unique_definitions)
    remaining = list(definitions)
    definition_names = frozenset(_cte_definition_name(definition) for definition in definitions)
    quote = dialect.identifier_quote
    rendered_queries = {
        _cte_definition_name(definition): _render_cte_reference_sql(
            _cte_definition_query(definition),
            dialect,
        )
        for definition in definitions
    }
    dependencies_by_name = {
        definition_name: _external_alias_dependencies(
            rendered_queries[definition_name],
            definition_names - {definition_name},
            quote,
        )
        for definition_name in definition_names
    }
    ordered: list[SqlCteDefinition] = []
    emitted: set[str] = set()
    while remaining:
        ready_index = next(
            (index for index, definition in enumerate(remaining) if dependencies_by_name[_cte_definition_name(definition)] <= emitted),
            None,
        )
        if ready_index is None:
            cycle_names = tuple(_cte_definition_name(definition) for definition in remaining)
            cycle_dependencies = {
                _cte_definition_name(definition): tuple(sorted(dependencies_by_name[_cte_definition_name(definition)]))
                for definition in remaining
            }
            generated_future_edges = {
                definition_name: tuple(
                    dependency
                    for dependency in dependencies_by_name[definition_name]
                    if dependency.startswith("b")
                    and dependency[1:].isdigit()
                    and dependency in cycle_names
                    and cycle_names.index(dependency) > cycle_names.index(definition_name)
                )
                for definition_name in cycle_names
            }
            generated_future_edges = {name: dependencies for name, dependencies in generated_future_edges.items() if dependencies}
            if generated_future_edges:
                msg = (
                    "Carried CTE definitions declare future generated dependencies: "
                    f"{generated_future_edges!r}; all_dependencies={cycle_dependencies!r}. "
                    "Producer dependency metadata must not include later generated aliases."
                )
                raise ValueError(msg)
            raise ValueError(f"Carried CTE definitions contain a dependency cycle among {cycle_names!r}: {cycle_dependencies!r}.")
        ready = remaining.pop(ready_index)
        ready_name = _cte_definition_name(ready)
        ready_sql = rendered_queries[ready_name]
        if ready_name.lower() in ready_sql.lower() and _cte_alias_reference_state(ready_sql, ready_name, quote) == (True, False):
            ready = replace(ready, recursive=True)
        ordered.append(ready)
        emitted.add(_cte_definition_name(ready))
    ordered_names = tuple(_cte_definition_name(definition) for definition in ordered)
    for index, definition in enumerate(ordered):
        definition_name = _cte_definition_name(definition)
        future_references = tuple(
            candidate for candidate in ordered_names[index + 1 :] if candidate in dependencies_by_name[definition_name]
        )
        if future_references:
            msg = f"Carried CTE {_cte_definition_name(definition)!r} precedes required definitions {future_references!r}."
            raise ValueError(msg)
    return tuple(ordered)


@_cte_reference_analysis_scope()
def _wrap_with_carried_defs(
    stmt: SqlRenderable,
    definitions: Sequence[SqlCteDefinition],
    *,
    recursive: bool,
    dialect: Any,
    render_cache: dict[int, tuple[SqlRenderable, str]] | None = None,
) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.domain.infra.stmt_affected_rows import SqlPreviousStatementAffectedRows

    if isinstance(stmt, SqlPreviousStatementAffectedRows):
        return stmt
    flattened_definitions: list[SqlCteDefinition] = []

    def _flatten_definition(
        definition: SqlCteDefinition,
        ancestors: frozenset[str],
        target: list[SqlCteDefinition],
    ) -> None:
        definition_name = _cte_definition_name(definition)
        if definition_name in ancestors:
            msg = f"Nested CTE definition cycle at {definition_name!r}."
            raise ValueError(msg)
        split_query = _outer_cte_splitter(_cte_definition_query(definition), dialect=dialect)
        if not callable(split_query):
            target.append(definition)
            return
        split_result = split_query()
        assert isinstance(split_result, tuple) and len(split_result) == 2
        inner_definitions, final_query = split_result
        assert isinstance(inner_definitions, Sequence)
        assert isinstance(final_query, SqlRenderable)
        typed_inner_definitions = [
            inner_definition
            if isinstance(inner_definition, SqlCteDefinition)
            else SqlCteDefinition(
                _cte_definition_name(inner_definition),
                _cte_definition_query(inner_definition),
                columns=tuple(getattr(inner_definition, "columns", ())),
                materialized=True,
                recursive=bool(getattr(inner_definition, "recursive", False)),
                dependency_names=frozenset(str(dependency) for dependency in getattr(inner_definition, "dependency_names", ())),
            )
            for inner_definition in inner_definitions
        ]
        if any(_cte_definition_name(inner_definition) == definition_name for inner_definition in typed_inner_definitions):
            target.append(definition)
            return
        next_ancestors = ancestors | frozenset({definition_name})
        for inner_definition in typed_inner_definitions:
            _flatten_definition(inner_definition, next_ancestors, target)
        target.append(replace(definition, query=final_query))

    for definition in definitions:
        _flatten_definition(definition, frozenset(), flattened_definitions)

    if isinstance(stmt, SqlStatementBatch):
        definitions_by_name = {_cte_definition_name(definition): definition for definition in flattened_definitions}

        def _required_definitions(statement: SqlRenderable) -> tuple[SqlCteDefinition, ...]:
            consumed_names = set(
                _structural_statement_local_cte_refs(statement, dialect=dialect),
            )
            split_statement = _outer_cte_splitter(statement, dialect=dialect)
            if callable(split_statement):
                split_result = split_statement()
                assert isinstance(split_result, tuple) and len(split_result) == 2
                owned_definitions, _statement_body = split_result
                assert isinstance(owned_definitions, Sequence)
                for owned_definition in owned_definitions:
                    consumed_names.update(str(dependency) for dependency in getattr(owned_definition, "dependency_names", ()))
                    consumed_names.update(
                        _structural_statement_local_cte_refs(
                            _cte_definition_query(owned_definition),
                            dialect=dialect,
                        ),
                    )
            required_names = set(definitions_by_name) & consumed_names
            changed = True
            while changed:
                changed = False
                for required_name in tuple(required_names):
                    required_definition = definitions_by_name[required_name]
                    required_query = _cte_definition_query(required_definition)
                    dependency_names = set(required_definition.dependency_names) | set(
                        _structural_statement_local_cte_refs(required_query, dialect=dialect),
                    )
                    new_names = (set(definitions_by_name) & dependency_names) - required_names
                    if new_names:
                        required_names.update(new_names)
                        changed = True
            return tuple(definition for definition in flattened_definitions if _cte_definition_name(definition) in required_names)

        wrapped_statements = []
        for statement in stmt.statements:
            required_definitions = _required_definitions(statement)
            wrapped_statements.append(
                _wrap_with_carried_defs(
                    statement,
                    required_definitions,
                    recursive=recursive and bool(required_definitions),
                    dialect=dialect,
                    render_cache=render_cache,
                )
                if required_definitions
                else statement
            )

        def _binds_external_params(statement: SqlRenderable) -> bool:
            current: object = statement
            seen: set[int] = set()
            while id(current) not in seen:
                seen.add(id(current))
                if isinstance(current, SqlBindExternalParams):
                    return True
                inner = getattr(current, "_inner", None)
                if not isinstance(inner, SqlRenderable):
                    return False
                current = inner
            return False

        retained_params = [
            None if _binds_external_params(statement) else params
            for statement, params in zip(
                stmt.statements,
                stmt.params_per_stmt,
                strict=True,
            )
        ]
        retained_external_order = [
            False if retained is None else external_first
            for retained, external_first in zip(
                retained_params,
                stmt.external_params_first_per_stmt,
                strict=True,
            )
        ]
        return SqlStatementBatch(
            wrapped_statements,
            category=stmt.category,
            relationships=stmt.relationships,
            params_per_stmt=retained_params,
            external_params_first=retained_external_order,
            needs_returning_per_stmt=stmt.needs_returning_per_stmt,
            collect_results_per_stmt=stmt.collect_results_per_stmt,
            savepoint_recovery_per_stmt=stmt.savepoint_recovery_per_stmt,
            result_labels_per_stmt=stmt.result_labels_per_stmt,
            statement_kinds_per_stmt=stmt.statement_kinds_per_stmt,
            logical_statement_count=stmt.logical_statement_count,
            logical_source_refs=stmt.logical_source_refs,
            logical_phase=stmt.logical_phase,
            terminal_program_id=stmt.terminal_program_id,
            terminal_program_phase=stmt.terminal_program_phase,
            terminal_node_ids=stmt.terminal_node_ids,
            terminal_dependencies=stmt.terminal_dependencies,
            terminal_result_columns=stmt.terminal_result_columns,
            terminal_generation_tags=stmt.terminal_generation_tags,
            terminal_generation_sources=stmt.terminal_generation_sources,
            terminal_result_types=stmt.terminal_result_types,
            terminal_read_only=stmt.terminal_read_only,
        )

    owned_cte_names = getattr(stmt, "owned_cte_names", None)
    raw_owned_cte_names = owned_cte_names() if callable(owned_cte_names) else ()
    if isinstance(raw_owned_cte_names, str) or not isinstance(raw_owned_cte_names, Iterable):
        actual_type = type(raw_owned_cte_names).__name__
        msg = f"owned_cte_names() must return a collection of SQL CTE names, not {actual_type}"
        raise TypeError(msg)
    structurally_owned_names = {str(name) for name in raw_owned_cte_names}

    unique_definitions: list[SqlCteDefinition] = []
    seen_definition_names: set[str] = set()
    for definition in flattened_definitions:
        definition_name = _cte_definition_name(definition)
        if definition_name in structurally_owned_names:
            continue
        if definition_name in seen_definition_names:
            continue
        seen_definition_names.add(definition_name)
        unique_definitions.append(definition)
    definitions = list(unique_definitions)
    definition_names = tuple(_cte_definition_name(definition) for definition in definitions)
    has_forward_reference = any(
        _grammar_has_external_cte_reference(
            _cte_definition_query(definition),
            candidate,
            dialect=dialect,
            render_cache=render_cache,
        )
        for index, definition in enumerate(definitions)
        for candidate in definition_names[index + 1 :]
    )
    has_recursive_reference = _cte_definitions_have_self_reference(
        definitions,
        dialect=dialect,
    )
    recursive = recursive or has_forward_reference or has_recursive_reference
    split_for_outer_cte = getattr(stmt, "split_for_mysql_outer_cte", None) if dialect.backend_type.is_mysql_family else None
    if not callable(split_for_outer_cte):
        split_for_outer_cte = getattr(stmt, "split_for_outer_cte", None)
    if callable(split_for_outer_cte):
        inner_defs, final_stmt = cast("tuple[Sequence[_CteDefinitionLike], Any]", split_for_outer_cte())
        all_inner_defs: list[_CteDefinitionLike] = list(inner_defs)
        while callable(nested_split := _outer_cte_splitter(final_stmt, dialect=dialect)):
            nested_split_result = nested_split()
            assert isinstance(nested_split_result, tuple) and len(nested_split_result) == 2
            nested_defs, nested_final_stmt = nested_split_result
            assert isinstance(nested_defs, Sequence)
            if not nested_defs or nested_final_stmt is final_stmt:
                break
            all_inner_defs.extend(nested_defs)
            final_stmt = nested_final_stmt
        merged_defs = [*definitions]
        normalized_inner_defs: list[SqlCteDefinition] = []
        for inner_definition in all_inner_defs:
            if isinstance(inner_definition, (SqlCteDefinition, SqlWithCteDefinition)):
                typed_inner_definition = tree_cte_definition(inner_definition)
            else:
                inner_name, inner_query = inner_definition
                typed_inner_definition = SqlCteDefinition(
                    str(inner_name),
                    inner_query,
                    columns=tuple(getattr(inner_definition, "columns", ())),
                    materialized=True,
                    recursive=bool(getattr(inner_definition, "recursive", False)),
                    dependency_names=frozenset(str(dependency) for dependency in getattr(inner_definition, "dependency_names", ())),
                )
            _flatten_definition(typed_inner_definition, frozenset(), normalized_inner_defs)
        seen_names = {_cte_definition_name(defn) for defn in merged_defs}
        for inner_definition in normalized_inner_defs:
            inner_name = _cte_definition_name(inner_definition)
            if inner_name in seen_names:
                continue
            seen_names.add(inner_name)
            merged_defs.append(inner_definition)
        if not merged_defs:
            return cast(SqlRenderable, final_stmt)
        merged_defs = _order_carried_cte_definitions(
            merged_defs,
            cast("SqlRenderable", final_stmt),
            dialect=dialect,
            render_cache=render_cache,
        )
        ordered_merged_definitions = _order_carried_definitions(
            merged_defs,
            dialect=dialect,
        )
        effective_recursive = recursive or _query_requires_recursive_cte_prefix(stmt) or _cte_definitions_need_recursive(merged_defs)
        from impl.common.l2100_sql_grammar.ddl_hierarchy import SqlDdl

        if isinstance(final_stmt, SqlDdl) and not callable(
            type(final_stmt).__dict__.get("render_with_cte_prefix"),
        ):
            return cast(SqlRenderable, final_stmt)
        if isinstance(final_stmt, SqlDdl):
            return place_with_clause(
                ordered_merged_definitions,
                cast(SqlRenderable, final_stmt),
                dialect,
                recursive=effective_recursive,
            )
        return SqlCte(
            ordered_merged_definitions,
            cast(SqlRenderable, final_stmt),
            recursive=effective_recursive,
        )
    if isinstance(stmt, (SqlInsertWithCte, SqlSelectWithCte)):
        existing_definitions = list(stmt._with_clause._ctes)
        existing_names = {str(definition._name) for definition in existing_definitions}
        merged_definition_specs = [
            *(definition for definition in definitions if _cte_definition_name(definition) not in existing_names),
            *(
                SqlCteDefinition(
                    str(definition._name),
                    definition._query,
                    columns=tuple(getattr(definition, "columns", ())),
                    materialized=True,
                    recursive=bool(getattr(definition, "recursive", False)),
                    dependency_names=frozenset(str(dependency) for dependency in getattr(definition, "dependency_names", ())),
                )
                for definition in existing_definitions
            ),
        ]
        ordered_definitions = _order_carried_definitions(
            merged_definition_specs,
            dialect=dialect,
        )
        effective_recursive = recursive or stmt._with_clause._recursive
        with_clause = SqlWithClause(
            [_with_cte_definition(definition) for definition in ordered_definitions],
            recursive=effective_recursive,
        )
        if isinstance(stmt, SqlInsertWithCte):
            return SqlInsertWithCte(with_clause, stmt._select)
        return SqlSelectWithCte(with_clause, stmt._select)
    if not definitions:
        return stmt
    terminal_ordered_definitions = _order_carried_cte_definitions(
        definitions,
        stmt,
        dialect=dialect,
        render_cache=render_cache,
    )
    terminal_ordered_definitions = list(
        _order_carried_definitions(terminal_ordered_definitions, dialect=dialect),
    )
    effective_recursive = recursive or _cte_definitions_need_recursive(
        terminal_ordered_definitions,
    )
    if isinstance(stmt, SqlNativePredicateAssertion):
        return stmt.with_predicate_ctes(
            terminal_ordered_definitions,
            recursive=effective_recursive,
        )
    from impl.common.l2100_sql_grammar.ddl_hierarchy import SqlDdl

    if isinstance(stmt, SqlDdl) and not callable(
        type(stmt).__dict__.get("render_with_cte_prefix"),
    ):
        return stmt
    if isinstance(stmt, SqlDdl) or callable(
        type(stmt).__dict__.get("render_with_cte_prefix"),
    ):
        return place_with_clause(
            terminal_ordered_definitions,
            stmt,
            dialect,
            recursive=effective_recursive,
        )
    return SqlCte(
        terminal_ordered_definitions,
        stmt,
        recursive=effective_recursive,
    )


def _order_immediate_predecessor_consumers(
    steps: Sequence[ServerPlanStep[Any]],
) -> tuple[ServerPlanStep[Any], ...]:
    """Place statement-state consumers directly after their declared producer."""

    def _tree_declared_refs(step: ServerPlanStep[Any]) -> frozenset[str]:
        return frozenset(
            (
                str(step.ref_id),
                *(str(ref_id) for ref_id in step.additional_batch_binding_ref_ids()),
                *(ref_id for child in step.physical_group_children() for ref_id in _tree_declared_refs(child)),
            ),
        )

    ordered = list(steps)
    claimed_producers: dict[int, ServerPlanStep[Any]] = {}
    for consumer in tuple(steps):
        predecessor_refs = consumer.ordered_statement_immediate_predecessor_refs()
        if not predecessor_refs:
            continue
        consumer_index = ordered.index(consumer)
        producer_indices = [
            index
            for index, candidate in enumerate(ordered[:consumer_index])
            if not predecessor_refs.isdisjoint(_tree_declared_refs(candidate))
        ]
        if not producer_indices:
            continue
        if len(producer_indices) != 1:
            msg = (
                f"{type(consumer).__name__} requires one earlier immediate predecessor for "
                f"{tuple(sorted(predecessor_refs))!r}; found {len(producer_indices)}. "
                "See docs/guides/auto_api_serverplan_1rtt.rst."
            )
            raise ValueError(msg)
        producer_index = producer_indices[0]
        producer = ordered[producer_index]
        prior_consumer = claimed_producers.get(id(producer))
        if prior_consumer is not None:
            msg = (
                f"{type(consumer).__name__} and {type(prior_consumer).__name__} both require "
                f"{type(producer).__name__} as their immediate predecessor."
            )
            raise ValueError(msg)
        claimed_producers[id(producer)] = consumer
        if producer_index + 1 == consumer_index:
            continue
        ordered.pop(consumer_index)
        ordered.insert(producer_index + 1, consumer)
    return tuple(ordered)


class CompoundSequenceCodegen(PhysicalRegionCodegen):
    """Execute SQLite mixed read/write SQL steps as one labeled compound sequence."""

    def __init__(self) -> None:
        self._compiled_children: dict[str, CompiledStep[Any]] = {}
        self._omitted_projection_indices: set[int] = set()

    def requires_compound_sequence_contracts(self: CompoundSequenceCodegen) -> bool:
        return True

    def compiled_children_for_result_planning(
        self,
    ) -> Mapping[str, CompiledStep[Any]]:
        return self._compiled_children

    def clear_compiled_runtime_state(self) -> None:
        self._compiled_children = {}

    def can_handle(
        self: CompoundSequenceCodegen,
        steps: Sequence[ServerPlanStep[Any]],
        ctx: OptimizationContext,
    ) -> bool:
        if len(steps) < _MIN_BATCH_SIZE:
            return False
        returning_relation_transport = ctx.backend_profile.traits.dml_returning_relation_transport
        if (
            returning_relation_transport is not DmlReturningRelationTransport.CONNECTION_LOCAL_JSON
            and has_runtime_row_publication_product(steps)
        ):
            return False
        return self.can_handle_with_dependency_resolver(
            steps,
            ctx,
            _runtime_publication_checked=True,
        )

    def can_handle_with_dependency_resolver(
        self: CompoundSequenceCodegen,
        steps: Sequence[ServerPlanStep[Any]],
        ctx: OptimizationContext,
        *,
        dependency_resolver: Callable[[ServerPlanStep[Any]], frozenset[str]] | None = None,
        ordered_dependency_resolver: Callable[[ServerPlanStep[Any]], frozenset[str]] | None = None,
        _runtime_publication_checked: bool = False,
    ) -> bool:
        if len(steps) < _MIN_BATCH_SIZE:
            return False
        returning_relation_transport = ctx.backend_profile.traits.dml_returning_relation_transport
        candidate_children = tuple(child for step in steps for child in _compound_children(step))
        repeatable_write_refs = {
            alias
            for child in candidate_children
            if not _compound_candidate_step_facts(child).is_read_only
            and child.publishes_repeatable_sql_write_product(returning_relation_transport)
            for alias in _compound_candidate_step_facts(child).ref_aliases
        }
        if (
            not _runtime_publication_checked
            and returning_relation_transport is not DmlReturningRelationTransport.CONNECTION_LOCAL_JSON
            and has_runtime_row_publication_product(steps)
        ):
            return False
        if returning_relation_transport is DmlReturningRelationTransport.CONNECTION_LOCAL_JSON and any(
            has_runtime_row_publication_product((step,))
            and not step.publishes_repeatable_sql_write_product(returning_relation_transport)
            and ((source_ref := step.publication_source_ref()) is None or str(source_ref) not in repeatable_write_refs)
            for step in steps
        ):
            return False
        dependency_cache: dict[int, frozenset[str]] = {}
        ordered_dependency_cache: dict[int, frozenset[str]] = {}

        def _dependencies(step: ServerPlanStep[Any]) -> frozenset[str]:
            step_id = id(step)
            cached = dependency_cache.get(step_id)
            if cached is not None:
                return cached
            dependencies = dependency_resolver(step) if dependency_resolver is not None else frozen_step_dependencies(step)
            dependency_cache[step_id] = dependencies
            return dependencies

        def _ordered_dependencies(step: ServerPlanStep[Any]) -> frozenset[str]:
            step_id = id(step)
            cached = ordered_dependency_cache.get(step_id)
            if cached is not None:
                return cached
            dependencies = (
                ordered_dependency_resolver(step) if ordered_dependency_resolver is not None else frozen_step_ordered_dependencies(step)
            )
            ordered_dependency_cache[step_id] = dependencies
            return dependencies

        children = candidate_children
        if any(
            child.requires_assertion_statement_transport() and not child._native_assertion_aborts_before_commit(ctx.backend_profile)
            for child in children
        ) and any(child.owns_database_commit() for child in children):
            # Runtime-only assertion decoding must complete before COMMIT.
            return False
        if not ctx.backend_type.is_sql_backend:
            return False
        later_ordered_dependencies: list[frozenset[str]] = [frozenset()] * len(steps)
        ordered_suffix: set[str] = set()
        for reverse_index in range(len(steps) - 1, -1, -1):
            later_ordered_dependencies[reverse_index] = frozenset(ordered_suffix)
            ordered_suffix.update(str(dependency) for dependency in _ordered_dependencies(steps[reverse_index]))
        for index, step in enumerate(steps):
            if not isinstance(step, PhysicalStatementGroup) or step.exports_child_bindings():
                continue
            nested_refs = {ref_id for child in step.children for ref_id in _compound_candidate_step_facts(child).ref_aliases}
            for child in step.children:
                contract = _sql_visible_contract(child)
                if contract is None:
                    continue
                child_base_ref = str(child.ref_id).split(".", 1)[0]
                nested_refs.update(f"{child_base_ref}.{column}" for column in contract.columns)
            if later_ordered_dependencies[index] & nested_refs:
                return False
        independent_read_only_group = all(_compound_candidate_step_facts(step).is_read_only for step in steps) and not any(
            _dependencies(step) for step in steps
        )
        if (
            ctx.backend_profile.traits.independent_read_transport is not IndependentReadTransport.ORDERED_STATEMENTS
            and independent_read_only_group
        ):
            return False
        if any(
            _compound_candidate_step_facts(step).execution_role
            not in {StepExecutionRole.SQL, StepExecutionRole.VIRTUAL, StepExecutionRole.APPLY, StepExecutionRole.CONTROL}
            for step in steps
        ):
            return False
        if any(
            child.scheduling_facts().requires_runtime_sequential_batch and bool(child.provided_staged_sources())
            for step in steps
            for child in _compound_candidate_step_facts(step).compound_children
        ):
            return False
        if any(
            _compound_candidate_step_facts(step).execution_role is StepExecutionRole.APPLY and not _is_transport_glue_child(step)
            for step in steps
        ):
            return False
        if not all(
            isinstance(step, PhysicalStatementGroup)
            or step.scheduling_facts().supports_sql_batch_transport
            or step.scheduling_facts().supports_ordered_sql_statement_batch
            or step.is_sql_session_preamble()
            or _is_compilable_child(step)
            or _is_transport_glue_child(step)
            for step in steps
        ):
            return False
        if any(isinstance(step, DdlEffectStep) for step in steps):
            return False
        if ctx.backend_type is BackendType.SQLITE and any(
            step.planning_contract().python_boundary.kind is PythonBoundaryKind.EXTERNAL_IO for step in steps
        ):
            return False
        from impl.common.l2070_server_plan.steps.conditional_builders import BooleanExpressionStep

        write_refs = {
            ref_id
            for candidate in steps
            if not _compound_candidate_step_facts(candidate).is_read_only
            for ref_id in _compound_candidate_step_facts(candidate).ref_aliases
        }
        returning_relation_transport = ctx.backend_profile.traits.dml_returning_relation_transport
        statement_local_write_aliases = write_refs - repeatable_write_refs
        if any(
            step.requires_sql_consumed_rows_relation()
            and bool({str(dependency) for dependency in _ordered_dependencies(step)} & statement_local_write_aliases)
            for step in steps
        ):
            return False
        if any(
            isinstance(candidate, BooleanExpressionStep) and {str(dep) for dep in _ordered_dependencies(candidate)} & write_refs
            for candidate in steps
        ):
            return False
        if ctx.backend_type.is_mysql_family and (
            any(isinstance(step, ConditionalStep) and not step.supports_ordered_sql_statement_batch() for step in steps)
            or any(
                child.publication_source_ref() is not None
                for step in steps
                for child in _compound_candidate_step_facts(step).compound_children
            )
        ):
            return False
        if ctx.backend_type is BackendType.POSTGRES or ctx.backend_type.is_mysql_family:
            statement_local_write_refs: set[str] = set()
            for candidate in steps:
                if _compound_candidate_step_facts(candidate).is_read_only or candidate.publishes_repeatable_sql_write_product(
                    returning_relation_transport
                ):
                    continue
                binding_refs = {str(candidate.ref_id)}
                result_ref = candidate.publication_result_ref()
                if result_ref is not None:
                    binding_refs.add(str(result_ref))
                publication = candidate.publication_contract()
                relation = publication.semantic if publication.publishes_runtime_value else publication.transport
                if relation is not None:
                    statement_local_write_refs.update(binding_refs)
                    statement_local_write_refs.update(
                        f"{binding_ref}.{column}" for binding_ref in binding_refs for column in relation.columns
                    )
            if any(
                {str(ref_id) for ref_id in _ordered_dependencies(step)} & statement_local_write_refs
                for step in steps
                if not _is_transport_glue_child(step)
            ):
                return False
        terminal_children = [child for step in steps for child in _compound_candidate_step_facts(step).sql_children]
        all_children = [child for step in steps for child in _compound_candidate_step_facts(step).compound_children]
        raw_source_producer_aliases = _sql_raw_source_aliases(tuple(all_children))
        later_child_dependencies: list[frozenset[str]] = [frozenset()] * len(steps)
        dependency_suffix: set[str] = set()
        for reverse_index in range(len(steps) - 1, -1, -1):
            later_child_dependencies[reverse_index] = frozenset(dependency_suffix)
            for child in _compound_candidate_step_facts(steps[reverse_index]).compound_children:
                if _is_transport_glue_child(child):
                    continue
                dependency_suffix.update(str(dependency) for dependency in _dependencies(child))
                dependency_suffix.update(str(dependency) for dependency in _ordered_dependencies(child))
        for producer_index, producer in enumerate(steps):
            if not isinstance(producer, PhysicalStatementGroup):
                continue
            hidden_child_aliases = {
                alias
                for child in _compound_candidate_step_facts(producer).compound_children
                for alias in _compound_candidate_step_facts(child).ref_aliases
            }
            if hidden_child_aliases & later_child_dependencies[producer_index]:
                return False
        # Ordered semantic statement batches preserve prior-statement visibility.
        # A hard prior boundary without ordered-batch support remains unfusable.
        if any(
            child.scheduling_facts().requires_prior_step_boundary
            and not child.scheduling_facts().supports_ordered_sql_statement_batch
            and not _is_transport_glue_child(child)
            and not child.supports_ordered_materialized_input_dispatch()
            for child in all_children
        ):
            return False
        for child in all_children:
            if child.requires_top_level_application_region():
                return False
            if (
                _compound_candidate_step_facts(child).execution_role == StepExecutionRole.SQL
                or _is_transport_glue_child(child)
                or child.planning_contract().python_boundary.kind is not PythonBoundaryKind.CLOSED_APPLICATION
            ):
                continue
            from l2070_batching.python_runtime_boundary_warnings import warn_python_runtime_sql_boundary

            warn_python_runtime_sql_boundary(
                callsite="impl.common.l2070_server_plan.codegen.compound_sequence:CompoundSequenceCodegen.can_handle",
                producer_type=type(child).__name__,
                ref_id=ServerPlanRefId(child.ref_id),
                consumer_context="sqlite_compound_sequence",
                reason="non-SQL runtime projection cannot be represented as an in-batch SQL CTE",
            )
            return False
        if any(
            _compound_candidate_step_facts(child).execution_role == StepExecutionRole.SQL
            and not _is_compilable_child(child)
            and not child.scheduling_facts().supports_ordered_sql_statement_batch
            and not _is_transport_glue_child(child)
            and (
                (source_ref := row_hydration_raw_payload_source_ref(child)) is None
                or not _has_sql_raw_source_child(source_ref, raw_source_producer_aliases)
            )
            for child in all_children
        ):
            return False
        child_aliases = set().union(
            *(_compound_candidate_step_facts(child).ref_aliases for child in all_children),
        )
        child_result_labels = {label for child in all_children for label in child.batch_result_labels()}
        child_alias_bases = {alias.split(".", 1)[0] for alias in child_aliases}
        if any(
            _compound_candidate_step_facts(child).execution_role == StepExecutionRole.VIRTUAL
            and child.consumes_executor_visible_dependencies()
            and not _is_transport_glue_child(child)
            and not {str(dep) for dep in _dependencies(child)}.issubset(child_aliases)
            for child in all_children
        ):
            return False
        if any(
            (source_ref := row_hydration_raw_payload_source_ref(child)) is not None and str(source_ref) not in child_result_labels
            for child in all_children
        ):
            return False
        dml_result_transport = ctx.backend_profile.traits.dml_result_transport

        def _consumes_repeatable_relation(child: ServerPlanStep[Any]) -> bool:
            dependencies = {str(dependency).split(".", 1)[0] for dependency in (*_dependencies(child), *_ordered_dependencies(child))}
            return bool(dependencies & repeatable_write_refs) or child.consumes_repeatable_post_write_relations_for_transport(
                dml_result_transport,
            )

        ambient_refs = {str(ref_id) for ref_id in seeded_constant_ref_ids_from_ctx(ctx)}
        if any(
            {
                str(ref_id).split(".", 1)[0]
                for ref_id in _ordered_dependencies(child)
                if str(ref_id) not in ambient_refs
                and not str(ref_id).startswith(("graphql.binding.", "api.binding.", "graphql.mutation."))
            }
            - child_alias_bases
            for child in all_children
            if not _consumes_repeatable_relation(child)
        ):
            return False
        if _depends_on_prior_unsafe_child(
            steps,
            repeatable_relation_consumer=_consumes_repeatable_relation,
            dependency_resolver=_dependencies,
            ordered_dependency_resolver=_ordered_dependencies,
        ):
            return False
        closed_read_group = (
            ctx.backend_profile.traits.inline_auxiliary_relation_queries_in_consumers
            and all(_compound_candidate_step_facts(step).is_read_only for step in terminal_children)
            and all(row_hydration_raw_payload_source_ref(child) is None for child in all_children)
            and all(_compound_candidate_step_facts(child).execution_role is StepExecutionRole.SQL for child in all_children)
            and not any("apply" in _compound_candidate_step_facts(child).step_tags for child in all_children)
            and not any(child.requires_assertion_statement_transport() for child in all_children)
            and not any(_compound_candidate_step_facts(child).step_tags & {"fts", "graph"} for child in all_children)
            and all(
                str(dependency).split(".", 1)[0] in child_alias_bases
                or str(dependency).startswith(("seed_", "graphql.binding.", "api.binding.", "graphql.mutation."))
                for child in all_children
                for dependency in _dependencies(child)
            )
        )
        return (
            bool(terminal_children)
            and (any(not _compound_candidate_step_facts(step).is_read_only for step in terminal_children) or closed_read_group)
            and any(_is_guaranteed_sql_statement_child(child) and not child.is_return_source_projection() for child in all_children)
        )

    def stable_dependency_rejection[T](
        self: CompoundSequenceCodegen,
        steps: Sequence[ServerPlanStep[T]],
        ctx: OptimizationContext,
        *,
        dependency_resolver: Callable[[ServerPlanStep[T]], frozenset[ServerPlanRefId]],
        ordered_dependency_resolver: Callable[[ServerPlanStep[T]], frozenset[ServerPlanRefId]],
    ) -> StableDependencyRejection:
        """Return the first rejection that appended steps cannot correct."""
        steps = tuple(steps)
        child_alias_bases = {
            ServerPlanRefId(alias.split(".", 1)[0])
            for parent in steps
            for child in _compound_children(parent)
            for alias in _ref_aliases(child)
        }
        ambient_bases = {ServerPlanRefId(str(ref_id).split(".", 1)[0]) for ref_id in seeded_constant_ref_ids_from_ctx(ctx)}
        external_rejection = len(steps)
        for parent_index, parent in enumerate(steps):
            for child in _compound_children(parent):
                if child.consumes_repeatable_post_write_relations_for_transport(
                    ctx.backend_profile.traits.dml_result_transport,
                ):
                    continue
                dependency_bases = {
                    ServerPlanRefId(str(ref_id).split(".", 1)[0])
                    for ref_id in ordered_dependency_resolver(child)
                    if not str(ref_id).startswith(("graphql.binding.", "api.binding.", "graphql.mutation."))
                }
                if dependency_bases - child_alias_bases - ambient_bases:
                    external_rejection = parent_index
                    break
            if external_rejection < len(steps):
                break
        prior_rejection = _first_prior_unsafe_parent_index(
            steps,
            repeatable_relation_consumer=lambda child: child.consumes_repeatable_post_write_relations_for_transport(
                ctx.backend_profile.traits.dml_result_transport,
            ),
            dependency_resolver=dependency_resolver,
            ordered_dependency_resolver=ordered_dependency_resolver,
        )
        return StableDependencyRejection(
            first_parent_index=min(prior_rejection, external_rejection),
            run_length=len(steps),
        )

    def fused_group_statement_accounting(
        self: CompoundSequenceCodegen,
        steps: Sequence[ServerPlanStep[Any]],
        ctx: OptimizationContext,
    ) -> tuple[int, str | None]:
        from l2070_batching.batching_strategy import (
            backend_attainable_fused_group_statement_accounting,
        )

        return backend_attainable_fused_group_statement_accounting(steps, ctx)

    @read_only_render_memo()
    @_cte_reference_analysis_scope()
    def compile_batch(
        self: CompoundSequenceCodegen,
        steps: Sequence[ServerPlanStep[Any]],
        ctx: CompilationContext,
    ) -> SqlStepIR:
        assert_no_runtime_row_publication_products(
            steps,
            strategy_name=OptimizerStepTag(type(self).__name__),
        )
        from impl.common.l2070_server_plan.overlay_policy import (
            supports_overlay_cte as _supports_overlay_cte,
        )
        from impl.common.l2070_server_plan.codegen.data_modifying_cte import _build_overlay_cte
        from impl.common.l2070_server_plan.codegen.data_modifying_cte_ordering import (
            order_steps_by_explicit_dependencies,
        )

        from impl.common.l2070_server_plan.steps.bootstrap_application_terminal import (
            BootstrapStaticDependencyStep,
        )

        self._compiled_children = {}
        self._omitted_projection_indices = set()
        dialect = ctx.dialect
        if dialect is None:
            raise ValueError("CompoundSequenceCodegen requires a SQL dialect")
        if any(isinstance(step, BootstrapStaticDependencyStep) for step in steps) or ctx.backend_type.is_mysql_family:
            # Bootstrap terminals own their closed physical inventory. MySQL-family
            # compound batches are already optimizer-ordered and must preserve that
            # effect sequence; a global topological sort can move a read ahead of a
            # prior write while waiting for unrelated explicit prerequisites.
            steps = tuple(steps)
        else:
            steps = order_steps_by_explicit_dependencies(
                steps,
                strategy_name="CompoundSequenceCodegen",
                preserve_cross_boundary_nested_batches=True,
            )
        steps = _order_immediate_predecessor_consumers(steps)

        sql_consumed_refs = frozenset(
            str(dependency) for child in steps for dependency in child.ordered_statement_sql_visible_dependencies()
        )
        statements: list[Any] = []
        params_per_stmt: list[tuple[Any, ...] | None] = []
        external_params_first: list[bool] = []
        needs_returning_per_stmt: list[bool] = []
        collect_results_per_stmt: list[bool] = []
        result_labels_per_stmt: list[str | None] = []
        statement_kinds_per_stmt: list[SqlStatementKind] = []
        savepoint_recovery_per_stmt: list[bool] = []
        carry_closure_per_stmt: list[bool] = []
        carried_reference_render_cache: dict[int, tuple[SqlRenderable, str]] = {}

        def _ensure_staged_overlays(step: ServerPlanStep[Any]) -> list[SqlCteDefinition]:
            auxiliary_defs: list[SqlCteDefinition] = []
            if ctx.backend_type in {BackendType.POSTGRES, BackendType.MARIADB}:
                for table_name in step.tables_read():
                    ctx.staged_source_cte_by_table.pop(table_name, None)
                    ctx.overlay_cte_by_table.pop(table_name, None)
                return auxiliary_defs

            def _cte_definition_pair(defn: object) -> tuple[str, SqlRenderable]:
                name = getattr(defn, "name", None)
                query = getattr(defn, "query", None)
                if name is None:
                    name = getattr(defn, "_name")
                if query is None:
                    query = getattr(defn, "_query")
                return str(name), cast(SqlRenderable, query)

            for read_table in step.tables_read():
                pending_sources = ctx.pending_staged_source_ctes_by_table.get(read_table, [])
                if read_table.endswith("_staged"):
                    pending_sources = [
                        source_name
                        for source_name in pending_sources
                        if (
                            (source_ref := ctx.cte_refs.get(source_name)) is not None
                            and source_ref.columns is not None
                            and _STAGED_SOURCE_REQUIRED_COLUMNS.issubset(set(source_ref.columns))
                        )
                    ]
                existing_overlay = ctx.staged_source_cte_by_table.get(read_table)
                if existing_overlay is not None:
                    existing_ref = ctx.cte_refs.get(existing_overlay)
                    if existing_ref is not None and existing_ref.auxiliary_query is not None:
                        auxiliary_defs.append(
                            SqlCteDefinition(existing_ref.ref_id, existing_ref.auxiliary_query),
                        )
                        continue
                if not pending_sources or not _supports_overlay_cte(
                    OptimizerTableName(read_table),
                ):
                    continue
                source_auxiliary_defs: list[SqlCteDefinition] = []
                resolved_pending_sources: list[str] = []
                for source_name in pending_sources:
                    source_ref = ctx.cte_refs.get(source_name)
                    if source_ref is not None and source_ref.auxiliary_query is not None:
                        source_def = SqlCteDefinition(
                            source_ref.ref_id,
                            source_ref.auxiliary_query,
                            materialized=True,
                        )
                        source_auxiliary_defs.append(source_def)
                        auxiliary_defs.append(source_def)
                    if source_ref is not None:
                        resolved_pending_sources.append(source_ref.ref_id)
                source_columns = next(
                    (
                        source_ref.columns
                        for source_name in pending_sources
                        if (source_ref := ctx.cte_refs.get(source_name)) is not None and source_ref.columns is not None
                    ),
                    None,
                )
                source_hints = next(
                    (
                        source_ref.column_type_hints
                        for source_name in pending_sources
                        if (source_ref := ctx.cte_refs.get(source_name)) is not None and source_ref.columns is not None
                    ),
                    None,
                )
                overlay_name = f"_compound_ov{len(statements)}_{len(auxiliary_defs)}"
                overlay_grammar = _build_overlay_cte(
                    SqlTableName(read_table),
                    resolved_pending_sources,
                    {ref.ref_id: ref.columns for ref in ctx.cte_refs.values() if ref.columns is not None},
                )
                auxiliary_defs.append(SqlCteDefinition(overlay_name, overlay_grammar))
                overlay_auxiliary_query = (
                    SqlCte(
                        [_cte_definition_pair(defn) for defn in source_auxiliary_defs],
                        overlay_grammar,
                        recursive=True,
                    )
                    if source_auxiliary_defs
                    else overlay_grammar
                )
                published_binding = CteReference(
                    ServerPlanRefId(overlay_name),
                    source_tables=frozenset({read_table}),
                    columns=source_columns,
                    column_type_hints=source_hints,
                    auxiliary_query=overlay_auxiliary_query,
                )
                publish_cte_binding(ctx, published_binding, overlay_name)
                ctx.staged_source_cte_by_table[read_table] = ServerPlanRefId(overlay_name)
                ctx.overlay_cte_by_table[read_table] = overlay_name
            return auxiliary_defs

        @_cte_reference_analysis_scope()
        def _dependency_auxiliary_defs(
            step: ServerPlanStep[Any],
            *,
            seen_names: set[str],
        ) -> list[SqlCteDefinition]:
            auxiliary_defs: list[SqlCteDefinition] = []
            analysis_dialect = ctx.sql_render_dialect()
            dependency_refs: set[str] = set()
            for dep in step.ordered_statement_sql_visible_dependencies():
                dependency_refs.add(str(dep))
            imported_refs_fn = getattr(step, "sql_imported_dependency_refs", None)
            if callable(imported_refs_fn):
                for imported_dep in cast("Iterable[object]", imported_refs_fn()):
                    dependency_refs.add(str(imported_dep))
            # Some SQL lowering helpers resolve ScalarServerRef values directly
            # from ctx.cte_refs without reflecting that use in dependencies().
            # Re-attach prior SQL-visible read CTEs so later statements in the
            # ordered batch never reference an out-of-scope CTE alias.
            visible_refs = tuple(ref_id for ref_id in dependency_refs if ref_id in ctx.cte_refs)
            for ref_id in visible_refs:
                cte_ref = ctx.cte_refs.get(ref_id)
                if cte_ref is None:
                    continue
                if cte_ref.auxiliary_query is None:
                    continue
                if cte_ref.ref_id in seen_names:
                    continue

                resolving_names: set[str] = set()
                owner_ref_id = str(cte_ref.ref_id)

                def append_required_carried_definitions(query: SqlRenderable) -> None:
                    policy_dependency_queries = getattr(
                        query,
                        "policy_dispatch_dependency_queries",
                        None,
                    )
                    if callable(policy_dependency_queries):
                        dependency_queries = cast(
                            "Iterable[SqlRenderable] | None",
                            policy_dependency_queries(),
                        )
                        if dependency_queries is not None:
                            for dependency_query in dependency_queries:
                                append_required_carried_definitions(dependency_query)
                            return
                    dialect = analysis_dialect
                    sql_text = _render_cte_reference_sql(query, dialect)
                    quote = dialect.identifier_quote
                    visible_bindings = {
                        str(binding.ref_id): binding for binding in ctx.cte_refs.values() if binding.auxiliary_query is not None
                    }
                    for name, binding in visible_bindings.items():
                        if name in seen_names or name in resolving_names or name == owner_ref_id:
                            continue
                        is_referenced, is_defined = _cte_alias_reference_state(sql_text, name, quote)
                        if not is_referenced or is_defined:
                            continue
                        assert binding.auxiliary_query is not None
                        resolving_names.add(name)
                        append_required_carried_definitions(binding.auxiliary_query)
                        resolving_names.remove(name)
                        seen_names.add(name)
                        auxiliary_defs.append(
                            SqlCteDefinition(name, binding.auxiliary_query, materialized=True),
                        )
                    for name, required_query in _carried_defs_referenced_by(
                        query,
                        carried_split_defs,
                        defined_names=seen_names,
                        dialect=dialect,
                        render_cache=carried_reference_render_cache,
                    ):
                        if name in seen_names or name in resolving_names or name == str(owner_ref_id):
                            continue
                        resolving_names.add(name)
                        append_required_carried_definitions(required_query)
                        resolving_names.remove(name)
                        seen_names.add(name)
                        auxiliary_defs.append(
                            _copy_carried_definition(
                                name,
                                required_query,
                                carried_split_defs,
                            ),
                        )

                auxiliary_query = cte_ref.auxiliary_query
                as_grammar = getattr(auxiliary_query, "as_grammar", None)
                if callable(as_grammar):
                    auxiliary_query = cast("SqlRenderable", as_grammar())
                split_for_outer_cte = _outer_cte_splitter(auxiliary_query, dialect=ctx.dialect)
                if callable(split_for_outer_cte):
                    inner_definitions, auxiliary_query = cast(
                        "tuple[Sequence[tuple[str, Any] | SqlCteDefinition], SqlRenderable]",
                        split_for_outer_cte(),
                    )
                    for inner_definition in inner_definitions:
                        if isinstance(inner_definition, SqlCteDefinition):
                            inner_name = _cte_definition_name(inner_definition)
                            inner_query = inner_definition.query
                        else:
                            inner_name_raw, inner_query = inner_definition
                            inner_name = str(inner_name_raw)
                        if inner_name in seen_names:
                            continue
                        append_required_carried_definitions(inner_query)
                        seen_names.add(inner_name)
                        auxiliary_defs.append(
                            _materialized_cte_definition(
                                inner_definition,
                                query=inner_query,
                            ),
                        )
                cte_ref_name = str(cte_ref.ref_id)
                if cte_ref_name not in seen_names:
                    append_required_carried_definitions(auxiliary_query)
                    seen_names.add(cte_ref_name)
                    auxiliary_defs.append(
                        SqlCteDefinition(cte_ref_name, auxiliary_query, materialized=True),
                    )
            if ctx.backend_type.is_mysql_family and not step.is_read_only():
                return auxiliary_defs
            required_carried_names = {name for name in carried_split_defs if name in dependency_refs}
            pending_required_names = list(required_carried_names)
            while pending_required_names:
                required_name = pending_required_names.pop()
                required_definition = carried_split_defs.get(required_name)
                if required_definition is None:
                    continue
                for referenced_name, _query in _carried_defs_referenced_by(
                    _cte_definition_query(required_definition),
                    carried_split_defs,
                    defined_names=(),
                    dialect=analysis_dialect,
                    render_cache=carried_reference_render_cache,
                ):
                    if referenced_name in required_carried_names:
                        continue
                    required_carried_names.add(referenced_name)
                    pending_required_names.append(referenced_name)
            for name, definition in carried_split_defs.items():
                if name not in required_carried_names or name in seen_names:
                    continue
                seen_names.add(name)
                auxiliary_defs.append(replace(definition, materialized=True))
            return auxiliary_defs

        from impl.common.l2070_server_plan.steps._auxiliary_ctes import (
            resolve_auxiliary_cte_binding,
        )

        available_result_labels: set[str] = set()
        carried_split_defs: dict[str, SqlCteDefinition] = {}
        for step in steps:
            dependency_refs = set(step.ordered_statement_sql_visible_dependencies())
            imported_refs_fn = getattr(step, "sql_imported_dependency_refs", None)
            if callable(imported_refs_fn):
                dependency_refs.update(str(imported_ref) for imported_ref in cast("Iterable[object]", imported_refs_fn()))
            for dependency_ref in dependency_refs:
                binding = resolve_auxiliary_cte_binding(
                    ctx,
                    ServerPlanRefId(str(dependency_ref)),
                )
                if binding is None or binding.auxiliary_query is None:
                    continue
                carried_split_defs.setdefault(
                    str(binding.ref_id),
                    SqlCteDefinition(
                        str(binding.ref_id),
                        binding.auxiliary_query,
                        materialized=True,
                    ),
                )
        carried_needs_recursive_with = False
        for step_index, step in enumerate(steps):
            is_transaction_control = step.owns_database_commit()
            alias_labels = _batch_result_alias_labels(step)

            reduction_input_relation = _batch_reduction_input_relation(
                step,
                steps[:step_index],
            )
            reduction_contract = (
                step.batch_postprocess_reduction_contract_for_relation(
                    reduction_input_relation,
                )
                if reduction_input_relation is not None
                else step.batch_postprocess_reduction_contract()
            )
            reduction_source_binding = None if reduction_contract is None else ctx.cte_refs.get(reduction_contract.source_ref)
            if (
                not is_transaction_control
                and step.is_read_only()
                and reduction_contract is not None
                and reduction_contract.source_ref in available_result_labels
                and (
                    reduction_source_binding is None
                    or reduction_source_binding.auxiliary_query is None
                    or step.reduces_available_result_with_replayable_relation()
                )
            ):
                publication_contract = _sql_visible_contract(step)
                if publication_contract is not None:
                    output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                        publication_contract,
                    )
                    self._compiled_children[str(step.ref_id)] = CompiledStep(
                        closed_post_op=reduction_contract.closed_post_op,
                        runtime_ref_ids=reduction_contract.dependency_ref_ids,
                        output_shape=output_shape,
                        result_relation=result_relation,
                        column_type_hints=column_type_hints,
                    )
                else:
                    self._compiled_children[str(step.ref_id)] = CompiledStep(
                        closed_post_op=reduction_contract.closed_post_op,
                        runtime_ref_ids=reduction_contract.dependency_ref_ids,
                    )
                if (
                    step.is_return_source_projection()
                    and reduction_source_binding is not None
                    and reduction_source_binding.auxiliary_query is not None
                ):
                    _publish_sql_visible_child(ctx, step, reduction_source_binding.auxiliary_query)
                available_result_labels.update(_ref_aliases(step))
                continue
            if not is_transaction_control and step.is_read_only() and alias_labels and available_result_labels.intersection(alias_labels):
                available_result_labels.update(_ref_aliases(step))
                continue
            is_ddl_effect = isinstance(step, DdlEffectStep)
            auxiliary_defs = [] if is_transaction_control or is_ddl_effect else _ensure_staged_overlays(step)
            ir, compiled_source = _compile_to_ir(step, ctx)
            if isinstance(compiled_source, CompiledStep):
                self._compiled_children[str(step.ref_id)] = compiled_source
            if ir is None:
                continue
            grammar = ir.grammar
            params_bound_before_cte = isinstance(grammar, SqlBindExternalParams)
            params_already_embedded = False

            as_grammar = getattr(grammar, "as_grammar", None)
            if callable(as_grammar):
                grammar = cast("SqlRenderable", as_grammar())

            child_needs_recursive_with = isinstance(compiled_source, CompiledStep) and compiled_source.needs_recursive_with
            params = ir.params or ()
            has_params = len(params) > 0
            carry_prior_ctes = (
                not is_transaction_control and not is_ddl_effect and not (ctx.backend_type.is_mysql_family and not step.is_read_only())
            )
            dependency_definitions = (
                _dependency_auxiliary_defs(step, seen_names=set()) if not is_transaction_control and not is_ddl_effect else []
            )
            if carry_prior_ctes:
                for dependency_definition in dependency_definitions:
                    carried_split_defs.setdefault(
                        _cte_definition_name(dependency_definition),
                        dependency_definition,
                    )
            cte_definitions = [*dependency_definitions]
            seen_cte_names = {_cte_definition_name(definition) for definition in cte_definitions}
            owned_cte_names = getattr(grammar, "owned_cte_names", None)
            raw_owned_cte_names = owned_cte_names() if callable(owned_cte_names) else ()
            assert isinstance(raw_owned_cte_names, Iterable)
            grammar_owned_cte_names = {str(name) for name in raw_owned_cte_names}
            if isinstance(compiled_source, CompiledStep) and not is_transaction_control and not is_ddl_effect:
                for auxiliary_cte in compiled_source.auxiliary_ctes or ():
                    if isinstance(auxiliary_cte, SqlCteDefinition):
                        aux_alias = _cte_definition_name(auxiliary_cte)
                        aux_query = _cte_definition_query(auxiliary_cte)
                    else:
                        aux_alias, aux_query_raw = auxiliary_cte
                        aux_alias = str(aux_alias)
                        aux_query = aux_query_raw
                    if aux_alias in grammar_owned_cte_names or aux_alias in seen_cte_names:
                        continue
                    as_grammar = getattr(aux_query, "as_grammar", None)
                    if callable(as_grammar):
                        aux_query = cast("SqlRenderable", as_grammar())
                    split_auxiliary_query = _outer_cte_splitter(aux_query, dialect=ctx.dialect)
                    if callable(split_auxiliary_query):
                        inner_auxiliary_definitions, aux_query = cast(
                            "tuple[Sequence[tuple[str, Any] | SqlCteDefinition], SqlRenderable]",
                            split_auxiliary_query(),
                        )
                        for inner_auxiliary_definition in inner_auxiliary_definitions:
                            if isinstance(inner_auxiliary_definition, SqlCteDefinition):
                                inner_auxiliary_name = _cte_definition_name(inner_auxiliary_definition)
                                normalized_inner_definition = replace(
                                    inner_auxiliary_definition,
                                    materialized=True,
                                )
                            else:
                                inner_auxiliary_name_raw, inner_auxiliary_query = inner_auxiliary_definition
                                inner_auxiliary_name = str(inner_auxiliary_name_raw)
                                normalized_inner_definition = SqlCteDefinition(
                                    inner_auxiliary_name,
                                    inner_auxiliary_query,
                                    materialized=True,
                                )
                            if inner_auxiliary_name in seen_cte_names:
                                continue
                            seen_cte_names.add(inner_auxiliary_name)
                            cte_definitions.append(normalized_inner_definition)
                    if aux_alias not in seen_cte_names:
                        seen_cte_names.add(aux_alias)
                        cte_definitions.append(
                            replace(auxiliary_cte, query=aux_query, materialized=True)
                            if isinstance(auxiliary_cte, SqlCteDefinition)
                            else SqlCteDefinition(aux_alias, aux_query, materialized=True),
                        )
            grammar_with_clause = getattr(grammar, "_with_clause", None)
            compiled_grammar = compiled_source.grammar if isinstance(compiled_source, CompiledStep) else None
            child_needs_recursive_with = child_needs_recursive_with or bool(
                getattr(grammar_with_clause, "_recursive", False)
                or (compiled_grammar is not None and _grammar_needs_recursive_with(compiled_grammar))
                or _grammar_needs_recursive_with(grammar)
            )
            if child_needs_recursive_with:
                carried_needs_recursive_with = True
            split_for_outer_cte = _outer_cte_splitter(grammar, dialect=ctx.dialect)
            if (
                callable(split_for_outer_cte)
                and not is_transaction_control
                and step.supports_sql_batch_transport()
                and extract_statement_batch(grammar) is None
                and not (ctx.backend_type.is_mysql_family and not step.is_read_only())
            ):
                split_owner_needs_recursive_with = child_needs_recursive_with or bool(getattr(grammar, "_recursive", False))
                split_result = cast("tuple[Sequence[tuple[str, Any]], Any]", split_for_outer_cte())
                inner_defs, grammar = split_result
                carried_needs_recursive_with = carried_needs_recursive_with or split_owner_needs_recursive_with
                for inner_def in inner_defs:
                    if isinstance(inner_def, SqlCteDefinition):
                        name = _cte_definition_name(inner_def)
                        split_def = replace(
                            inner_def,
                            materialized=True,
                            recursive=inner_def.recursive or split_owner_needs_recursive_with,
                        )
                    else:
                        name_raw, query = inner_def
                        name = str(name_raw)
                        split_def = SqlCteDefinition(
                            name,
                            query,
                            materialized=True,
                            recursive=split_owner_needs_recursive_with,
                            dependency_names=frozenset(str(dependency) for dependency in getattr(inner_def, "dependency_names", ())),
                        )
                    if name in seen_cte_names:
                        continue
                    seen_cte_names.add(name)
                    cte_definitions.append(split_def)
                    carried_split_defs[name] = split_def
            publication_ref = ctx.cte_refs.get(str(step.ref_id))
            if (
                step.is_read_only()
                and publication_ref is not None
                and not isinstance(grammar, SqlStatementBatch)
                and sqlite_allows_cte_body(grammar)
            ):
                carried_split_defs.setdefault(
                    publication_ref.ref_id,
                    SqlCteDefinition(publication_ref.ref_id, grammar, materialized=True),
                )
            for defn in auxiliary_defs:
                name = _cte_definition_name(defn)
                if name in seen_cte_names:
                    continue
                seen_cte_names.add(name)
                cte_definitions.append(_materialized_cte_definition(defn))
            if not is_transaction_control and not is_ddl_effect:
                cte_definitions.extend(_dependency_auxiliary_defs(step, seen_names=seen_cte_names))
                if not isinstance(grammar, SqlStatementBatch):
                    for name, query in _carried_defs_referenced_by(
                        grammar,
                        carried_split_defs,
                        defined_names=seen_cte_names,
                        dialect=ctx.dialect,
                        render_cache=carried_reference_render_cache,
                    ):
                        seen_cte_names.add(name)
                        cte_definitions.append(
                            _copy_carried_definition(name, query, carried_split_defs),
                        )
            if is_transaction_control or not step.supports_sql_batch_transport():
                cte_definitions = []
            if len(cte_definitions) > 1:
                cte_definitions = list(
                    _order_carried_definitions(
                        cte_definitions,
                        dialect=dialect,
                    ),
                )

            def _register_carried_definition(definition: SqlCteDefinition) -> None:
                carried_name = _cte_definition_name(definition)
                carried_query = _cte_definition_query(definition)
                as_grammar = getattr(carried_query, "as_grammar", None)
                if callable(as_grammar):
                    carried_query = cast("SqlRenderable", as_grammar())
                split_carried_query = _outer_cte_splitter(carried_query, dialect=ctx.dialect)
                if not callable(split_carried_query):
                    carried_split_defs.setdefault(
                        carried_name,
                        replace(definition, query=carried_query),
                    )
                    return
                inner_definitions, final_query = cast(
                    "tuple[Sequence[tuple[str, Any] | SqlCteDefinition], SqlRenderable]",
                    split_carried_query(),
                )
                inner_names = frozenset(_cte_definition_name(inner_definition) for inner_definition in inner_definitions)
                final_query_dependencies = frozenset(
                    inner_name
                    for inner_name in inner_names
                    if _grammar_has_external_cte_reference(
                        final_query,
                        inner_name,
                        dialect=dialect,
                        render_cache=carried_reference_render_cache,
                    )
                )
                declared_dependencies = frozenset(str(dependency) for dependency in getattr(definition, "dependency_names", ()))
                retained_dependencies = frozenset(
                    dependency
                    for dependency in declared_dependencies
                    if dependency not in inner_names or dependency in final_query_dependencies
                )
                owner_needs_recursive_with = definition.recursive or _grammar_needs_recursive_with(carried_query)
                carried_split_defs.setdefault(
                    carried_name,
                    SqlCteDefinition(
                        carried_name,
                        final_query,
                        materialized=True,
                        recursive=owner_needs_recursive_with,
                        dependency_names=retained_dependencies | final_query_dependencies,
                    ),
                )
                for inner_definition in inner_definitions:
                    if isinstance(inner_definition, SqlCteDefinition):
                        typed_inner_definition = replace(
                            inner_definition,
                            recursive=(inner_definition.recursive or owner_needs_recursive_with),
                        )
                    else:
                        inner_name, inner_query = inner_definition
                        typed_inner_definition = SqlCteDefinition(
                            str(inner_name),
                            inner_query,
                            materialized=True,
                            recursive=owner_needs_recursive_with
                            or bool(
                                getattr(inner_definition, "_recursive", False),
                            ),
                            dependency_names=frozenset(
                                str(dependency) for dependency in getattr(inner_definition, "dependency_names", ())
                            ),
                        )
                    _register_carried_definition(typed_inner_definition)

            for carried_definition in cte_definitions:
                _register_carried_definition(carried_definition)
            cte_definitions = _order_carried_cte_definitions(
                cte_definitions,
                grammar,
                dialect=ctx.dialect,
                render_cache=carried_reference_render_cache,
            )
            closed_policy_dispatch = None
            if ctx.backend_type is BackendType.MARIADB:
                from impl.common.l2100_sql_grammar.domain.versioning.policy_dispatched_read import close_policy_dispatched_relations

                if extract_statement_batch(grammar) is None:
                    closed_policy_dispatch = close_policy_dispatched_relations(
                        grammar,
                        cte_definitions,
                        recursive=child_needs_recursive_with
                        or carried_needs_recursive_with
                        or _cte_definitions_need_recursive(cte_definitions),
                    )
            if closed_policy_dispatch is not None:
                grammar = closed_policy_dispatch
                cte_definitions = []
            statement_local_ctes = getattr(grammar, "with_statement_local_ctes", None)
            if callable(statement_local_ctes):
                grammar = cast("SqlRenderable", statement_local_ctes(cte_definitions))
                publication_grammar: SqlRenderable = grammar
                cte_definitions = []
            if cte_definitions and ctx.backend_type.is_mysql_family and not step.is_read_only():
                from impl.common.l2100_sql_grammar.tree.statements import SqlStatementLocalWith

                publication_grammar = SqlStatementLocalWith(
                    cte_definitions,
                    grammar,
                    recursive=(
                        child_needs_recursive_with or carried_needs_recursive_with or _cte_definitions_need_recursive(cte_definitions)
                    ),
                )
            else:
                publication_grammar = (
                    _wrap_with_carried_defs(
                        grammar,
                        cte_definitions,
                        recursive=(
                            child_needs_recursive_with or carried_needs_recursive_with or _cte_definitions_need_recursive(cte_definitions)
                        ),
                        dialect=ctx.dialect,
                        render_cache=carried_reference_render_cache,
                    )
                    if cte_definitions
                    else grammar
                )
            if (
                not is_transaction_control
                and (child_needs_recursive_with or _cte_definitions_need_recursive(cte_definitions))
                and callable(_outer_cte_splitter(grammar, dialect=ctx.dialect))
                and extract_statement_batch(grammar) is None
            ):
                grammar = _wrap_with_carried_defs(
                    grammar,
                    (),
                    recursive=True,
                    dialect=dialect,
                    render_cache=carried_reference_render_cache,
                )
            grammar_batch = extract_statement_batch(grammar)
            if grammar_batch is not None:
                grammar_batch = grammar_batch.flatten_for_executor()
                nested_visible_defs = list(cte_definitions)
                nested_visible_seen = {str(getattr(defn, "_name", getattr(defn, "name"))) for defn in nested_visible_defs}
                child_batch_dependencies = step.sql_visible_dependencies()

                def _wrap_compound_child(child_stmt: Any) -> Any:
                    from impl.common.l2100_sql_grammar.domain.infra.stmt_affected_rows import SqlPreviousStatementAffectedRows

                    if isinstance(
                        child_stmt,
                        SqlPreviousStatementAffectedRows | SqlTxnControl | SqlDropTemporaryTableIfExists,
                    ):
                        return child_stmt
                    child_batch = extract_statement_batch(child_stmt)
                    if child_batch is not None:
                        wrapped_batch = SqlStatementBatch(
                            [_wrap_compound_child(statement) for statement in child_batch.statements],
                            category=child_batch.category,
                            relationships=child_batch.relationships,
                            params_per_stmt=child_batch.params_per_stmt,
                            external_param_counts_per_stmt=child_batch.external_param_counts_per_stmt,
                            external_params_first=child_batch.external_params_first_per_stmt,
                            needs_returning_per_stmt=child_batch.needs_returning_per_stmt,
                            collect_results_per_stmt=child_batch.collect_results_per_stmt,
                            result_labels_per_stmt=child_batch.result_labels_per_stmt,
                            statement_kinds_per_stmt=child_batch.statement_kinds_per_stmt,
                            savepoint_recovery_per_stmt=child_batch.savepoint_recovery_per_stmt,
                            logical_statement_count=child_batch.logical_statement_count,
                            logical_source_refs=child_batch.logical_source_refs,
                            logical_phase=child_batch.logical_phase,
                        )
                        closed_product = child_batch.closed_terminal_product
                        if closed_product is not None:
                            rebind = getattr(closed_product, "rebind_normalized_source_batch", None)
                            if not callable(rebind):
                                msg = "Compound CTE wrapping cannot discard an unbindable closed terminal product"
                                raise TypeError(msg)
                            wrapped_batch.publish_closed_terminal_product(rebind(child_batch, wrapped_batch))
                        return wrapped_batch
                    child_defs: list[SqlCteDefinition] = []
                    child_seen: set[str] = set()
                    child_split_for_outer_cte = _outer_cte_splitter(child_stmt, dialect=ctx.dialect)
                    if callable(child_split_for_outer_cte):
                        child_split_result = cast(
                            "tuple[Sequence[tuple[str, Any]], Any]",
                            child_split_for_outer_cte(),
                        )
                        inner_child_defs, child_stmt = child_split_result
                        if ctx.backend_type.is_mysql_family and isinstance(child_stmt, SqlPreviousStatementAffectedRows):
                            return child_stmt
                        for inner_child_def in inner_child_defs:
                            if isinstance(inner_child_def, SqlCteDefinition):
                                name = _cte_definition_name(inner_child_def)
                                query = inner_child_def.query
                                child_def = replace(inner_child_def, materialized=True)
                            else:
                                name_raw, query = inner_child_def
                                name = str(name_raw)
                                child_def = SqlCteDefinition(
                                    name,
                                    query,
                                    materialized=True,
                                    recursive=bool(getattr(inner_child_def, "recursive", False)),
                                    columns=tuple(getattr(inner_child_def, "columns", ())),
                                    dependency_names=frozenset(
                                        str(dependency) for dependency in getattr(inner_child_def, "dependency_names", ())
                                    ),
                                )
                            if name in child_seen:
                                continue
                            if (
                                isinstance(step, ConditionalStep)
                                and not ctx.supports_data_modifying_ctes
                                and not sqlite_allows_cte_body(cast(SqlRenderable, query))
                            ):
                                continue
                            child_seen.add(name)
                            child_defs.append(child_def)
                            if name not in nested_visible_seen and sqlite_allows_cte_body(cast(SqlRenderable, query)):
                                nested_visible_seen.add(name)
                                nested_visible_defs.append(child_def)
                            replay_binding = next(
                                (
                                    binding
                                    for binding in ctx.cte_refs.values()
                                    if str(binding.ref_id) == name and binding.auxiliary_query is not None
                                ),
                                None,
                            )
                            replay_query = None if replay_binding is None else replay_binding.auxiliary_query
                            if replay_query is not None:
                                carried_split_defs[name] = SqlCteDefinition(
                                    name,
                                    replay_query,
                                    materialized=True,
                                )
                            else:
                                carried_split_defs[name] = child_def
                            split_child_definition = getattr(
                                replay_query if replay_query is not None else query,
                                "split_for_outer_cte",
                                None,
                            )
                            if callable(split_child_definition):
                                nested_child_definitions, _nested_child_body = cast(
                                    "tuple[Sequence[tuple[str, Any] | SqlCteDefinition], SqlRenderable]",
                                    split_child_definition(),
                                )
                                for nested_child_definition in nested_child_definitions:
                                    if isinstance(nested_child_definition, SqlCteDefinition):
                                        nested_name = _cte_definition_name(nested_child_definition)
                                        carried_split_defs.setdefault(nested_name, nested_child_definition)
                                    else:
                                        nested_name_raw, nested_query = nested_child_definition
                                        nested_name = str(nested_name_raw)
                                        carried_split_defs.setdefault(
                                            nested_name,
                                            SqlCteDefinition(
                                                nested_name,
                                                nested_query,
                                                materialized=True,
                                                recursive=bool(
                                                    getattr(nested_child_definition, "_recursive", False),
                                                )
                                                or _grammar_needs_recursive_with(nested_query),
                                            ),
                                        )
                    child_candidate_defs = dict(carried_split_defs)
                    for visible_definition in nested_visible_defs:
                        child_candidate_defs.setdefault(
                            _cte_definition_name(visible_definition),
                            visible_definition,
                        )
                    child_dependency_names: tuple[str, ...]
                    child_local_refs_value: object
                    if isinstance(child_stmt, DeclaresCompleteStatementLocalCteRefs):
                        child_local_refs_value = child_stmt.complete_statement_local_cte_refs()
                        child_dependency_names = ()
                    else:
                        child_dependency_names = (
                            tuple(str(name) for name in child_stmt.input_names)
                            if isinstance(child_stmt, SqlDeclaredCteInputs)
                            else tuple(str(ref).split(".", 1)[0] for ref in child_batch_dependencies)
                        )
                        child_ref_supplier = getattr(child_stmt, "statement_local_cte_refs", None)
                        child_local_refs_value = child_ref_supplier() if callable(child_ref_supplier) else ()
                    assert isinstance(child_local_refs_value, (tuple, list, set, frozenset))
                    assert all(isinstance(ref, str) for ref in child_local_refs_value)
                    child_local_refs = tuple(child_local_refs_value)
                    for dependency_name in {
                        *child_dependency_names,
                        *(str(ref).split(".", 1)[0] for ref in child_local_refs),
                    }:
                        dependency_definition = child_candidate_defs.get(dependency_name)
                        if dependency_definition is None or dependency_name in child_seen:
                            continue
                        child_seen.add(dependency_name)
                        child_defs.append(replace(dependency_definition, materialized=True))
                    from impl.common.l2100_sql_grammar.ddl_hierarchy import SqlDdl

                    if isinstance(child_stmt, SqlDeclaredCteInputs) and isinstance(child_stmt.statement, SqlDdl):
                        # Input declarations guide closure construction. Keep the
                        # DDL node visible to temporary-schema authority and cleanup.
                        child_stmt = child_stmt.statement
                    renderable_child = cast(SqlRenderable, child_stmt)
                    dependency_scopes = [
                        *(_cte_definition_query(definition) for definition in child_defs),
                        renderable_child,
                    ]
                    for dependency_scope in dependency_scopes:
                        for name, query in _carried_defs_referenced_by(
                            dependency_scope,
                            child_candidate_defs,
                            defined_names=child_seen,
                            dialect=ctx.dialect,
                            render_cache=carried_reference_render_cache,
                        ):
                            child_seen.add(name)
                            child_defs.append(SqlCteDefinition(name, query, materialized=True))
                    if not child_defs:
                        if ctx.backend_type is BackendType.MARIADB:
                            closed_child = close_policy_dispatched_relations(renderable_child, ())
                            if closed_child is not None:
                                return closed_child
                        return child_stmt
                    child_defs = _order_carried_cte_definitions(
                        child_defs,
                        renderable_child,
                        dialect=ctx.dialect,
                        render_cache=carried_reference_render_cache,
                    )
                    unique_child_defs: list[SqlCteDefinition] = []
                    unique_child_names: set[str] = set()
                    for child_definition in child_defs:
                        child_definition_name = _cte_definition_name(child_definition)
                        if child_definition_name in unique_child_names:
                            continue
                        unique_child_names.add(child_definition_name)
                        unique_child_defs.append(child_definition)
                    if ctx.backend_type is BackendType.MARIADB:
                        closed_child = close_policy_dispatched_relations(
                            renderable_child,
                            unique_child_defs,
                            recursive=child_needs_recursive_with
                            or carried_needs_recursive_with
                            or _cte_definitions_need_recursive(child_defs),
                        )
                        if closed_child is not None:
                            return closed_child
                    return SqlCte(
                        _order_carried_definitions(
                            unique_child_defs,
                            dialect=dialect,
                        ),
                        renderable_child,
                        recursive=(
                            child_needs_recursive_with
                            or carried_needs_recursive_with
                            or _query_requires_recursive_cte_prefix(renderable_child)
                            or _cte_definitions_need_recursive(child_defs)
                        ),
                    )

                grammar = SqlStatementBatch(
                    [_wrap_compound_child(child_stmt) for child_stmt in grammar_batch.statements],
                    category=grammar_batch.category,
                    relationships=grammar_batch.relationships,
                    params_per_stmt=grammar_batch.params_per_stmt,
                    external_param_counts_per_stmt=grammar_batch.external_param_counts_per_stmt,
                    external_params_first=grammar_batch.external_params_first_per_stmt,
                    needs_returning_per_stmt=grammar_batch.needs_returning_per_stmt,
                    collect_results_per_stmt=grammar_batch.collect_results_per_stmt,
                    result_labels_per_stmt=grammar_batch.result_labels_per_stmt,
                    statement_kinds_per_stmt=grammar_batch.statement_kinds_per_stmt,
                    savepoint_recovery_per_stmt=grammar_batch.savepoint_recovery_per_stmt,
                )
            elif cte_definitions:
                cte_definitions = _order_carried_cte_definitions(
                    cte_definitions,
                    grammar,
                    dialect=ctx.dialect,
                    render_cache=carried_reference_render_cache,
                )
                recursive_with = (
                    child_needs_recursive_with
                    or carried_needs_recursive_with
                    or _cte_definitions_need_recursive(cte_definitions)
                    or _cte_definitions_have_self_reference(
                        cte_definitions,
                        dialect=dialect,
                    )
                )
                connection_state_effect = step.applies_sql_session_context() or step.applies_sql_queue_auth()
                if connection_state_effect:
                    pass
                elif ctx.backend_type.is_mysql_family and not step.is_read_only():
                    if cte_definitions:
                        from impl.common.l2100_sql_grammar.tree.statements import (
                            SqlStatementLocalWith,
                        )

                        grammar = SqlStatementLocalWith(
                            cte_definitions,
                            grammar,
                            recursive=recursive_with,
                        )
                else:
                    grammar = _wrap_with_carried_defs(
                        grammar,
                        cte_definitions,
                        recursive=recursive_with,
                        dialect=dialect,
                        render_cache=carried_reference_render_cache,
                    )
            if has_params and not isinstance(grammar, SqlStatementBatch):
                from impl.common.l2100_sql_grammar.placeholder_count import (
                    rendered_bind_placeholder_count,
                )

                rendered_sql, embedded_params = render_to_sql(grammar, dialect)
                params_already_embedded = rendered_bind_placeholder_count(rendered_sql) == len(embedded_params) and len(
                    embedded_params
                ) >= len(params)
            if has_params and not params_bound_before_cte and not params_already_embedded:
                # Auxiliary CTE parameters remain outside the bound statement body.
                # Preserve the body's external-before-embedded order after splitting.
                bind_external_params_first = ir.external_params_first
                bind_policy_arm_params = getattr(grammar, "with_external_params", None)
                if callable(bind_policy_arm_params):
                    grammar = cast(
                        "SqlRenderable",
                        bind_policy_arm_params(
                            params,
                            external_params_first=bind_external_params_first,
                        ),
                    )
                else:
                    grammar = SqlBindExternalParams(
                        grammar,
                        params,
                        external_params_first=bind_external_params_first,
                    )
            if (
                isinstance(compiled_source, CompiledStep)
                and compiled_source.grammar is None
                and compiled_source.ir is None
                and compiled_source.repeatable_sql_publication_query() is not None
            ):
                _publish_sql_visible_child(ctx, step, publication_grammar)
                binding = ctx.cte_refs[str(step.ref_id)]
                binding.ephemeral = False
                self._omitted_projection_indices.add(step_index)
                continue
            from impl.common.l2070_server_plan.codegen.request_value_storage import capture_shared_producer_row

            captured = (
                None
                if step.requires_assertion_statement_transport()
                else capture_shared_producer_row(
                    step,
                    ctx,
                    grammar,
                    sql_consumed=any(alias in sql_consumed_refs for alias in _ref_aliases(step)),
                )
            )
            if captured is not None:
                grammar, publication_grammar = captured
            if isinstance(step, DdlEffectStep):
                step_statement_kind = SqlStatementKind.DDL
            elif isinstance(step, GrammarEffectStep):
                step_statement_kind = SqlStatementKind.DML
            elif step.requires_assertion_statement_transport():
                step_statement_kind = SqlStatementKind.ASSERTION
            else:
                step_statement_kind = SqlStatementKind.RUNTIME
            if isinstance(grammar, SqlStatementBatch):
                step_result_label = _result_label_for_step(step)
                remaining_outer_params = list(params)

                def _append_batch_statements(batch: SqlStatementBatch, inherited_label: str | None = None) -> None:
                    for index, statement in enumerate(batch.statements):
                        child_label = batch.result_labels_per_stmt[index] if index < len(batch.result_labels_per_stmt) else None
                        nested_batch = extract_statement_batch(statement)
                        if nested_batch is not None:
                            _append_batch_statements(nested_batch, inherited_label=child_label or inherited_label)
                            continue
                        collect_results = batch.collect_results_per_stmt[index] if index < len(batch.collect_results_per_stmt) else True
                        statements.append(statement)
                        assert dialect is not None
                        statement_is_transaction_control = isinstance(statement, SqlTxnControl)
                        statement_is_standalone_drop = isinstance(statement, SqlDropTemporaryTableIfExists)
                        carry_closure_per_stmt.append(
                            not statement_is_transaction_control and not statement_is_standalone_drop and not is_ddl_effect,
                        )
                        statement_params = batch.params_per_stmt[index] if index < len(batch.params_per_stmt) else None
                        if statement_params is None and remaining_outer_params:
                            from impl.common.l2100_sql_grammar.placeholder_count import (
                                rendered_bind_placeholder_count,
                            )

                            rendered_sql, embedded_params = render_to_sql(statement, dialect)
                            missing_count = rendered_bind_placeholder_count(rendered_sql) - len(embedded_params)
                            if missing_count > 0 and remaining_outer_params:
                                statement_params = tuple(remaining_outer_params[:missing_count])
                                del remaining_outer_params[:missing_count]
                        params_per_stmt.append(statement_params)
                        external_params_first.append(
                            batch.external_params_first_per_stmt[index] if index < len(batch.external_params_first_per_stmt) else False
                        )
                        needs_returning_per_stmt.append(
                            batch.needs_returning_per_stmt[index] if index < len(batch.needs_returning_per_stmt) else False
                        )
                        collect_results_per_stmt.append(collect_results)
                        result_labels_per_stmt.append(child_label or inherited_label or (step_result_label if collect_results else None))
                        child_kind = batch.statement_kinds_per_stmt[index]
                        statement_kinds_per_stmt.append(step_statement_kind if child_kind is SqlStatementKind.UNSPECIFIED else child_kind)
                        savepoint_recovery_per_stmt.append(
                            batch.savepoint_recovery_per_stmt[index] if index < len(batch.savepoint_recovery_per_stmt) else True
                        )

                _append_batch_statements(grammar)
                available_result_labels.update(label for label in result_labels_per_stmt if label is not None)
                available_result_labels.update(step.batch_result_labels())
            else:
                statements.append(grammar)
                statement_is_transaction_control = isinstance(grammar, SqlTxnControl)
                carry_closure_per_stmt.append(
                    not statement_is_transaction_control and not is_ddl_effect,
                )
                params_per_stmt.append(None)
                external_params_first.append(False if has_params else ir.external_params_first)
                needs_returning_per_stmt.append(ir.needs_returning)
                collect_results_per_stmt.append(True)
                step_result_label = _result_label_for_step(step)
                result_labels_per_stmt.append(step_result_label)
                statement_kinds_per_stmt.append(step_statement_kind)
                available_result_labels.add(step_result_label)
                available_result_labels.update(step.batch_result_labels())
                savepoint_recovery_per_stmt.append(ir.use_savepoint_recovery)

            _publish_sql_visible_child(
                ctx,
                step,
                publication_grammar,
                post_write_publication_query=(
                    compiled_source.repeatable_sql_publication_query()
                    if isinstance(compiled_source, CompiledStep) and not step.physical_group_children()
                    else None
                ),
            )
            physical_children = step.physical_group_children() if ctx.backend_type is BackendType.POSTGRES else ()
            for physical_child in physical_children:
                for alias in _ref_aliases(physical_child):
                    binding = ctx.cte_refs.get(alias)
                    if binding is None or binding.auxiliary_query is None:
                        continue
                    published_binding = CteReference(
                        binding.ref_id,
                        source_tables=binding.source_tables,
                        columns=binding.columns,
                        column_type_hints=binding.column_type_hints,
                        relation_role=binding.relation_role,
                        scalar_control_kind=binding.scalar_control_kind,
                        scalar_value_column=binding.scalar_value_column,
                        auxiliary_query=None,
                        ephemeral=binding.ephemeral,
                        recursive=binding.recursive,
                    )
                    publish_cte_binding(ctx, published_binding, alias)

            if step.dependent_read_cte_alias_source() is not None:
                carried_split_defs.setdefault(
                    str(step.ref_id),
                    SqlCteDefinition(str(step.ref_id), publication_grammar, materialized=True),
                )
        if not statements:
            child_types = tuple(f"{step.ref_id}:{type(step).__name__}" for step in steps)
            msg = f"CompoundSequenceCodegen requires at least one compiled SQL statement; children={child_types!r}"
            raise ValueError(msg)

        dialect = ctx.dialect
        assert dialect is not None
        statements = _finalize_carried_cte_statements(
            statements,
            carried_split_defs,
            dialect=dialect,
            render_cache=carried_reference_render_cache,
        )
        statements = [_normalize_cte_definition_order(statement, dialect=ctx.dialect) for statement in statements]
        if ctx.backend_type is BackendType.MARIADB:
            from impl.common.l2100_sql_grammar.domain.versioning.policy_dispatched_read import (
                SqlPolicyDispatchedRead,
                close_policy_dispatched_relations,
            )

            statements = [
                statement
                if isinstance(statement, SqlPolicyDispatchedRead)
                else close_policy_dispatched_relations(statement, ()) or statement
                for statement in statements
            ]

        _verify_no_dangling_carried_ctes(statements, carried_split_defs, dialect=ctx.dialect)
        if ctx.backend_type in (BackendType.MARIADB, BackendType.POSTGRES):
            from impl.common.l2100_sql_grammar.domain.infra.expr_assertion import (
                SqlAssertionGuardLabel,
                SqlAssertionTransportQuery,
                SqlCheckAssertionGuard,
                SqlResetAssertionGuard,
            )
            from impl.common.l2100_sql_grammar.domain.versioning.policy_dispatched_read import SqlPolicyDispatchedRead

            for index in reversed(range(len(statements))):
                if statement_kinds_per_stmt[index] is not SqlStatementKind.ASSERTION:
                    continue
                assertion_label = result_labels_per_stmt[index] or f"assertion_statement_{index}"
                assertion_statement = statements[index]
                from impl.common.l2070_server_plan.steps.sql_error_gate import _assertion_select
                from impl.common.l2100_sql_grammar.domain.infra.request_scalar import _request_terminal
                from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
                    SqlNativePredicateAssertion,
                )
                from impl.common.l2100_sql_grammar.domain.versioning.stmt_versioned_upsert import (
                    SqlCoalesceExpr,
                )
                from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
                from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlInlineLiteral

                assertion_terminal = _request_terminal(assertion_statement)
                bound_assertion: SqlBindExternalParams | None = None
                if isinstance(assertion_terminal, SqlBindExternalParams):
                    bound_assertion = assertion_terminal
                    assertion_terminal = _request_terminal(assertion_terminal._inner)
                if isinstance(assertion_terminal, SqlNativePredicateAssertion):
                    message = assertion_terminal._message.value
                    assert isinstance(message, str)
                    predicate_query: SqlRenderable = assertion_terminal._predicate_query
                    if bound_assertion is not None:
                        predicate_query = SqlBindExternalParams(
                            predicate_query,
                            bound_assertion._params,
                            external_params_first=bound_assertion._external_params_first,
                        )
                    assertion_statement = _assertion_select(
                        SqlCoalesceExpr(
                            SqlSubquery(predicate_query),
                            SqlInlineLiteral(False),
                        ),
                        error_message=message,
                    )
                statements[index] = (
                    assertion_statement.with_assertion_transport(label=assertion_label)
                    if isinstance(assertion_statement, SqlPolicyDispatchedRead)
                    else SqlAssertionTransportQuery(
                        assertion_statement,
                        label=assertion_label,
                    )
                )
                if ctx.backend_type is BackendType.POSTGRES:
                    continue
                for position, guard in (
                    (index + 1, SqlCheckAssertionGuard(SqlAssertionGuardLabel(assertion_label))),
                    (index, SqlResetAssertionGuard()),
                ):
                    statements.insert(position, guard)
                    params_per_stmt.insert(position, None)
                    external_params_first.insert(position, False)
                    needs_returning_per_stmt.insert(position, False)
                    collect_results_per_stmt.insert(position, False)
                    result_labels_per_stmt.insert(position, None)
                    statement_kinds_per_stmt.insert(position, SqlStatementKind.RUNTIME)
                    savepoint_recovery_per_stmt.insert(position, False)
        needs_returning = any(needs_returning_per_stmt)
        bootstrap_terminal_ref = next(
            (str(ref_id) for step in steps if (ref_id := getattr(step, "_bootstrap_application_terminal_ref_id", None)) is not None),
            None,
        )
        batch = SqlStatementBatch(
            statements,
            category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            params_per_stmt=params_per_stmt,
            external_params_first=external_params_first,
            needs_returning_per_stmt=needs_returning_per_stmt,
            collect_results_per_stmt=collect_results_per_stmt,
            result_labels_per_stmt=result_labels_per_stmt,
            statement_kinds_per_stmt=statement_kinds_per_stmt,
            savepoint_recovery_per_stmt=savepoint_recovery_per_stmt,
            logical_phase=(
                f"bootstrap_application_terminal:{bootstrap_terminal_ref}"
                if bootstrap_terminal_ref is not None
                else "session_preamble"
                if any(getattr(step, "_session_preamble_batch_child", False) for step in steps)
                else None
            ),
        )
        dialect = ctx.dialect
        if bootstrap_terminal_ref is not None and dialect is not None and dialect.backend_type is BackendType.POSTGRES:
            from impl.common.l2100_sql_grammar.postgres_bootstrap_terminal import (
                _bootstrap_profile_span,
                close_postgres_bootstrap_terminal_batch,
            )

            with _bootstrap_profile_span("bootstrap_postgres_terminal.close"):
                close_postgres_bootstrap_terminal_batch(
                    batch,
                    dialect=dialect,
                    static_publications=tuple(str(step.ref_id) for step in steps if step.is_bootstrap_static_publication()),
                )
        return SqlStepIR(
            grammar=batch,
            params=None,
            needs_returning=needs_returning,
        )

    def split_results(
        self: CompoundSequenceCodegen,
        combined_result: RawResult,
        steps: Sequence[ServerPlanStep[Any]],
    ) -> Sequence[RawResult]:
        results_by_label: dict[str, list[dict[str, Any]]] = {}
        for row in combined_result:
            row_dict = dict(row) if not isinstance(row, dict) else dict(row)
            labels = {
                str(label)
                for label in (
                    row_dict.get("__compound_parent_step__"),
                    row_dict.get(_COMPOUND_STEP_LABEL),
                )
                if label is not None
            }
            for label in labels:
                results_by_label.setdefault(label, []).append(row_dict)

        def _batch_plan_labels(plan: BatchResultExecutionPlan) -> list[str]:
            labels: list[str] = []
            for child_result in plan.child_results:
                labels.extend(child_result.split_labels)
                if child_result.raw_source_label is not None:
                    labels.append(child_result.raw_source_label)
                if child_result.nested_batch_plan is not None:
                    labels.extend(_batch_plan_labels(child_result.nested_batch_plan))
            return labels

        def _labels_for_step(step: ServerPlanStep[Any]) -> tuple[str, ...]:
            labels = [_result_label_for_step(step)]
            labels.extend(_batch_result_alias_labels(step))
            labels.extend(step.batch_result_labels())
            compiled_step = self._compiled_children.get(str(step.ref_id))
            if compiled_step is not None and compiled_step.batch_result_plan is not None:
                labels.extend(_batch_plan_labels(compiled_step.batch_result_plan))
            nested = getattr(step, "children", None)
            if nested is not None:
                for child in nested:
                    labels.extend(_labels_for_step(child))
            for plan_name in ("then_plan", "else_plan"):
                plan = getattr(step, plan_name, None)
                for child in tuple(getattr(plan, "steps", ()) or ()):
                    labels.extend(_labels_for_step(child))
            for steps_name in ("if_true_steps", "else_steps"):
                for child in tuple(getattr(step, steps_name, ()) or ()):
                    labels.extend(_labels_for_step(child))
            return tuple(dict.fromkeys(labels))

        results: list[RawResult] = []
        for step in steps:
            reduction_contract = step.batch_postprocess_reduction_contract()
            if reduction_contract is not None and str(step.ref_id) not in self._compiled_children:
                count_rows = results_by_label.get(reduction_contract.raw_source_label)
                if count_rows is None:
                    source_step = next(
                        (candidate for candidate in steps if str(candidate.ref_id) == reduction_contract.source_ref),
                        None,
                    )
                    if source_step is not None:
                        count_rows = next(
                            (results_by_label[label] for label in _labels_for_step(source_step) if label in results_by_label),
                            None,
                        )
                source_rows = count_rows if count_rows is not None else []
                publication_contract = _sql_visible_contract(step)
                if (
                    publication_contract is not None
                    and publication_contract.scalar_control_kind is ScalarControlKind.ROW_COUNT
                    and publication_contract.scalar_value_column is not None
                ):
                    value_column = publication_contract.scalar_value_column.to_row_key()
                    rows = [{value_column: len(source_rows)}]
                else:
                    rows = source_rows
            else:
                direct_rows = results_by_label.get(str(step.ref_id))
                rows = (
                    direct_rows
                    if direct_rows is not None
                    else [row for label in _labels_for_step(step) for row in results_by_label.get(label, [])]
                )
            if not isinstance(step, PhysicalStatementGroup):
                rows = [
                    {key: value for key, value in row.items() if key not in {"__compound_parent_step__", _COMPOUND_STEP_LABEL}}
                    for row in rows
                ]
            step_contract = _sql_visible_contract(step)
            is_declared_count = step_contract is not None and step_contract.scalar_control_kind in {
                ScalarControlKind.AFFECTED_COUNT,
                ScalarControlKind.ROW_COUNT,
            }
            if step.result_cardinality() is Cardinality.NONE and rows and is_declared_count:
                results.append(rows[:1])
            else:
                results.append(rows)
        return results


