def _record_transaction_control_batch_timing(
    statements: tuple[SqlRenderable, ...],
    elapsed_ms: float,
) -> None:
    """Record SQL-native transaction controls through the shared timing contract."""
    from impl.common.l2100_sql_grammar.tree.enums import TxnControlKind
    from impl.common.l2100_sql_grammar.tree.statements import SqlTxnControl
    from l2092_timing_tracking import record_commit_timing, record_rollback_timing

    for statement in statements:
        if not isinstance(statement, SqlTxnControl):
            continue
        if statement.transaction_kind is TxnControlKind.COMMIT:
            record_commit_timing(elapsed_ms)
        elif statement.transaction_kind is TxnControlKind.ROLLBACK:
            record_rollback_timing(elapsed_ms)


