def _extract_schema_column_cache(
    conn: object,
    planning_catalog: object | None = None,
) -> MappingProxyType[SqlTableName, frozenset[SqlColumnName]]:
    """Snapshot connection-known table columns for pure compile-time filtering."""
    snapshot: dict[SqlTableName, frozenset[SqlColumnName]]
    if isinstance(conn, _ColumnCacheCarrier) and isinstance(conn._column_cache, dict):
        raw_column_cache = conn._column_cache
        snapshot = {
            SqlTableName(str(table_name)): frozenset(SqlColumnName(str(column)) for column in columns)
            for table_name, columns in raw_column_cache.items()
            if columns
        }
    elif isinstance(conn, _CachedTableColumnSnapshotCarrier):
        raw_snapshot = conn.cached_table_columns_snapshot()
        snapshot = {
            SqlTableName(str(table_name)): frozenset(SqlColumnName(str(column)) for column in columns)
            for table_name, columns in raw_snapshot.items()
            if columns
        }
    elif not isinstance(conn, _SqlConnectionCore):
        snapshot = {}
    else:
        snapshot = {
            SqlTableName(str(table_name)): frozenset(SqlColumnName(str(column)) for column in columns)
            for table_name, columns in conn.cached_table_columns_snapshot().items()
            if columns
        }
    from l2070_batching.planning_catalog import PlanningCatalog
    from l1000_schema.table_registry import get_model_for_table
    from l1000_schema.schema_def import get_db_column_name
    from l1400_types import DynamicFieldName

    if isinstance(planning_catalog, PlanningCatalog):
        for shape in planning_catalog.tables.values():
            staged_name = SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(shape.table_name))).staged)
            if staged_name in snapshot:
                continue
            staged_model = get_model_for_table(staged_name)
            if staged_model is not None:
                snapshot[staged_name] = frozenset(
                    get_db_column_name(staged_model, DynamicFieldName(name)) for name in staged_model.model_fields
                )
    delta = planning_catalog.delta if isinstance(planning_catalog, _PlanningCatalogDeltaCarrier) else None
    delta_projected_columns = delta.columns_by_table if isinstance(delta, _ColumnsByTableCarrier) else None
    if isinstance(delta_projected_columns, Mapping):
        for table_name, columns in delta_projected_columns.items():
            if not columns:
                continue
            normalized_table = SqlTableName(str(table_name))
            existing = set(snapshot.get(normalized_table, frozenset()))
            if isinstance(columns, frozenset):
                existing.update(SqlColumnName(str(column)) for column in columns)
            snapshot[normalized_table] = frozenset(existing)
    return MappingProxyType(snapshot)


def _extract_scalar_server_ref_value(
    ref: ScalarServerRef[object],
) -> str | None:  # broad-type: accepted
    """Resolve a scalar server ref to a literal when it is already available."""
    raw_ref_id = ref.ref_id
    if raw_ref_id is not None:
        found_seed, seeded_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(raw_ref_id))
        if found_seed:
            return optional_branded_text(_stringify_scalar(seeded_value), str)
    pre_populated = ref._pre_populated if isinstance(ref, _PrePopulatedValueCarrier) else None
    if pre_populated is not None:
        return optional_branded_text(_stringify_scalar(pre_populated), str)
    if isinstance(ref, _ResolvedLazyValueCarrier) and ref._state == LazyState.RESOLVED:
        return optional_branded_text(_stringify_scalar(ref._value), str)
    return optional_branded_text(None, str)


