def _resolve_session_id_from_candidates(
    explicit_session_id: SessionId | None,
    txn_candidates: tuple[object, ...],
) -> SessionId | None:
    if explicit_session_id is not None:
        return explicit_session_id
    for candidate in txn_candidates:
        if isinstance(candidate, _TransactionSessionCarrier):
            candidate_session_id = candidate._session_id
            if isinstance(candidate_session_id, SessionId):
                return candidate_session_id
    return None


def _resolve_session_source_from_candidates(
    txn_candidates: tuple[PlanTarget, ...],
) -> LazySessionSqlSource | SessionId | ScalarServerRef[SessionId] | None:
    concrete_source: SessionId | None = None
    for candidate in txn_candidates:
        source: object
        if isinstance(candidate, LazyReadTransaction):
            if candidate._transaction_principal_ref is not None:
                return candidate._transaction_principal_ref
            source = candidate._session_id_source
        else:
            source = candidate._session_id_source if isinstance(candidate, _SessionSourceCarrier) else None
        symbolic_source = session_sql_source_or_none(source)
        if symbolic_source is not None:
            return symbolic_source
        if isinstance(source, LazyResult):
            shape = inspect_server_value_shape_for_planning(
                source,
                site="_resolve_session_source_from_candidates",
            )
            if shape.has_literal_value:
                literal = shape.literal_value
                concrete_source = literal if isinstance(literal, SessionId) else SessionId(str(literal))
                continue
            if shape.symbolic_ref_id is None:
                raise TypeError("Deferred session source must publish one scalar plan reference.")
            return ServerRefs.from_ref_id(
                shape.symbolic_ref_id,
                variant="scalar",
                type_hint=SessionId,
            )
        if concrete_source is None and isinstance(source, SessionId):
            concrete_source = source
    return concrete_source


def _symbolic_session_source_from_candidates(
    txn_candidates: tuple[PlanTarget, ...],
) -> LazySessionSqlSource | ScalarServerRef[SessionId] | None:
    """The session's query, when the session is a query and not a value.

    Narrower than ``_resolve_session_source_from_candidates``, which returns the
    source whatever it is -- and it is a plain ``SessionId`` on every ordinary
    transaction, since the source field is initialised to the concrete
    identifier. Callers deciding whether to treat the session symbolically need
    to distinguish those two cases, and doing the isinstance check at each site
    invites getting it wrong at one of them.
    """
    source = _resolve_session_source_from_candidates(tuple(txn_candidates))
    return source if isinstance(source, LazySessionSqlSource | ScalarServerRef) else None


