def _extract_branch_id(txn_candidates: tuple[PlanTarget, ...]) -> BranchExtraction:
    """Extract branch_id and is_versioned from transaction candidates.

    Uses isinstance checks on SyncVersionedWriteTransaction and
    SyncVersionedReadTransaction to avoid hasattr probing.
    """
    for candidate in txn_candidates:
        if isinstance(candidate, _versioned_write_transaction_types()):
            anchor = cast(Any, candidate).branch_anchor
            if anchor is not None and not isinstance(anchor, ScalarServerRef):
                bid = _stringify_scalar(anchor)
                if bid is not None:
                    return bid, True
            continue
        if isinstance(candidate, _versioned_read_transaction_types()):
            anchor = cast(Any, candidate).branch_anchor
            if isinstance(anchor, ScalarServerRef):
                continue
            bid = _unwrap_branded_to_str(anchor)
            if bid is not None:
                return bid, True
            continue
        anchor = _static_branch_anchor(candidate, DynamicFieldName("_branch_anchor"))
        if anchor is _MISSING_ATTR or anchor is None:
            anchor = _static_branch_anchor(candidate, DynamicFieldName("branch_anchor"))
        if anchor is _MISSING_ATTR:
            anchor = None
        if anchor is not None and not isinstance(anchor, ScalarServerRef):
            bid = _unwrap_branded_to_str(anchor)
            if bid is not None:
                return bid, True
    is_versioned: bool = any(isinstance(c, _versioned_transaction_types()) for c in txn_candidates)
    return None, is_versioned


def _extract_versioned_read_strategy_flags(
    txn_candidates: tuple[PlanTarget, ...],
) -> tuple[bool, bool]:
    """Extract pure compile-time read-strategy flags from txn candidates."""
    prefer_tip_strategy = False
    prefer_tip_merged = False
    for candidate in txn_candidates:
        prefer_tip_strategy = prefer_tip_strategy or _read_private_bool_flag(
            candidate,
            DynamicFieldName("_prefer_tip_strategy"),
        )
        observe_staged_from = _read_private_attr(candidate, DynamicFieldName("_observe_staged_from"))
        prefer_tip_merged = (
            prefer_tip_merged
            or _read_private_bool_flag(
                candidate,
                DynamicFieldName("_prefer_tip_merged"),
            )
            or (observe_staged_from is not _MISSING_ATTR and observe_staged_from is not None)
        )
    return prefer_tip_strategy, prefer_tip_merged


def _branch_tip_materialization_flag(materialization: BranchTipMaterializationInput) -> bool | None:
    """Normalize a branch tip materialization marker to a boolean when known."""

    if materialization is _MISSING_ATTR or materialization is None:
        return None
    if isinstance(materialization, ScalarServerRef):
        return None
    if materialization == BranchTipMaterialization.TIPLESS or str(materialization) == BranchTipMaterialization.TIPLESS.value:
        return False
    if materialization == BranchTipMaterialization.MATERIALIZED or str(materialization) == BranchTipMaterialization.MATERIALIZED.value:
        return True
    return None


def _resolve_branch_tip_materialized(
    default: bool,
    txn_candidates: tuple[PlanTarget, ...],
) -> bool:
    """Resolve branch-tip materialization from transaction-owned state only.

    A confirmed marker on any candidate wins. An unresolved runtime ref is not a
    confirmation — the branch row has not been read yet, so the tip may not exist —
    and published-state visibility is correct for either materialization, so an
    unconfirmed branch compiles that shape instead of taking the tip shortcut.
    """

    saw_unresolved_ref = False
    for candidate in txn_candidates:
        materialization = _static_branch_tip_materialization(candidate)
        if materialization is not None and not isinstance(
            materialization,
            _MissingAttr | BranchTipMaterialization | ScalarServerRef | str,
        ):
            continue
        resolved = _branch_tip_materialization_flag(materialization)
        if resolved is not None:
            return resolved
        if isinstance(materialization, ScalarServerRef):
            saw_unresolved_ref = True
    if saw_unresolved_ref:
        return False
    return default


def _extract_staged_commit_id(
    txn_candidates: tuple[PlanTarget, ...],
) -> StagedCommitIdText | None:
    """Extract the write staged-commit id for compile-time value routing."""
    for candidate in txn_candidates:
        staged_commit_id = _read_private_attr(candidate, DynamicFieldName("_staged_commit_id"))
        if staged_commit_id is not None:
            unwrap_to_str = _read_private_attr(staged_commit_id, DynamicFieldName("unwrap_to_str"))
            if callable(unwrap_to_str):
                return StagedCommitIdText(str(unwrap_to_str()))
            return StagedCommitIdText(str(staged_commit_id))
    return None


def _extract_staged_visibility_fields(
    txn_candidates: tuple[PlanTarget, ...],
) -> StagedVisibilityFields:
    """Extract staged-visibility inputs from txn candidates.

    Returns ``(staged_visibility, connection_id_str, source_txn)``.
    ``source_txn`` is the first candidate that carries a staged-visibility
    attribute (``_staged_visibility`` on a write txn, or
    ``_observe_staged_from`` on a read txn — Slice 4).  It is the txn that
    :func:`_build_staged_visibility_filter` reads from to resolve the
    domain's staged-commits table name and branch id.

    All three are ``None`` when no candidate is a versioned write txn and no
    candidate carries a read-side observer. Ordinary branch-tip reads then use
    the published tip path unless their transaction explicitly opts into a
    merged staged overlay.
    """
    for candidate in txn_candidates:
        staged_visibility = _read_private_attr(candidate, DynamicFieldName("_staged_visibility"))
        observe_staged_from = _read_private_attr(candidate, DynamicFieldName("_observe_staged_from"))
        if staged_visibility is None and observe_staged_from is None:
            continue
        connection_id = _read_private_attr(candidate, DynamicFieldName("_connection_id"))
        if staged_visibility is None and observe_staged_from is not None:
            connection_id = observe_staged_from
        connection_id_str: str | None = None
        if connection_id is not None:
            unwrap_to_uuid_compatible_str = _read_private_attr(connection_id, DynamicFieldName("unwrap_to_uuid_compatible_str"))
            if callable(unwrap_to_uuid_compatible_str):
                connection_id_str = str(unwrap_to_uuid_compatible_str())
            else:
                unwrap_to_str = _read_private_attr(connection_id, DynamicFieldName("unwrap_to_str"))
                if callable(unwrap_to_str):
                    connection_id_str = str(unwrap_to_str())
                else:
                    connection_id_str = str(connection_id)
        if staged_visibility is not None and not isinstance(staged_visibility, StagedVisibility):
            msg = f"Invalid staged visibility value: {staged_visibility!r}"
            raise TypeError(msg)
        return staged_visibility, connection_id_str, candidate
    return None, None, None


def _read_private_attr(candidate: object, attr_name: DynamicFieldName) -> object | None:
    try:
        value: object = object.__getattribute__(candidate, attr_name)
        return value
    except AttributeError:
        return None


def _read_private_bool_flag(candidate: object, attr_name: DynamicFieldName) -> bool:
    value = _read_private_attr(candidate, attr_name)
    return value if isinstance(value, bool) else False


def _collect_versioning_domains[StepResultT](step: ServerPlanStep[StepResultT], domains: set[type[Any]]) -> None:
    from l7000_versioned_schema.versioned_schema import VersionedObjectRow

    model_cls = _read_private_attr(step, DynamicFieldName("_model_cls"))
    if isinstance(model_cls, type) and issubclass(model_cls, VersionedObjectRow):
        domain = model_cls.__versioning_domain__
        if domain is not None:
            domains.add(domain)
    if isinstance(step, PhysicalStatementGroup):
        for child in step.children:
            _collect_versioning_domains(child, domains)


def _unambiguous_versioning_domain[StepResultT](step: ServerPlanStep[StepResultT]) -> type[Any] | None:
    """Versioning domain implied by a step tree, when every model agrees on one.

    Batching strategies compile fused children themselves, so a child's own model
    never reaches ``compile_step``. The domain has to be resolved from the whole
    tree before the batch is compiled, and only when it is unambiguous.
    """
    domains: set[type[Any]] = set()
    _collect_versioning_domains(step, domains)
    if len(domains) != 1:
        return None
    return next(iter(domains))


def _unwrap_sql_connection(candidate: PlanTarget) -> _SqlConnectionCore:
    """Resolve transaction and wrapper layers down to the backing SQL connection."""

    def _looks_like_sql_connection(value: object) -> bool:
        value_type = type(value)
        if (
            value_type.__module__,
            value_type.__name__,
        ) in {
            ("impl.common.l2200_sql_dialect.sql_connection", "_SqlConnectionCore"),
            ("impl.sqlite.connection", "_SqliteConnectionCore"),
            ("impl.postgres.connection", "_PostgresConnectionCore"),
            ("impl.mariadb.connection", "_MariaDBConnectionCore"),
            ("impl.doltdb.connection", "_DoltDBConnectionCore"),
        }:
            return True
        try:
            return callable(getattr_static(value, "_execute_direct_internal", None)) and callable(
                getattr_static(value, "_execute_direct_internal_async", None),
            )
        except RecursionError:
            return False

    def _direct_connection_target(value: object) -> object | None:
        from l2000_connection.schema_transaction import _InternalSchemaTransaction
        from l2050_transaction.transaction import ReadTransaction, WriteTransaction

        if isinstance(value, (ReadTransaction, WriteTransaction)):
            txn_connection: object | None = get_transaction_connection(value)
            return txn_connection
        if isinstance(value, _InternalSchemaTransaction):
            schema_connection: object | None = get_schema_transaction_connection(value)
            return schema_connection
        return None

    current: object = candidate
    seen: set[int] = set()
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        if _looks_like_sql_connection(current):
            return cast(_SqlConnectionCore, current)

        next_current: object | None = _direct_connection_target(current)
        if next_current is not None and next_current is not current:
            current = next_current
            continue

        next_current = _get_base_txn_wrapper_target(current)
        if next_current is not None:
            current = next_current
            continue

        next_current = _get_cache_txn_wrapper_target(current)
        if next_current is not None:
            current = next_current
            continue

        next_current = _get_conn_wrapper_target(current)
        if next_current is not None:
            current = next_current
            continue

        next_current = _get_cache_conn_wrapper_target(current)
        if next_current is not None:
            current = next_current
            continue

        break
    if current is not None and _looks_like_sql_connection(current):
        return cast(_SqlConnectionCore, current)
    msg = f"Could not unwrap _SqlConnectionCore from {type(candidate).__name__}"
    raise TypeError(msg)


def _target_is_write_transaction(target: object) -> bool:
    from l2050_transaction.transaction import ReadTransaction, WriteTransaction

    if isinstance(target, WriteTransaction):
        return True
    if isinstance(target, ReadTransaction):
        return False
    return isinstance(target, _versioned_write_transaction_types())


class _PipelineScopeLease(ABC):
    """Coordinate nested users of one native driver scope."""

    @abstractmethod
    def borrow(self: _PipelineScopeLease) -> bool:
        """Join an open scope or reject a scope that started cleanup."""
        raise NotImplementedError

    @abstractmethod
    def release(self: _PipelineScopeLease) -> None:
        """Release one successful borrow."""
        raise NotImplementedError


@dataclass(eq=False)
class _SyncPipelineScopeLease(_PipelineScopeLease):
    borrowers: int = 0
    accepting_borrowers: bool = True
    condition: threading.Condition = field(default_factory=threading.Condition)

    def borrow(self: _SyncPipelineScopeLease) -> bool:
        with self.condition:
            if not self.accepting_borrowers:
                return False
            self.borrowers += 1
            return True

    def release(self: _SyncPipelineScopeLease) -> None:
        with self.condition:
            if self.borrowers == 0:
                msg = "Cannot release a synchronous pipeline scope without an active borrower"
                raise RuntimeError(msg)
            self.borrowers -= 1
            if self.borrowers == 0:
                self.condition.notify_all()

    def close_and_wait(self: _SyncPipelineScopeLease) -> None:
        with self.condition:
            if not self.accepting_borrowers:
                msg = "Cannot close a synchronous pipeline scope more than once"
                raise RuntimeError(msg)
            self.accepting_borrowers = False
            while self.borrowers > 0:
                self.condition.wait()


@dataclass(eq=False)
class _AsyncPipelineScopeLease(_PipelineScopeLease):
    loop: asyncio.AbstractEventLoop
    drained: asyncio.Event
    borrowers: int = 0
    accepting_borrowers: bool = True
    mutex: threading.Lock = field(default_factory=threading.Lock)

    def borrow(self: _AsyncPipelineScopeLease) -> bool:
        with self.mutex:
            if not self.accepting_borrowers:
                return False
            self.drained.clear()
            self.borrowers += 1
            return True

    def release(self: _AsyncPipelineScopeLease) -> None:
        with self.mutex:
            if self.borrowers == 0:
                msg = "Cannot release an asynchronous pipeline scope without an active borrower"
                raise RuntimeError(msg)
            self.borrowers -= 1
            should_signal = self.borrowers == 0
        if should_signal:
            self.loop.call_soon_threadsafe(self.drained.set)

    async def wait_until_drained_async(self: _AsyncPipelineScopeLease) -> None:
        with self.mutex:
            if not self.accepting_borrowers:
                msg = "Cannot close an asynchronous pipeline scope more than once"
                raise RuntimeError(msg)
            self.accepting_borrowers = False
            has_borrowers = self.borrowers > 0
        if not has_borrowers:
            return
        waiter = asyncio.create_task(self.drained.wait())
        cancellation: asyncio.CancelledError | None = None
        while not waiter.done():
            try:
                await asyncio.shield(waiter)
            except asyncio.CancelledError as exc:
                cancellation = exc
        await waiter
        if cancellation is not None:
            raise cancellation


@dataclass(frozen=True, slots=True)
class _AsyncExecutionLockWaiter:
    loop: asyncio.AbstractEventLoop
    ready: asyncio.Future[None]


class _PipelineExecutionLock:
    """Serialize sync and async scopes without occupying an executor thread.

    This lock keeps one ownership boundary across execution modes. See
    ``docs/design/SERVERPLAN_GENERIC_TARGET_ARCHITECTURE.md``.
    """

    def __init__(self: _PipelineExecutionLock) -> None:
        self._condition = threading.Condition()
        self._held = False
        self._async_waiters: deque[_AsyncExecutionLockWaiter] = deque()

    @contextmanager
    def acquire_sync(self: _PipelineExecutionLock) -> Generator[None]:
        with self._condition:
            while self._held:
                self._condition.wait()
            self._held = True
        try:
            yield
        finally:
            self.release()

    @asynccontextmanager
    async def acquire_async(self: _PipelineExecutionLock) -> AsyncGenerator[None]:
        loop = asyncio.get_running_loop()
        ready = loop.create_future()
        with self._condition:
            if not self._held:
                self._held = True
                ready.set_result(None)
            else:
                self._async_waiters.append(_AsyncExecutionLockWaiter(loop, ready))
        cancellation: asyncio.CancelledError | None = None
        while not ready.done():
            try:
                await asyncio.shield(ready)
            except asyncio.CancelledError as exc:
                cancellation = exc
        await ready
        if cancellation is not None:
            self.release()
            raise cancellation
        try:
            yield
        finally:
            self.release()

    def release(self: _PipelineExecutionLock) -> None:
        waiter: _AsyncExecutionLockWaiter | None = None
        with self._condition:
            if not self._held:
                msg = "Cannot release a pipeline execution lock that is not held"
                raise RuntimeError(msg)
            if self._async_waiters:
                waiter = self._async_waiters.popleft()
            else:
                self._held = False
                self._condition.notify()
        if waiter is not None:
            waiter.loop.call_soon_threadsafe(waiter.ready.set_result, None)


class _NoPipelineAccounting:
    """Mark an execution envelope without prior accounting."""


class _NoPipelineObserver:
    """Mark an execution envelope without an active RTT observer."""


class _NoPreparedTerminalExecution:
    """Mark a native statement that did not use terminal prerendering."""


_NO_PIPELINE_ACCOUNTING = _NoPipelineAccounting()
_NO_PIPELINE_OBSERVER = _NoPipelineObserver()
_NO_PREPARED_TERMINAL_EXECUTION = _NoPreparedTerminalExecution()


class SqlBackendExecutor[
    ProfileT: ServerPlanBackendProfile = ServerPlanBackendProfile,
](BackendExecutor):
    """BackendExecutor for SQL backends (SQLite, PostgreSQL, MariaDB, DoltDB).

    Wraps a _SqlConnectionCore to execute compiled SqlStepIR grammar.
    """

    _native_pipeline_receipt_active: bool = False
    _native_batch_statement_count: int = 0
    _native_batch_driver_round_trips: int = 0
    _native_batch_execution_count: int = 0
    _last_reported_native_flush_count: int = 0
    _last_native_accounting: PipelineAccounting | _NoPipelineAccounting = _NO_PIPELINE_ACCOUNTING
    _native_pipeline_observer: RttTrackingContext | _NoPipelineObserver = _NO_PIPELINE_OBSERVER
    _native_pipeline_statement_count: int = 0
    _native_pipeline_driver_round_trip_count: int = 0

    def __init__(
        self,
        txn_or_conn: PlanTarget,
        *,
        is_write_transaction: bool = False,
        session_id: SessionId | None = None,
        backend_profile: ProfileT,
        planning_catalog: PlanningCatalog | None = None,
        strict_permission_provenance_enforcement: bool | None = None,
        permission_provenance_secret: bytes | None = None,
    ) -> None:
        """Initialize with a transaction-scoped SQL execution target.

        The executor extracts the underlying _SqlConnectionCore for grammar execution
        and requires the transaction's immutable ``planning_catalog`` snapshot.
        The caller must pass the resolved backend profile that was selected for
        this execution path so lowering, optimization, and compilation all
        observe the same backend policy.

        Strict permission provenance
        =============================

        Omitted ``strict_permission_provenance_enforcement`` and
        ``permission_provenance_secret`` resolve **only** from environment
        variables (see ``resolve_strict_permission_provenance_enforcement`` /
        ``resolve_permission_provenance_secret``). Nested SQL must receive an
        explicit ``CompilationContext`` (or constructor kwargs) from the parent
        executor; strict mode is never inferred from context variables alone.
        """
        from impl.common.l2200_sql_dialect.sql_connection import _SqlConnectionCore as _SqlConn

        if isinstance(txn_or_conn, _SqlConn):
            msg = "SqlBackendExecutor requires a transaction target, not a _SqlConnectionCore"
            raise TypeError(msg)
        self._txn = txn_or_conn
        txn_conn = _unwrap_sql_connection(txn_or_conn)
        if isinstance(txn_conn, _SqlConn):
            self._conn = txn_conn
        else:
            self._conn = _unwrap_sql_connection(txn_or_conn)
        self._is_write_transaction: bool = is_write_transaction or _target_is_write_transaction(
            txn_or_conn,
        )
        self._session_id: SessionId | None = session_id
        self._backend_profile: ProfileT = backend_profile
        self._native_pipeline_receipt_active = False
        self._native_pipeline_execution_lock = _PipelineExecutionLock()
        self._native_pipeline_context: ContextVar[_PipelineScopeLease | None] = ContextVar(
            f"native_pipeline_context_{id(self)}",
            default=None,
        )
        self._native_pipeline_executed = False
        self._last_native_pipeline_flush_count: int | None = None
        self._native_batch_statement_count = 0
        self._native_batch_driver_round_trips = 0
        self._native_batch_execution_count = 0
        self._last_reported_native_flush_count = 0
        self._native_pipeline_statement_count = 0
        self._native_pipeline_driver_round_trip_count = 0
        self._last_native_accounting = _NO_PIPELINE_ACCOUNTING
        self._native_pipeline_observer = _NO_PIPELINE_OBSERVER
        self._planning_catalog = _require_planning_catalog(planning_catalog, txn_or_conn)
        self._strict_permission_provenance_enforcement = resolve_strict_permission_provenance_enforcement(
            strict_permission_provenance_enforcement,
        )
        self._permission_provenance_secret = resolve_permission_provenance_secret(
            permission_provenance_secret,
        )
        self._prepared_steps_by_ref: dict[str, _PreparedStep] = {}
        self._executor_runtime_values: Mapping[
            RuntimeParameterSlotName,
            object,
        ] = {}
        self._plan_sql_rtt_tracked = False

    def prepare_scheduling_effects(
        self: SqlBackendExecutor,
        effects: frozenset[SchedulingEffect],
    ) -> None:
        """Prepare SQL transaction state required by physical scheduling effects."""
        if SchedulingEffect.REQUIRES_EXECUTOR_TEMPORARY_RELATION in effects:
            self._conn._enable_temporary_writes_in_read_transaction()
        if SchedulingEffect.REQUIRES_STABLE_READ_SNAPSHOT in effects:
            self._conn._require_stable_read_snapshot()

    def scheduling_effect_setup_async(
        self: SqlBackendExecutor,
        effects: frozenset[SchedulingEffect],
    ) -> Awaitable[None]:
        """Return asynchronous SQL transaction setup for physical effects."""

        async def _prepare_async() -> None:
            if SchedulingEffect.REQUIRES_EXECUTOR_TEMPORARY_RELATION in effects:
                await self._conn._enable_temporary_writes_in_read_transaction_async()
            if SchedulingEffect.REQUIRES_STABLE_READ_SNAPSHOT in effects:
                await self._conn._require_stable_read_snapshot_async()

        return _prepare_async()

    def bind_executor_runtime_values(
        self: SqlBackendExecutor,
        values: Mapping[RuntimeParameterSlotName, object],
    ) -> None:
        """Bind executor-owned runtime values for late SQL parameter slots."""
        self._executor_runtime_values = values

    def _consume_plan_sql_rtt_tracking(self: SqlBackendExecutor) -> bool:
        """Track one driver RTT per ServerPlan execution envelope."""
        if self._plan_sql_rtt_tracked:
            return False
        self._plan_sql_rtt_tracked = True
        return True

    def validate_execution_ir(self: SqlBackendExecutor, ir: SqlStepIR) -> None:
        """Strict manifest validation runs in ``_permission_provenance_context`` (context entry).

        Avoid calling ``validate_strict_permission_provenance_manifest`` again here: that
        duplicates work already done by ``strict_permission_provenance_execution_context``.
        """
        del ir

    def invalidate_session_validation_after_write[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
    ) -> None:
        """Discard identity caches after a successful ``sys_sessions`` write."""
        written_tables = {str(table) for table in step.tables_written()}
        if "sys_sessions" not in written_tables:
            return
        session_id = self._session_id
        if not isinstance(session_id, SessionId) or session_id.is_schema_session():
            return
        session_id_sql = session_id.unwrap_to_sql()
        if isinstance(self._conn, _SessionValidationCacheCarrier):
            self._conn._validated_sessions.clear()
            self._conn._validated_session_user_ids.clear()
        preamble_ids = self._resolve_sql_preamble_ref_ids()
        if preamble_ids is not None:
            preamble_ids.discard(ServerPlanRefId("__session_validation"))
            preamble_ids.discard(ServerPlanRefId("__apply_sql_session_context"))
        for txn in self._build_txn_candidates():
            if _has_session_validation_flag(txn):
                object.__setattr__(txn, "_session_validated_in_enter", False)
            for attribute in (
                DynamicFieldName("_nera_validated_session_user_id"),
                DynamicFieldName("_nera_validated_session_type"),
            ):
                if _has_static_private_attr(txn, attribute):
                    object.__setattr__(txn, attribute, None)

    def _permission_provenance_context(
        self: SqlBackendExecutor,
        sql_ir: SqlStepIR,
    ) -> AbstractContextManager[None]:
        """Return the lower-layer provenance gate context for this SQL IR."""
        if not isinstance(sql_ir, SqlStepIR):
            return nullcontext()
        if sql_ir.grammar is None:
            return nullcontext()
        if sql_ir.allow_empty_provenance_manifest and not sql_ir.provenance_manifest:
            return nullcontext()
        provenance_context: AbstractContextManager[None] = strict_permission_provenance_execution_context(
            sql_ir.provenance_manifest,
            strict_enforcement=self._strict_permission_provenance_enforcement,
            secret=self._permission_provenance_secret,
        )
        return provenance_context

    @staticmethod
    def _class_name_to_snake(step_name: PythonClassName) -> PlanStepMethodName:
        step_name_for_snake = step_name.replace("SQLite", "Sqlite")
        acronym_split = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", step_name_for_snake)
        return PlanStepMethodName(re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", acronym_split).lower())

    @classmethod
    def _step_method_name[StepResultT](
        cls,
        step: ServerPlanStep[StepResultT],
        *,
        prefix: PlanStepMethodPrefix,
    ) -> PlanStepMethodName:
        step_name = cls._class_name_to_snake(PythonClassName(type(step).__name__))
        return PlanStepMethodName(f"_{prefix}_{step_name}")

    def _reset_native_pipeline_receipt(self: SqlBackendExecutor) -> None:
        """Discard receipt state from an earlier execution envelope."""
        self._native_pipeline_statement_count = 0
        self._native_pipeline_driver_round_trip_count = 0
        self._native_pipeline_receipt_active = False
        self._native_pipeline_executed = False
        self._last_native_pipeline_flush_count = None
        self._native_batch_statement_count = 0
        self._native_batch_driver_round_trips = 0
        self._native_batch_execution_count = 0
        self._plan_sql_rtt_tracked = False

    def begin_native_pipeline_receipt(self: SqlBackendExecutor) -> None:
        """Start recording one backend-native pipeline scope."""
        assert isinstance(self._native_pipeline_observer, _NoPipelineObserver)
        observer = RttTrackingContext(propagate_to_parent=True)
        observer.__enter__()
        self._reset_native_pipeline_receipt()
        self._native_pipeline_observer = observer
        self._last_native_accounting = _NO_PIPELINE_ACCOUNTING
        self._native_pipeline_receipt_active = True
        self._last_reported_native_flush_count = 0

    def end_native_pipeline_receipt(self: SqlBackendExecutor) -> None:
        """Close the scope and retain the transport's observed round trips."""
        self._native_pipeline_receipt_active = False
        observer = self._native_pipeline_observer
        if isinstance(observer, RttTrackingContext):
            observer.__exit__()
            observed_round_trips = observer.total_round_trips
            self._last_native_pipeline_flush_count = (
                observed_round_trips if observed_round_trips > 0 else self._native_pipeline_driver_round_trip_count
            )
            self._native_pipeline_observer = _NO_PIPELINE_OBSERVER

    def failed_native_pipeline_execution_receipt(
        self: SqlBackendExecutor,
    ) -> NativePipelineExecutionReceipt:
        """Return native SQL counts even when a closed post-op raises."""
        return self.native_pipeline_execution_receipt(None, sql_group_count=0)

    def native_pipeline_execution_receipt(
        self: SqlBackendExecutor,
        accounting: PipelineAccounting | None,
        *,
        sql_group_count: int,
    ) -> NativePipelineExecutionReceipt:
        del sql_group_count
        if accounting is None:
            flush_count = self._last_native_pipeline_flush_count
            if flush_count is None:
                flush_count = self._native_pipeline_driver_round_trip_count
            statement_count = self._native_pipeline_statement_count
            if statement_count == 0 and flush_count > 0:
                statement_count = 1
            return NativePipelineExecutionReceipt(
                statement_count=statement_count,
                sql_group_count=statement_count,
                flush_count=flush_count,
                transaction_control_count=0,
            )
        if self._backend_profile.traits.backend_type is BackendType.MARIADB:
            statement_count = max(self._native_pipeline_statement_count, self._native_batch_statement_count)
            flush_count = max(
                0,
                accounting.driver_round_trips - self._native_batch_execution_count + self._native_batch_driver_round_trips,
            )
            return NativePipelineExecutionReceipt(
                statement_count=statement_count,
                sql_group_count=accounting.sql_groups_executed,
                flush_count=flush_count,
                transaction_control_count=accounting.transaction_control_count,
            )
        flush_count = self._last_native_pipeline_flush_count
        if flush_count is not None:
            flush_count = max(0, flush_count)
        elif self._native_pipeline_executed:
            flush_count = self._native_pipeline_driver_round_trip_count
        else:
            flush_count = accounting.driver_round_trips - self._native_batch_execution_count + self._native_batch_driver_round_trips
            if (
                isinstance(self._last_native_accounting, PipelineAccounting)
                and accounting is self._last_native_accounting
                and flush_count < self._last_reported_native_flush_count
            ):
                raise ValueError("Observed native dispatch accounting cannot decrease")
            self._last_native_accounting = accounting
            self._last_reported_native_flush_count = flush_count
        return NativePipelineExecutionReceipt(
            statement_count=accounting.db_statements_executed,
            sql_group_count=accounting.sql_groups_executed,
            flush_count=flush_count,
            transaction_control_count=accounting.transaction_control_count,
        )

    @contextmanager
    def pipeline_execution_scope(self: SqlBackendExecutor) -> Generator[None]:
        """Own receipt lifetime and the synchronous SQL pipeline.

        Schema execution keeps the driver scope as a no-op. The executor owns
        this decision so generic plans cannot inspect driver state. See
        ``docs/design/SERVERPLAN_GENERIC_TARGET_ARCHITECTURE.md``.
        """
        from l2000_connection.schema_transaction import _InternalSchemaTransaction

        inherited_marker = self._native_pipeline_context.get()
        if inherited_marker is not None and inherited_marker.borrow():
            try:
                yield
            finally:
                inherited_marker.release()
            return
        with self._native_pipeline_execution_lock.acquire_sync():
            self._reset_native_pipeline_receipt()
            scope_marker = _SyncPipelineScopeLease()
            scope_token = self._native_pipeline_context.set(scope_marker)
            try:
                self.begin_native_pipeline_receipt()
                try:
                    if isinstance(self._txn, _InternalSchemaTransaction):
                        try:
                            yield
                        finally:
                            scope_marker.close_and_wait()
                    else:
                        with self._conn.native_pipeline():
                            try:
                                yield
                            finally:
                                scope_marker.close_and_wait()
                finally:
                    self.end_native_pipeline_receipt()
            finally:
                self._native_pipeline_context.reset(scope_token)

    def async_pipeline_execution_scope(self: SqlBackendExecutor) -> AbstractAsyncContextManager[None]:
        """Return the async SQL data-write execution scope."""
        return self._async_pipeline_execution_scope_async()

    @asynccontextmanager
    async def _async_pipeline_execution_scope_async(self: SqlBackendExecutor) -> AsyncGenerator[None]:
        """Use the available async SQL pipeline only for data-write execution.

        The shared lock prevents sync and async scopes from sharing mutable
        receipt state or one native driver scope.
        """
        from l2000_connection.schema_transaction import _InternalSchemaTransaction

        inherited_marker = self._native_pipeline_context.get()
        if inherited_marker is not None and inherited_marker.borrow():
            try:
                yield
            finally:
                inherited_marker.release()
            return
        loop = asyncio.get_running_loop()
        async with self._native_pipeline_execution_lock.acquire_async():
            self._reset_native_pipeline_receipt()
            scope_marker = _AsyncPipelineScopeLease(loop=loop, drained=asyncio.Event())
            scope_token = self._native_pipeline_context.set(scope_marker)
            try:
                self.begin_native_pipeline_receipt()
                try:
                    if (
                        not self._is_write_transaction
                        or isinstance(self._txn, _InternalSchemaTransaction)
                        or not self._conn.has_native_pipeline_async()
                    ):
                        try:
                            yield
                        finally:
                            await scope_marker.wait_until_drained_async()
                    else:
                        async with self._conn.native_pipeline_async():
                            try:
                                yield
                            finally:
                                await scope_marker.wait_until_drained_async()
                finally:
                    self.end_native_pipeline_receipt()
            finally:
                self._native_pipeline_context.reset(scope_token)

    def lower_step[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[StepResultT]]:
        """Apply the nearest semantic lowering override before default lowering."""
        for step_cls in type(step).__mro__:
            method_name = f"_lower_{SqlBackendExecutor._class_name_to_snake(PythonClassName(step_cls.__name__))}"
            for executor_cls in type(self).__mro__:
                if method_name not in executor_cls.__dict__:
                    continue
                lower_method = cast(
                    Callable[[ServerPlanStep[StepResultT], LoweringContext], Sequence[ServerPlanStep[StepResultT]]],
                    executor_cls.__dict__[method_name].__get__(self, type(self)),
                )
                return lower_method(step, ctx)
        return step.lower(ctx)

    def _lower_conditional_step[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        ctx: LoweringContext,
    ) -> Sequence[HeterogeneousServerPlanStep]:
        from impl.common.l2070_server_plan.steps.sql_conditional import (
            SqlConditionalStep,
        )
        from l2070_batching.conditional_step import ConditionalStep

        if not isinstance(step, ConditionalStep):
            msg = "SQL conditional lowering requires ConditionalStep."
            raise TypeError(msg)
        from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
            encapsulate_commit_dependency_refs,
        )

        then_steps, else_steps = step.conditional_branch_steps()
        lowered_then_steps = tuple(lowered for child in then_steps for lowered in self.lower_step(child, ctx))
        lowered_else_steps = tuple(lowered for child in else_steps for lowered in self.lower_step(child, ctx))
        encapsulate_commit_dependency_refs(ctx, (*lowered_then_steps, *lowered_else_steps), step.ref_id)
        return (
            SqlConditionalStep.from_semantic(
                step,
                then_steps=lowered_then_steps,
                else_steps=lowered_else_steps,
                same_plan_write_transport=ctx.backend_profile.traits.same_plan_write_transport,
            ),
        )

    def _lower_flatten_result_sequences_step(
        self: SqlBackendExecutor,
        step: FlattenResultSequencesStep[DatabaseObjectRow],
        ctx: LoweringContext,
    ) -> Sequence[FlattenResultsStep | MaterializedFlattenSequenceResultsAfterDepsStep]:
        """Choose the declared SQL or materialized collection transport.

        The semantic step stays backend-neutral. This physical boundary follows
        ``EXPLICIT_SQL_TRANSPORT_AND_RUNTIME_PUBLICATION_ARCHITECTURE.rst``.
        """
        from l1000_schema.schema_def import DatabaseObjectRow
        from impl.common.l2070_server_plan.steps.collect_results import (
            FlattenResultSequencesStep,
            FlattenResultsStep,
            MaterializedFlattenSequenceResultsAfterDepsStep,
        )
        from l2070_batching.backend_profile import SamePlanWriteTransport
        from l2070_batching.planning_contract import ResultTransportKind

        if not isinstance(step, FlattenResultSequencesStep):
            msg = "Sequence collection lowering requires FlattenResultSequencesStep."
            raise TypeError(msg)
        transport = step.planning_contract().result_transport
        if transport.kind is not ResultTransportKind.COLLECT_VALUES or not transport.collection_flatten:
            msg = "Sequence collection lowering requires a flattening COLLECT_VALUES contract."
            raise TypeError(msg)
        source_refs = transport.collection_source_refs
        model_cls = transport.collection_model_cls
        if model_cls is None or not issubclass(model_cls, DatabaseObjectRow):
            msg = "Sequence collection lowering requires a DatabaseObjectRow collection model class."
            raise TypeError(msg)
        write_transport = ctx.backend_profile.traits.same_plan_write_transport
        if write_transport is SamePlanWriteTransport.DATA_MODIFYING_CTE:
            return (
                FlattenResultsStep(
                    step.ref_id,
                    [str(source_ref) for source_ref in source_refs],
                    source_model_cls=model_cls,
                ),
            )
        if write_transport is SamePlanWriteTransport.ORDERED_STATEMENTS:
            return (
                MaterializedFlattenSequenceResultsAfterDepsStep(
                    step.ref_id,
                    source_refs,
                    model_cls,
                ),
            )
        msg = (
            "FlattenResultSequencesStep requires DATA_MODIFYING_CTE or ORDERED_STATEMENTS "
            f"same-plan write transport; backend {ctx.backend_profile.backend_type.value!r} declares "
            f"{write_transport.value!r}."
        )
        raise RuntimeError(msg)

    def register_transaction_selection(
        self: SqlBackendExecutor, selection: PublicationSelectionContract, table: SqlTableName, hints: SqlColumnTypeHints
    ) -> None:
        from impl.common.l2200_sql_dialect.sql_connection import _SqlConnectionCore

        if not isinstance(self._conn, _SqlConnectionCore):
            raise TypeError("Physical publication selection requires a SQL connection owner")
        self._conn._register_transaction_selection(selection, table, hints)

    def compile_step[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        ctx: CompilationContext,
    ) -> CompiledStep[StepResultT]:
        """Apply ``_compile_xxx`` only for a deliberately preserved step.

        Compilation is not a fallback backend selector. Dialect rendering occurs
        after lowering ownership is settled, so generic/default compile methods
        must not branch on optional dialect presence.
        """
        # Lowering owns the complete CompilationContext. In particular, the
        # versioning domain must not be reconstructed from a step's private model
        # fields here: doing so makes executor behavior depend on incidental step
        # layout and hides a missing symbolic planning fact.
        from impl.common.l2200_sql_dialect.sql_connection import _SqlConnectionCore
        from l2070_batching.compilation import CteReference

        if isinstance(ctx.sql_handle, _SqlConnectionCore):
            for selection, table, hints in ctx.sql_handle._transaction_selection_snapshot():
                ctx.publication_selections.setdefault(
                    selection.identity,
                    CteReference(
                        ref_id=ServerPlanRefId(table),
                        columns=tuple(sorted(str(column) for column in selection.columns)),
                        column_type_hints=hints,
                        source_tables=frozenset({str(selection.identity.source_table)}),
                        ephemeral=False,
                    ),
                )
        method_name = self._step_method_name(
            step,
            prefix=PlanStepMethodPrefix("compile"),
        )
        for cls in type(self).__mro__:
            if method_name in cls.__dict__:
                compile_method = cast(
                    Callable[[ServerPlanStep[StepResultT], CompilationContext], CompiledStep[StepResultT]],
                    cls.__dict__[method_name].__get__(self, type(self)),
                )
                return compile_method(step, ctx)
        return super().compile_step(step, ctx)

    def _build_txn_candidates(self: SqlBackendExecutor) -> tuple[PlanTarget, ...]:
        """Collect the transaction and related objects that may carry context."""
        from impl.common.l2070_server_plan.base_server_plan import BaseServerPlan
        from impl.common.l7300_sql_versioned_transactions.sql_write_transaction import (
            SqlWriteTransactionBase,
        )

        txn = self._txn_or_none()
        candidates: list[PlanTarget] = []

        def _append_candidate(value: object | None) -> None:
            if value is None or value in candidates:
                return
            candidates.append(cast("PlanTarget", value))
            if isinstance(value, _WrappedTxnCarrier):
                wrapped_txn = value._txn
                if wrapped_txn is not None and wrapped_txn not in candidates:
                    candidates.append(cast("PlanTarget", wrapped_txn))

        if isinstance(txn, _CallbackVersionedTxnCarrier):
            _append_candidate(txn._callback_versioned_txn)
        base_txn = txn._base_txn if isinstance(txn, _BaseTxnCarrier) else None
        if isinstance(base_txn, _CallbackVersionedTxnCarrier):
            _append_candidate(base_txn._callback_versioned_txn)
        _append_candidate(txn)
        if isinstance(txn, _WrappedTxnCarrier):
            _append_candidate(txn._txn)
        if isinstance(txn, _SqlConnectionCore):
            active_plan = txn._active_plan
            if isinstance(active_plan, BaseServerPlan):
                active_plan_txn = active_plan._txn
                _append_candidate(active_plan_txn)
        if isinstance(txn, _PlanCarrier):
            txn_plan = txn._plan
            if isinstance(txn_plan, BaseServerPlan):
                _append_candidate(txn_plan._txn)
        if isinstance(txn, SqlWriteTransactionBase):
            plan = txn._plan
            if isinstance(plan, BaseServerPlan):
                plan_txn: PlanTarget = plan._txn
                _append_candidate(plan_txn)
        for candidate in tuple(candidates):
            if isinstance(candidate, _versioned_transaction_types()):
                base = cast(Any, candidate)._base_txn
                _append_candidate(base)
        return tuple(candidates)

    def _resolve_sql_preamble_ref_ids(
        self: SqlBackendExecutor,
    ) -> set[ServerPlanRefId] | None:
        """Return the transaction-owned set used to de-duplicate session preamble steps."""
        from impl.common.l7300_sql_versioned_transactions.sql_read_transaction import (
            SqlReadTransactionBase,
        )
        from impl.common.l7300_sql_versioned_transactions.sql_write_transaction import (
            SqlWriteTransactionBase,
        )

        for candidate in self._build_txn_candidates():
            if isinstance(candidate, _versioned_transaction_types()) and (cast(Any, candidate)._base_txn is not None):
                continue
            if isinstance(
                candidate,
                (
                    SqlReadTransactionBase,
                    SqlWriteTransactionBase,
                ),
            ):
                satisfied_ref_ids: set[ServerPlanRefId] | None = candidate._sql_preamble_satisfied_ref_ids
                return satisfied_ref_ids
        return None

    def execute_lifecycle_effect(
        self: SqlBackendExecutor,
        effect: PipelineLifecycleEffect,
        runtime_txn: object | None,
    ) -> bool:
        """Apply SQL-backend transaction state for declarative lifecycle effects."""
        del runtime_txn
        from impl.common.l2070_server_plan.steps.session_validation import (
            MarkSqlPreambleSessionContextAppliedEffect,
            MarkSqlPreambleSessionValidatedEffect,
        )

        if isinstance(effect, MarkSqlPreambleSessionContextAppliedEffect):
            for txn in self._build_txn_candidates():
                if _has_sql_session_context_flag(txn):
                    object.__setattr__(txn, "_sql_session_context_applied_via_plan", True)
            return True
        if isinstance(effect, MarkSqlPreambleSessionValidatedEffect):
            for txn in self._build_txn_candidates():
                if _has_session_validation_flag(txn):
                    object.__setattr__(txn, "_session_validated_in_enter", True)
            return True
        return False

    def _extract_versioning_info(self: SqlBackendExecutor) -> _VersioningInfo:
        """Extract all versioning context from the transaction candidates."""
        txn_candidates = self._build_txn_candidates()
        branch_id, is_versioned = _extract_branch_id(txn_candidates)
        session_id_str: str | None = _unwrap_session_id(
            _resolve_session_id_from_candidates(self._session_id, txn_candidates),
        )
        session_id_source = _resolve_session_source_from_candidates(txn_candidates)

        lazy_revision: ScalarServerRef[RevisionId] | None = None
        lazy_branch: ScalarServerRef[BranchId] | None = None
        branch_tip_materialization_ref: ScalarServerRef[BranchTipMaterialization] | None = None
        revision_id: str | None = None
        explicit_revision_id: str | None = None
        branch_table: SqlTableName | None = None
        branch_id_column = SqlColumnName("sys_id")
        branch_tip_revision_column = SqlColumnName("tip_revision_sys_id")
        branch_deleted_column = SqlColumnName("sys_deleted")
        staging_ctx_factory: StagingContextFactory | None = None
        branch_tip_materialized = True
        vtxn_materialization: object | None = None
        versioning_domain: type[VersioningDomain] | None = None

        vtxn: object | None = None
        for candidate in txn_candidates:
            if isinstance(candidate, _versioned_transaction_types()):
                vtxn = candidate
                break

        if vtxn is not None:
            is_versioned = True
            vtxn_snapshot = cast(
                VersionedTransactionPlanningSnapshotProvider,
                vtxn,
            ).versioned_transaction_planning_snapshot()
            vtxn_materialization = vtxn_snapshot.branch_tip_materialization
            if vtxn_materialization is None:
                msg = (
                    "Versioned query planning requires tip materialization from persisted branch metadata "
                    "or the explicit historical-revision query shape"
                )
                raise TypeError(msg)
            if vtxn_materialization is not None and not isinstance(vtxn_materialization, ScalarServerRef):
                branch_tip_materialized = vtxn_materialization != BranchTipMaterialization.TIPLESS
                branch_tip_materialization_ref = ServerRefs.scalar(vtxn_materialization)
            elif isinstance(vtxn_materialization, ScalarServerRef):
                branch_tip_materialization_ref = vtxn_materialization
                # Unknown plan-owned branch metadata must use the sparse path.
                # Assuming a materialized tip can silently hide inherited rows.
                branch_tip_materialized = False
            raw_lazy_revision = vtxn_snapshot.lazy_revision
            raw_lazy_branch = vtxn_snapshot.lazy_branch
            revision_id = _unwrap_branded_to_str(vtxn_snapshot.revision_id)
            if revision_id is None and isinstance(raw_lazy_revision, LazyResult) and raw_lazy_revision._state == LazyState.RESOLVED:
                revision_id = _unwrap_branded_to_str(raw_lazy_revision._value)
            if branch_id is None and isinstance(raw_lazy_branch, LazyResult):
                pre_populated_branch = raw_lazy_branch._pre_populated
                if pre_populated_branch is not None:
                    branch_id = _stringify_scalar(pre_populated_branch)
                elif raw_lazy_branch._state == LazyState.RESOLVED and raw_lazy_branch._value is not None:
                    branch_id = _stringify_scalar(raw_lazy_branch._value)
            if (
                branch_id is None
                and raw_lazy_branch is not None
                and not isinstance(
                    raw_lazy_branch,
                    LazyResult | ScalarServerRef,
                )
            ):
                branch_id = _stringify_scalar(raw_lazy_branch)
            explicit_rid: object = vtxn_snapshot.explicit_base_revision_id
            if explicit_rid is None and (not isinstance(vtxn, _versioned_write_transaction_types()) or not branch_tip_materialized):
                explicit_rid = vtxn_snapshot.base_revision_id
            if branch_id is None and isinstance(raw_lazy_branch, ScalarServerRef):
                branch_id = _extract_scalar_server_ref_value(cast("ScalarServerRef[object]", raw_lazy_branch))
            if explicit_rid is not None:
                explicit_revision_id = _unwrap_branded_to_str(explicit_rid)
                if revision_id is None:
                    revision_id = explicit_revision_id

            if revision_id is not None:
                direct_revision = vtxn_snapshot.revision_id
                if direct_revision is None and explicit_rid is not None:
                    direct_revision = RevisionId(str(explicit_rid))
                if direct_revision is not None:
                    lazy_revision = ServerRefs.scalar(direct_revision)
                elif lazy_revision is None:
                    lazy_revision = ServerRefs.scalar(RevisionId(revision_id))
            elif (
                isinstance(raw_lazy_revision, LazyResult)
                and raw_lazy_revision._state == LazyState.RESOLVED
                and raw_lazy_revision._value is not None
            ):
                resolved_revision = raw_lazy_revision._value
                lazy_revision = ServerRefs.scalar(
                    resolved_revision if isinstance(resolved_revision, RevisionId) else RevisionId(str(resolved_revision))
                )
            elif isinstance(raw_lazy_revision, ScalarServerRef):
                lazy_revision = raw_lazy_revision
            elif raw_lazy_revision is not None:
                lazy_revision_deps = tuple(lazy_param_deps(raw_lazy_revision))
                if len(lazy_revision_deps) > 1:
                    msg = f"Expected at most one lazy revision dependency, got {lazy_revision_deps!r}"
                    raise RuntimeError(msg)
                if lazy_revision_deps:
                    lazy_revision = ServerRefs.from_ref_id(
                        ServerPlanRefId(lazy_revision_deps[0]),
                        variant="scalar",
                        type_hint=RevisionId,
                    )
            if branch_id is not None:
                lazy_branch = ServerRefs.scalar(BranchId(branch_id))
            elif (
                isinstance(raw_lazy_branch, LazyResult)
                and raw_lazy_branch._state == LazyState.RESOLVED
                and raw_lazy_branch._value is not None
            ):
                resolved_branch = raw_lazy_branch._value
                lazy_branch = ServerRefs.scalar(
                    resolved_branch if isinstance(resolved_branch, BranchId) else BranchId(str(resolved_branch))
                )
            elif isinstance(raw_lazy_branch, ScalarServerRef):
                lazy_branch = raw_lazy_branch
            elif raw_lazy_branch is not None:
                lazy_branch_deps = tuple(lazy_param_deps(raw_lazy_branch))
                if len(lazy_branch_deps) > 1:
                    msg = f"Expected at most one lazy branch dependency, got {lazy_branch_deps!r}"
                    raise RuntimeError(msg)
                if lazy_branch_deps:
                    lazy_branch = ServerRefs.from_ref_id(
                        ServerPlanRefId(lazy_branch_deps[0]),
                        variant="scalar",
                        type_hint=BranchId,
                    )
            domain = vtxn_snapshot.domain
            if domain is not None:
                versioning_domain = domain
                branch_table = get_table_name(domain.branch_model)
                branch_id_column = SqlColumnName(
                    get_db_column_name(domain.branch_model, DynamicFieldName("sys_id")),
                )
                branch_tip_revision_column = SqlColumnName(
                    get_db_column_name(
                        domain.branch_model,
                        DynamicFieldName("tip_revision_sys_id"),
                    ),
                )
                branch_deleted_column = SqlColumnName(
                    get_db_column_name(domain.branch_model, DynamicFieldName("deleted")),
                )
            staging_ctx_factory = vtxn_snapshot.staging_context_factory

        if versioning_domain is None:
            from l7000_versioned_schema.versioned_schema import VersioningDomain

            for candidate in txn_candidates:
                candidate_domain = _read_private_attr(candidate, DynamicFieldName("domain"))
                if candidate_domain is None:
                    candidate_domain = _read_private_attr(candidate, DynamicFieldName("_versioning_domain"))
                if candidate_domain is None:
                    candidate_domain = _read_private_attr(candidate, DynamicFieldName("_active_readthrough_domain"))
                if isinstance(candidate_domain, type) and issubclass(candidate_domain, VersioningDomain):
                    versioning_domain = candidate_domain
                    is_versioned = True
                    branch_table = get_table_name(candidate_domain.branch_model)
                    branch_id_column = SqlColumnName(
                        get_db_column_name(candidate_domain.branch_model, DynamicFieldName("sys_id")),
                    )
                    branch_tip_revision_column = SqlColumnName(
                        get_db_column_name(
                            candidate_domain.branch_model,
                            DynamicFieldName("tip_revision_sys_id"),
                        ),
                    )
                    branch_deleted_column = SqlColumnName(
                        get_db_column_name(candidate_domain.branch_model, DynamicFieldName("deleted")),
                    )
                    break

        if vtxn is None or vtxn_materialization is None:
            branch_tip_materialized = _resolve_branch_tip_materialized(
                branch_tip_materialized,
                txn_candidates,
            )

        if is_versioned and versioning_domain is None:
            msg = "SqlBackendExecutor._extract_versioning_info requires an explicit versioning_domain for versioned execution."
            raise RuntimeError(msg)

        return _VersioningInfo(
            branch_id=BranchIdText(branch_id) if branch_id is not None else None,
            revision_id=revision_id,
            explicit_revision_id=explicit_revision_id,
            session_id_source=session_id_source,
            session_id_str=(SessionIdText(session_id_str) if session_id_str is not None else None),
            is_versioned=is_versioned,
            lazy_revision=lazy_revision,
            lazy_branch=lazy_branch,
            branch_tip_materialization_ref=branch_tip_materialization_ref,
            branch_table=branch_table,
            branch_id_column=branch_id_column,
            branch_tip_revision_column=branch_tip_revision_column,
            branch_deleted_column=branch_deleted_column,
            staging_ctx_factory=staging_ctx_factory,
            branch_tip_materialized=branch_tip_materialized,
            versioning_domain=versioning_domain,
        )

    def _validate_ir(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
    ) -> SqlStepIR:
        if not isinstance(ir, SqlStepIR):
            msg = (
                "SqlBackendExecutor only executes SqlStepIR; "
                f"got {type(ir).__name__}. Lower this path to SQL-bearing IR before execution."
            )
            raise TypeError(msg)
        return ir

    def _trace_ir_if_enabled(
        self: SqlBackendExecutor,
        sql_ir: SqlStepIR,
    ) -> None:
        from impl.common.l2070_server_plan.pipeline_trace import is_trace_enabled, trace_execute_ir

        if not is_trace_enabled():
            return

        preview = build_trace_preview(self._conn.get_dialect(), sql_ir)
        if isinstance(preview, SqlTracePreview):
            trace_execute_ir(
                sql_ir,
                sql_preview=preview.sql,
                params_preview=preview.params or None,
            )

    def _normalize_ir(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
    ) -> tuple[SqlStepIR, bool]:
        """Validate and close grammar before describing or executing its physical shape."""
        sql_ir = self._validate_ir(ir)
        if sql_ir.grammar is not None:
            grammar = prepare_sql_grammar_for_execution(sql_ir.grammar)
            if grammar is not sql_ir.grammar:
                sql_ir = replace(sql_ir, grammar=grammar)
        return sql_ir, is_statement_batch_sql_ir(sql_ir)

    def _validate_and_prepare_ir(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
    ) -> tuple[SqlStepIR, bool]:
        """Close SQL grammar before a write can materialize its backend transaction."""
        sql_ir, _is_normalized_batch = self._normalize_ir(ir)
        if sql_ir.grammar is not None:
            grammar = self._statement_batch_executable_stmt(
                sql_ir.grammar,
                backend_type=self._backend_profile.traits.backend_type,
                needs_returning=sql_ir.needs_returning,
            )
            if grammar is not sql_ir.grammar:
                sql_ir = replace(sql_ir, grammar=grammar)
        is_statement_batch = is_statement_batch_sql_ir(sql_ir)
        if not is_statement_batch:
            self._trace_ir_if_enabled(sql_ir)
        return sql_ir, is_statement_batch

    def _dispatch_compile_ctx_runtime_ir(
        self: SqlBackendExecutor,
        sql_ir: object,
        *,
        is_async: bool,
        execute_sync: Callable[[object, object, object], RawResult],
        execute_async: Callable[[object, object, object], Awaitable[RawResult]],
    ) -> RawResult | Awaitable[RawResult]:
        compile_ctx = self.get_compilation_context()
        if is_async:
            return execute_async(self._txn, compile_ctx, sql_ir)
        return execute_sync(self._txn, compile_ctx, sql_ir)

    def _dispatch_simple_ir(
        self: SqlBackendExecutor,
        sql_ir: SqlStepIR,
    ) -> RawResult:
        """Execute a non-batch IR synchronously after preparation is complete."""
        return self._execute_simple_sql_ir(sql_ir)

    async def _dispatch_simple_ir_async(
        self: SqlBackendExecutor,
        sql_ir: SqlStepIR,
    ) -> RawResult:
        """Execute a non-batch IR asynchronously after preparation is complete."""
        return await self._execute_simple_sql_ir_async(sql_ir)

    def _finish_inline_step_result[StepResultT](
        self: SqlBackendExecutor,
        *,
        _step: ServerPlanStep[StepResultT],
        compiled: CompiledStep[StepResultT],
        raw: RawResult,
        resolved: MutableResolvedRefs,
    ) -> object:
        from impl.common.l2070_server_plan.steps._compile_helpers import _resolve_sql_conn
        from l2070_batching.executor import no_sql_context

        materialization_hydrator = bind_runtime_hydrator(
            ModelHydrator(),
            sql_conn=_resolve_sql_conn(self._txn, self._conn),
            txn=self._txn,
        )
        with no_sql_context():
            if compiled.closed_post_op is not None:
                return materialize_compiled_post_op(
                    compiled.closed_post_op,
                    raw,
                    materialization_hydrator,
                )
            return raw

    def _store_inline_step_result[StepResultT](
        self: SqlBackendExecutor,
        *,
        step: ServerPlanStep[StepResultT],
        compiled: CompiledStep[StepResultT],
        result: object,
        resolved: MutableResolvedRefs,
        compilation_ctx: CompilationContext,
        publication_liveness: PublicationLivenessState,
    ) -> None:
        if not isinstance(publication_liveness, PublicationLivenessState):
            msg = (
                "publication.liveness_required: _store_inline_step_result reached "
                f"a publication decision for {type(step).__name__}({step.ref_id!s}) "
                "without a PublicationLivenessState"
            )
            raise PublicationLivenessError(msg)
        publication_liveness.assert_step_known(step)
        should_publish = _step_can_publish_executor_visible_binding(step) and (
            step.always_publishes_executor_visible_binding()
            or _step_has_remaining_executor_visible_consumer(
                step,
                publication_liveness,
            )
        )
        if isinstance(result, dict) and step.expands_results():
            expanded = result
            assert isinstance(expanded, dict)
            resolved.update(expanded)
            if should_publish and str(step.ref_id) in expanded:
                self._publish_inline_executor_visible_binding(
                    step=step,
                    compiled=compiled,
                    result=expanded[str(step.ref_id)],
                    resolved=resolved,
                    compilation_ctx=compilation_ctx,
                )
        else:
            resolved[step.ref_id] = result
            if should_publish:
                self._publish_inline_executor_visible_binding(
                    step=step,
                    compiled=compiled,
                    result=result,
                    resolved=resolved,
                    compilation_ctx=compilation_ctx,
                )
                try:
                    result_ref = object.__getattribute__(step, "result_ref")
                except AttributeError:
                    result_ref = None
                if isinstance(result_ref, str) and result_ref != step.ref_id:
                    published = compilation_ctx.cte_refs.get(step.ref_id)
                    if published is not None:
                        publish_cte_binding(compilation_ctx, published, result_ref)

    def _publish_inline_executor_visible_binding[StepResultT](
        self: SqlBackendExecutor,
        *,
        step: ServerPlanStep[StepResultT],
        compiled: CompiledStep[StepResultT],
        result: object,
        resolved: MutableResolvedRefs,
        compilation_ctx: CompilationContext,
    ) -> None:
        sentinel = object()
        prior_ctx = vars(self).get("_compilation_ctx", sentinel)
        if "_published_cte_counter" not in vars(self):
            self._published_cte_counter = 0
        self._compilation_ctx = compilation_ctx
        try:
            publication_origin = publication_origin_for_contract(step)
            PlanExecutor._publish_executor_visible_binding(
                cast(Any, self),
                step,
                result,
                resolved,
                value_origin=publication_origin,
            )
        finally:
            if prior_ctx is sentinel:
                del self._compilation_ctx
            else:
                self._compilation_ctx = cast(CompilationContext, prior_ctx)

    @staticmethod
    def _inline_clear_batch_cte_ctx(compilation_ctx: CompilationContext) -> None:
        clear_batch_scoped_cte_state(compilation_ctx)

    def _inline_handle_execution_error[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        compilation_ctx: CompilationContext,
        error: Exception,
    ) -> Never:
        if isinstance(step, SessionValidationStep) and isinstance(error, TableNotFoundError):
            if "sys_sessions" in str(error):
                # A resolved session has no identifier to report: the identifier
                # is a column of a relation that this very failure means nothing
                # read. The message still describes the session generically, and
                # ``session_id`` is left unset rather than filled with the
                # placeholder, which would name a session the caller never held.
                session_id = step._session_id
                reported = session_id if isinstance(session_id, SessionId) else None
                described = reported if reported is not None else "resolved from the presented credential"
                error = SessionValidationError(
                    f"Session {described} cannot be validated because sys_sessions does not exist",
                    session_id=reported,
                    reason="not_found",
                )
        elif isinstance(step, PhysicalStatementGroup):
            prepared = self._prepared_steps_by_ref.get(str(step.ref_id))
            batch_plan = (
                prepared.compiled.batch_result_plan if prepared is not None and prepared.compiled.batch_result_plan is not None else None
            )
            if batch_plan is not None:
                _raise_batch_execution_error_from_plan(batch_plan, error)
        raise StepExecutionError(step_ref_id=step.ref_id, original_error=error) from error

    def _inline_strict_permission_ctx_for_compiled(
        self: SqlBackendExecutor,
        prepared: _PreparedStep,
        compilation_ctx: CompilationContext,
    ) -> AbstractContextManager[None]:
        from l2070_batching.permission_provenance import (
            strict_permission_provenance_execution_context,
        )

        provenance = prepared.compiled.permission_provenance()
        if provenance.permits_empty_manifest():
            return nullcontext()
        provenance_context: AbstractContextManager[None] = strict_permission_provenance_execution_context(
            provenance.manifest,
            strict_enforcement=compilation_ctx.strict_permission_provenance_enforcement,
            secret=compilation_ctx.permission_provenance_secret,
        )
        return provenance_context

    def _inline_explicit_lifecycle_raw_sync[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        accounting: PipelineAccounting,
    ) -> RawResult | None:
        from impl.common.l2070_server_plan.steps.transaction_lifecycle_steps import (
            CacheRollbackStep,
            DatabaseCommitStep,
            DatabaseRollbackStep,
            EventDispatchStep,
            PendingLazyOpsRollbackStep,
            RollbackFinalizeStep,
            VersionedRollbackStateStep,
            execute_cache_rollback_runtime,
            execute_database_commit_runtime_sync,
            execute_database_rollback_runtime_sync,
            execute_event_dispatch_runtime_sync,
            execute_pending_lazy_ops_rollback_runtime,
            execute_rollback_finalize_runtime,
            execute_versioned_rollback_state_runtime,
        )

        txn = self._txn_or_none()
        sql_connection = self._conn
        if isinstance(step, EventDispatchStep):
            accounting.record(driver_round_trips=0, db_statements_executed=0, unfused_statements=0)
            execute_event_dispatch_runtime_sync(txn)
            return []
        if isinstance(step, DatabaseCommitStep):
            execute_database_commit_runtime_sync(txn, sql_connection)
            return []
        if isinstance(step, DatabaseRollbackStep):
            execute_database_rollback_runtime_sync(txn, sql_connection)
            return []
        if isinstance(step, CacheRollbackStep):
            accounting.record(driver_round_trips=0, db_statements_executed=0, unfused_statements=0)
            execute_cache_rollback_runtime(txn)
            return []
        if isinstance(step, PendingLazyOpsRollbackStep):
            accounting.record(driver_round_trips=0, db_statements_executed=0, unfused_statements=0)
            execute_pending_lazy_ops_rollback_runtime(txn)
            return []
        if isinstance(step, VersionedRollbackStateStep):
            accounting.record(driver_round_trips=0, db_statements_executed=0, unfused_statements=0)
            execute_versioned_rollback_state_runtime(txn)
            return []
        if isinstance(step, RollbackFinalizeStep):
            accounting.record(driver_round_trips=0, db_statements_executed=0, unfused_statements=0)
            execute_rollback_finalize_runtime(txn)
            return []
        return None

