    def _inline_prepare_step[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        resolved: MutableResolvedRefs,
        compilation_ctx: CompilationContext,
    ) -> _PreparedStep:
        from impl.common.l2070_server_plan.execution_context import lowering_context as _compile_ctx
        from impl.common.l2070_server_plan.pipeline_trace import trace_compile
        from impl.common.l2070_server_plan.purity_harness import guard_compile_inputs

        del resolved
        symbolic_ctx = replace(
            compilation_ctx,
            materialized_pipeline=MaterializedPipeline(),
        )
        with _compile_ctx(), guard_compile_inputs(step, symbolic_ctx):
            compiled = self.compile_step(step, symbolic_ctx)
        trace_compile(step, compiled)
        prepared = _PreparedStep(compiled, compiled.materialize_ir())
        self._prepared_steps_by_ref[str(step.ref_id)] = prepared
        return prepared

    def _inline_prime_read_epoch_sync(self: SqlBackendExecutor) -> None:
        """Schema evolution resolves revision metadata only at converter use sites."""

    async def _inline_prime_read_epoch_async(self: SqlBackendExecutor) -> None:
        """Async counterpart for the no-op sync epoch hook."""

    def _init_inline_execution(
        self: SqlBackendExecutor,
        initial_resolved: InitialResolvedRefs,
    ) -> tuple[
        MutableResolvedRefs,
        _InlineExecutionLifecycle,
        PipelineAccounting,
        CompilationContext,
    ]:
        resolved = MutableResolvedRefs(
            {} if isinstance(initial_resolved, NoInitialResolvedRefs) else dict(initial_resolved),
        )
        lifecycle = _InlineExecutionLifecycle()
        accounting = PipelineAccounting()
        compilation_ctx = self.get_compilation_context()
        reset_pipeline_cte_state(compilation_ctx)
        self._published_cte_counter = 0
        return resolved, lifecycle, accounting, compilation_ctx

    def _preprocess_inline_terminal_step(
        self: SqlBackendExecutor,
        step: ServerPlanStep,
        resolved: MutableResolvedRefs,
    ) -> None:
        from impl.common.l2070_server_plan.purity_harness import guard_preprocess_inputs

        assert step.is_terminal, (
            f"{type(step).__name__} is level {step.level}, not terminal. All steps must be lowered to level 0 before inline execution."
        )
        step_resolved = resolved.snapshot()
        with guard_preprocess_inputs(step, step_resolved):
            step.preprocess(step_resolved)

    def _record_inline_prepared_ir[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        prepared: _PreparedStep,
        accounting: PipelineAccounting,
    ) -> None:
        if isinstance(step, BootstrapApplicationTerminalStep):
            inventory = step.statement_inventory()
            accounting.record(
                driver_round_trips=1 if inventory.total_backend_statements else 0,
                db_statements_executed=inventory.total_backend_statements,
                unfused_statements=inventory.total_logical_statements,
            )
            return
        if prepared.ir is None:
            return
        delta = self.describe_ir_execution(prepared.ir)
        delta.unfused_statements = (
            _count_logical_sql_statements(step) if isinstance(step, PhysicalStatementGroup) else delta.db_statements_executed
        )
        accounting.record(
            driver_round_trips=delta.driver_round_trips,
            db_statements_executed=delta.db_statements_executed,
            unfused_statements=delta.unfused_statements,
        )

    def _finish_prepared_inline_step[StepResultT](
        self: SqlBackendExecutor,
        *,
        step: ServerPlanStep[StepResultT],
        prepared: _PreparedStep,
        raw: RawResult,
        resolved: MutableResolvedRefs,
        lifecycle: _InlineExecutionLifecycle,
        compilation_ctx: CompilationContext,
        publication_liveness: PublicationLivenessState,
    ) -> None:
        result = self._finish_inline_step_result(
            _step=step,
            compiled=prepared.compiled,
            raw=raw,
            resolved=resolved,
        )
        PlanExecutor._collect_result_conditioned_lifecycle_actions(
            prepared,
            result,
            lifecycle.success,
            lifecycle.failure,
        )
        PlanExecutor._capture_result_bound_lifecycle_effects(prepared, result)
        PlanExecutor._append_lifecycle_actions(prepared, lifecycle.success, lifecycle.failure)
        publication_liveness.consume_step(step)
        self._store_inline_step_result(
            step=step,
            compiled=prepared.compiled,
            result=result,
            resolved=resolved,
            compilation_ctx=compilation_ctx,
            publication_liveness=publication_liveness,
        )
        self._inline_clear_batch_cte_ctx(compilation_ctx)

    def _raise_inline_step_failure[StepResultT](
        self: SqlBackendExecutor,
        step: ServerPlanStep[StepResultT],
        compilation_ctx: CompilationContext,
        exc: Exception,
    ) -> None:
        self._inline_handle_execution_error(step, compilation_ctx, exc)
        raise AssertionError("_inline_handle_execution_error unexpectedly returned") from None

    def _finalize_inline_execution_success(
        self: SqlBackendExecutor,
        lifecycle: _InlineExecutionLifecycle,
        compilation_ctx: CompilationContext,
        resolved: MutableResolvedRefs,
    ) -> None:
        effect_executor = _InlineLifecycleEffectExecutor(self, compilation_ctx)
        PlanExecutor._run_pipeline_success_lifecycle_actions(
            cast(Any, effect_executor),
            tuple(lifecycle.success),
            dict(resolved),
        )

    def _finalize_inline_execution_failure(
        self: SqlBackendExecutor,
        *,
        error: Exception,
        lifecycle: _InlineExecutionLifecycle,
        compilation_ctx: CompilationContext,
    ) -> None:
        effect_executor = _InlineLifecycleEffectExecutor(self, compilation_ctx)
        rollback_errors = PlanExecutor._run_pipeline_failure_lifecycle_actions(
            cast(Any, effect_executor),
            tuple(lifecycle.failure),
        )
        try:
            PlanExecutor._annotate_with_rollback_failures(error, rollback_errors)
        finally:
            self._inline_clear_batch_cte_ctx(compilation_ctx)

    def _execute_lowered_steps_inline(
        self: SqlBackendExecutor,
        steps: tuple[HeterogeneousServerPlanStep, ...],
        *,
        initial_resolved: InitialResolvedRefs = NO_INITIAL_RESOLVED_REFS,
    ) -> MutableResolvedRefs:
        """Compile and execute lowered terminal steps on this executor's transaction.

        Uses the same compile guards, ``runtime_ref_ids`` / ``post_op_with_refs``,
        lifecycle dispatch, and CTE batch clearing contract as ``PlanExecutor``,
        without re-entering eager plan execution.
        """
        (
            resolved,
            lifecycle,
            accounting,
            compilation_ctx,
        ) = self._init_inline_execution(initial_resolved)
        publication_liveness = PublicationLivenessState.from_steps(steps)
        publication_liveness.verify_sql_visible_dependencies(
            imported_binding_refs=frozenset(str(ref_id) for ref_id in compilation_ctx.cte_refs),
        )
        try:
            for step in steps:
                self._preprocess_inline_terminal_step(step, resolved)
                try:
                    prepared = self._inline_prepare_step(step, resolved, compilation_ctx)
                    self._record_inline_prepared_ir(step, prepared, accounting)
                    PlanExecutor._collect_failure_lifecycle_actions(prepared, lifecycle.failure)
                    lifecycle_raw = self._inline_explicit_lifecycle_raw_sync(step, accounting)
                    if lifecycle_raw is not None:
                        raw = lifecycle_raw
                    else:
                        with self._inline_strict_permission_ctx_for_compiled(
                            prepared,
                            compilation_ctx,
                        ):
                            raw = (
                                []
                                if prepared.ir is None
                                else self.execute_ir_with_materialization_hint(
                                    prepared.ir,
                                    materializes_backend=bool(step.tables_written()),
                                )
                            )
                    self._inline_prime_read_epoch_sync()
                    self._finish_prepared_inline_step(
                        step=step,
                        prepared=prepared,
                        raw=raw,
                        resolved=resolved,
                        lifecycle=lifecycle,
                        compilation_ctx=compilation_ctx,
                        publication_liveness=publication_liveness,
                    )
                except Exception as exc:
                    self._raise_inline_step_failure(step, compilation_ctx, exc)
        except Exception as error:
            self._finalize_inline_execution_failure(
                error=error,
                lifecycle=lifecycle,
                compilation_ctx=compilation_ctx,
            )
            raise
        self._finalize_inline_execution_success(lifecycle, compilation_ctx, resolved)
        return resolved

