    def _build_visible_embedding_write_steps(
        self: SqlBackendExecutor,
        *,
        writes: tuple[object, ...],
    ) -> Sequence[HeterogeneousServerPlanStep]:
        """Lower visible whole-document embedding writes for inline execution."""
        from impl.common.l2070_server_plan.steps.intent_embedding import (
            lower_set_visible_embedding_many_steps,
        )

        if not writes:
            return []
        lowered_steps: list[HeterogeneousServerPlanStep] = lower_set_visible_embedding_many_steps(
            ServerPlanRefId("emb_compute_apply.visible"),
            cast(Sequence[Any], writes),
            self.get_lowering_context(),
        )
        return lowered_steps

    def _prepare_replay_terminal_steps(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
        resolved: MutableResolvedRefs,
    ) -> tuple[tuple[_PreparedStep, ...], CompilationContext]:
        from impl.common.l2070_server_plan.purity_harness import guard_preprocess_inputs

        compilation_ctx = self.get_compilation_context()
        prepared_steps: list[_PreparedStep] = []
        for step in terminal_steps:
            step_resolved = resolved.snapshot()
            with guard_preprocess_inputs(step, step_resolved):
                step.preprocess(step_resolved)
            prepared_steps.append(self._inline_prepare_step(step, resolved, compilation_ctx))
            self._inline_clear_batch_cte_ctx(compilation_ctx)
        return tuple(prepared_steps), compilation_ctx

    def _analyze_replay_terminal_steps(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
    ) -> _RuntimeReplayBatchingAnalysis:
        backend_type, _dialect, supports_dml_ctes = self._get_backend_info()
        terminal_facts = [step.scheduling_facts() for step in terminal_steps]
        statement_count = len(terminal_steps)
        if statement_count < _MIN_FUSABLE_RUNTIME_STEP_COUNT:
            return _RuntimeReplayBatchingAnalysis(
                can_fuse=False,
                portable_min_db_statements=statement_count,
                backend_attainable_min_db_statements=statement_count,
                barriers=(),
            )

        barriers: list[BatchingBarrier] = []
        if not all(facts.supports_sql_batch_transport for facts in terminal_facts):
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.MISSING_SQL_BATCH_TRANSPORT,
                    bucket=BatchingBarrierBucket.BACKEND_CEILING,
                    detail="runtime_replay",
                ),
            )
        if any(facts.requires_materialized_inputs for facts in terminal_facts):
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.MATERIALIZED_INPUTS,
                    bucket=BatchingBarrierBucket.AVOIDABLE_DEOPT,
                    detail="runtime_replay",
                ),
            )
        if any(facts.requires_prior_step_boundary for facts in terminal_facts):
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.PRIOR_STEP_BOUNDARY,
                    bucket=BatchingBarrierBucket.HARD_SEMANTIC,
                    detail="runtime_replay",
                ),
            )
        if any(facts.requires_runtime_sequential_batch for facts in terminal_facts):
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.RUNTIME_SEQUENTIAL_BATCH,
                    bucket=BatchingBarrierBucket.AVOIDABLE_DEOPT,
                    detail="runtime_replay",
                ),
            )
        if backend_type != BackendType.SQLITE and not supports_dml_ctes:
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.BACKEND_NO_DML_CTES,
                    bucket=BatchingBarrierBucket.BACKEND_CEILING,
                    detail="runtime_replay",
                ),
            )

        has_semantic_barrier = any(barrier.bucket is BatchingBarrierBucket.HARD_SEMANTIC for barrier in barriers)
        has_backend_ceiling = any(barrier.bucket is BatchingBarrierBucket.BACKEND_CEILING for barrier in barriers)
        portable_min = statement_count if has_semantic_barrier else 1
        backend_attainable = statement_count if (has_semantic_barrier or has_backend_ceiling) else 1
        return _RuntimeReplayBatchingAnalysis(
            can_fuse=not barriers,
            portable_min_db_statements=portable_min,
            backend_attainable_min_db_statements=backend_attainable,
            barriers=tuple(barriers),
        )

    def _execute_prepared_replay_steps_sequential(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
        prepared_steps: tuple[_PreparedStep, ...],
        *,
        resolved: MutableResolvedRefs,
        compilation_ctx: CompilationContext,
        publication_liveness: PublicationLivenessState,
    ) -> None:
        for step, prepared in zip(terminal_steps, prepared_steps, strict=True):
            if prepared.ir is None:
                raw: object = []
            else:
                raw = self.execute_ir(prepared.ir)
            result = self._finish_inline_step_result(
                _step=step,
                compiled=prepared.compiled,
                raw=cast(RawResult, raw),
                resolved=resolved,
            )
            publication_liveness.consume_step(step)
            self._store_inline_step_result(
                step=step,
                compiled=prepared.compiled,
                result=result,
                resolved=resolved,
                compilation_ctx=compilation_ctx,
                publication_liveness=publication_liveness,
            )
            self._apply_replay_child_success_lifecycle(prepared, result, resolved, compilation_ctx)
            self._inline_clear_batch_cte_ctx(compilation_ctx)

    async def _execute_prepared_replay_steps_sequential_async(
        self: SqlBackendExecutor,
