            )
            self._apply_replay_child_success_lifecycle(prepared, result, resolved, compilation_ctx)
            self._inline_clear_batch_cte_ctx(compilation_ctx)

    def _prepare_runtime_terminal_dispatch(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
    ) -> _RuntimeTerminalDispatch:
        resolved, prepared_steps, compilation_ctx = self._prepare_runtime_terminal_execution(
            terminal_steps,
        )
        batch_analysis = self._analyze_replay_terminal_steps(terminal_steps)
        publication_liveness = PublicationLivenessState.from_steps(terminal_steps)
        publication_liveness.verify_sql_visible_dependencies(
            imported_binding_refs=frozenset(str(ref_id) for ref_id in compilation_ctx.cte_refs),
        )
        return _RuntimeTerminalDispatch(
            resolved=resolved,
            prepared_steps=prepared_steps,
            compilation_ctx=compilation_ctx,
            publication_liveness=publication_liveness,
            can_fuse=bool(terminal_steps and batch_analysis.can_fuse),
        )

    def _execute_runtime_terminal_steps(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
    ) -> RawResult:
        dispatch = self._prepare_runtime_terminal_dispatch(terminal_steps)
        if dispatch.can_fuse:
            self._execute_runtime_terminal_batch(
                terminal_steps,
                dispatch.prepared_steps,
                resolved=dispatch.resolved,
                publication_liveness=dispatch.publication_liveness,
            )
        else:
            self._execute_prepared_replay_steps_sequential(
                terminal_steps,
                dispatch.prepared_steps,
                resolved=dispatch.resolved,
                compilation_ctx=dispatch.compilation_ctx,
                publication_liveness=dispatch.publication_liveness,
            )
        return []

    async def _execute_runtime_terminal_steps_async(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
    ) -> RawResult:
        dispatch = self._prepare_runtime_terminal_dispatch(terminal_steps)
        if dispatch.can_fuse:
            await self._execute_runtime_terminal_batch_async(
                terminal_steps,
                dispatch.prepared_steps,
                resolved=dispatch.resolved,
                publication_liveness=dispatch.publication_liveness,
            )
        else:
            await self._execute_prepared_replay_steps_sequential_async(
                terminal_steps,
                dispatch.prepared_steps,
                resolved=dispatch.resolved,
                compilation_ctx=dispatch.compilation_ctx,
                publication_liveness=dispatch.publication_liveness,
            )
        return []

    def _prepare_runtime_terminal_execution(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
    ) -> tuple[MutableResolvedRefs, tuple[_PreparedStep, ...], CompilationContext]:
        resolved = MutableResolvedRefs({})
        prepared_steps, compilation_ctx = self._prepare_replay_terminal_steps(terminal_steps, resolved)
        return resolved, prepared_steps, compilation_ctx

    def _store_runtime_terminal_batch_results(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
        prepared_steps: tuple[_PreparedStep, ...],
        split_results: tuple[RawResult, ...],
        *,
        resolved: MutableResolvedRefs,
        publication_liveness: PublicationLivenessState,
    ) -> None:
        for step, prepared, split_raw in zip(
            terminal_steps,
            prepared_steps,
            split_results,
            strict=True,
        ):
            result = self._finish_inline_step_result(
                _step=step,
                compiled=prepared.compiled,
                raw=split_raw,
                resolved=resolved,
            )
            publication_liveness.consume_step(step)
            self._store_inline_step_result(
                step=step,
                compiled=prepared.compiled,
                result=result,
                resolved=resolved,
                compilation_ctx=self._compilation_ctx,
                publication_liveness=publication_liveness,
            )
            self._apply_replay_child_success_lifecycle(prepared, result, resolved, self._compilation_ctx)

    def _apply_replay_child_success_lifecycle(
        self: SqlBackendExecutor,
        prepared: _PreparedStep,
        result: object,
        resolved: MutableResolvedRefs,
        compilation_ctx: CompilationContext,
    ) -> None:
        lifecycle = _InlineExecutionLifecycle()
        PlanExecutor._capture_result_bound_lifecycle_effects(prepared, result)
        PlanExecutor._append_lifecycle_actions(prepared, lifecycle.success, lifecycle.failure)
        if not lifecycle.success:
            return
        effect_executor = _InlineLifecycleEffectExecutor(self, compilation_ctx)
        PlanExecutor._run_pipeline_success_lifecycle_actions(
            cast(Any, effect_executor),
            tuple(lifecycle.success),
            dict(resolved),
        )

    def _execute_runtime_terminal_batch(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
        prepared_steps: tuple[_PreparedStep, ...],
        *,
        resolved: MutableResolvedRefs,
        publication_liveness: PublicationLivenessState,
    ) -> None:
        batch_plan, batch_ir = self._prepare_runtime_terminal_batch_ir(terminal_steps)
        batch_result = self.execute_ir(batch_ir)
        self._finish_runtime_terminal_batch(
            batch_plan,
            terminal_steps,
            prepared_steps,
            batch_result,
            resolved=resolved,
            publication_liveness=publication_liveness,
        )

