    def _prepare_runtime_terminal_batch_ir(
        self: SqlBackendExecutor,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
    ) -> tuple[BatchResultExecutionPlan, SqlStepIR]:
        from impl.common.l2070_server_plan.codegen.data_modifying_cte import (
            DataModifyingCteStrategy,
        )

        strategy = DataModifyingCteStrategy()
        batch_ir = strategy.compile_batch(list(terminal_steps), self.get_compilation_context())
        child_result_specs = tuple(
            BatchChildResultSpec(
                ref_id=str(step.ref_id),
                expands_results=step.expands_results(),
                closed_post_op=None,
                dependency_ref_ids=(),
                binary_field_names=_batch_binary_field_names_for_step(step),
                bool_field_names=_batch_bool_field_names_for_step(step),
                column_type_hints=_batch_column_type_hints_for_step(step),
                tables_written=frozenset(str(table) for table in step.tables_written()),
            )
            for step in terminal_steps
        )
        batch_plan = BatchResultExecutionPlan(
            splitter_name=type(strategy).__name__,
            child_results=child_result_specs,
            count_only_indices=tuple(int(index) for index in strategy.count_only_indices()),
            omitted_projection_indices=tuple(int(index) for index in strategy.omitted_projection_indices()),
            result_label_indices=strategy.result_label_indices_for(
                tuple(spec.ref_id for spec in child_result_specs),
            ),
        )
        return batch_plan, batch_ir

    def _finish_runtime_terminal_batch(
        self: SqlBackendExecutor,
        batch_plan: BatchResultExecutionPlan,
        terminal_steps: tuple[HeterogeneousServerPlanStep, ...],
        prepared_steps: tuple[_PreparedStep, ...],
        batch_result: RawResult,
        *,
        resolved: MutableResolvedRefs,
        publication_liveness: PublicationLivenessState,
    ) -> None:
        split_results = PlanExecutor._split_batched_raw_result(
            cast(Any, self),
            batch_plan,
            batch_result,
        )
        self._store_runtime_terminal_batch_results(
            terminal_steps,
            prepared_steps,
            split_results,
            resolved=resolved,
            publication_liveness=publication_liveness,
        )

    def _enforce_final_bind_parameter_capacity(
        self: SqlBackendExecutor,
        grammar: SqlRenderable,
        external_params: Sequence[object] | None = None,
    ) -> None:
        """Validate final bind count before a statement reaches the driver."""
        sql_text, grammar_params = render_to_sql(grammar, self._conn.get_dialect())
        enforce_statement_capacity(
            rendered_sql_bytes=len(sql_text.encode("utf-8")),
            parameter_count=len(grammar_params) + len(external_params or ()),
            capacity=self._conn._sql_statement_capacity(),
        )

    def _enforce_statement_batch_bind_parameter_capacity(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> None:
        """Validate every leaf in a physical statement batch before dispatch."""
        for index, statement in enumerate(batch.statements):
            nested = extract_statement_batch(statement)
            if nested is not None:
                self._enforce_statement_batch_bind_parameter_capacity(nested)
                continue
            external_params, _external_first, _recover, returning_override, _collect, _label = self._statement_batch_stmt_params(
                batch, index
            )
            needs_returning = returning_override if returning_override is not None else self._has_returning_clause(statement)
            executable = self._statement_batch_executable_stmt(
                statement,
                backend_type=self._backend_profile.traits.backend_type,
                needs_returning=needs_returning,
            )
            self._enforce_final_bind_parameter_capacity(executable, external_params)

    def _effective_savepoint_recovery(
        self: SqlBackendExecutor,
        sql_ir: SqlStepIR,
    ) -> bool:
        """Force statement recovery for readonly direct SQL execution."""
        use_savepoint_recovery: bool = sql_ir.use_savepoint_recovery
        if self._conn._read_only:
            return True
        if self._backend_profile.traits.backend_type is BackendType.POSTGRES:
            return True
        return use_savepoint_recovery

    def _is_skippable_missing_column_schema_ddl(
        self: SqlBackendExecutor,
        grammar: SqlRenderable,
        *,
        sql_text: RawSqlText | Unset = UNSET,
    ) -> bool:
        """Recognize generated schema index DDL that can be retried after column reconciliation."""
        grammar_name = type(grammar).__name__
        if grammar_name in {"SqlDdlConcat", "_SqlDdlConcat", "SqlCreateIndexStmt", "SqlCreateIndexWithOrder"}:
            return True
        if sql_text is UNSET:
            rendered_sql, _params = render_to_sql(grammar, self._conn.get_dialect())
            sql_text = RawSqlText(rendered_sql)
        stripped_sql = sql_text.lstrip().upper()
        return stripped_sql.startswith("CREATE INDEX") or stripped_sql.startswith("CREATE UNIQUE INDEX")

    def _execute_simple_sql_ir(
        self: SqlBackendExecutor,
        sql_ir: SqlStepIR,
    ) -> RawResult:
        from impl.common.l2070_server_plan.execution_context import (
            allow_direct_sql_in_step_execution,
            server_plan_execution_context,
        )

        with server_plan_execution_context(), allow_direct_sql_in_step_execution():
            if sql_ir.grammar is None:
                return []
            statement_batch = extract_statement_batch(sql_ir.grammar)
            if statement_batch is not None:
                statement_batch = self._statement_batch_with_ir_params(sql_ir, statement_batch)
                result = self._run_statement_batch_plan(statement_batch)
                self._track_bytes_if_enabled(sql_ir, result)
                return result
            session_state = self._mariadb_session_state_grammar()
            use_savepoint_recovery = self._effective_savepoint_recovery(sql_ir)
            if session_state is not None and sql_ir.needs_returning:
                session_batch = SqlStatementBatch(
                    [session_state, sql_ir.grammar],
                    category=SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY,
                    params_per_stmt=[None, sql_ir.params],
                    external_params_first=[False, sql_ir.external_params_first],
                    needs_returning_per_stmt=[False, True],
                    collect_results_per_stmt=[False, True],
                    savepoint_recovery_per_stmt=[False, use_savepoint_recovery],
                )
                result = self._run_statement_batch_plan(session_batch)
                self._track_bytes_if_enabled(sql_ir, result)
                return result
            if session_state is not None:
                self._conn._execute_direct_internal(
                    session_state,
                    fetch_mode="none",
                    use_savepoint_recovery=False,
                    track_rtt=self._consume_plan_sql_rtt_tracking(),
                )
            self._before_sql_statement_execution(sql_ir.grammar)
            if not use_savepoint_recovery and self._is_skippable_missing_column_schema_ddl(sql_ir.grammar):
                use_savepoint_recovery = True
            if sql_ir.needs_returning:
                try:
                    rows = cast(
                        list[DatabaseRow],
                        self._conn._execute_direct_internal(
                            sql_ir.grammar,
                            params=sql_ir.params,
                            external_params_first=sql_ir.external_params_first,
                            fetch_mode="all",
                            use_savepoint_recovery=use_savepoint_recovery,
                            track_rtt=self._consume_plan_sql_rtt_tracking(),
                        ),
                    )
                except Exception:
                    if os.environ.get("NERA_DEBUG_FAILED_SIMPLE_SQL"):
                        sql, params = render_to_sql(sql_ir.grammar, self._conn.get_dialect())
                        print("[FAILED_SIMPLE_SQL]", sql, params, file=sys.stderr)
                    raise
                result = _rows_to_raw_result(tuple(rows) if rows is not None else None)
                self._track_bytes_if_enabled(sql_ir, result)
                return result
            try:
                self._conn._execute_direct_internal(
                    sql_ir.grammar,
                    params=sql_ir.params,
                    external_params_first=sql_ir.external_params_first,
                    fetch_mode="none",
                    use_savepoint_recovery=use_savepoint_recovery,
                    track_rtt=self._consume_plan_sql_rtt_tracking(),
                )
            except Exception:
                if os.environ.get("NERA_DEBUG_FAILED_SIMPLE_SQL"):
                    sql, params = render_to_sql(sql_ir.grammar, self._conn.get_dialect())
                    print("[FAILED_SIMPLE_SQL]", sql, params, file=sys.stderr)
                raise
            result = _rowcount_result(self._conn._rowcount())
            self._track_bytes_if_enabled(sql_ir, result)
            return result

