                    if os.environ.get("NERA_DEBUG_FAILED_SIMPLE_SQL"):
                        sql, params = render_to_sql(sql_ir.grammar, self._conn.get_dialect())
                        print("[FAILED_SIMPLE_SQL]", sql, params, file=sys.stderr)
                    raise
                result = _rows_to_raw_result(tuple(rows) if rows is not None else None)
                self._track_bytes_if_enabled(sql_ir, result)
                return result
            try:
                await self._conn._execute_direct_internal_async(
                    sql_ir.grammar,
                    params=sql_ir.params,
                    external_params_first=sql_ir.external_params_first,
                    fetch_mode="none",
                    use_savepoint_recovery=use_savepoint_recovery,
                    track_rtt=self._consume_plan_sql_rtt_tracking(),
                )
            except Exception as exc:
                sql_text: str | None = None
                if os.environ.get("NERA_DEBUG_FAILED_SIMPLE_SQL"):
                    sql, params = render_to_sql(sql_ir.grammar, self._conn.get_dialect())
                    sql_text = sql
                    print("[FAILED_SIMPLE_SQL]", sql, params, file=sys.stderr)
                if isinstance(exc, ColumnNotFoundError):
                    if sql_text is None:
                        sql_text, _params = render_to_sql(sql_ir.grammar, self._conn.get_dialect())
                    if self._is_skippable_missing_column_schema_ddl(sql_ir.grammar, sql_text=RawSqlText(sql_text)):
                        result = _rowcount_result(0)
                        self._track_bytes_if_enabled(sql_ir, result)
                        return result
                raise
            result = _rowcount_result(self._conn._rowcount())
            self._track_bytes_if_enabled(sql_ir, result)
            return result

    def _prepare_ir_execution(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
        materializes_backend: bool | None,
    ) -> _PreparedSqlIrExecution:
        sql_ir, is_statement_batch = self._validate_and_prepare_ir(ir)
        accounting = self._describe_normalized_ir_execution(
            sql_ir,
            is_statement_batch=is_statement_batch,
        )
        if self._native_pipeline_receipt_active and accounting.db_statements_executed > 0:
            self._native_pipeline_executed = True
            self._native_pipeline_statement_count += accounting.db_statements_executed if is_statement_batch else 1
            self._native_pipeline_driver_round_trip_count += accounting.driver_round_trips if is_statement_batch else 1
        return _PreparedSqlIrExecution(
            sql_ir=sql_ir,
            is_statement_batch=is_statement_batch,
            accounting=accounting,
            materializes_backend=(accounting.db_statements_executed > 0 if materializes_backend is None else materializes_backend),
        )

    @contextmanager
    def _ir_execution_authority_scope(
        self: SqlBackendExecutor,
        execution: _PreparedSqlIrExecution,
        *,
        commit_context: DiagnosticLabel,
    ) -> Generator[None]:
        contains_commit = self._is_write_transaction and self._ir_contains_database_commit(execution.sql_ir)
        commit_started = time.perf_counter() if contains_commit else None
        with self._permission_provenance_context(execution.sql_ir):
            validate_active_strict_permission_provenance_execution()
            self.validate_execution_ir(execution.sql_ir)
            yield
            if contains_commit:
                self._conn._mark_data_transaction_backend_committed()
                self._conn._finish_transaction_trace_safely(context=commit_context)
                assert commit_started is not None
                from l2092_timing_tracking import record_commit_timing

                record_commit_timing((time.perf_counter() - commit_started) * 1000.0)

    @contextmanager
    def _ir_driver_timing_scope(
        self: SqlBackendExecutor,
        execution: _PreparedSqlIrExecution,
    ) -> Generator[None]:
        trace_db_active_before = self._conn._transaction_db_active_ms_snapshot()
        dispatch_started = time.perf_counter()
        try:
            yield
        finally:
            if self._is_write_transaction and execution.materializes_backend and trace_db_active_before is not None:
                trace_db_active_after = self._conn._transaction_db_active_ms_snapshot()
                if trace_db_active_after is not None:
                    dispatch_ms = (time.perf_counter() - dispatch_started) * 1000.0
                    recorded_delta = max(0.0, trace_db_active_after - trace_db_active_before)
                    missing_driver_ms = dispatch_ms - recorded_delta
                    recorder = _static_db_time_recorder(self._conn)
                    if missing_driver_ms > 0.0 and callable(recorder):
                        recorder(missing_driver_ms)

    @staticmethod
    def _statement_batch_with_ir_params(sql_ir: SqlStepIR, batch: SqlStatementBatch) -> SqlStatementBatch:
        """Attach SQL IR boundary parameters to a one-statement extracted batch."""
        if not sql_ir.params:
            return batch
        if len(batch.statements) != 1:
            msg = "SQL IR boundary parameters cannot be assigned to a multi-statement batch."
            raise ValueError(msg)
        existing_params = batch.params_per_stmt[0] if batch.params_per_stmt else None
        merged_params = (*(existing_params or ()), *sql_ir.params)
        return SqlStatementBatch(
            batch.statements,
            category=batch.category,
            relationships=batch.relationships,
            params_per_stmt=[merged_params],
            external_params_first=[batch.external_params_first_per_stmt[0] or sql_ir.external_params_first],
            needs_returning_per_stmt=batch.needs_returning_per_stmt,
            collect_results_per_stmt=batch.collect_results_per_stmt,
            savepoint_recovery_per_stmt=batch.savepoint_recovery_per_stmt,
            result_labels_per_stmt=batch.result_labels_per_stmt,
            statement_kinds_per_stmt=batch.statement_kinds_per_stmt,
            logical_statement_count=batch.logical_statement_count,
            logical_source_refs=batch.logical_source_refs,
            logical_phase=batch.logical_phase,
        )

    def _register_owned_temporary_relation(self: SqlBackendExecutor, grammar: SqlRenderable) -> None:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_temporary_relation import (
            SqlCreateTemporaryTableAsSelect,
            SqlDropTemporaryTableIfExists as SqlOwnedTemporaryTableCleanup,
        )
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlIdentifier
        from impl.common.l2100_sql_grammar.tree.statements import SqlCreateTemporaryTableAs
        from impl.common.l2200_sql_dialect.sql_connection import _SqlConnectionCore

        from impl.common.l2100_sql_grammar.protocols import SqlOuterCteSplitProtocol

        from impl.common.l2100_sql_grammar.tree.with_placement import placed_with_body

        visited: set[int] = set()
        while id(grammar) not in visited:
            visited.add(id(grammar))
            placed = placed_with_body(grammar)
            if placed is not None:
                grammar = placed
            elif isinstance(grammar, SqlOuterCteSplitProtocol):
                _, grammar = grammar.split_for_outer_cte()
            else:
                break
        cleanup: SqlOwnedTemporaryTableCleanup | None = None
        if isinstance(grammar, SqlCreateTemporaryTableAsSelect) and grammar.transaction_owned:
            cleanup = grammar.cleanup_statement
        elif isinstance(grammar, SqlCreateTemporaryTableAs) and isinstance(grammar.table, SqlIdentifier):
            cleanup = SqlOwnedTemporaryTableCleanup(SqlTableName(str(grammar.table.name)))
        if cleanup is not None:
            if not isinstance(self._conn, _SqlConnectionCore):
                raise RuntimeError("Owned temporary relations require a SQL transaction.")
            self._conn._register_transaction_temporary_relation(cleanup)

    def _dispatch_resource_owners(
        self: SqlBackendExecutor, execution: _PreparedSqlIrExecution
    ) -> tuple[TransactionTemporaryRelationOwner, ...]:
        if not self._is_write_transaction or not self._ir_contains_database_commit(execution.sql_ir):
            return ()
        from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner

        return (self._conn,) if isinstance(self._conn, TransactionTemporaryRelationOwner) else ()

    def _dispatch_statement_batch(self: SqlBackendExecutor, execution: _PreparedSqlIrExecution) -> SqlStatementBatch:
        assert execution.is_statement_batch
        sql_ir = _require_sql_executable_ir(execution.sql_ir)
        return self._statement_batch_with_ir_params(sql_ir, self._validate_statement_batch(sql_ir.grammar))

    def _finish_resource_dispatch(
        self: SqlBackendExecutor,
        execution: _PreparedSqlIrExecution,
        owners: tuple[TransactionTemporaryRelationOwner, ...],
        result: RawResult,
    ) -> RawResult:
        del execution
        for owner in owners:
            if self._backend_profile.traits.backend_type is BackendType.SQLITE:
                # SQLite temporary tables survive COMMIT, including a COMMIT
                # inside one direct native program.
                owner._release_transaction_temporary_relations()
            owner._forget_transaction_temporary_relations()
        return result

    async def _finish_resource_dispatch_async(
        self: SqlBackendExecutor,
        owners: tuple[TransactionTemporaryRelationOwner, ...],
        result: RawResult,
    ) -> RawResult:
        for owner in owners:
            if self._backend_profile.traits.backend_type is BackendType.SQLITE:
                await owner._release_transaction_temporary_relations_async()
            owner._forget_transaction_temporary_relations()
        return result

    def _prepared_dispatch_runners(
        self: SqlBackendExecutor, execution: _PreparedSqlIrExecution
    ) -> tuple[Callable[[], RawResult], Callable[[], Awaitable[RawResult]]]:
        """Bind transport and resource lifetime once for either execution mode."""
        owners = self._dispatch_resource_owners(execution)
        owner = owners[0] if owners else None
        batch = self._dispatch_statement_batch(execution) if execution.is_statement_batch else None
        if batch is None:
            self._register_owned_temporary_relation(execution.sql_ir.grammar)
            execute_sync = lambda: self._dispatch_simple_ir(execution.sql_ir)
            execute_async = lambda: self._dispatch_simple_ir_async(execution.sql_ir)
        else:
            execute_sync = lambda: self._run_statement_batch_plan(batch)
            execute_async = lambda: self._run_statement_batch_plan_for_async_target_async(batch)
        release_before = owner if batch is None else None

        def run_sync() -> RawResult:
            if release_before is not None:
                release_before._release_transaction_temporary_relations()
            return self._finish_resource_dispatch(execution, owners, execute_sync())

        async def run_async() -> RawResult:
            if release_before is not None:
                await release_before._release_transaction_temporary_relations_async()
            return await self._finish_resource_dispatch_async(owners, await execute_async())

        return run_sync, run_async

    def _dispatch_prepared_ir(self: SqlBackendExecutor, execution: _PreparedSqlIrExecution) -> RawResult:
        run_sync, _ = self._prepared_dispatch_runners(execution)
        return run_sync()

    def _execute_ir_transport(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
        *,
        materializes_backend: bool | None = None,
    ) -> RawResult:
        raise_if_sql_grammar_execution_from_post_op(operation="SqlBackendExecutor.execute_ir")
        execution = self._prepare_ir_execution(ir, materializes_backend)
        with self._ir_execution_authority_scope(
            execution,
            commit_context=DiagnosticLabel("serverplan_sql_commit"),
        ):
            if self._is_write_transaction and execution.materializes_backend:
                if (
                    self._ir_contains_database_commit(execution.sql_ir)
                    and self._backend_profile.traits.backend_type is BackendType.SQLITE
                ):
                    from l2070_batching.backend_runtime_capabilities import SyncInlineTransactionEnvelope

                    if not isinstance(self._conn, SyncInlineTransactionEnvelope):
                        raise TypeError("SQLite backend does not provide inline transaction preparation")
                    self._conn._prepare_inline_transaction_envelope()
                else:
                    self._conn._materialize_data_transaction_backend()
            if self._is_write_transaction and self._ir_contains_database_commit(execution.sql_ir):
                from l1400_types.type_surface_contracts import DatabaseIdentity
                from l5000_subscriptions.deferred_dispatch import commit_capture_scope_sync

                with commit_capture_scope_sync(
                    self._txn,
                    DatabaseIdentity(self._conn.database_identity),
                ):
                    with self._ir_driver_timing_scope(execution):
                        return self._dispatch_prepared_ir(execution)
            with self._ir_driver_timing_scope(execution):
                return self._dispatch_prepared_ir(execution)

    def execute_ir_with_materialization_hint(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
        *,
        materializes_backend: bool | None,
    ) -> RawResult:
        rows = self._execute_ir_transport(
            ir,
            materializes_backend=materializes_backend,
        )
        return self.result_decoder.decode_transport_result(ir, rows)

    @staticmethod
    def _has_returning_clause(stmt: SqlRenderable) -> bool:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
            SqlSelectExpressions,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_json_agg import (
            SqlJsonAggCteSelect,
        )
        from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import SqlDynamicSelectStmt
        from impl.common.l2100_sql_grammar.domain.infra.dml_wrapper import (
            SqlDmlWrapperKind,
            is_dml_wrapper_kind,
        )
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import (
            SqlDmlReturningWrapper,
            SqlSelectWithCte,
        )
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect, SqlSuffixedQuery

        if isinstance(stmt, SqlDmlReturningWrapper):
            return True
        if isinstance(
            stmt,
            (
                SqlDynamicSelectStmt,
                SqlJsonAggCteSelect,
                SqlSelect,
                SqlSelectExpressions,
                SqlSelectWithCte,
                SqlSuffixedQuery,
            ),
        ):
            return True
        if is_dml_wrapper_kind(
            stmt,
            SqlDmlWrapperKind.SELECT_COUNT_SUBQUERY,
            SqlDmlWrapperKind.SELECT_EXISTS_SUBQUERY,
        ):
            return True
        for attr in ("_returning", "_returning_frag", "_returning_cols"):
            try:
                if object.__getattribute__(stmt, attr) is not None:
                    return True
            except AttributeError:
                continue
        # Wrapping grammars (e.g. SqlCte, SqlBindExternalParams) carry the
        # returning-bearing DML inside a final query / inner grammar. Recurse
        # so the compound-write path still routes through fetch_mode="all"
        # and avoids leaving RETURNING rows in the cursor (which breaks commit
        # on SQLite with ``SQL statements in progress``).
        for attr in ("_final_query", "_inner", "_stmt", "_grammar", "_select"):
            try:
                inner = object.__getattribute__(stmt, attr)
            except AttributeError:
                continue
            if inner is None or inner is stmt:
                continue
            if isinstance(inner, SqlRenderable) and SqlBackendExecutor._has_returning_clause(inner):
                return True
        return False

    @staticmethod
    def _statement_batch_stmt_params(
        batch: SqlStatementBatch,
        index: int,
    ) -> tuple[
        tuple[Any, ...] | None,
        bool,
        bool,
        bool | None,
        StatementBatchResultMode,
        DiagnosticLabel | None,
    ]:
        """Extract per-statement execution metadata for a batch child."""
        params_list: list[tuple[Any, ...] | None] = batch.params_per_stmt
        epf_list: list[bool] = batch.external_params_first_per_stmt
        returning_list: list[bool] = batch.needs_returning_per_stmt
        result_modes = batch.result_modes_per_stmt
        recovery_list: list[bool] = batch.savepoint_recovery_per_stmt
        label_list: list[str | None] = batch.result_labels_per_stmt
        ext_params: tuple[Any, ...] | None = params_list[index] if index < len(params_list) else None
        ext_first: bool = epf_list[index] if index < len(epf_list) else False
        needs_returning: bool | None = returning_list[index] if index < len(returning_list) else None
        result_mode = result_modes[index]
        use_savepoint_recovery: bool = recovery_list[index] if index < len(recovery_list) else True
        raw_result_label = label_list[index] if index < len(label_list) else None
        result_label = DiagnosticLabel(raw_result_label) if raw_result_label is not None else None
        return ext_params, ext_first, use_savepoint_recovery, needs_returning, result_mode, result_label

    @staticmethod
    def _singleton_ordered_statement_batch(
        batch: SqlStatementBatch,
        index: int,
    ) -> SqlStatementBatch:
        """Preserve one budget-split child's complete native transport metadata."""
        return SqlStatementBatch(
            [batch.statements[index]],
            category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            params_per_stmt=[batch.params_per_stmt[index]],
            external_param_counts_per_stmt=(
                None if batch.external_param_counts_per_stmt is None else [batch.external_param_counts_per_stmt[index]]
            ),
            external_params_first=[batch.external_params_first_per_stmt[index]],
            needs_returning_per_stmt=[batch.needs_returning_per_stmt[index]],
            collect_results_per_stmt=[batch.collect_results_per_stmt[index]],
            result_labels_per_stmt=[batch.result_labels_per_stmt[index]],
            statement_kinds_per_stmt=[batch.statement_kinds_per_stmt[index]],
            savepoint_recovery_per_stmt=[batch.savepoint_recovery_per_stmt[index]],
        )

    @staticmethod
    def _validate_statement_batch(batch: object) -> SqlStatementBatch:
        """Assert and return typed statement batch."""
        extracted = extract_statement_batch(batch)
        if extracted is None:
            msg = f"Expected SqlStatementBatch, got {type(batch).__name__}"
            raise TypeError(msg)
        return extracted

    @staticmethod
    def _is_statement_batch_like(stmt: object) -> bool:
        """Return whether a statement should be recursively expanded as a batch."""
        return extract_statement_batch(stmt) is not None

    @staticmethod
    def _label_statement_batch_result_rows(
        rows: RawResult | None,
        result_label: str | None,  # broad-type: accepted
    ) -> tuple[DatabaseRow, ...]:
        if rows is None:
            return ()
        if result_label is None:
            return tuple(rows)
        labeled_rows: list[DatabaseRow] = []
        for row in rows:
            row_dict = dict(row) if not isinstance(row, dict) else dict(row)
            label_key = "__compound_parent_step__" if "__compound_step__" in row_dict else "__compound_step__"
            row_dict[label_key] = result_label
            labeled_rows.append(row_dict)
        return tuple(labeled_rows)

    def _count_statement_batch_leaf_statements(self: SqlBackendExecutor, batch: SqlStatementBatch) -> int:
        """Count leaf SQL statements in a statement batch."""
        leaf_statement_count: int = batch.leaf_statement_count()
        return leaf_statement_count

    @staticmethod
    def _count_transaction_control_statements(batch: SqlStatementBatch) -> int:
        """Count transaction-control leaves in a nested statement batch."""

        def _count(statement: SqlRenderable) -> int:
            if isinstance(statement, SqlTxnControl):
                return 1
            if isinstance(statement, SqlStatementBatch):
                return sum(_count(child) for child in statement.statements)
            return 0

        return sum(_count(statement) for statement in batch.statements)

    def _describe_normalized_ir_execution(
        self: SqlBackendExecutor,
        sql_ir: SqlStepIR,
        *,
        is_statement_batch: bool,
    ) -> PipelineAccounting:
        if is_statement_batch:
            statement_batch = self._validate_statement_batch(
                _require_sql_executable_ir(sql_ir).grammar,
            )
            statement_count = self._count_statement_batch_leaf_statements(
                statement_batch,
            )
            return PipelineAccounting(
                driver_round_trips=1,
                db_statements_executed=statement_count,
                transaction_control_count=statement_batch.transaction_control_count(),
            )
        return describe_special_ir_execution(sql_ir)

    def describe_ir_execution(self: SqlBackendExecutor, ir: SqlStepIR) -> PipelineAccounting:
        """Return actual backend work for one ``execute_ir`` dispatch."""
        sql_ir, is_statement_batch = self._normalize_ir(ir)
        return self._describe_normalized_ir_execution(
            sql_ir,
            is_statement_batch=is_statement_batch,
        )

    def _statement_batch_metrics(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> PipelineBatchingMetrics:
        actual_statements = self._count_statement_batch_leaf_statements(batch)
        transaction_control_count = batch.transaction_control_count()
        portable_min = batch.portable_min_db_statements() + transaction_control_count
        backend_type, _dialect, supports_dml_ctes = self._get_backend_info()
        backend_attainable = portable_min
        barriers: list[BatchingBarrier] = []
        if batch.category is SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY:
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.REQUEST_FALLBACK_BATCH,
                    bucket=BatchingBarrierBucket.AVOIDABLE_DEOPT,
                ),
            )
            if backend_type != BackendType.SQLITE and not supports_dml_ctes:
                backend_attainable = actual_statements
                barriers.append(
                    BatchingBarrier(
                        kind=BatchingBarrierKind.BACKEND_NO_DML_CTES,
                        bucket=BatchingBarrierBucket.BACKEND_CEILING,
                    ),
                )
        elif batch.category is SqlStatementBatchCategory.BUDGET_SPLIT:
            backend_attainable = actual_statements
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.PARAM_BUDGET_SPLIT,
                    bucket=BatchingBarrierBucket.BACKEND_CEILING,
                ),
            )
        elif batch.category in {
            SqlStatementBatchCategory.ORDERED_SEMANTIC,
            SqlStatementBatchCategory.DEPENDENCY_GRAPH,
        }:
            portable_min = actual_statements
            backend_attainable = actual_statements
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.ORDERED_SEMANTIC_BATCH,
                    bucket=BatchingBarrierBucket.HARD_SEMANTIC,
                ),
            )
        elif batch.category is SqlStatementBatchCategory.DDL:
            portable_min = actual_statements
            backend_attainable = actual_statements
            barriers.append(
                BatchingBarrier(
                    kind=BatchingBarrierKind.DDL_BATCH,
                    bucket=BatchingBarrierBucket.HARD_SEMANTIC,
                ),
            )
        elif batch.category is SqlStatementBatchCategory.BOOTSTRAP_DML:
            portable_min = actual_statements
            capabilities = frozenset(self._conn.get_capabilities())
            supports_native_bootstrap_dml_batch = (
                BackendCapability.PARAMETERIZED_DML_STATEMENT_BATCH in capabilities or backend_type is BackendType.SQLITE
            )
            backend_attainable = 1 if supports_native_bootstrap_dml_batch else actual_statements
            if not supports_native_bootstrap_dml_batch:
                barriers.append(
                    BatchingBarrier(
                        kind=BatchingBarrierKind.BACKEND_NO_NATIVE_BATCH_EXECUTION,
                        bucket=BatchingBarrierBucket.BACKEND_CEILING,
                    ),
                )
        return PipelineBatchingMetrics(
            portable_min_db_statements=portable_min,
            backend_attainable_min_db_statements=backend_attainable,
            actual_db_statements_executed=backend_attainable
            if batch.category is SqlStatementBatchCategory.BOOTSTRAP_DML
            else actual_statements,
            driver_round_trips=1,
            unfused_statements=actual_statements,
            barriers=tuple(barriers),
        )

    def describe_ir_batching(self: SqlBackendExecutor, ir: SqlStepIR) -> PipelineBatchingMetrics:
        sql_ir, is_statement_batch = self._normalize_ir(ir)
        if is_statement_batch:
            metrics = self._statement_batch_metrics(
                self._validate_statement_batch(_require_sql_executable_ir(sql_ir).grammar),
            )
            return metrics
        accounting = self._describe_normalized_ir_execution(
            sql_ir,
            is_statement_batch=False,
        )
        return PipelineBatchingMetrics(
            portable_min_db_statements=accounting.db_statements_executed,
            backend_attainable_min_db_statements=accounting.db_statements_executed,
            actual_db_statements_executed=accounting.db_statements_executed,
            driver_round_trips=accounting.driver_round_trips,
            unfused_statements=accounting.db_statements_executed,
        )

    def _before_sql_statement_execution(
        self: SqlBackendExecutor,
        stmt: SqlRenderable,
    ) -> None:
        """Backend hook for per-statement session settings."""

        del stmt

    def _before_sql_statement_execution_for_async(
        self: SqlBackendExecutor,
        stmt: SqlRenderable,
    ) -> None:
        """Backend hook for session settings before async driver execution."""

        self._before_sql_statement_execution(stmt)

    def _statement_batch_executable_stmt(
        self: SqlBackendExecutor,
        stmt: SqlRenderable,
        *,
        backend_type: BackendType,
        needs_returning: bool,
    ) -> SqlRenderable:
        """Drop synthetic output CTE wrappers around non-returning MySQL DML."""

        if not backend_type.is_mysql_family:
            return stmt
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import (
            SqlForcedInlineCteDml,
            SqlSelectWithCte,
        )
        from impl.common.l2100_sql_grammar.tree.statements import SqlCteDefinition, SqlWith

        if isinstance(stmt, SqlSelectWithCte) and stmt._needs_inline_ctes(
            stmt._unwrap_outer_wrappers(),
        ):
            return SqlForcedInlineCteDml(stmt)
        if needs_returning or not isinstance(stmt, SqlWith):
            return stmt
        definitions = stmt._definitions
        final_query = stmt._final_query
        if not definitions:
            return stmt
        for definition in definitions:
            if not isinstance(definition, SqlCteDefinition):
                return stmt
            name = str(definition.name)
            if not name.startswith("out_"):
                return stmt
        return final_query

    def _mariadb_session_state_grammar(self: SqlBackendExecutor) -> SqlRenderable | None:
        """Build the connection-local authority required by one MariaDB request."""
        if self._backend_profile.traits.backend_type is not BackendType.MARIADB or not isinstance(self._session_id, SessionId):
            return None
        if isinstance(
            _resolve_session_source_from_candidates(self._build_txn_candidates()),
            ScalarServerRef,
        ):
            return None
        queue_auth_token: str | None = None
        for candidate in self._build_txn_candidates():
            if isinstance(candidate, _RippleQueueAuthTokenCarrier):
                queue_auth_token = candidate._desired_ripple_queue_auth_token
                if queue_auth_token is not None:
                    break
        session_id = self._session_id
        session_type = SqlSessionType(
            "system" if session_id.is_schema_session() else "user",
        )
        return SqlApplySessionAndQueueAuthState(
            SysIdValue(session_id.unwrap_to_sql()),
            session_type,
            None if queue_auth_token is None else SqlSessionValue(queue_auth_token),
        )

    @staticmethod
    def _grammar_contains_transaction_boundary(grammar: SqlStatementBatch) -> bool:
        visited: set[int] = set()

        def _contains_boundary(node: object) -> bool:
            node_id = id(node)
            if node_id in visited:
                return False
            visited.add(node_id)
            if isinstance(node, SqlTxnControl):
                return node.transaction_kind in {
                    TxnControlKind.BEGIN,
                    TxnControlKind.COMMIT,
                    TxnControlKind.ROLLBACK,
                }
            nested_batch = extract_statement_batch(node)
            if nested_batch is not None:
                return any(_contains_boundary(child) for child in nested_batch.statements)
            for attribute in map(DynamicFieldName, ("_inner", "_final_query", "_select")):
                child = _read_private_attr(node, attribute)
                if child is not None and _contains_boundary(child):
                    return True
            return False

        return _contains_boundary(grammar)

    @read_only_render_memo()
    def _prepare_native_statement_batch(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> (
        tuple[  # broad-type: accepted
            SqlBatch,
            tuple[tuple[bool, str | None, bool], ...],
        ]
        | None
    ):
        if self._backend_profile.traits.backend_type not in {
            BackendType.POSTGRES,
            BackendType.MARIADB,
        }:
            return None
        if batch.category not in {
            SqlStatementBatchCategory.ORDERED_SEMANTIC,
            SqlStatementBatchCategory.DEPENDENCY_GRAPH,
            SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY,
        }:
            return None
        from l2070_batching.executor import ordered_closed_request_region_is_required

        if (
            batch.category is SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY
            and not single_sql_request_is_required()
            and not ordered_closed_request_region_is_required()
        ):
            return None
        # PostgreSQL prepares a native pipeline before earlier temporary relations exist.
        # Keep visibility-dependent batches sequential. See
        # NER1541_GRAPH_WALK_EXECUTION_ARCHITECTURE.rst.
        if self._backend_profile.traits.backend_type is BackendType.POSTGRES and any(
            relationship.kind is SqlStatementRelationshipKind.DATA_VISIBILITY for relationship in batch.relationships
        ):
            return None
        if not isinstance(self._conn, _SqlBatchFactory):
            return None
        if any(extract_statement_batch(stmt) is not None for stmt in batch.statements):
            return None
        from l2070_batching.backend_runtime_capabilities import NativeListBindingBatch

        native_batch = self._conn.create_sql_batch()
        if not isinstance(native_batch, SqlBatch):
            return None
        request_batch = native_batch if isinstance(native_batch, NativeListBindingBatch) else None
        if self._backend_profile.traits.backend_type is BackendType.POSTGRES:
            if not self._grammar_contains_transaction_boundary(batch):
                native_batch.enable_savepoint_recovery()
        elif request_batch is None:
            return None
        from impl.common.l2100_sql_grammar.domain.infra.request_scalar import (
            RequestScalarName,
            SqlRequestStatement,
            request_boolean_assignment_name,
            request_integer_assignment_name,
            request_value_declarations,
        )

        additional_locals: set[RequestScalarName] = set()
        result_specs: list[tuple[bool, str | None, bool]] = []
        dialect = self._conn.get_dialect()
        from impl.common.l2100_sql_params.sql_params import validate_sql_param_tuple

        def _add_checked_native_statement(
            grammar: SqlRenderable,
            sql_text: RawSqlText,
            params: tuple[object, ...],
            prepared_execution: PreparedTerminalExecution | _NoPreparedTerminalExecution = (_NO_PREPARED_TERMINAL_EXECUTION),
            *,
            explain_eligible: bool = False,
        ) -> None:
            normalized_params = validate_sql_param_tuple(params)
            enforce_statement_capacity(
                rendered_sql_bytes=len(sql_text.encode("utf-8")),
                parameter_count=len(normalized_params),
                capacity=self._conn._sql_statement_capacity(),
            )
            if request_batch is not None:
                from impl.common.l2100_sql_grammar.domain.mariadb_recursive import (
                    mariadb_instrumentation_statement,
                    requires_mariadb_recursion_diagnostics,
                )
                from impl.common.l2100_sql_params.native_list_driver import has_native_list_payload

                if has_native_list_payload(normalized_params):
                    request_batch.mark_native_list_binding()
                instrumentation_statement: tuple[str, tuple[object, ...] | None] | None = None
                if explain_eligible:
                    instrumentation_grammar = mariadb_instrumentation_statement(grammar)
                    instrumentation_fragment = instrumentation_grammar.render(dialect)
                    instrumentation_sql, instrumentation_params = instrumentation_fragment.to_sql(dialect)
                    instrumentation_params = cast(
                        "tuple[object, ...]",
                        _bind_prepared_runtime_slots(
                            instrumentation_params,
                            {str(key): value for key, value in self._executor_runtime_values.items()},
                        ),
                    )
                    instrumentation_statement = (instrumentation_sql, instrumentation_params or None)
                prepared_info = None
                statement_framing = None
                if isinstance(prepared_execution, PreparedTerminalExecution):
                    prepared_info = prepared_execution.prerender_info
                    statement_framing = prepared_execution.statement_framing
                request_batch.add_typed_statement(
                    sql_text,
                    normalized_params or None,
                    requires_recursion_diagnostics=requires_mariadb_recursion_diagnostics(grammar),
                    explain_eligible=explain_eligible,
                    instrumentation_statement=instrumentation_statement,
                    prerender_info=prepared_info,
                    statement_framing=statement_framing,
                )
                return
            native_batch.add(sql_text, normalized_params or None)

        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlSessionType,
            SqlSessionValue,
            SysIdValue,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_session_context import (
            SqlApplySessionAndQueueAuthState,
            SqlApplySessionContext,
            SqlApplySessionState,
        )

        has_session_state_statement = any(
            isinstance(stmt, SqlApplySessionState | SqlApplySessionAndQueueAuthState) for stmt in batch.statements
        )
        session_state = None if has_session_state_statement else self._mariadb_session_state_grammar()
        mariadb_session_state_prepended = session_state is not None
        if session_state is not None:
            state_sql, state_params = render_to_sql(session_state, dialect)
            _add_checked_native_statement(session_state, RawSqlText(state_sql), tuple(state_params))
            result_specs.append((False, None, False))
        elif (
            self._backend_profile.traits.backend_type is BackendType.POSTGRES
            and isinstance(self._session_id, SessionId)
            and not has_session_state_statement
        ):
            session_type = SqlSessionType(
                "system" if self._session_id.is_schema_session() else "user",
            )
            session_state = SqlApplySessionContext(
                SysIdValue(self._session_id.unwrap_to_sql()),
                session_type,
            )
            state_sql, state_params = render_to_sql(session_state, dialect)
            _add_checked_native_statement(session_state, RawSqlText(state_sql), tuple(state_params))
            result_specs.append((False, None, False))
        pending_owned_cleanups = self._conn._pending_transaction_temporary_cleanups()
        owned_temp_cleanups: dict[SqlTableName, SqlRenderable] = {cleanup.table_name: cleanup for cleanup in pending_owned_cleanups}
        prepared_owned_temp_tables: set[SqlTableName] = {cleanup.table_name for cleanup in pending_owned_cleanups}
        for index, stmt in enumerate(batch.statements):
            ext_params, ext_first, _recover, needs_returning_override, result_mode, result_label = self._statement_batch_stmt_params(
                batch,
                index,
            )
            needs_returning = needs_returning_override if needs_returning_override is not None else self._has_returning_clause(stmt)
            collect_results = result_mode is not StatementBatchResultMode.DISCARD
            stmt_to_execute = self._statement_batch_executable_stmt(
                stmt,
                backend_type=self._backend_profile.traits.backend_type,
                needs_returning=needs_returning,
            )
            from impl.common.l2100_sql_grammar.domain.infra.stmt_temporary_relation import (
                SqlCreateTemporaryTableAsSelect,
                SqlDropTemporaryTableIfExists as SqlOwnedTemporaryTableCleanup,
            )
            from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlBindExternalParams
            from impl.common.l2100_sql_grammar.tree.identifiers import SqlIdentifier
            from impl.common.l2100_sql_grammar.tree.statements import (
                SqlCreateTemporaryTableAs,
                SqlStatementLocalWith,
                SqlWith,
            )

            owned_temp_create = stmt_to_execute
            while isinstance(owned_temp_create, SqlBindExternalParams | SqlWith | SqlStatementLocalWith):
                if isinstance(owned_temp_create, SqlBindExternalParams):
                    owned_temp_create = owned_temp_create._inner
                elif isinstance(owned_temp_create, SqlWith):
                    owned_temp_create = owned_temp_create._final_query
                else:
                    owned_temp_create = owned_temp_create.split_for_outer_cte()[1]
            cleanup: SqlOwnedTemporaryTableCleanup | None = None
            if isinstance(owned_temp_create, SqlCreateTemporaryTableAsSelect) and owned_temp_create.transaction_owned:
                cleanup = owned_temp_create.cleanup_statement
            elif isinstance(owned_temp_create, SqlCreateTemporaryTableAs):
                table = owned_temp_create.table
                if isinstance(table, SqlIdentifier):
                    cleanup = SqlOwnedTemporaryTableCleanup(SqlTableName(str(table.name)))
            if cleanup is not None:
                from impl.common.l2200_sql_dialect.sql_connection import _SqlConnectionCore

                table_name = cleanup.table_name
                relation_already_owned = table_name in prepared_owned_temp_tables or (
                    isinstance(self._conn, _SqlConnectionCore) and self._conn._owns_transaction_temporary_relation(table_name)
                )
                self._register_owned_temporary_relation(owned_temp_create)
                cleanup_sql, cleanup_params = render_to_sql(cleanup, dialect)
                if relation_already_owned:
                    _add_checked_native_statement(cleanup, RawSqlText(cleanup_sql), tuple(cleanup_params))
                    result_specs.append((False, None, False))
                prepared_owned_temp_tables.add(table_name)
                owned_temp_cleanups[table_name] = cleanup
            if isinstance(stmt_to_execute, SqlTxnControl) and stmt_to_execute.transaction_kind is TxnControlKind.COMMIT:
                for pending_cleanup in owned_temp_cleanups.values():
                    cleanup_sql, cleanup_params = render_to_sql(pending_cleanup, dialect)
                    _add_checked_native_statement(pending_cleanup, RawSqlText(cleanup_sql), tuple(cleanup_params))
                    result_specs.append((False, None, False))
                owned_temp_cleanups.clear()

            if self._backend_profile.traits.backend_type is BackendType.MARIADB:
                scalar_name = request_boolean_assignment_name(stmt)
                if scalar_name is not None:
                    assert request_batch is not None
                    request_batch.declare_request_boolean(scalar_name)
                integer_name = request_integer_assignment_name(stmt)
                if integer_name is not None:
                    assert request_batch is not None
                    request_batch.declare_request_bigint(integer_name)
                for declaration in request_value_declarations(stmt):
                    assert request_batch is not None
                    request_batch.declare_request_value(declaration)

            if mariadb_session_state_prepended:
                from impl.common.l2070_server_plan.codegen.data_modifying_cte_child_policy import (
                    _statement_effect_is_not_a_relation,
                )

                if _statement_effect_is_not_a_relation(stmt_to_execute):
                    continue
            from impl.common.l2100_sql_grammar.domain.infra.stmt_affected_rows import SqlPreviousStatementAffectedRows
            from impl.common.l2100_sql_grammar.tree.statements import SqlStatementLocalWith, SqlWith

            count_body = stmt_to_execute
            while isinstance(count_body, SqlWith | SqlStatementLocalWith):
                count_body = count_body._final_query if isinstance(count_body, SqlWith) else count_body.split_for_outer_cte()[1]
            if isinstance(count_body, SqlPreviousStatementAffectedRows) and request_batch is not None:
                request_batch.add_previous_statement_count()
                result_specs.append((collect_results, result_label, False))
                continue

            external = tuple(ext_params or ())
            if self._backend_profile.traits.backend_type is BackendType.MARIADB:
                assert request_batch is not None
                scoped_statement = SqlRequestStatement(stmt_to_execute)
                for local_name in scoped_statement.additional_boolean_locals:
                    if local_name not in additional_locals:
                        request_batch.declare_request_boolean(local_name)
                        additional_locals.add(local_name)
                stmt_to_execute = scoped_statement
                from impl.common.l2100_sql_grammar.domain.mariadb_recursive import MariaDbDiagnosticRenderScope

                render_scope = MariaDbDiagnosticRenderScope()
                with render_scope:
                    prepared = self._conn.prepare_terminal_sql(
                        stmt_to_execute,
                        params=external,
                        external_params_first=ext_first,
                        needs_returning=needs_returning,
                    )
                if render_scope.uses_previous_count:
                    request_batch.require_previous_count_snapshot()
            else:
                prepared = self._conn.prepare_terminal_sql(
                    stmt_to_execute,
                    params=external,
                    external_params_first=ext_first,
                    needs_returning=needs_returning,
                )
            sql_text = prepared.sql
            from impl.common.l2100_sql_grammar.statement_boundaries import split_top_level_sql_statements

            if self._backend_profile.traits.backend_type is not BackendType.MARIADB and len(split_top_level_sql_statements(sql_text)) > 1:
                return None
            bound_params = _bind_prepared_runtime_slots(
                prepared.params,
                {str(key): value for key, value in self._executor_runtime_values.items()},
            )
            assert isinstance(bound_params, tuple)
            params = validate_sql_param_tuple(bound_params)
            from impl.common.l2070_server_plan.pipeline_trace import trace_execute_ir

            trace_execute_ir(stmt, sql_preview=sql_text, params_preview=params)
            from impl.common.l2100_sql_grammar.tree.statements import _is_typed_explainable_query

            _add_checked_native_statement(
                stmt_to_execute,
                RawSqlText(sql_text),
                params,
                prepared,
                explain_eligible=_is_typed_explainable_query(stmt_to_execute),
            )
            empty_as_count = result_mode is StatementBatchResultMode.DRIVER_ROWCOUNT
            result_specs.append((collect_results, result_label, empty_as_count))
        return native_batch, tuple(result_specs)

    def _materialize_native_statement_batch_results(
        self: SqlBackendExecutor,
        results: tuple[SqlBatchResult, ...],
        result_specs: tuple[tuple[bool, str | None, bool], ...],  # broad-type: accepted
    ) -> RawResult:
        materialized: list[DatabaseRow] = []
        for result, (collect_results, result_label, empty_as_count) in zip(results, result_specs, strict=True):
            if not collect_results:
                continue
            rows: list[DatabaseRow]
            if result.rows:
                rows = [dict(row) for row in result.rows]
            elif empty_as_count:
                rows = [{"count": result.rowcount if result.rowcount >= 0 else 0}]
            else:
                rows = []
            materialized.extend(self._label_statement_batch_result_rows(rows, result_label))
        return materialized

    def _register_statement_batch_owned_temporary_relations(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> None:
        """Register nested resources owned by a transaction-terminal program.

        Nonterminal batches own and clean up their nested temporary relations within
        one request. Registering those relations as transaction resources would add
        a physical request boundary. See
        ``docs/design/NER1689_MARIADB_GRAPH_BOOTSTRAP.rst``.
        """
        if not self._statement_batch_contains_database_commit(batch):
            return

        def _register_nested(nested_owner: SqlStatementBatch) -> None:
            for statement in nested_owner.statements:
                nested_batch = extract_statement_batch(statement)
                if nested_batch is None:
                    self._register_owned_temporary_relation(statement)
                else:
                    _register_nested(nested_batch)

        _register_nested(batch)

    @staticmethod
    def _statement_batch_contains_database_commit(batch: SqlStatementBatch) -> bool:
        for statement in batch.statements:
            if isinstance(statement, SqlTxnControl) and statement.transaction_kind is TxnControlKind.COMMIT:
                return True
            nested = extract_statement_batch(statement)
            if nested is not None and SqlBackendExecutor._statement_batch_contains_database_commit(nested):
                return True
        return False

    def _batch_requires_resource_boundaries(self: SqlBackendExecutor, batch: SqlStatementBatch) -> bool:
        if not self._is_write_transaction:
            return False
        from impl.common.l2100_sql_grammar.domain.infra.stmt_temporary_relation import SqlCreateTemporaryTableAsSelect
        from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner

        if isinstance(self._conn, TransactionTemporaryRelationOwner) and self._conn._has_transaction_temporary_relations():
            return True
        for statement in batch.statements:
            if isinstance(statement, SqlCreateTemporaryTableAsSelect) and statement.transaction_owned:
                return True
            nested = extract_statement_batch(statement)
            if nested is not None and self._batch_requires_resource_boundaries(nested):
                return True
        return False

    def _admit_statement_batch(self: SqlBackendExecutor, batch: SqlStatementBatch) -> None:
        """Reject declared subdivisions before any enclosing batch can submit SQL."""
        if not single_sql_request_is_required():
            return
        if batch.category is SqlStatementBatchCategory.BUDGET_SPLIT:
            admit_sql_request_regions(self._count_statement_batch_leaf_statements(batch))
        for statement in batch.statements:
            nested = extract_statement_batch(statement)
            if nested is not None:
                self._admit_statement_batch(nested)

    def _closed_request_temporary_cleanups(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> tuple[SqlDropTemporaryTableIfExists, ...]:
        if batch.category is not SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY and not single_sql_request_is_required():
            return ()
        from impl.common.l2200_sql_dialect.sql_connection import _SqlConnectionCore

        if not isinstance(self._conn, _SqlConnectionCore):
            return ()
        return self._conn._pending_transaction_temporary_cleanups()

    def _release_closed_request_temporary_relations(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> None:
        """Release request-owned temporary relations inside the same SQL request."""
        pending = self._closed_request_temporary_cleanups(batch)
        for cleanup in pending:
            self._before_sql_statement_execution(cleanup)
            self._conn._execute_direct_internal(
                cleanup,
                params=None,
                external_params_first=False,
                fetch_mode="none",
                use_savepoint_recovery=False,
                track_rtt=self._consume_plan_sql_rtt_tracking(),
            )
        self._conn._mark_transaction_temporary_relations_released(
            tuple(cleanup.table_name for cleanup in pending),
        )

    async def _release_closed_request_temporary_relations_async(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> None:
        """Async release of request-owned temporary relations in the same request."""
        pending = self._closed_request_temporary_cleanups(batch)
        for cleanup in pending:
            self._before_sql_statement_execution_for_async(cleanup)
            await self._conn._execute_direct_internal_async(
                cleanup,
                params=None,
                external_params_first=False,
                fetch_mode="none",
                use_savepoint_recovery=False,
                track_rtt=self._consume_plan_sql_rtt_tracking(),
            )
        self._conn._mark_transaction_temporary_relations_released(
            tuple(cleanup.table_name for cleanup in pending),
        )

    def _run_statement_batch_plan(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> RawResult:
        """Execute each child statement of a statement batch sequentially."""
        from impl.common.l2070_server_plan.execution_context import (
            allow_direct_sql_in_step_execution,
            server_plan_execution_context,
        )

        batch_typed = self._validate_statement_batch(batch)
        self._admit_statement_batch(batch_typed)
        self._register_statement_batch_owned_temporary_relations(batch_typed)
        resource_boundaries = self._batch_requires_resource_boundaries(batch_typed)
        uses_native_postgres_terminal = (
            not resource_boundaries
            and self._backend_profile.traits.backend_type is BackendType.POSTGRES
            and isinstance(self._conn, _BootstrapTerminalBatchExecutor)
        )
        if not uses_native_postgres_terminal:
            batch_typed = self._split_postgres_create_table_foreign_keys(batch_typed)
        batch_started = time.perf_counter()
        with server_plan_execution_context(), allow_direct_sql_in_step_execution():
            backend_type = self._backend_profile.traits.backend_type
            boundary_expansion_required = batch_typed.category is SqlStatementBatchCategory.BUDGET_SPLIT
            if (
                backend_type is BackendType.SQLITE
                and not boundary_expansion_required
                and (not resource_boundaries or self._statement_batch_contains_database_commit(batch_typed))
            ):
                try:
                    result = self._conn._execute_direct_internal(
                        batch_typed,
                        fetch_mode="all",
                        use_savepoint_recovery=False,
                        track_rtt=self._consume_plan_sql_rtt_tracking(),
                    )
                except TypeError as exc:
                    msg = (
                        "SQL statement-batch direct execution rejected the declared batch. "
                        f"category={batch_typed.category.value!r} "
                        f"statement_count={self._count_statement_batch_leaf_statements(batch_typed)}. "
                        "A dispatched batch cannot retry through child expansion."
                    )
                    raise TypeError(msg) from exc
                if result is None:
                    msg = (
                        "SQL statement-batch direct execution returned no result. "
                        f"category={batch_typed.category.value!r} "
                        f"statement_count={self._count_statement_batch_leaf_statements(batch_typed)}. "
                        "A dispatched batch cannot retry through child expansion."
                    )
                    raise RuntimeError(msg)
                from l2092_timing_tracking import merge_active_pipeline_step_timing

                merge_active_pipeline_step_timing(
                    {
                        "statement_batch_category": batch_typed.category.value,
                        "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                        "statement_batch_statement_count": self._count_statement_batch_leaf_statements(batch_typed),
                    },
                )
                return cast("RawResult", result)
            statement_count = self._count_statement_batch_leaf_statements(batch_typed)
            if (
                not resource_boundaries
                and backend_type is BackendType.POSTGRES
                and isinstance(self._conn, _BootstrapTerminalBatchExecutor)
            ):
                result = self._conn._execute_bootstrap_application_terminal_statement_batch(
                    batch_typed,
                    dialect=self._conn.get_dialect(),
                )
                if result is not None:
                    from l2092_timing_tracking import merge_active_pipeline_step_timing

                    merge_active_pipeline_step_timing(
                        {
                            "statement_batch_category": batch_typed.category.value,
                            "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                            "statement_batch_statement_count": statement_count,
                        },
                    )
                    return result
            if batch_typed.category is SqlStatementBatchCategory.BOOTSTRAP_DML:
                self._enforce_statement_batch_bind_parameter_capacity(batch_typed)
                capabilities = frozenset(self._conn.get_capabilities())
                if BackendCapability.PARAMETERIZED_DML_STATEMENT_BATCH in capabilities and isinstance(
                    self._conn, _BootstrapDmlBatchExecutor
                ):
                    result = self._conn._execute_bootstrap_dml_statement_batch(
                        batch_typed,
                        dialect=self._conn.get_dialect(),
                    )
                    from l2092_timing_tracking import merge_active_pipeline_step_timing

                    merge_active_pipeline_step_timing(
                        {
                            "statement_batch_category": batch_typed.category.value,
                            "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                            "statement_batch_statement_count": statement_count,
                        },
                    )
                    return result
                if statement_count > 1 or BackendCapability.PARAMETERIZED_DML_STATEMENT_BATCH in capabilities:
                    msg = (
                        "BOOTSTRAP_DML requires backend-native statement-batch execution; "
                        f"backend={backend_type.value!r} statement_count={statement_count}"
                    )
                    raise RuntimeError(msg)
                # A singleton batch has no cross-statement atomicity or parameter-routing
                # semantics to preserve, so execute its sole child through the normal lane.
            native_statement_batch = self._prepare_native_statement_batch(batch_typed)
            if native_statement_batch is not None:
                native_batch, result_specs = native_statement_batch
                for stmt in batch_typed.statements:
                    self._before_sql_statement_execution(stmt)
                    self._register_owned_temporary_relation(stmt)
                native_results = native_batch.execute()
                if self._backend_profile.traits.backend_type is BackendType.MARIADB:
                    from l2070_batching.backend_profile import SqlListTransport
                    from l2070_batching.backend_runtime_capabilities import NativeListBindingBatch
                    from l2070_batching.native_list_diagnostics import (
                        mark_native_list_driver_shape_observed,
                    )

                    if isinstance(native_batch, NativeListBindingBatch) and native_batch.native_list_binding:
                        mark_native_list_driver_shape_observed(SqlListTransport.MARIADB_JSON_TABLE)
                _record_transaction_control_batch_timing(
                    tuple(batch_typed.statements),
                    (time.perf_counter() - batch_started) * 1000.0,
                )
                receipt = native_batch.execution_receipt
                if receipt is not None:
                    self._native_batch_statement_count += receipt.statement_count
                    self._native_batch_driver_round_trips += receipt.driver_round_trips
                    self._native_batch_execution_count += 1
                return self._materialize_native_statement_batch_results(tuple(native_results), result_specs)
            if backend_type is BackendType.SQLITE and statement_count > 1 and self._consume_plan_sql_rtt_tracking():
                from l2070_batching.backend_runtime_capabilities import BatchRoundTripTracker

                if isinstance(self._conn, BatchRoundTripTracker):
                    self._conn._track_pipelined_batch_round_trip(statement_count)
            admit_sql_request_regions(1 if backend_type is BackendType.SQLITE else statement_count)
            results: list[DatabaseRow] = []
            for i, stmt in enumerate(batch_typed.statements):
                raw_result_label = batch_typed.result_labels_per_stmt[i] if i < len(batch_typed.result_labels_per_stmt) else None
                result_label = raw_result_label if raw_result_label is not None else None
                nested_batch = extract_statement_batch(stmt)
                if nested_batch is not None:
                    nested_results = self._run_statement_batch_plan(nested_batch)
                    results.extend(self._label_statement_batch_result_rows(nested_results, result_label))
                    continue
                if boundary_expansion_required and not resource_boundaries:
                    singleton_batch = self._singleton_ordered_statement_batch(batch_typed, i)
                    native_singleton = self._prepare_native_statement_batch(singleton_batch)
                    if native_singleton is not None:
                        native_batch, result_specs = native_singleton
                        self._before_sql_statement_execution(stmt)
                        native_results = native_batch.execute()
                        receipt = native_batch.execution_receipt
                        if receipt is not None:
                            self._native_batch_statement_count += receipt.statement_count
                            self._native_batch_driver_round_trips += receipt.driver_round_trips
                            self._native_batch_execution_count += 1
                        results.extend(
                            self._materialize_native_statement_batch_results(tuple(native_results), result_specs),
                        )
                        continue
                param_extract_started = time.perf_counter()
                (
                    ext_params,
                    ext_first,
                    use_savepoint_recovery,
                    needs_returning_override,
                    result_mode,
                    result_label,
                ) = self._statement_batch_stmt_params(
                    batch_typed,
                    i,
                )
                needs_returning = needs_returning_override if needs_returning_override is not None else self._has_returning_clause(stmt)
                collect_results = result_mode is not StatementBatchResultMode.DISCARD
                from l2092_timing_tracking import add_active_pipeline_step_duration

                add_active_pipeline_step_duration(
                    "statement_batch_metadata_ms",
                    (time.perf_counter() - param_extract_started) * 1000.0,
                )
                stmt_to_execute = self._statement_batch_executable_stmt(
                    stmt,
                    backend_type=backend_type,
                    needs_returning=needs_returning,
                )
                self._before_sql_statement_execution(stmt_to_execute)
                if isinstance(stmt_to_execute, SqlTxnControl) and stmt_to_execute.transaction_kind is TxnControlKind.COMMIT:
                    from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner

                    if isinstance(self._conn, TransactionTemporaryRelationOwner):
                        self._conn._release_transaction_temporary_relations()
                server_execution_started = time.perf_counter()
                if needs_returning:
                    try:
                        rows = cast(
                            list[DatabaseRow],
                            self._conn._execute_direct_internal(
                                stmt_to_execute,
                                params=ext_params,
                                external_params_first=ext_first,
                                fetch_mode="all",
                                use_savepoint_recovery=use_savepoint_recovery,
                                track_rtt=self._consume_plan_sql_rtt_tracking(),
                            ),
                        )
                    finally:
                        from l2092_timing_tracking import add_active_pipeline_step_duration

                        add_active_pipeline_step_duration(
                            "server_execution_ms",
                            (time.perf_counter() - server_execution_started) * 1000.0,
                            count_field="server_execution_count",
                        )
                    if collect_results:
                        results.extend(self._label_statement_batch_result_rows(rows, result_label))
                else:
                    try:
                        self._conn._execute_direct_internal(
                            stmt_to_execute,
                            params=ext_params,
                            external_params_first=ext_first,
                            fetch_mode="none",
                            use_savepoint_recovery=use_savepoint_recovery,
                            track_rtt=self._consume_plan_sql_rtt_tracking(),
                        )
                    except Exception:
                        if os.environ.get("NERA_DEBUG_STATEMENT_BATCH_CHILD"):
                            from impl.common.l2100_sql_grammar.tree.statements import SqlCteDefinition, SqlWith

                            definitions = stmt._definitions if isinstance(stmt, SqlWith) else ()
                            print(
                                "[FAILED_STATEMENT_BATCH_CHILD]",
                                {
                                    "index": i,
                                    "type": type(stmt).__name__,
                                    "extracts_batch": extract_statement_batch(stmt) is not None,
                                    "result_label": result_label,
                                    "cte_count": len(definitions) if isinstance(definitions, tuple | list) else None,
                                    "cte_preview": [
                                        (
                                            str(definition.name),
                                            type(definition.query).__name__,
                                        )
                                        for definition in tuple(definitions)[:12]
                                        if isinstance(definition, SqlCteDefinition)
                                    ]
                                    if definitions
                                    else None,
                                },
                                file=sys.stderr,
                            )
                        raise
                    finally:
                        from l2092_timing_tracking import add_active_pipeline_step_duration

                        add_active_pipeline_step_duration(
                            "server_execution_ms",
                            (time.perf_counter() - server_execution_started) * 1000.0,
                            count_field="server_execution_count",
                        )
                    rowcount = self._conn._rowcount()
                    if collect_results:
                        result_row: DatabaseRow = {"count": rowcount if rowcount >= 0 else 0}
                        results.extend(self._label_statement_batch_result_rows([result_row], result_label))
                self._register_owned_temporary_relation(stmt_to_execute)
            from l2092_timing_tracking import merge_active_pipeline_step_timing

            merge_active_pipeline_step_timing(
                {
                    "statement_batch_category": batch_typed.category.value,
                    "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                    "statement_batch_statement_count": self._count_statement_batch_leaf_statements(batch_typed),
                },
            )
            return results

    def _split_postgres_create_table_foreign_keys(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> SqlStatementBatch:
        """Create all table bodies before adding FK constraints.

        PostgreSQL and MariaDB both support typed ``ALTER TABLE ... ADD`` FK
        creation. MariaDB additionally requires this partition for forward and
        cyclic references because inline CREATE TABLE constraints require the
        target table to exist. SQLite retains inline constraints because its
        ALTER TABLE surface cannot add them later.
        """

        backend_type = self._backend_profile.traits.backend_type
        if backend_type not in {BackendType.POSTGRES, BackendType.MARIADB}:
            return batch
        logical_phase = batch.logical_phase or ""
        if logical_phase.startswith("bootstrap_application_terminal:"):
            return batch
        from impl.common.l2100_sql_grammar.postgres_bootstrap_ddl_plan import (
            split_postgres_statement_batch_foreign_keys,
        )

        # ``_conn`` is a concrete SQL connection by constructor contract. Do not
        # synthesize dialect behavior when that contract is broken; the splitter
        # consumes typed statement structure and needs no fallback dialect.
        return cast(
            SqlStatementBatch,
            split_postgres_statement_batch_foreign_keys(batch),
        )

    def _split_create_table_foreign_keys_for_bootstrap(
        self: SqlBackendExecutor,
        stmt: SqlRenderable,
    ) -> tuple[SqlRenderable, tuple[SqlRenderable, ...]] | None:
        del self, stmt
        return None

    async def _run_statement_batch_plan_for_async_target_async(
        self: SqlBackendExecutor,
        batch: SqlStatementBatch,
    ) -> RawResult:
        """Async variant of statement-batch execution."""
        from impl.common.l2070_server_plan.execution_context import (
            allow_direct_sql_in_step_execution,
            server_plan_execution_context,
        )

        batch_typed = self._validate_statement_batch(batch)
        self._admit_statement_batch(batch_typed)
        self._register_statement_batch_owned_temporary_relations(batch_typed)
        resource_boundaries = self._batch_requires_resource_boundaries(batch_typed)
        batch_typed = self._split_postgres_create_table_foreign_keys(batch_typed)
        batch_started = time.perf_counter()
        with server_plan_execution_context(), allow_direct_sql_in_step_execution():
            backend_type = self._backend_profile.traits.backend_type
            boundary_expansion_required = batch_typed.category is SqlStatementBatchCategory.BUDGET_SPLIT
            if (
                self._conn is not None
                and backend_type is BackendType.SQLITE
                and not boundary_expansion_required
                and (not resource_boundaries or self._statement_batch_contains_database_commit(batch_typed))
            ):
                try:
                    result = await self._conn._execute_direct_internal_async(
                        batch_typed,
                        fetch_mode="all",
                        use_savepoint_recovery=False,
                        track_rtt=self._consume_plan_sql_rtt_tracking(),
                    )
                except TypeError as exc:
                    msg = (
                        "Async SQL statement-batch direct execution rejected the declared batch. "
                        f"category={batch_typed.category.value!r} "
                        f"statement_count={self._count_statement_batch_leaf_statements(batch_typed)}. "
                        "Backends must either execute SqlStatementBatch explicitly or avoid exposing "
                        "_execute_direct_internal_async for batch objects; silent sequential fallback is forbidden."
                    )
                    raise TypeError(msg) from exc
                if result is None:
                    msg = (
                        "Async SQL statement-batch direct execution returned no result. "
                        f"category={batch_typed.category.value!r} "
                        f"statement_count={self._count_statement_batch_leaf_statements(batch_typed)}. "
                        "A dispatched batch cannot retry through child expansion."
                    )
                    raise RuntimeError(msg)
                from l2092_timing_tracking import merge_active_pipeline_step_timing

                merge_active_pipeline_step_timing(
                    {
                        "statement_batch_category": batch_typed.category.value,
                        "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                        "statement_batch_statement_count": self._count_statement_batch_leaf_statements(batch_typed),
                    },
                )
                return cast("RawResult", result)
            statement_count = self._count_statement_batch_leaf_statements(batch_typed)
            if not resource_boundaries and backend_type is BackendType.POSTGRES:
                from impl.common.l2100_sql_grammar.postgres_bootstrap_terminal import (
                    execute_postgres_bootstrap_application_terminal_async,
                )

                postgres_terminal_result = await execute_postgres_bootstrap_application_terminal_async(
                    self._conn,
                    batch_typed,
                    dialect=self._conn.get_dialect(),
                )
                if postgres_terminal_result is not None:
                    from l2092_timing_tracking import merge_active_pipeline_step_timing

                    merge_active_pipeline_step_timing(
                        {
                            "statement_batch_category": batch_typed.category.value,
                            "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                            "statement_batch_statement_count": statement_count,
                        },
                    )
                    return cast("RawResult", postgres_terminal_result)
            if batch_typed.category is SqlStatementBatchCategory.BOOTSTRAP_DML:
                self._enforce_statement_batch_bind_parameter_capacity(batch_typed)
                capabilities = frozenset(self._conn.get_capabilities())
                if BackendCapability.PARAMETERIZED_DML_STATEMENT_BATCH in capabilities and isinstance(
                    self._conn, _AsyncBootstrapDmlBatchExecutor
                ):
                    result = await self._conn._execute_bootstrap_dml_statement_batch_async(
                        batch_typed,
                        dialect=self._conn.get_dialect(),
                    )
                    from l2092_timing_tracking import merge_active_pipeline_step_timing

                    merge_active_pipeline_step_timing(
                        {
                            "statement_batch_category": batch_typed.category.value,
                            "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                            "statement_batch_statement_count": statement_count,
                        },
                    )
                    return result
                msg = (
                    "BOOTSTRAP_DML requires backend-native async statement-batch execution; "
                    f"backend={backend_type.value!r} statement_count={statement_count}"
                )
                raise RuntimeError(msg)
            native_statement_batch = self._prepare_native_statement_batch(batch_typed)
            if native_statement_batch is not None:
                native_batch, result_specs = native_statement_batch
                for stmt in batch_typed.statements:
                    self._before_sql_statement_execution_for_async(stmt)
                    self._register_owned_temporary_relation(stmt)
                native_results = await native_batch.execute_async()
                if self._backend_profile.traits.backend_type is BackendType.MARIADB:
                    from l2070_batching.backend_profile import SqlListTransport
                    from l2070_batching.backend_runtime_capabilities import NativeListBindingBatch
                    from l2070_batching.native_list_diagnostics import (
                        mark_native_list_driver_shape_observed,
                    )

                    if isinstance(native_batch, NativeListBindingBatch) and native_batch.native_list_binding:
                        mark_native_list_driver_shape_observed(SqlListTransport.MARIADB_JSON_TABLE)
                _record_transaction_control_batch_timing(
                    tuple(batch_typed.statements),
                    (time.perf_counter() - batch_started) * 1000.0,
                )
                return self._materialize_native_statement_batch_results(
                    tuple(native_results),
                    result_specs,
                )
            if backend_type is BackendType.SQLITE and statement_count > 1 and self._consume_plan_sql_rtt_tracking():
                from l2070_batching.backend_runtime_capabilities import BatchRoundTripTracker

                if isinstance(self._conn, BatchRoundTripTracker):
                    self._conn._track_pipelined_batch_round_trip(statement_count)
            admit_sql_request_regions(1 if backend_type is BackendType.SQLITE else statement_count)
            results: list[DatabaseRow] = []
            for i, stmt in enumerate(batch_typed.statements):
                raw_result_label = batch_typed.result_labels_per_stmt[i] if i < len(batch_typed.result_labels_per_stmt) else None
                result_label = raw_result_label if raw_result_label is not None else None
                nested_batch = extract_statement_batch(stmt)
                if nested_batch is not None:
                    nested_results = await self._run_statement_batch_plan_for_async_target_async(nested_batch)
                    results.extend(self._label_statement_batch_result_rows(nested_results, result_label))
                    continue
                if boundary_expansion_required and not resource_boundaries:
                    singleton_batch = self._singleton_ordered_statement_batch(batch_typed, i)
                    native_singleton = self._prepare_native_statement_batch(singleton_batch)
                    if native_singleton is not None:
                        native_batch, result_specs = native_singleton
                        self._before_sql_statement_execution_for_async(stmt)
                        results.extend(
                            self._materialize_native_statement_batch_results(
                                tuple(await native_batch.execute_async()),
                                result_specs,
                            ),
                        )
                        continue
                param_extract_started = time.perf_counter()
                (
                    ext_params,
                    ext_first,
                    use_savepoint_recovery,
                    needs_returning_override,
                    result_mode,
                    result_label,
                ) = self._statement_batch_stmt_params(
                    batch_typed,
                    i,
                )
                needs_returning = needs_returning_override if needs_returning_override is not None else self._has_returning_clause(stmt)
                collect_results = result_mode is not StatementBatchResultMode.DISCARD
                from l2092_timing_tracking import add_active_pipeline_step_duration

                add_active_pipeline_step_duration(
                    "statement_batch_metadata_ms",
                    (time.perf_counter() - param_extract_started) * 1000.0,
                )
                stmt_to_execute = self._statement_batch_executable_stmt(
                    stmt,
                    backend_type=backend_type,
                    needs_returning=needs_returning,
                )
                self._before_sql_statement_execution_for_async(stmt_to_execute)
                if isinstance(stmt_to_execute, SqlTxnControl) and stmt_to_execute.transaction_kind is TxnControlKind.COMMIT:
                    from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner

                    if isinstance(self._conn, TransactionTemporaryRelationOwner):
                        await self._conn._release_transaction_temporary_relations_async()
                server_execution_started = time.perf_counter()
                if needs_returning:
                    try:
                        rows = cast(
                            list[DatabaseRow],
                            await self._conn._execute_direct_internal_async(
                                stmt_to_execute,
                                params=ext_params,
                                external_params_first=ext_first,
                                fetch_mode="all",
                                use_savepoint_recovery=use_savepoint_recovery,
                                track_rtt=self._consume_plan_sql_rtt_tracking(),
                            ),
                        )
                    except Exception:
                        if os.environ.get("NERA_DEBUG_FAILED_SIMPLE_SQL"):
                            sql, params = render_to_sql(stmt, self._conn.get_dialect())
                            print("[FAILED_STATEMENT_BATCH_SQL]", sql, params, file=sys.stderr)
                        raise
                    finally:
                        from l2092_timing_tracking import add_active_pipeline_step_duration

                        add_active_pipeline_step_duration(
                            "server_execution_ms",
                            (time.perf_counter() - server_execution_started) * 1000.0,
                            count_field="server_execution_count",
                        )
                    if collect_results:
                        results.extend(self._label_statement_batch_result_rows(rows, result_label))
                else:
                    try:
                        await self._conn._execute_direct_internal_async(
                            stmt_to_execute,
                            params=ext_params,
                            external_params_first=ext_first,
                            fetch_mode="none",
                            use_savepoint_recovery=use_savepoint_recovery,
                            track_rtt=self._consume_plan_sql_rtt_tracking(),
                        )
                    except Exception:
                        if os.environ.get("NERA_DEBUG_FAILED_SIMPLE_SQL"):
                            sql, params = render_to_sql(stmt, self._conn.get_dialect())
                            print("[FAILED_STATEMENT_BATCH_SQL]", sql, params, file=sys.stderr)
                        raise
                    finally:
                        from l2092_timing_tracking import add_active_pipeline_step_duration

                        add_active_pipeline_step_duration(
                            "server_execution_ms",
                            (time.perf_counter() - server_execution_started) * 1000.0,
                            count_field="server_execution_count",
                        )
                    rowcount = self._conn._rowcount()
                    if collect_results:
                        result_row: DatabaseRow = {"count": rowcount if rowcount >= 0 else 0}
                        results.extend(self._label_statement_batch_result_rows([result_row], result_label))
                self._register_owned_temporary_relation(stmt_to_execute)
            from l2092_timing_tracking import merge_active_pipeline_step_timing

            merge_active_pipeline_step_timing(
                {
                    "statement_batch_category": batch_typed.category.value,
                    "statement_batch_ms": round((time.perf_counter() - batch_started) * 1000.0, 3),
                    "statement_batch_statement_count": self._count_statement_batch_leaf_statements(batch_typed),
                },
            )
            return results

    def _track_bytes_if_enabled(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
        result: RawResult,
    ) -> None:
        from l2090_byte_tracking import is_byte_tracking_enabled, track_query_bytes

        if not is_byte_tracking_enabled():
            return
        if ir.grammar is None:
            return
        dialect = self._conn.get_dialect()
        frag = ir.grammar.render(dialect)
        sql_str, params = frag.to_sql(dialect)
        all_params = (ir.params or ()) + params
        track_query_bytes(sql_str, all_params, result)

    @staticmethod
    def _ir_contains_database_commit(ir: SqlStepIR) -> bool:
        visited: set[int] = set()

        def _stmt_is_commit(stmt: object) -> bool:
            stmt_id = id(stmt)
            if stmt_id in visited:
                return False
            visited.add(stmt_id)
            if isinstance(stmt, SqlTxnControl):
                return stmt.transaction_kind is TxnControlKind.COMMIT
            statement_batch = extract_statement_batch(stmt)
            if statement_batch is not None:
                return any(_stmt_is_commit(child) for child in statement_batch.statements)
            for attribute in map(DynamicFieldName, ("_inner", "_final_query", "_select")):
                child = _read_private_attr(stmt, attribute)
                if child is not None and _stmt_is_commit(child):
                    return True
            return False

        grammar = _require_sql_executable_ir(ir).grammar
        return _stmt_is_commit(grammar)

    async def _dispatch_prepared_ir_async(
        self: SqlBackendExecutor,
        execution: _PreparedSqlIrExecution,
    ) -> RawResult:
        _, run_async = self._prepared_dispatch_runners(execution)
        return await run_async()

    async def _execute_ir_transport_async(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
        *,
        materializes_backend: bool | None = None,
    ) -> RawResult:
        raise_if_sql_grammar_execution_from_post_op(operation="SqlBackendExecutor.execute_ir_async")
        execution = self._prepare_ir_execution(ir, materializes_backend)
        with self._ir_execution_authority_scope(
            execution,
            commit_context=DiagnosticLabel("serverplan_sql_commit_async"),
        ):
            if self._is_write_transaction and execution.materializes_backend:
                if (
                    self._ir_contains_database_commit(execution.sql_ir)
                    and self._backend_profile.traits.backend_type is BackendType.SQLITE
                ):
                    from l2070_batching.backend_runtime_capabilities import AsyncInlineTransactionEnvelope

                    if not isinstance(self._conn, AsyncInlineTransactionEnvelope):
                        raise TypeError("SQLite backend does not provide async inline transaction preparation")
                    await self._conn._prepare_inline_transaction_envelope_async()
                else:
                    await self._conn._materialize_data_transaction_backend_async()
            if self._is_write_transaction and self._ir_contains_database_commit(execution.sql_ir):
                from l1400_types.type_surface_contracts import DatabaseIdentity
                from l5000_subscriptions.deferred_dispatch import commit_capture_scope_async

                async with commit_capture_scope_async(
                    self._txn,
                    DatabaseIdentity(self._conn.database_identity),
                ):
                    with self._ir_driver_timing_scope(execution):
                        return await self._dispatch_prepared_ir_async(execution)
            with self._ir_driver_timing_scope(execution):
                return await self._dispatch_prepared_ir_async(execution)

    async def execute_ir_with_materialization_hint_async(
        self: SqlBackendExecutor,
        ir: SqlStepIR,
        *,
        materializes_backend: bool | None,
    ) -> RawResult:
        rows = await self._execute_ir_transport_async(
            ir,
            materializes_backend=materializes_backend,
        )
        return self.result_decoder.decode_transport_result(ir, rows)

    def get_batching_strategies(self: SqlBackendExecutor) -> tuple[PhysicalRegionCodegen, ...]:
        strategies: tuple[PhysicalRegionCodegen, ...] = self._backend_profile.batching_strategies
        return strategies

    def get_extra_optimizers(self: SqlBackendExecutor) -> tuple[PlanOptimizer, ...]:
        return tuple(self._backend_profile.pass_registry.extra_optimizers)

    def _lower_commit_intent(
        self: SqlBackendExecutor,
        step: CommitIntent,
        ctx: LoweringContext,
    ) -> tuple[ServerPlanStep[None], ...]:
        """Lower CommitIntent to the backend transaction lifecycle steps."""
        lifecycle_sql_dependencies = step.lifecycle_sql_dependencies()
        if not lifecycle_sql_dependencies:
            lifecycle_sql_dependencies = frozenset(ServerPlanRefId(dependency) for dependency in step.dependencies())
        owner_plan = ctx.owner_plan
        if isinstance(owner_plan, _ProducerStepOwner):
            expanded_dependencies: set[ServerPlanRefId] = set()
            pending_dependencies = list(lifecycle_sql_dependencies)
            visited_dependencies: set[ServerPlanRefId] = set()
            while pending_dependencies:
                dependency_ref = pending_dependencies.pop()
                if dependency_ref in visited_dependencies:
                    continue
                visited_dependencies.add(dependency_ref)
                producer = owner_plan.producer_step(dependency_ref)
                if producer is None:
                    expanded_dependencies.add(dependency_ref)
                    continue
                if (
                    producer.execution_role() is StepExecutionRole.APPLY
                    and producer.emits_sql_for_accounting() is False
                    and producer.allows_later_sql_transport()
                ):
                    pending_dependencies.extend(ServerPlanRefId(ref_id) for ref_id in producer.dependencies())
                    continue
                expanded_dependencies.update(producer.lifecycle_sql_dependency_refs(ctx))
            lifecycle_sql_dependencies = frozenset(expanded_dependencies)
        if ctx.backend_type is BackendType.SQLITE:
            lifecycle_sql_dependencies = frozenset()
        return self._build_commit_intent_lifecycle_steps(
            step.ref_id,
            depends_on=frozenset(ServerPlanRefId(dep) for dep in step.dependencies()),
            lifecycle_sql_dependencies=lifecycle_sql_dependencies,
        )

    def _build_commit_intent_lifecycle_steps(
        self: SqlBackendExecutor,
        ref: ServerPlanRefId,
        *,
        depends_on: frozenset[ServerPlanRefId] = frozenset(),
        lifecycle_sql_dependencies: frozenset[ServerPlanRefId] = frozenset(),
    ) -> tuple[ServerPlanStep[None], ...]:
        """Assemble structural commit lifecycle steps."""
        return self._build_commit_lifecycle_steps(
            ref,
            finalize_suffix=None,
            versioned_state_depends_on=depends_on,
            session_timestamp_depends_on=lifecycle_sql_dependencies,
        )

    def _lower_staged_commit_intent(
        self: SqlBackendExecutor,
        step: StagedCommitIntent,
        ctx: LoweringContext,
    ) -> tuple[ServerPlanStep[None], ...]:
        """Lower staged-only commits without publish/session/event lifecycle work."""
        del ctx
        return self._build_staged_commit_lifecycle_steps(
            step.ref_id,
            depends_on=frozenset(ServerPlanRefId(dep) for dep in step.dependencies()),
        )

    def _build_staged_commit_lifecycle_steps(
        self: SqlBackendExecutor,
        ref: ServerPlanRefId,
        *,
        depends_on: frozenset[ServerPlanRefId] = frozenset(),
    ) -> tuple[HeterogeneousServerPlanStep, ...]:
        from impl.common.l2070_server_plan.steps.commit_branch_steps import VersionedStateMarkStep
        from impl.common.l2070_server_plan.steps.transaction_lifecycle_steps import (
            CommitFinalizeAfterDepsStep,
            DatabaseCommitAfterDepsStep,
        )

        return (
            VersionedStateMarkStep(
                ServerPlanRefId(f"{ref}_vstate"),
                depends_on=depends_on,
            ),
            DatabaseCommitAfterDepsStep(
                ServerPlanRefId(f"{ref}_db_commit"),
                source_refs=[ServerPlanRefId(f"{ref}_vstate")],
            ),
            CommitFinalizeAfterDepsStep(
                ref,
                source_refs=[ServerPlanRefId(f"{ref}_db_commit")],
            ),
        )

    def _lower_commit_branch_intent(
        self: SqlBackendExecutor,
        step: CommitBranchIntent,
        ctx: LoweringContext,
    ) -> Sequence[HeterogeneousServerPlanStep]:
        """Lower semantic commit-branch work and splice executor-owned lifecycle."""
        from impl.common.l2070_server_plan.steps.commit_branch_steps import (
            ProjectCommitBranchResultStep,
        )

        semantic_steps = list(step.lower(ctx))
        if not semantic_steps:
            return semantic_steps
        result_step = semantic_steps[-1]
        if not isinstance(result_step, ProjectCommitBranchResultStep):
            msg = "CommitBranchIntent semantic lowering must end with ProjectCommitBranchResultStep"
            raise RuntimeError(msg)
        local_exports: set[str] = set()
        for semantic_step in semantic_steps[:-1]:
            local_ref = str(semantic_step.ref_id)
            local_exports.add(local_ref)
            contract = semantic_step.cte_publication_contract()
            if contract is not None and contract.columns is not None:
                local_exports.update(f"{local_ref}.{column}" for column in contract.columns)
        semantic_dependencies = frozenset(
            ServerPlanRefId(dependency) for dependency in result_step.dependencies() if dependency in local_exports
        )
        lifecycle_tail = (
            self._build_commit_branch_lifecycle_steps(
                step.ref_id,
                depends_on=semantic_dependencies,
            )
            if step.owns_database_commit()
            else ()
        )
        lifecycle_dependencies = frozenset({lifecycle_tail[-1].ref_id}) if lifecycle_tail else frozenset()
        result_with_lifecycle_dependency = result_step.with_additional_dependencies(
            lifecycle_dependencies,
        )
        return cast(
            Sequence[HeterogeneousServerPlanStep],
            [*semantic_steps[:-1], *lifecycle_tail, result_with_lifecycle_dependency],
        )

    def _lower_squash_branch_intent(
        self: SqlBackendExecutor,
        step: SquashBranchIntent,
        ctx: LoweringContext,
    ) -> Sequence[HeterogeneousServerPlanStep]:
        """Lower squash work and splice commit lifecycle before the result projection."""
        from impl.common.l2070_server_plan.steps.squash_steps import SelectSquashBranchResultStep

        semantic_steps = list(step.lower(ctx))
        trailing_apply_and_select = 2
        if len(semantic_steps) < trailing_apply_and_select:
            return semantic_steps
        apply_if_needed = semantic_steps[-trailing_apply_and_select]
        select_raw = semantic_steps[-1]
        if not isinstance(select_raw, SelectSquashBranchResultStep):
            msg = "SquashBranchIntent semantic lowering must end with SelectSquashBranchResultStep"
            raise RuntimeError(msg)
        head = semantic_steps[:-2]
        lifecycle_tail = self._build_commit_lifecycle_steps(
            step.ref_id,
            finalize_suffix=ServerPlanRefSuffix("base_finalize"),
            versioned_state_depends_on=frozenset({apply_if_needed.ref_id}),
        )
        finalize_ref = ServerPlanRefId(f"{step.ref_id}_base_finalize")
        select_step = SelectSquashBranchResultStep(
            select_raw.ref_id,
            is_noop_ref_id=select_raw._is_noop_ref_id,
            base_revision_ref_id=select_raw._base_revision_ref_id,
            apply_result_ref_id=select_raw._apply_result_ref_id,
            extra_dependencies=frozenset({finalize_ref}),
        )
        return cast(
            Sequence[HeterogeneousServerPlanStep],
            [*head, apply_if_needed, *lifecycle_tail, select_step],
        )

    def _build_commit_branch_lifecycle_steps(
        self: SqlBackendExecutor,
        ref: ServerPlanRefId,
        *,
        depends_on: frozenset[ServerPlanRefId] = frozenset(),
    ) -> tuple[ServerPlanStep[None], ...]:
        """Assemble the commit-branch lifecycle tail structurally."""
        return self._build_commit_lifecycle_steps(
            ref,
            finalize_suffix=ServerPlanRefSuffix("base_finalize"),
            versioned_state_depends_on=frozenset({ServerPlanRefId(f"{ref}_update_tip"), *depends_on}),
        )

    def _build_commit_lifecycle_steps(
        self: SqlBackendExecutor,
        ref: ServerPlanRefId,
        *,
        finalize_suffix: ServerPlanRefSuffix | None,
        versioned_state_depends_on: frozenset[ServerPlanRefId] | None = None,
        session_timestamp_depends_on: frozenset[ServerPlanRefId] = frozenset(),
    ) -> tuple[HeterogeneousServerPlanStep, ...]:
        """Assemble structural commit lifecycle steps with the requested finalize step."""
        from impl.common.l2070_server_plan.steps.commit_branch_steps import VersionedStateMarkStep
        from impl.common.l2070_server_plan.steps.transaction_lifecycle_steps import (
            CommitFinalizeAfterDepsStep,
            DatabaseCommitAfterDepsStep,
            RuntimeDatabaseCommitAfterDepsStep,
            SessionTimestampUpdateStep,
            _resolve_cache_lifecycle_owner,
            _resolve_cache_transaction,
            build_cache_commit_lifecycle_steps,
        )

        txn = self._txn_or_none()
        if isinstance(txn, _versioned_write_transaction_types()) and not cast(Any, txn)._owns_base_txn:
            state_ref = ref if finalize_suffix is None else ServerPlanRefId(f"{ref}_vstate")
            return (VersionedStateMarkStep(state_ref, depends_on=versioned_state_depends_on),)
        finalize_ref = ref if finalize_suffix is None else ServerPlanRefId(f"{ref}_{finalize_suffix}")
        steps: list[HeterogeneousServerPlanStep] = [
            VersionedStateMarkStep(
                ServerPlanRefId(f"{ref}_vstate"),
                depends_on=versioned_state_depends_on,
            ),
            SessionTimestampUpdateStep(
                ServerPlanRefId(f"{ref}_session_ts"),
                depends_on=session_timestamp_depends_on,
            ),
        ]
        cache_owner = _resolve_cache_lifecycle_owner(txn)
        cache_txn = None if cache_owner is None else _resolve_cache_transaction(cache_owner)
        if cache_txn is not None:
            concrete_cache_txn = cast("CacheTransaction", cache_txn)
            steps.extend(
                build_cache_commit_lifecycle_steps(
                    ref_id=ref,
                    cache_txn=concrete_cache_txn,
                    finalize_ref=finalize_ref,
                ),
            )
            return tuple(steps)
        runtime_commit_required = bool(
            versioned_state_depends_on and not versioned_state_depends_on.issubset(session_timestamp_depends_on)
        )
        commit_step_type = RuntimeDatabaseCommitAfterDepsStep if runtime_commit_required else DatabaseCommitAfterDepsStep
        steps.extend(
            [
                commit_step_type(
                    ServerPlanRefId(f"{ref}_db_commit"),
                    source_refs=sorted(
                        {ServerPlanRefId(f"{ref}_vstate"), ServerPlanRefId(f"{ref}_session_ts")},
                        key=str,
                    ),
                ),
                CommitFinalizeAfterDepsStep(
                    finalize_ref,
                    source_refs=[ServerPlanRefId(f"{ref}_db_commit")],
                ),
            ],
        )
        return tuple(steps)

    def _lower_rollback_intent(
        self: SqlBackendExecutor,
        step: RollbackIntent,
        ctx: LoweringContext,
    ) -> tuple[ServerPlanStep[None], ...]:
        """Lower RollbackIntent to the backend transaction lifecycle steps."""
        del ctx
        return self._build_rollback_intent_lifecycle_steps(step.ref_id)

    def _build_rollback_intent_lifecycle_steps(
        self: SqlBackendExecutor,
        ref: ServerPlanRefId,
    ) -> tuple[ServerPlanStep[None], ...]:
        """Assemble structural rollback lifecycle steps."""
        from impl.common.l2070_server_plan.steps.transaction_lifecycle_steps import (
            CacheRollbackStep,
            DatabaseRollbackStep,
            PendingLazyOpsRollbackStep,
            RollbackFinalizeStep,
            VersionedRollbackStateStep,
        )

        txn = self._txn_or_none()
        if isinstance(txn, _versioned_write_transaction_types()) and not cast(Any, txn)._owns_base_txn:
            return (
                PendingLazyOpsRollbackStep(ServerPlanRefId(f"{ref}_pending_ops")),
                VersionedRollbackStateStep(ref),
            )
        return (
            PendingLazyOpsRollbackStep(ServerPlanRefId(f"{ref}_pending_ops")),
            VersionedRollbackStateStep(ServerPlanRefId(f"{ref}_vstate")),
            CacheRollbackStep(ServerPlanRefId(f"{ref}_cache_rb")),
            DatabaseRollbackStep(ServerPlanRefId(f"{ref}_db_rollback")),
            RollbackFinalizeStep(ref),
        )

    def get_lowering_context(self: SqlBackendExecutor) -> LoweringContext:
        """Build a LoweringContext from the backend's capabilities."""
        backend_type, dialect, _supports_dml_ctes = self._get_backend_info()
        vi = self._extract_versioning_info()
        profile = self._backend_profile
        txn_candidates = self._build_txn_candidates()
        emit_table_event_intents = not any(
            isinstance(candidate, _versioned_read_transaction_types()) and cast(Any, candidate)._disable_benchmark_table_events
            for candidate in txn_candidates
        )

        def _cache_source_connections() -> tuple[_SqlConnectionCore, ...]:
            conn_for_cache = self._conn
            if not isinstance(conn_for_cache, _SqlConnectionCore):
                conn_for_cache = _unwrap_sql_connection(cast(PlanTarget, conn_for_cache))
            cache_connections = [conn_for_cache]
            sync_schema_conn: object | None = None
            for candidate in (self._conn, conn_for_cache):
                sync_schema_conn = _extract_sync_schema_conn(candidate)
                if sync_schema_conn is not None:
                    break
            if sync_schema_conn is not None and not isinstance(sync_schema_conn, _SqlConnectionCore):
                sync_schema_conn = _unwrap_sql_connection(cast(PlanTarget, sync_schema_conn))
            if sync_schema_conn is not None and sync_schema_conn is not conn_for_cache:
                cache_connections.append(sync_schema_conn)
            return tuple(cache_connections)

        def _embedding_write_infra_factory() -> bool:
            from l4100_queue.queue_message import QueueMessage
            from l5200_vector_index.content_addressable_models import EmbeddingRef
            from l5200_vector_index.embedding_metadata import EmbeddingMetadata

            for table_name in (
                get_table_name(QueueMessage),
                SqlTableName("sys_embedding_metadata"),
                SqlTableName("sys_embedding_refs"),
            ):
                table_name_str = str(table_name)
                cached_states = tuple(source_conn._table_exists_from_cache(table_name) for source_conn in _cache_source_connections())
                if any(state is True for state in cached_states):
                    continue
                authoritative_states = tuple(
                    table_name_str in authoritative_tables
                    for source_conn in _cache_source_connections()
                    for authoritative_tables in (
                        source_conn._authoritative_template_existing_tables
                        if isinstance(source_conn, _AuthoritativeTemplateTablesCarrier)
                        else None,
                    )
                    if isinstance(authoritative_tables, frozenset)
                )
                if any(authoritative_states):
                    continue
                return False
            return True

        def _table_exists_in_cache(table_name: SqlTableName) -> bool | None:
            saw_false = False
            for source_conn in _cache_source_connections():
                cached = source_conn._table_exists_from_cache(table_name)
                if cached is True:
                    return True
                if cached is None and isinstance(source_conn, _AuthoritativeTemplateTablesCarrier):
                    authoritative_tables = source_conn._authoritative_template_existing_tables
                    if isinstance(authoritative_tables, frozenset) and str(table_name) in authoritative_tables:
                        return True
                if cached is False:
                    saw_false = True
            return False if saw_false else None

        def _native_fts_index_exists_in_cache(
            model_table: SqlTableName,
            table_type: VersionedTableType,
        ) -> bool | None:
            cache_key = (model_table, table_type)
            for source_conn in _cache_source_connections():
                if isinstance(source_conn, _NativeFtsIndexCacheCarrier) and cache_key in source_conn._native_fts_index_exists_cache:
                    return bool(source_conn._native_fts_index_exists_cache[cache_key])
            return None

        prefer_tip_strategy, prefer_tip_merged = _extract_versioned_read_strategy_flags(
            txn_candidates,
        )
        _staged_visibility, _connection_id, visibility_source_txn = _extract_staged_visibility_fields(
            txn_candidates,
        )
        if visibility_source_txn is not None:
            prefer_tip_merged = True
        effective_is_write_transaction = self._is_write_transaction or any(
            _target_is_write_transaction(candidate) for candidate in txn_candidates
        )
        publish_budget_bytes = commit_publish_planner_memory_budget_bytes_from_env()
        if (
            publish_budget_bytes is None
            and backend_type == BackendType.POSTGRES
            and not commit_publish_planner_memory_budget_env_is_set()
        ):
            publish_budget_bytes = DEFAULT_COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_BYTES

        branch_tip_materialized = (
            vi.branch_tip_materialized
            if vi.is_versioned
            else _resolve_branch_tip_materialized(
                vi.branch_tip_materialized,
                txn_candidates,
            )
        )

        session_id_source = vi.session_id_source
        lowering_session_id = (
            session_id_source
            if session_id_source is not None
            else SessionId(vi.session_id_str)
            if vi.session_id_str is not None
            else None
        )
        permission_filtering_enabled = True
        authority_session_id = (
            session_id_source
            if isinstance(session_id_source, SessionId)
            else SessionId(vi.session_id_str)
            if vi.session_id_str is not None
            else None
        )
        if authority_session_id is not None:
            permission_filtering_enabled = not (authority_session_id.is_schema_session())

        lowering = LoweringContext(
            backend_type=backend_type,
            dialect=dialect,
            backend_profile=profile,
            has_native_fts=profile.traits.has_native_fts,
            embedding_write_infra_factory=_embedding_write_infra_factory,
            table_exists_in_cache=_table_exists_in_cache,
            native_fts_index_exists_in_cache=_native_fts_index_exists_in_cache,
            has_database_triggers=profile.traits.has_database_triggers,
            has_returning_clause=profile.traits.has_returning_clause,
            branch_id=vi.branch_id,
            revision_id=vi.revision_id,
            explicit_revision_id=vi.explicit_revision_id,
            session_id=lowering_session_id,
            permission_filtering_enabled=permission_filtering_enabled,
            capability_lifecycle_admin_authority=next(
                (
                    authority
                    for candidate in txn_candidates
                    if (authority := capability_lifecycle_admin_authority_for(candidate)) is not None
                ),
                None,
            ),
            staged_commit_id=_extract_staged_commit_id(txn_candidates),
            is_versioned=vi.is_versioned,
            is_write_transaction=effective_is_write_transaction,
            prefer_tip_strategy=prefer_tip_strategy,
            prefer_tip_merged=prefer_tip_merged,
            branch_tip_materialized=branch_tip_materialized,
            emit_table_event_intents=emit_table_event_intents,
            lazy_revision=vi.lazy_revision,
            lazy_branch=vi.lazy_branch,
            lazy_branch_tip_materialization=vi.branch_tip_materialization_ref,
            branch_table=vi.branch_table,
            branch_id_column=vi.branch_id_column,
            branch_tip_revision_column=vi.branch_tip_revision_column,
            branch_deleted_column=vi.branch_deleted_column,
            versioning_domain=cast("Any", vi.versioning_domain),
            staging_ctx_factory=vi.staging_ctx_factory,
            executor_txn_handle=cast(Any, self._txn_or_none()),
            planning_catalog=self._planning_catalog,
            schema_column_cache=_extract_schema_column_cache(self._conn, self._planning_catalog),
            commit_publish_planner_memory_budget_bytes=publish_budget_bytes,
        )
        # The session resolver's query is not a plan step, so the pipeline's
        # lowering pass will never reach it. This is the first point at which a
        # lowering context exists, so it is where that one step gets lowered.
        resolver_source = session_sql_source_or_none(session_id_source)
        if resolver_source is not None:
            resolver_source.lower_resolver(lowering)
        return lowering

    def _get_backend_info(
        self: SqlBackendExecutor,
    ) -> tuple[BackendType, SqlDialect, bool]:
        """Return (backend_type, dialect, supports_dml_ctes) for context construction."""
        traits = self._backend_profile.traits
        dialect = traits.dialect
        if dialect is None:
            msg = "SQL backend profile must provide a SQL dialect"
            raise RuntimeError(msg)
        return traits.backend_type, dialect, traits.supports_data_modifying_ctes

    def get_optimization_context(self: SqlBackendExecutor) -> OptimizationContext:
        backend_type, dialect, supports_dml_ctes = self._get_backend_info()
        txn = self._txn_or_none()
        txn_candidates: tuple[Any, ...] = self._build_txn_candidates()
        cached_validation_hit = False
        cached_validated_user_id: str | None = None
        current_session_source = _resolve_session_source_from_candidates(txn_candidates)
        current_symbolic_source = (
            current_session_source if isinstance(current_session_source, LazySessionSqlSource | ScalarServerRef) else None
        )
        symbolic_session_source = current_symbolic_source
        # Persisted session authority is revalidated for each transaction. A
        # connection-local success cache cannot observe revocation committed by
        # another pooled connection or process. The transaction-local flag below
        # still avoids duplicate validation across flushes in one transaction.
        session_validated = (
            any(candidate._session_validated_in_enter for candidate in txn_candidates if _has_session_validation_flag(candidate))
            or cached_validation_hit
        )
        session_context_applied = any(
            candidate._sql_session_context_applied_via_plan for candidate in txn_candidates if _has_sql_session_context_flag(candidate)
        )

        queue_auth_token: str | None = None
        queue_auth_preamble_required = False
        for candidate in txn_candidates:
            if isinstance(candidate, _RippleQueueAuthTokenCarrier):
                candidate_token = candidate._desired_ripple_queue_auth_token
                if candidate_token is not None:
                    queue_auth_token = candidate_token
            if isinstance(candidate, _QueueAuthPreambleRequirementCarrier):
                queue_auth_preamble_required = queue_auth_preamble_required or candidate._queue_auth_preamble_required
            if queue_auth_token is not None and queue_auth_preamble_required:
                break
        preamble_ids = self._resolve_sql_preamble_ref_ids()
        if preamble_ids is None:
            preamble_ids = set()
        sql_preamble_memo = SqlPreambleMemo(
            frozenset(ServerPlanRefId(ref_id) for ref_id in preamble_ids),
        )
        resolved_session_id = _resolve_session_id_from_candidates(self._session_id, txn_candidates)
        effective_is_write_transaction = self._is_write_transaction or any(
            _target_is_write_transaction(candidate) for candidate in txn_candidates
        )
        return OptimizationContext(
            backend_type=backend_type,
            dialect=dialect,
            supports_data_modifying_ctes=supports_dml_ctes,
            is_write_transaction=effective_is_write_transaction,
            backend_profile=self._backend_profile,
            session_id=resolved_session_id,
            session_id_source=symbolic_session_source,
            batching_strategies=self.get_batching_strategies(),
            session_already_validated=session_validated,
            has_cached_validated_session_user_id=cached_validation_hit,
            cached_validated_session_user_id=cached_validated_user_id,
            session_context_already_applied=session_context_applied,
            queue_auth_token=queue_auth_token,
            queue_auth_preamble_required=queue_auth_preamble_required,
            staged_publish_inline_budget_bytes=staged_publish_inline_budget_bytes_from_env(),
            sql_statement_capacity=self._conn._sql_statement_capacity(),
            sql_preamble_memo=sql_preamble_memo,
            planning_catalog=self._planning_catalog,
            transaction_execution_facts=self._conn._data_transaction_execution_facts(),
            physical_fusion_max_batch_steps=(
                None
                if self._backend_profile.traits.same_plan_write_transport is SamePlanWriteTransport.ORDERED_STATEMENTS
                else 48
                if supports_dml_ctes
                else 64
            ),
        )

    def get_compilation_context(self: SqlBackendExecutor) -> CompilationContext:
        backend_type, dialect, supports_dml_ctes = self._get_backend_info()
        vi = self._extract_versioning_info()

        txn_candidates: tuple[Any, ...] = self._build_txn_candidates()
        branch_tip_materialized = (
            vi.branch_tip_materialized
            if vi.is_versioned
            else _resolve_branch_tip_materialized(
                vi.branch_tip_materialized,
                txn_candidates,
            )
        )
        revision_id = vi.revision_id
        if not branch_tip_materialized and revision_id is None:
            for candidate in txn_candidates:
                candidate_revision: object | None
                if isinstance(candidate, _versioned_transaction_types()):
                    snapshot = cast(
                        VersionedTransactionPlanningSnapshotProvider,
                        candidate,
                    ).versioned_transaction_planning_snapshot()
                    candidate_revision = snapshot.base_revision_id or snapshot.revision_id
                else:
                    candidate_revision = candidate._base_revision_id if isinstance(candidate, _BaseRevisionIdCarrier) else None
                    if candidate_revision is None and isinstance(candidate, _RevisionIdCarrier):
                        candidate_revision = candidate._revision_id
                if candidate_revision is not None:
                    revision_id = _unwrap_branded_to_str(candidate_revision)
                    break
        compilation_revision_id: str | None = None if branch_tip_materialized else revision_id
        prefer_tip_strategy, prefer_tip_merged = _extract_versioned_read_strategy_flags(
            txn_candidates,
        )
        effective_is_write_transaction = self._is_write_transaction or any(
            _target_is_write_transaction(candidate) for candidate in txn_candidates
        )
        staged_commit_id = _extract_staged_commit_id(txn_candidates)
        staged_visibility, connection_id_str, visibility_source_txn = _extract_staged_visibility_fields(
            txn_candidates,
        )
        if visibility_source_txn is not None:
            prefer_tip_merged = True
        if not (branch_tip_materialized and prefer_tip_strategy and not effective_is_write_transaction):
            for candidate in txn_candidates:
                if isinstance(candidate, _versioned_transaction_types()):
                    snapshot = cast(
                        VersionedTransactionPlanningSnapshotProvider,
                        candidate,
                    ).versioned_transaction_planning_snapshot()
                    candidate_revision_id = _unwrap_branded_to_str(snapshot.revision_id or snapshot.base_revision_id)
                    if compilation_revision_id is None and candidate_revision_id is not None:
                        compilation_revision_id = candidate_revision_id
                        break

        queue_insert_auth_serialized: str | None = None
        current_queue_token = _extract_current_queue_token(self._conn)
        if current_queue_token is not None:
            queue_insert_auth_serialized = current_queue_token.serialize()

        query_spec_prerender_attacher = (
            self._conn.remember_query_spec_prerender_info_for_stmt if isinstance(self._conn, _QuerySpecPrerenderAttacher) else None
        )
        txn_target = self._txn_or_none()

        def _mark_sys_sessions_table_exists() -> None:
            if isinstance(txn_target, _SysSessionsTableExistsMarker):
                txn_target._sys_sessions_table_exists = True

        def _record_validated_session_state(
            session_id: object,
            expires_at: object | None,
            session_type: object | None,
            user_id_raw: object | None,
        ) -> None:
            if not isinstance(self._conn, _SessionValidationCacheCarrier):
                return
            if not isinstance(session_id, SessionId):
                msg = f"Validated session ID is not a SessionId: {session_id!r}"
                raise TypeError(msg)
            session_id_sql = str(session_id.unwrap_to_sql())
            self._conn._validated_sessions[session_id_sql] = (
                expires_at if expires_at is None or isinstance(expires_at, datetime) else None
            )
            from l4000_permissions.rbac_ids import UserId

            user_id = user_id_raw if isinstance(user_id_raw, UserId) else (UserId(str(user_id_raw)) if user_id_raw is not None else None)
            self._conn._validated_session_user_ids[session_id_sql] = str(user_id) if user_id is not None else None
            if isinstance(self._conn, _CachedSessionIdCarrier):
                self._conn._cached_session_id = session_id_sql
            if isinstance(self._conn, _CachedSessionTypeCarrier):
                self._conn._cached_session_type = str(session_type) if session_type is not None else None

        staged_visibility_filter: Any | None = None
        if visibility_source_txn is not None and vi.lazy_branch is None:
            from impl.common.l7248_sparse_versioned_transactions.sparse_versioned_write_query import (
                _build_staged_visibility_filter,
            )
            from l2050_transaction.transaction import ReadTransaction, WriteTransaction

            assert isinstance(visibility_source_txn, ReadTransaction | WriteTransaction)
            staged_visibility_filter = _build_staged_visibility_filter(
                visibility_source_txn,
                branch_id_override=BranchId(vi.branch_id) if vi.branch_id is not None else None,
                staged_commit_id_override=staged_commit_id,
            )
        elif (
            (branch_tip_materialized or prefer_tip_strategy)
            and prefer_tip_strategy
            and not prefer_tip_merged
            and not effective_is_write_transaction
            and staged_commit_id is None
            and connection_id_str is None
        ):
            from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlInlineLiteral
            from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

            staged_visibility_filter = SqlBinaryOp(
                SqlInlineLiteral(1),
                BinaryOp.EQ,
                SqlInlineLiteral(0),
            )

        compilation_session_id: LazySessionSqlSource | SessionId | ScalarServerRef[SessionId] | None = (
            vi.session_id_source
            if vi.session_id_source is not None
            else SessionId(vi.session_id_str)
            if vi.session_id_str is not None
            else None
        )
        permission_filtering_enabled = True
        effective_session_source = vi.session_id_source
        if isinstance(effective_session_source, SessionId):
            literal_session_id = effective_session_source
            compilation_session_id = literal_session_id
            permission_filtering_enabled = not (literal_session_id.is_schema_session())
        elif (
            vi.session_id_str is not None
            and session_sql_source_or_none(effective_session_source) is None
            and not isinstance(effective_session_source, ScalarServerRef)
        ):
            literal_session_id = SessionId(vi.session_id_str)
            compilation_session_id = literal_session_id
            if literal_session_id.is_schema_session():
                permission_filtering_enabled = False

        return CompilationContext(
            backend_type=backend_type,
            dialect=dialect,
            supports_data_modifying_ctes=supports_dml_ctes,
            backend_profile=self._backend_profile,
            branch_id=vi.branch_id,
            revision_id=compilation_revision_id,
            explicit_revision_id=vi.explicit_revision_id,
            lazy_revision=vi.lazy_revision,
            lazy_branch=vi.lazy_branch,
            lazy_branch_tip_materialization=vi.branch_tip_materialization_ref,
            is_versioned=vi.is_versioned,
            is_write_transaction=effective_is_write_transaction,
            uses_bound_transaction_principal=isinstance(
                effective_session_source,
                ScalarServerRef,
            ),
            transaction_execution_facts=self._conn._data_transaction_execution_facts(),
            sql_statement_capacity=self._conn._sql_statement_capacity(),
            txn=cast(Any, txn_target),
            sql_handle=self._conn,
            session_validation_state_marker=txn_target,
            session_validation_cache_marker=self._conn,
            planning_catalog=self._planning_catalog,
            schema_column_cache=_extract_schema_column_cache(self._conn, self._planning_catalog),
            queue_insert_auth_serialized=queue_insert_auth_serialized,
            query_spec_prerender=query_spec_prerender_attacher,
            sys_sessions_presence_marker=_mark_sys_sessions_table_exists,
            validated_session_recorder=_record_validated_session_state,
            session_id=compilation_session_id,
            system_authority=(system_authority_for_plan_target(txn_target) if txn_target is not None else None),
            capability_lifecycle_admin_authority=capability_lifecycle_admin_authority_for(txn_target),
            session_gate_policy=SessionGatePolicy.REQUIRED,
