        )

    def _txn_or_none(self: SqlBackendExecutor) -> PlanTarget | None:
        """Return the bound transaction when the executor was fully initialized."""
        try:
            return self._txn
        except AttributeError:
            return None

"""Typed server-side symbolic value references.

``ServerRef[T]`` is the abstract base for all server-side values that
flow through the server-plan pipeline. Concrete subtypes distinguish the
allowed semantics:

* ``ScalarServerRef[T]``: symbolic scalar value
* ``ObjectServerRef[T]``: single object / row payload
* ``ScalarSequenceServerRef[T]``: sequence of scalar values
* ``ObjectSequenceServerRef[T]``: sequence of objects / rows

``LazyResult[T]`` remains separate: it is a client-side lazy execution
container, not itself a server-side plan value. Callers normalize raw
inputs into the appropriate ref subtype before constructing intents.
"""

