_PHYSICAL_SERVER_REF_BYTE_LIMIT = SqlIdentifierByteLimit(60)
_PHYSICAL_SERVER_REF_DIGEST_LENGTH = 12


def physical_server_plan_ref_alias(
    ref_id: ServerPlanRefId,
    *,
    max_length: SqlIdentifierByteLimit = _PHYSICAL_SERVER_REF_BYTE_LIMIT,
) -> ServerPlanRefId:
    """Return a deterministic SQL relation alias for one logical plan reference.

    The 60-byte limit reserves three bytes below PostgreSQL's identifier limit
    for SQL-lowering decorations. Long aliases include a 48-bit digest of the
    complete logical reference.
    """
    ref_bytes = ref_id.encode("utf-8")
    if len(ref_bytes) <= max_length:
        return ref_id
    digest = hashlib.sha256(ref_bytes).hexdigest()[:_PHYSICAL_SERVER_REF_DIGEST_LENGTH]
    prefix_budget = max_length - _PHYSICAL_SERVER_REF_DIGEST_LENGTH - 1
    if prefix_budget < 1:
        msg = (
            f"Server-plan alias limit {max_length} leaves no room for a prefix and {_PHYSICAL_SERVER_REF_DIGEST_LENGTH}-character digest"
        )
        raise ValueError(msg)
    prefix = ""
    for character in ref_id:
        next_prefix = prefix + character
        if len(next_prefix.encode("utf-8")) > prefix_budget:
            break
        prefix = next_prefix
    return ServerPlanRefId(f"{prefix}_{digest}")


def _large_column_scalar_ref_id(ref_id: ServerPlanRefId, type_hint: object, field_name: str) -> ServerPlanRefId | None:
    if "." in ref_id and (".raw." in ref_id or ".hydrated." in ref_id):
        return None
    if not isinstance(type_hint, type):
        return None
    try:
        large_fields = {config.column for config in get_large_column_configs(type_hint)}
    except TypeError:
        return None
    if field_name not in large_fields:
        return None
    return ServerPlanRefId(f"{ref_id}.hydrated.{field_name}")


