@pure_lazy
def _validate_ref_id(ref_id: ServerPlanRefId) -> None:
    if not isinstance(ref_id, str):  # pyright: ignore[reportUnnecessaryIsInstance]
        msg = f"ref_id must be a string, got {type(ref_id).__name__}"
        raise InjectionAttemptError(
            msg,
            injection_type="server_ref_id",
            attempted_value=str(ref_id),
        )
    if not _REF_ID_PATTERN.match(ref_id):
        msg = (
            f"Invalid ref_id format: {ref_id!r}. Must be 'step_N', 'seed_N', 'out_N', "
            "a scoped 'namespace:generation:kind_N' semantic ref, one of those with a "
            "'.field_name[.field_name]*' projection suffix, or a closed "
            "'graphql.binding.N.coercion' or 'api.binding.namespace.N' runtime binding, "
            "where N is non-negative."
        )
        raise InjectionAttemptError(
            msg,
            injection_type="server_ref_id",
            attempted_value=ref_id,
        )


def _coerce_ref_id(ref_id: ServerPlanRefId | str) -> ServerPlanRefId:
    if isinstance(ref_id, ServerPlanRefId):
        return ref_id
    return ServerPlanRefId(ref_id)


def rewrite_server_ref_id(
    ref_id: ServerPlanRefId | None,
    ref_id_map: Mapping[str, str],
) -> ServerPlanRefId | None:
    """Return ``ref_id`` with its producing internal base ref remapped."""
    if ref_id is None:
        return None
    raw_ref_id = str(ref_id)
    base_ref, separator, suffix = raw_ref_id.partition(".")
    rewritten_base = ref_id_map.get(base_ref)
    if rewritten_base is None:
        return ref_id
    rewritten_ref_id = f"{rewritten_base}.{suffix}" if separator else rewritten_base
    return ref_id if rewritten_ref_id == raw_ref_id else ServerPlanRefId(rewritten_ref_id)


def clone_server_ref(
    ref: ServerRef[Any],
    *,
    ref_id: ServerPlanRefId | None | str | object = _PRESERVE_REF_ID,
) -> ServerRef[Any]:
    """Clone a ``ServerRef`` while preserving its explicit typed state."""
    cloned_ref = type(ref).__new__(type(ref))
    if ref_id is _PRESERVE_REF_ID:
        next_ref_id = ref._ref_id
    elif ref_id is None:
        next_ref_id = None
    else:
        assert isinstance(ref_id, ServerPlanRefId | str)
        next_ref_id = _coerce_ref_id(ref_id)
    _init_server_ref_state(cloned_ref, ref_id=next_ref_id, type_hint=ref._type_hint)
    if isinstance(ref, ScalarSequenceServerRef):
        assert isinstance(cloned_ref, ScalarSequenceServerRef)
        cloned_ref._field_identity = ref._field_identity
    return cloned_ref


def remap_server_ref(ref: ServerRef[Any], ref_id_map: Mapping[str, str]) -> ServerRef[Any]:
    """Clone ``ref`` with its internal plan reference id rewritten explicitly."""
    return clone_server_ref(ref, ref_id=rewrite_server_ref_id(ref._ref_id, ref_id_map))


@pure_lazy
def server_ref_named_payload_items(ref: ServerRef[object]) -> tuple[tuple[str, object], ...]:
    """Expose ServerRef payload state through a single sanctioned helper."""
    items: list[tuple[str, object]] = [
        ("_ref_id", ref._ref_id),
        ("_type_hint", ref._type_hint),
    ]
    if isinstance(ref, ScalarSequenceServerRef) and ref._field_identity is not None:
        items.append(("_field_identity", ref._field_identity))
    dependencies = ref.dependencies()
    if dependencies:
        items.append(("_dependency_refs", dependencies))
    return tuple(items)


