def _make_symbolic_ref(
    cls: type[ServerRef[Any]],
    ref_id: ServerPlanRefId,
    type_hint: type[Any] | None = None,
) -> ServerRef[Any]:
    """Construct a symbolic ``ServerRef`` that resolves at execution time."""
    _validate_ref_id(ref_id)
    ref = cls.__new__(cls)
    _init_server_ref_state(ref, ref_id=ref_id, type_hint=type_hint)
    return ref


def _projected_field_type_hint(
    model_cls: type[Any] | None,
    field_name: str,
) -> type[Any] | None:
    """Return the concrete Pydantic field type for a symbolic projection."""
    if model_cls is None or not issubclass(model_cls, BaseModel):
        return None
    field_info = model_cls.model_fields.get(field_name)
    if field_info is None:
        return None
    annotation, _was_optional = unwrap_optional(field_info.annotation)
    return annotation if isinstance(annotation, type) else None


