) -> ServerRef[Any]:
    """Construct an out-of-plan placeholder that carries no Python value."""
    ref = cls.__new__(cls)
    _init_server_ref_state(ref, ref_id=None, type_hint=type_hint)
    return ref


def _variant_for_ref_class(cls: type[ServerRef[Any]]) -> ServerRefVariant:
    if cls is ScalarServerRef:
        return "scalar"
    if cls is ObjectServerRef:
        return "object"
    if cls is ScalarSequenceServerRef:
        return "scalar_sequence"
    if cls is ObjectSequenceServerRef:
        return "object_sequence"
    msg = f"Unknown ServerRef class: {cls.__name__}"
    raise TypeError(msg)


def _make_seeded_ref_for_current_plan(
    cls: type[ServerRef[Any]],
    value: object,
    type_hint: type[Any] | None = None,
    current_plan_getter: Callable[[], object | None] = _current_plan,
    build_phase_getter: Callable[[], bool] = _is_build_phase,
    phase_scope_factory: Callable[..., Any] = _pipeline_phase_scope,
) -> ServerRef[Any]:
    effective_type_hint = type_hint or type(value)
    plan = current_plan_getter()
    if plan is None:
        return _make_symbolic_ref(
            cls,
            _register_planless_seeded_constant(value),
            effective_type_hint,
        )
    if not build_phase_getter():
        seeded_constants = getattr(plan, "seeded_constants", None)
        with phase_scope_factory("build", seeded_constants=seeded_constants):
            return _allocate_ref(
                plan,
                kind="seed",
                variant=_variant_for_ref_class(cls),
                type_hint=effective_type_hint,
                seed_value=value,
            )
    return _allocate_ref(
        plan,
        kind="seed",
        variant=_variant_for_ref_class(cls),
        type_hint=effective_type_hint,
        seed_value=value,
    )


def _make_lazy_ref(
    cls: type[ServerRef[Any]],
    lazy_value: object,
    type_hint: type[Any] | None = None,
) -> ServerRef[Any]:
    """Construct a ref backed by a ``LazyResult`` / step reference."""
    lazy_result_type, lazy_seq_type = _lazy_result_types()

    if not isinstance(lazy_value, lazy_result_type | lazy_seq_type):
        msg = "lazy_value must be a LazyResult or LazySeq"
        raise TypeError(msg)
    effective_type_hint = type_hint
    if effective_type_hint is None:
        try:
            expected_type = object.__getattribute__(lazy_value, "_expected_type")
        except AttributeError:
            expected_type = None
        effective_type_hint = expected_type if isinstance(expected_type, type) else None
    shape = inspect_server_value_shape_for_planning(lazy_value, site="_make_lazy_ref")
    if shape.has_literal_value:
        return _make_seeded_ref_for_current_plan(cls, shape.literal_value, effective_type_hint)
    if shape.symbolic_ref_id is not None:
        return _make_symbolic_ref(cls, shape.symbolic_ref_id, effective_type_hint)
    dependency_provider = cast("LazyResult[Any] | LazySeq[Any]", lazy_value)
    dependency_refs = tuple(dependency_provider.dependencies())
    if len(dependency_refs) == 1:
        return _make_symbolic_ref(cls, ServerPlanRefId(dependency_refs[0]), effective_type_hint)
    if len(dependency_refs) > 1:
        msg = f"Lazy value must publish at most one ref before conversion to ServerRef, got {dependency_refs!r}"
        raise TypeError(msg)
    msg = "Lazy value must publish a ref dependency before conversion to ServerRef"
    raise TypeError(msg)


PlanningValueT_co = TypeVar("PlanningValueT_co", covariant=True, default=object)


@dataclass(frozen=True, slots=True)
class PlanningServerValueShape(Generic[PlanningValueT_co]):
    """Single sanctioned planning-time inspection result for server values.

    Lowering/compile code should use this instead of ad-hoc peeks at
    ``ref_id``, ``_step_ref_id``, or ``dependencies()``.
    """

    symbolic_ref_id: ServerPlanRefId | None
    dependency_refs: frozenset[str]
    has_literal_value: bool = False
    literal_value: PlanningValueT_co | None = None
    has_error: bool = False


@dataclass(frozen=True, slots=True)
class ObjectSequenceInputSource[T]:
    """Planning-time object-sequence input normalized at the ServerRef boundary."""

    literal_values: tuple[T, ...] | None
    source_ref_id: ServerPlanRefId | None

    @property
    def is_deferred(self: ObjectSequenceInputSource[T]) -> bool:
        return self.source_ref_id is not None

    def to_ref(self: ObjectSequenceInputSource[T]) -> ObjectSequenceServerRef[T]:
        if self.source_ref_id is not None:
            return ServerRefs.from_ref_id(
                self.source_ref_id,
                variant="object_sequence",
            )
        assert self.literal_values is not None
        return ServerRefs.object_sequence(self.literal_values)


@overload
def inspect_server_value_shape_for_planning[T](
    value: LazyResult[T] | ServerRef[T],
    *,
    site: str, prefer_materialized_value: bool = False,
) -> PlanningServerValueShape[T]: ...


