@overload
def inspect_server_value_shape_for_planning(
    value: object,
    *,
    site: str, prefer_materialized_value: bool = False,
) -> PlanningServerValueShape[object]: ...


@pure_lazy
def inspect_server_value_shape_for_planning(
    value: object,
    *,
    site: str, prefer_materialized_value: bool = False,
) -> PlanningServerValueShape[object]:
    """Return the symbolic dependency shape through one narrow planning exception."""
    lazy_result_type, lazy_seq_type = _lazy_result_types()
    if isinstance(value, ServerRef):
        raw_ref_id = value._ref_id
        if raw_ref_id is None:
            return PlanningServerValueShape(
                symbolic_ref_id=None,
                dependency_refs=frozenset(),
            )
        dependency_ref = _dependency_ref_for_symbolic_ref(raw_ref_id)
        deps = frozenset() if raw_ref_id.startswith("seed_") else frozenset({dependency_ref})
        return PlanningServerValueShape(
            symbolic_ref_id=raw_ref_id,
            dependency_refs=deps,
        )
    if isinstance(value, lazy_result_type | lazy_seq_type):
        step_ref_id = object.__getattribute__(value, "_step_ref_id")
        planning_ref_id = getattr(value, "_planning_ref_id", None)
        state = object.__getattribute__(value, "_state")
        is_sequence = isinstance(value, lazy_seq_type)
        use_materialized = prefer_materialized_value and state.name == "RESOLVED"
        if isinstance(step_ref_id, str) and not use_materialized:
            dependency_refs: frozenset[str] = getattr(value, "_dependency_refs", frozenset())
            if dependency_refs:
                dependency_refs = frozenset(str(ref_id) for ref_id in dependency_refs)
            else:
                dependency_refs = frozenset({step_ref_id})
            return PlanningServerValueShape(
                symbolic_ref_id=ServerPlanRefId(planning_ref_id if isinstance(planning_ref_id, str) else step_ref_id),
                dependency_refs=dependency_refs,
            )
        if getattr(state, "name", None) == "ERROR":
            return PlanningServerValueShape(
                symbolic_ref_id=None,
                dependency_refs=frozenset(),
                has_error=True,
            )
        if getattr(state, "name", None) == "RESOLVED":
            return PlanningServerValueShape(
                symbolic_ref_id=None,
                dependency_refs=frozenset(),
                has_literal_value=True,
                literal_value=object.__getattribute__(value, "_items" if is_sequence else "_value"),
            )
        if not is_sequence and (pre_populated := object.__getattribute__(value, "_pre_populated")) is not None:
            return PlanningServerValueShape(
                symbolic_ref_id=None,
                dependency_refs=frozenset(),
                has_literal_value=True,
                literal_value=pre_populated,
            )
        return PlanningServerValueShape(
            symbolic_ref_id=None,
            dependency_refs=frozenset(),
        )
    msg = f"{site} requires ServerRef, LazyResult, or LazySeq planning inputs; got {type(value).__name__}."
    raise TypeError(msg)


