) -> ServerPlanRefId:
    """Return the published ServerPlan ref id for lazy planning inputs."""

    shape = inspect_server_value_shape_for_planning(value, site=context)
    if shape.symbolic_ref_id is not None:
        return shape.symbolic_ref_id
    msg = f"{context} requires a published plan-backed source ref"
