@pure_lazy
def normalize_object_sequence_input[T](
    value: Sequence[T] | LazyResult[Sequence[T]] | LazyResult[list[T]] | LazyResult[tuple[T, ...]] | ObjectSequenceServerRef[T],
    *,
    context: str,
) -> ObjectSequenceInputSource[T]:
    """Normalize caller bulk-row inputs without resolving symbolic lazy values."""

    if isinstance(value, ObjectSequenceServerRef):
        ref_id = value.ref_id
        if ref_id is None:
            msg = f"{context} requires a published object-sequence ref"
            raise TypeError(msg)
        return ObjectSequenceInputSource(
            literal_values=None,
            source_ref_id=ref_id,
        )

    lazy_result_type, _lazy_seq_type = _lazy_result_types()
    if isinstance(value, lazy_result_type):
        shape = inspect_server_value_shape_for_planning(value, site=context)
        if shape.symbolic_ref_id is not None:
            return ObjectSequenceInputSource(
                literal_values=None,
                source_ref_id=shape.symbolic_ref_id,
            )
        if not shape.has_literal_value:
            msg = f"{context} requires a literal sequence or a published object-sequence ref"
            raise TypeError(msg)
