) -> ScalarServerRef[T]:
    """Normalize scalar API input into a typed server ref."""

    if isinstance(value, ScalarServerRef):
        return value
    lazy_result_type, _lazy_seq_type = _lazy_result_types()
    if isinstance(value, lazy_result_type):
