@pure_lazy
def unwrap_literal_sql_value(value: object) -> object:
    if isinstance(value, ConnectionId):
        return value.unwrap_to_sql()
    if type(value) in _LITERAL_UNWRAP_IDENTITY_TYPES:
        return value

    value_type = type(value)
    cached_unwrapper = _literal_unwrap_type_fact(value_type)
    if isinstance(cached_unwrapper, _NoLiteralUnwrap):
        return value
    if callable(cached_unwrapper):
        return cached_unwrapper(value)

    try:
        instance_dict = object.__getattribute__(value, "__dict__")
    except AttributeError:
        return value

    if not isinstance(instance_dict, dict):
        return value

    for method_name in _LITERAL_UNWRAP_METHOD_NAMES:
        class_method = getattr(value_type, method_name, None)
        if callable(class_method):
            return class_method(value)
        instance_method = instance_dict.get(method_name)
        if callable(instance_method):
            return instance_method()
    return value


@pure_lazy
def _literal_unwrap_type_fact(value_type: type) -> Callable[[object], object] | _NoLiteralUnwrap | None:
    cache_key = _type_cache_key(value_type)
    cached = _LITERAL_UNWRAP_TYPE_FACTS.get(cache_key)
    if cached is not None:
        cached_value = cached.value
        if cached_value is None or isinstance(cached_value, _NoLiteralUnwrap) or callable(cached_value):
            return cached_value
        return _NoLiteralUnwrap()

    has_instance_dict = any("__dict__" in cls.__dict__ for cls in value_type.__mro__)
    if has_instance_dict:
        _LITERAL_UNWRAP_TYPE_FACTS.set(cache_key, _LiteralUnwrapTypeFact(None))
        return None

    for method_name in _LITERAL_UNWRAP_METHOD_NAMES:
        class_method = getattr(value_type, method_name, None)
        if callable(class_method):
            unwrapper = cast(Callable[[object], object], class_method)
            _LITERAL_UNWRAP_TYPE_FACTS.set(cache_key, _LiteralUnwrapTypeFact(unwrapper))
            return unwrapper

    no_unwrap = _NoLiteralUnwrap()
    _LITERAL_UNWRAP_TYPE_FACTS.set(cache_key, _LiteralUnwrapTypeFact(no_unwrap))
    return no_unwrap


class ServerRef[T](ABC):
    """Abstract base for server-side value handles.

    The concrete subtype determines whether the value is scalar, object,
    or sequence-shaped. References contain only symbolic identity and type
    metadata, so runtime purity guards do not need to traverse them.
    """

    __pure_lazy_surface__: ClassVar[bool] = True
    __slots__ = (
        "_ref_id",
        "_type_hint",
    )
    _ref_id: ServerPlanRefId | None
    _type_hint: type[T] | None

    # -- Constructors ---------------------------------------------------------

    def __init__(
        self,
        plan: object | None,
        ref_id: ServerPlanRefId,
        type_hint: type[T] | None = None,
    ) -> None:
        """Create a ServerRef from a plan step reference.

        This is the constructor used by ``ServerPlan._add_server_step()``.
        For other construction paths, use the class methods.
        """
        del plan
        _validate_ref_id(ref_id)
        _init_server_ref_state(self, ref_id=ref_id, type_hint=type_hint)

    @property
    def variant(self) -> ServerRefVariant:
        """Concrete variant identifier.

        The base class preserves scalar-compatible semantics for legacy
        direct construction; subtype-specific code should prefer the
        concrete subclasses and ``ServerRefs`` factory helpers.
        """
        return "scalar"

    # -- Dependency tracking --------------------------------------------------

    def dependencies(self: ServerRef[T]) -> frozenset[ServerPlanRefId]:
        """Return the set of step ref_ids this value depends on.

        Returns the full dotted ``ref_id`` so the dependency ordering
        optimizer can resolve to the most specific registered step.
        Legacy callers that needed only the base ref can apply
        ``ref.split('.', 1)[0]`` themselves; the optimizer walks the
        dotted prefix chain to find the registered ancestor.

        Seed refs (literals routed through ``ref_allocation.allocate_ref``
        with ``kind="seed"``) are satisfied at runtime from
        ``plan.seeded_constants`` rather than by a plan step. They must not
        appear in the step-dependency graph. We detect them by prefix so
        this check stays decoupled from the typed ``SeedRefId`` import.
        """
        ref_id = self._ref_id
        if ref_id is None:
            return frozenset()
        if ref_id.startswith("seed_") or ref_id == _ABSENT_OBJECT_RELATION_REF:
            return frozenset()
        return frozenset({_dependency_ref_for_symbolic_ref(ref_id)})

    # -- Resolution (step.preprocess phase) -----------------------------------

    def resolve(self: ServerRef[T], resolved_refs: Any) -> None:
        """Resolve deferred references using completed step results.

        In sequential execution: a ref resolves to a concrete value.
        In CTE batch compilation: a ref remains symbolic when the base
        maps to a ``CteReference``.
        """
        _raise_if_forbidden_in_preprocess(
            operation="*.resolve(resolved)",
            path=f"ServerRef.resolve({self._ref_id!r})",
        )
        if self._ref_id is not None:
            val = resolved_refs.resolve_server_ref(self)
            if isinstance(val, ServerRef):
                return
            if isinstance(val, _cte_reference_type()):
                return
            self._ref_id = None

    # -- Introspection --------------------------------------------------------

    @property
    def is_resolved(self: ServerRef[T]) -> bool:
        """True if this value has been resolved out of the server-ref graph."""
        _raise_if_forbidden_phase_value_access(
            operation="ServerRef.is_resolved",
            path=f"ServerRef.is_resolved({self._ref_id!r})",
            kind="resolved server-ref state inspection",
        )
        return self._ref_id is None

    @property
    def ref_id(self: ServerRef[T]) -> ServerPlanRefId | None:
        """Underlying symbolic reference id, if any."""
        return self._ref_id

    @property
    def value_type(self: ServerRef[T]) -> type[T] | None:
        """Return the declared runtime value type, when the producer supplies one."""
        return self._type_hint

    # -- String representation ------------------------------------------------

    def __repr__(self: ServerRef[T]) -> str:
        cls_name = type(self).__name__
        if self._ref_id is not None:
            type_name = self._type_hint.__name__ if self._type_hint else "?"
            return f"{cls_name}[{type_name}]({self._ref_id!r})"
        return f"{cls_name}(unset)"

    # -- Hash (identity-based) -------------------------------------------------

    def __hash__(self: ServerRef[T]) -> int:
        return id(self)

    def __deepcopy__(self: ServerRef[T], memo: dict[int, object]) -> ServerRef[T]:
        """Copy symbolic state without treating projected fields as copy hooks."""
        existing = memo.get(id(self))
        if isinstance(existing, ServerRef):
            return cast("ServerRef[T]", existing)
        if self._ref_id is None:
            copied = _make_unbound_ref(type(self), self._type_hint)
        else:
            copied = _make_symbolic_ref(type(self), self._ref_id, self._type_hint)
        if isinstance(self, ScalarSequenceServerRef) and isinstance(copied, ScalarSequenceServerRef):
            copied._field_identity = self._field_identity
        memo[id(self)] = copied
        return cast("ServerRef[T]", copied)

    def field(self: ServerRef[T], name: str) -> ServerRef[Any]:
        """Project a named field from a plan-backed ref.

        Legacy direct ``ServerRef(...)`` construction historically allowed
        ``.field(...)`` even before callers were updated to the concrete object
        ref variants, so keep that projection path available here.
        """
        ref_id = self._ref_id
        if ref_id is None:
            msg = "Cannot project a field from an unbound server ref"
            raise RuntimeError(msg)
        return cast(
            ScalarServerRef[object],
            _make_symbolic_ref(
                ScalarServerRef,
                ServerPlanRefId(f"{ref_id}.{name}"),
                _projected_field_type_hint(self._type_hint, name),
            ),
        )


