        identity = scalar_sequence_field_identity(
            model_type,
            field_name,
            nullable_elements=nullable_elements,
        )
        ref = cast(
            ScalarSequenceServerRef[Any],
            _make_symbolic_ref(
                ScalarSequenceServerRef,
                _coerce_ref_id(ref_id),
                identity.element_type,
            ),
        )
        ref._field_identity = identity
        return ref

    @staticmethod
    @overload
    def object_sequence[T](value: ObjectSequenceServerRef[T]) -> ObjectSequenceServerRef[T]: ...

    @staticmethod
    @overload
    def object_sequence(value: builtins.object) -> ObjectSequenceServerRef[Any]: ...

    @staticmethod
    def object_sequence(value: builtins.object) -> ObjectSequenceServerRef[Any]:
        if isinstance(value, ObjectSequenceServerRef):
            return value
        lazy_result_type, lazy_seq_type = _lazy_result_types()
        if isinstance(value, (lazy_result_type, lazy_seq_type)):
            return cast(ObjectSequenceServerRef[Any], _make_lazy_ref(ObjectSequenceServerRef, value))
        if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
            msg = "object_sequence() expects a sequence or lazy sequence"
            raise TypeError(msg)
        return cast(
            ObjectSequenceServerRef[Any],
            _make_seeded_ref_for_current_plan(
                ObjectSequenceServerRef,
                list(cast(Sequence[Any], value)),
            ),
        )

    @staticmethod
    def infer(value: builtins.object) -> ServerRef[Any]:
        if isinstance(value, ServerRef):
            return value
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
            sequence = cast(Sequence[object], value)
            if sequence and hasattr(sequence[0], "__dict__"):
                return ServerRefs.object_sequence(value)
            return ServerRefs.scalar_sequence(value)
        if hasattr(value, "__dict__"):
            return ServerRefs.object(value)
        return ServerRefs.scalar(value)

"""FTS polyfill index management.

This module provides index creation, maintenance, and updates for the FTS polyfill
using inverted index tables. Unlike native FTS implementations, the polyfill stores
tokenized data in regular database tables and implements search at the application level.

The polyfill is primarily designed for DoltDB (MySQL-compatible without BOOLEAN MODE)
but can be used with any backend that lacks native FTS capabilities.
"""

