@pure_lazy
def _schema_artifact_tables_exist_for_planning(
    schema_owner: Any,
    table_names: tuple[SqlTableName, ...],
) -> bool:
    existing_by_table: dict[str, bool] = {}
    unknown_table_names: list[str] = []
    for table_name in table_names:
        projected = schema_owner.projected_or_cached_table_exists(table_name)
        if isawaitable(projected):
            projected = cast("Awaitable[SchemaFactPresence]", projected)
        if projected is SchemaFactPresence.PRESENT:
            existing_by_table[table_name] = True
        elif projected is SchemaFactPresence.ABSENT:
            existing_by_table[table_name] = False
        else:
            unknown_table_names.append(table_name)
    if unknown_table_names:
        seeded = schema_owner.table_exists_many_for_schema_batch_lazy(tuple(unknown_table_names))
        shape = inspect_server_value_shape_for_planning(
            seeded,
            site="FTS schema artifact table facts",
        )
        if not shape.has_literal_value or not isinstance(shape.literal_value, Mapping):
            raise LazyPurityError("FTS schema artifact checks require projected table facts")
        existing_by_table.update(
            {table_name: bool(shape.literal_value.get(str(table_name), False)) for table_name in unknown_table_names},
        )
    return all(bool(existing_by_table.get(table_name, False)) for table_name in table_names)


