def _enqueue_sql_grammar_query_lazy(
    txn: WriteTransactionLazyMixin,
    *,
    grammar_builder: Callable[[], SqlRenderable],
    closed_post_op: CompiledPostOp,
    cardinality_name: Literal["none", "many"],
) -> LazyResult[object]:
    from impl.common.l2070_server_plan.steps.intent_graph import (
        SqlGrammarQueryStep,
    )
    from l1400_types import ServerPlanRefId
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
    from l2070_batching.cardinality import Cardinality

    cardinality = Cardinality.NONE if cardinality_name == "none" else Cardinality.MANY
    step = SqlGrammarQueryStep(
        ref_id=ServerPlanRefId(next_lazy_plan_ref(txn)),
        grammar_builder=grammar_builder,
        closed_post_op=closed_post_op,
        cardinality=cardinality,
    )
    return cast(LazyResult[object], enqueue_lazy_plan_intent(txn, step))


