class FTSPolyfillManager:
    """Manages FTS polyfill inverted indexes.

    This class handles creation and maintenance of inverted index tables for
    full-text search. Unlike native FTS implementations (SQLite FTS5, PostgreSQL
    tsvector), the polyfill stores tokenized data in regular tables and implements
    search logic at the application level.

    Architecture:
        - Per-model inverted index tables: {table}_fts_index
        - Token → document mappings with position tracking
        - Synchronous updates (maintains index consistency)
        - Porter stemming with stop-word filtering

    Example:
        >>> from impl.common.l5150_fts_polyfill import FTSPolyfillManager
        >>> manager = FTSPolyfillManager()
        >>> with conn.schema_transaction(SessionId.schema()) as schema_txn:
        ...     manager.create_fts_index(schema_txn, Product)
        >>> conn.session(SessionId.system()).write(
        ...     fn=lambda txn: manager.rebuild_fts_index(Product, txn=txn),
        ... )
        >>>
        >>> # After updating a product
        >>> manager.update_object_index(Product, product, operation="update")

    See Also:
        - :class:`~l5100_fts.polyfill.searcher.FTSPolyfillSearcher`: Search operations
        - :class:`~l5100_fts.polyfill.index_schema.FTSInvertedIndex`: Index schema
        - :class:`~l5100_fts.polyfill.tokenizers.porter.PorterStemTokenizer`: Tokenizer
    """

    def __init__(self: FTSPolyfillManager) -> None:
        """Initialize the stateless FTS polyfill manager."""

    @legacy_sync
    def create_fts_index(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> bool:
        """Create inverted index table for a model.

        Creates a new table with the schema defined in FTSInvertedIndex. The table
        name follows the convention: {table_name}_fts_index

        Table Structure:
            - token: str (lowercased, stemmed)
            - content_hash: str (hash of FTS-indexed fields for deduplication)
