    @external_io_boundary
    def _create_fts_index_under_schema_authority_impl(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        *,
        table_name: SqlTableName,
        fts_index_class: type[FTSInvertedIndex],
        fts_metadata_class: type[FTSMetadata],
        fts_idf_cache_class: type[Any],
        fts_stats_class: type[Any],
    ) -> bool:
        """Create polyfill FTS tables and indexes under one explicit schema owner."""
        artifact_table_names = _polyfill_artifact_table_names(table_name)
        (
            index_table_name,
            metadata_table_name,
            idf_cache_table_name,
            stats_table_name,
        ) = artifact_table_names

        if _schema_artifact_tables_exist_for_planning(schema_owner, artifact_table_names):
            return False

        schema_owner.drop_table(SqlTableName(index_table_name), True)
        schema_owner.drop_table(SqlTableName(metadata_table_name), True)
        schema_owner.drop_table(SqlTableName(idf_cache_table_name), True)
        schema_owner.drop_table(SqlTableName(stats_table_name), True)
        schema_owner.create_table_from_schema(fts_index_class)
        schema_owner.create_table_from_schema(fts_metadata_class)
        schema_owner.create_table_from_schema(fts_idf_cache_class)
        schema_owner.create_table_from_schema(fts_stats_class)
        self._create_fts_indexes_lazy(schema_owner, fts_index_class)
        return True

    @pure_lazy
    def _create_fts_index_under_schema_authority_lazy(
        self: FTSPolyfillManager,
        schema_owner: Any,
        *,
        table_name: SqlTableName,
        fts_index_class: type[FTSInvertedIndex],
        fts_metadata_class: type[FTSMetadata],
        fts_idf_cache_class: type[Any],
        fts_stats_class: type[Any],
        preserve_existing_artifacts: bool = False,
    ) -> LazyResult[bool]:
        """Async polyfill FTS table/index creation under one explicit schema owner."""
        artifact_table_names = _polyfill_artifact_table_names(table_name)
        (
            index_table_name,
            metadata_table_name,
            idf_cache_table_name,
            stats_table_name,
        ) = artifact_table_names

        artifacts_existed = _schema_artifact_tables_exist_for_planning(
            schema_owner,
            artifact_table_names,
        )
        if artifacts_existed:
            return LazyResult.of(False)

        drop_effects = (
            ()
            if preserve_existing_artifacts
            else (
                schema_owner.drop_table_lazy(index_table_name, if_exists=True),
                schema_owner.drop_table_lazy(metadata_table_name, if_exists=True),
                schema_owner.drop_table_lazy(idf_cache_table_name, if_exists=True),
                schema_owner.drop_table_lazy(stats_table_name, if_exists=True),
            )
        )
        artifact_models = (
            fts_index_class,
            fts_metadata_class,
            fts_idf_cache_class,
            fts_stats_class,
        )
        create_effects = (
            tuple(schema_owner.create_table_from_schema_lazy(model_cls, if_not_exists=True) for model_cls in artifact_models)
            if preserve_existing_artifacts
            else (
                schema_owner._bootstrap_table_schema_plan_lazy(
                    artifact_models,
                    produced_ref=ServerPlanRefId(schema_owner.schema_plan_builder()._next_ref()),
                ),
            )
        )
        effects = (
            *drop_effects,
            *create_effects,
            self._create_fts_indexes_lazy(schema_owner, fts_index_class),
        )
        from l2000_connection.schema_transaction import (
            _schema_dependency_refs_for_planning,
            _schema_static_value_lazy,
        )

        dependency_refs = tuple(ref_id for effect in effects for ref_id in _schema_dependency_refs_for_planning(effect))
        return _schema_static_value_lazy(
            schema_owner,
            not artifacts_existed,
            dependency_refs=tuple(dict.fromkeys(dependency_refs)),
        )

    @pure_lazy
    def _create_fts_indexes_lazy(
        self: FTSPolyfillManager,
        schema_txn: _SchemaDdlTransaction,
        fts_index_class: type[FTSInvertedIndex],
    ) -> LazyResult[Any]:
        """Enqueue FTS polyfill index grammar through the schema owner."""
        del self
        from l1000_schema.schema_def import safe_index_name

        table_name = get_table_name(fts_index_class)
        indexes = (
            SqlCreateIndex(
                name=SqlIndexIdent(SqlIndexName(safe_index_name(f"idx_{table_name}_token"))),
                table=SqlTableIdent(SqlTableName(table_name)),
                columns=[SqlColumnIdent(SqlColumnName("token"))],
                if_not_exists=True,
            ),
            SqlCreateIndex(
                name=SqlIndexIdent(SqlIndexName(safe_index_name(f"idx_{table_name}_content_hash"))),
                table=SqlTableIdent(SqlTableName(table_name)),
                columns=[SqlColumnIdent(SqlColumnName("content_hash"))],
                if_not_exists=True,
            ),
        )

        from l2000_connection.schema_transaction import (
            _schema_dependency_refs_for_planning,
            _schema_static_value_lazy,
        )

        dependencies = tuple(
            ref_id
            for index, statement in enumerate(indexes)
            for ref_id in _schema_dependency_refs_for_planning(
                schema_txn._bootstrap_ddl_bundle_plan_lazy(
                    (statement,),
                    name=SchemaDdlOperationName(f"fts_polyfill_index:{table_name}:{index}"),
                    phase=SchemaDdlPhase("fts"),
                ),
            )
        )
        return _schema_static_value_lazy(
            schema_txn,
            None,
            dependency_refs=tuple(dict.fromkeys(dependencies)),
        )

