    def _update_object_index_impl_lazy[RowT: DatabaseObjectRow[SysId]](
        self: FTSPolyfillManager,
        txn: WriteTransactionLazyMixin,
        model_type: type[RowT],
        obj: LazyResult[RowT],
        operation: Literal["insert", "update", "delete"],
    ) -> LazyResult[None]:
        from impl.common.l2070_server_plan.steps.write_side_effect_intents import (
            _PolyfillFtsMaintenanceConfig,
            _PolyfillFtsMaintenanceStep,
            _PolyfillFtsVisibleRowsStep,
        )
        from l1400_types import ServerPlanRefId

        if operation == "delete":
            msg = (
                "FTS polyfill delete maintenance is not supported via FTSPolyfillManager.update_object_index(). "
                "Content-addressed cleanup requires an explicit garbage-collection flow."
            )
            raise NotImplementedError(msg)

        config = get_fts_config(model_type)
        if config is None:
            msg = f"{model_type.__name__} not configured for FTS (missing @fts_indexed)"
            raise ValueError(msg)
        del config

        plan = txn._get_transaction_plan_lazy()
        visible_rows_ref = obj.plan_owned_result_ref(plan.owned_step_ref_ids())
        if visible_rows_ref is None:
            row = obj.resolved_value_for_planning()
            visible_rows_ref = ServerPlanRefId(plan._next_ref())
            plan.add_step(_PolyfillFtsVisibleRowsStep(visible_rows_ref, [row]))
        maintenance_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            _PolyfillFtsMaintenanceStep(
                maintenance_ref,
                model_type,
                _PolyfillFtsMaintenanceConfig(
                    visible_rows_ref=visible_rows_ref,
                ),
            ),
        )
        return cast(LazyResult[None], txn._add_intent_by_ref(ServerPlanRefId(maintenance_ref)))

