    def _tokenize_field(
        self: FTSPolyfillManager,
        text: str,
        language: str = "en",
    ) -> list[str]:
        """Tokenize a field's text content.

        Args:
            text: Text to tokenize
            language: ISO 639-1 language code

        Returns:
            List of normalized tokens (lowercased, stemmed)

        Example:
            >>> tokens = manager._tokenize_field("Running quickly through the forest")
            >>> print(tokens)
            ['run', 'quick', 'forest']
        """
        return [str(token) for token in _default_tokenizer().tokenize(text, language=language)]

    def _build_index_entries(
        self: FTSPolyfillManager,
        obj: DatabaseObjectRow[SysId],
        config: FTSIndexConfig,
    ) -> list[FTSInvertedIndex]:
        """Build inverted index entries for an object.

        Tokenizes each configured field and creates index entries with:
        - content_hash: Hash of FTS-indexed field values (for JOINs)
        - Token (stemmed)
        - Field name
        - Position (for phrase search)
        - Frequency (for BM25 ranking)

        Args:
            obj: Object to index
            config: FTS configuration

        Returns:
            List of index entries to insert

        Example:
            >>> product = Product(id=42, name="Wireless Keyboard", ...)
            >>> entries = manager._build_index_entries(product, config)
            >>> print(entries[0])
            FTSInvertedIndex(content_hash='a1b2...', token='wireless', field_name='name', ...)
        """
        entries: list[FTSInvertedIndex] = []

        # Compute content hash from FTS-indexed fields
        content_hash = compute_fts_content_hash(obj, config)

        from l1000_schema.dynamic_field_utils import get_field_value

        # Process each configured field
        for field_name in config.fields:
            # Get field value (handles dynamic types with properties)
            field_value = get_field_value(obj, DynamicFieldName(field_name))
            if field_value is None:
                continue  # Skip null fields

            # Convert to string if needed
            if not isinstance(field_value, str):
                field_value = str(field_value)

            # Tokenize the field
            tokens = self._tokenize_field(field_value, language=config.languages[0])

            # Count token frequencies in this field
            token_freq: dict[str, int] = {}
            token_positions: dict[str, list[int]] = {}
            for pos, token in enumerate(tokens):
                token_freq[token] = token_freq.get(token, 0) + 1
                if token not in token_positions:
                    token_positions[token] = []
                token_positions[token].append(pos)

            # Create index entries (one per token occurrence)
            for token, frequency in token_freq.items():
                for position in token_positions[token]:
                    entry = FTSInvertedIndex(
                        content_hash=content_hash,
                        token=token,
                        field_name=field_name,
                        position=position,
                        frequency=frequency,
                    )
                    entries.append(entry)

        return entries

    def _build_index_entries_from_dict(
        self: FTSPolyfillManager,
        obj_dict: dict[str, Any],
        config: FTSIndexConfig,
        *,
        is_dynamic: bool = False,
    ) -> list[FTSInvertedIndex]:
        """Build inverted index entries from a dictionary (for versioned table indexing).

        Similar to _build_index_entries but works with dicts instead of objects.
        Used when indexing versioned tables via the generic FTS helpers.

        Args:
            obj_dict: Object as dictionary (from model_dump() or replay)
            config: FTS configuration
            is_dynamic: If True, fields are read from ``obj_dict["properties"]``.

        Returns:
            List of index entries to insert
        """
        from l1000_schema.dynamic_field_utils import get_field_value_from_dict

        entries: list[FTSInvertedIndex] = []

        # Compute content hash from FTS-indexed fields
        content_hash = compute_fts_content_hash_from_dict(obj_dict, config, is_dynamic=is_dynamic)

        # Process each configured field
        for field_name in config.fields:
            # Get field value (handles dynamic types with properties)
            field_value = get_field_value_from_dict(obj_dict, DynamicFieldName(field_name), is_dynamic=is_dynamic)
            if field_value is None:
                continue  # Skip null fields

            # Convert to string if needed
            if not isinstance(field_value, str):
                field_value = str(field_value)

            # Tokenize the field
            tokens = self._tokenize_field(field_value, language=config.languages[0])

            # Count token frequencies in this field
            token_freq: dict[str, int] = {}
            token_positions: dict[str, list[int]] = {}
            for pos, token in enumerate(tokens):
                token_freq[token] = token_freq.get(token, 0) + 1
                if token not in token_positions:
                    token_positions[token] = []
                token_positions[token].append(pos)

            # Create index entries (one per token occurrence)
            for token, frequency in token_freq.items():
                for position in token_positions[token]:
                    entry = FTSInvertedIndex(
                        content_hash=content_hash,
                        token=token,
                        field_name=field_name,
                        position=position,
                        frequency=frequency,
                    )
                    entries.append(entry)

        return entries

