@dataclass(frozen=True, slots=True)
class PlannedVersionedFtsMaterializationPartition:
    result: LazyResult[VersionedFtsMaterializationPartition]
    ref_id: ServerPlanRefId


@pure_lazy
def partition_revision_ids_by_materialization_lazy(
    txn: LazyReadTransaction,
    revision_ids: Sequence[RevisionId],
    domain: type[VersioningDomain],
) -> LazyResult[VersionedFtsMaterializationPartition]:
    """Partition FTS revisions without forcing materialization checks eagerly."""
    return partition_revision_ids_by_materialization_planned_lazy(txn, revision_ids, domain).result


@pure_lazy
def partition_revision_ids_by_materialization_planned_lazy(
    txn: LazyReadTransaction,
    revision_ids: Sequence[RevisionId],
    domain: type[VersioningDomain],
) -> PlannedVersionedFtsMaterializationPartition:
    """Partition FTS revisions and return the explicit ServerPlan ref."""
    plan = txn._get_transaction_plan_lazy()
    revision_ids_tuple = tuple(revision_ids)
    if not revision_ids_tuple:
        ref_id = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            ReturnValueStep(
                ref_id,
                VersionedFtsMaterializationPartition(
                    materialized=[],
                    non_materialized=[],
                ),
            ),
        )
        return PlannedVersionedFtsMaterializationPartition(
            result=cast(LazyResult[VersionedFtsMaterializationPartition], txn._add_intent_by_ref(ref_id)),
            ref_id=ref_id,
        )

    planned_checks = tuple(_is_revision_materialized_planned_lazy(txn, domain, revision_id) for revision_id in revision_ids)
    materialized_ref_ids = [planned_check.ref_id for planned_check in planned_checks]
    ref_id = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        PartitionRevisionIdsByMaterializationStep(
            ref_id,
            revision_ids=revision_ids_tuple,
            materialized_ref_ids=materialized_ref_ids,
        ),
    )
    return PlannedVersionedFtsMaterializationPartition(
        result=cast(LazyResult[VersionedFtsMaterializationPartition], txn._add_intent_by_ref(ref_id)),
        ref_id=ref_id,
    )


@pure_lazy
def require_all_revision_ids_materialized_lazy(
    txn: LazyReadTransaction,
    partition: PlannedVersionedFtsMaterializationPartition,
) -> LazyResult[VersionedFtsMaterializationPartition]:
    """Require that a lazy FTS partition contains only materialized revisions."""
    return require_all_revision_ids_materialized_planned_lazy(txn, partition).result


@pure_lazy
def require_all_revision_ids_materialized_planned_lazy(
    txn: LazyReadTransaction,
    partition: PlannedVersionedFtsMaterializationPartition,
) -> PlannedVersionedFtsMaterializationPartition:
    """Require materialized revisions and return the explicit ServerPlan ref."""
    plan = txn._get_transaction_plan_lazy()
    ref_id = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        RequireAllRevisionIdsMaterializedStep(
            ref_id,
            partition_ref_id=partition.ref_id,
        ),
    )
    return PlannedVersionedFtsMaterializationPartition(
        result=cast(LazyResult[VersionedFtsMaterializationPartition], txn._add_intent_by_ref(ref_id)),
        ref_id=ref_id,
    )

